QW.lxloaded(9,{"ذكر":{"mf":"الذِّكْرُ: تارة يقال ويراد به هيئة للنّفس بها يمكن للإنسان أن يحفظ ما يقتنيه من المعرفة، وهو كالحفظ إلّا أنّ الحفظ يقال اعتبارا بإحرازه، والذِّكْرُ يقال اعتبارا باستحضاره، وتارة يقال لحضور الشيء القلب أو القول، ولذلك قيل:<br><strong>الذّكر ذكران:</strong><br>ذكر بالقلب.<br>وذكر باللّسان.<br><strong>وكلّ واحد منهما ضربان:</strong><br>ذكر عن نسيان.<br>وذكر لا عن نسيان بل عن إدامة الحفظ. وكلّ قول يقال له ذكر، فمن الذّكر باللّسان قوله تعالى: لَقَدْ أَنْزَلْنا إِلَيْكُمْ كِتاباً فِيهِ ذِكْرُكُمْ [الأنبياء/ ١٠]، وقوله تعالى: وَهذا ذِكْرٌ مُبارَكٌ أَنْزَلْناهُ [الأنبياء/ ٥٠]، وقوله:<br>هذا ذِكْرُ مَنْ مَعِيَ وَذِكْرُ مَنْ قَبْلِي [الأنبياء/ ٢٤]، وقوله: أَأُنْزِلَ عَلَيْهِ الذِّكْرُ مِنْ بَيْنِنا [ص/ ٨]، أي: القرآن، وقوله تعالى: ص وَالْقُرْآنِ ذِي الذِّكْرِ [ص/ ١]، وقوله: وَإِنَّهُ لَذِكْرٌ لَكَ وَلِقَوْمِكَ [الزخرف/ ٤٤]، أي:<br>شرف لك ولقومك، وقوله: فَسْئَلُوا أَهْلَ الذِّكْرِ [النحل/ ٤٣]، أي: الكتب المتقدّمة.<br>وقوله قَدْ أَنْزَلَ اللَّهُ إِلَيْكُمْ ذِكْراً رَسُولًا [الطلاق/ ١٠- ١١]، فقد قيل: الذكر هاهنا وصف للنبيّ صلّى الله عليه وسلم <strong>«٢»</strong>، كما أنّ الكلمة وصف لعيسى عليه السلام من حيث إنه بشّر به في الكتب المتقدّمة، فيكون قوله: (رسولا) بدلا منه.<br>وقيل: (رسولا) منتصب بقوله (ذكرا) <strong>«٣»</strong> كأنه قال: قد أنزلنا إليكم كتابا ذكرا رسولا يتلو، نحو قوله: أَوْ إِطْعامٌ فِي يَوْمٍ ذِي مَسْغَبَةٍ يَتِيماً [البلد/ ١٤- ١٥]، ف (يتيما) نصب بقوله (إطعام).<br>ومن الذّكر عن النسيان قوله: فَإِنِّي نَسِيتُ الْحُوتَ وَما أَنْسانِيهُ إِلَّا الشَّيْطانُ أَنْ أَذْكُرَهُ<br><br>[الكهف/ ٦٣]، ومن الذّكر بالقلب واللّسان معا قوله تعالى: فَاذْكُرُوا اللَّهَ كَذِكْرِكُمْ آباءَكُمْ أَوْ أَشَدَّ ذِكْراً [البقرة/ ٢٠٠]، وقوله:<br>فَاذْكُرُوا اللَّهَ عِنْدَ الْمَشْعَرِ الْحَرامِ وَاذْكُرُوهُ كَما هَداكُمْ [البقرة/ ١٩٨]، وقوله: وَلَقَدْ كَتَبْنا فِي الزَّبُورِ مِنْ بَعْدِ الذِّكْرِ [الأنبياء/ ١٠٥]، أي: من بعد الكتاب المتقدم. وقوله هَلْ أَتى عَلَى الْإِنْسانِ حِينٌ مِنَ الدَّهْرِ لَمْ يَكُنْ شَيْئاً مَذْكُوراً [الدهر/ ١]، أي: لم يكن شيئا موجودا بذاته، وإن كان موجودا في علم الله تعالى.<br>وقوله: أَوَلا يَذْكُرُ الْإِنْسانُ أَنَّا خَلَقْناهُ مِنْ قَبْلُ [مريم/ ٦٧]، أي: أولا يذكر الجاحد للبعث أوّل خلقه، فيستدلّ بذلك على إعادته، وكذلك قوله تعالى: قُلْ يُحْيِيهَا الَّذِي أَنْشَأَها أَوَّلَ مَرَّةٍ [يس/ ٧٩]، وقوله: وَهُوَ الَّذِي يَبْدَؤُا الْخَلْقَ ثُمَّ يُعِيدُهُ [الروم/ ٢٧]، وقوله:<br>وَلَذِكْرُ اللَّهِ أَكْبَرُ [العنكبوت/ ٤٥]، أي:<br>ذكر الله لعبده أكبر من ذكر العبد له، وذلك حثّ على الإكثار من ذكره. والذِّكْرَى: كثرة الذّكر، وهو أبلغ من الذّكر، قال تعالى: رَحْمَةً مِنَّا وَذِكْرى لِأُولِي الْأَلْبابِ [ص/ ٤٣]، وَذَكِّرْ فَإِنَّ الذِّكْرى تَنْفَعُ الْمُؤْمِنِينَ [الذاريات/ ٥٥]، في آي كثيرة. والتَّذْكِرَةُ: ما يتذكّر به الشيء، وهو أعمّ من الدّلالة والأمارة، قال تعالى: فَما لَهُمْ عَنِ التَّذْكِرَةِ مُعْرِضِينَ [المدثر/ ٤٩]، كَلَّا إِنَّها تَذْكِرَةٌ [عبس/ ١١]، أي: القرآن.<br>وذَكَّرْتُهُ كذا، قال تعالى: وَذَكِّرْهُمْ بِأَيَّامِ اللَّهِ [إبراهيم/ ٥]، وقوله: فَتُذَكِّرَ إِحْداهُمَا الْأُخْرى [البقرة/ ٢٨٢]، قيل: معناه تعيد ذكره، وقد قيل: تجعلها ذكرا في الحكم <strong>«١»</strong>. قال بعض العلماء <strong>«٢»</strong> في الفرق بين قوله: فَاذْكُرُونِي أَذْكُرْكُمْ [البقرة/ ١٥٢]، وبين قوله: اذْكُرُوا نِعْمَتِيَ [البقرة/ ٤٠] : إنّ قوله: فَاذْكُرُونِي مخاطبة لأصحاب النبي صلّى الله عليه وسلم الذين حصل لهم فضل قوّة بمعرفته تعالى، فأمرهم بأن يذكروه بغير واسطة، وقوله تعالى: اذْكُرُوا نِعْمَتِيَ مخاطبة لبني إسرائيل الذين لم يعرفوا الله إلّا بآلائه، فأمرهم أن يتبصّروا نعمته، فيتوصّلوا بها إلى معرفته. والذَّكَرُ: ضدّ الأنثى، قال تعالى:<br>وَلَيْسَ الذَّكَرُ كَالْأُنْثى [آل عمران/ ٣٦]، وقال: آلذَّكَرَيْنِ حَرَّمَ أَمِ الْأُنْثَيَيْنِ [الأنعام/ ١٤٤]، وجمعه: ذُكُور وذُكْرَان، قال تعالى: ذُكْراناً وَإِناثاً [الشورى/ ٥٠]، وجعل الذَّكَر كناية عن العضو المخصوص.<br>والمُذْكِرُ: المرأة التي ولدت ذكرا، والمِذْكَار:<br>التي عادتها أن تذكر، وناقة مُذَكَّرَة: تشبه الذّكر في عظم خلقها، وسيف ذو ذُكْرٍ، ومُذَكَّر:<br>صارم، تشبيها بالذّكر، وذُكُورُ البقل: ما غلظ منه.<br>","mq":[["عنهما يتفرع كلم الباب"],"الذال والكاف والراء أصلان، عنهما يتفرَّع كلِم الباب.<br>فالمُذْكِر: التى وَلَدَتْ ذكراً. والمِذْكار: التى تَلِد الذُّكْرانَ عادةً. قال عدىّ:<br>لَقد عَدَّيْتُ دَوسَرَةً … كعَلَاةِ القَين مِذْكارَا (٣)<br>والمِذْكار: الأرض تُنْبِت ذُكور العُشْب. والمُذَكَّرة من النُّوق: التى خَلْقها وخُلُقها كخَلْق البعير أو"],"ln":"<p><b>1.</b> <b class=\"ar\">ذَكَرَهُ</b> , [aor. <b class=\"ar\">ذَكُرَ</b> ,] inf. n. <span class=\"ar\">ذِكْرَى</span>, (S, A, Msb,) which is fem., (Msb,) and imperfectly decl., (S,) and <span class=\"ar\">ذِكْرٌ</span> (A, K) [and <span class=\"ar\">ذُكْرٌ</span>, or, accord. to EtTebreezee, (Ham p. 26,) the latter of these two but not the former, or, as is said in the Msb., both are properly substs., and a distinction is made between them, as will be shown below,] and <span class=\"ar\">تَذْكَارٌ</span>, (K,) <i>He preserved it in his memory:</i> (K, * TA:) <i>he remembered it;</i> (S, A;) as also <span class=\"ar\">ذَكَرَهُ بِقَلْبِهِ</span> [to distinguish it from <span class=\"ar\">ذَكَرَ</span> in a sense afterwards to be explained], (S, Msb,) and <span class=\"ar\"> <span class=\"ar\">تذكّرهُ</span></span>; (S, A;) and <span class=\"ar\"> <span class=\"ar\">اِدَّكَرَهُ</span></span> (S, K, TA,) originally <span class=\"ar\">اِذْتَكَرَهُ</span> (S,) and <span class=\"ar\">اِذَّكَرَهُ</span> (TA, and so in the CK,) and <span class=\"ar\">اِذْدَكَرَهُ</span> (K,) and <span class=\"ar\"> <span class=\"ar\">استذكرهُ</span></span>, (AZ, K,) signify the same as <span class=\"ar\">تذكّرهُ</span> (K) [as explained above]: <span class=\"ar\"> <span class=\"ar\">تذكّرهُ</span></span> signifies also <i>he became reminded of it;</i> (Msb;) [and so <span class=\"ar\"> <span class=\"ar\">ادّكرهُ</span></span> and its variations: and <span class=\"ar\"> <span class=\"ar\">استذكرهُ</span></span> seems properly to signify, as also <span class=\"ar\"> <span class=\"ar\">تذكرّهُ</span></span>, <i>he recollected it;</i> or <i>called it to mind:</i> and <i>he sought to remember it:</i> and <span class=\"ar\"> <span class=\"ar\">استذكر</span></span> and <span class=\"ar\"> <span class=\"ar\">تذكّر</span></span> used intransitively, <i>he sought,</i> or <i>endeavoured, to remember.</i>] You say, <span class=\"ar\">ذَكَرْتُ الشَّىْءَ بَعْدَ النِّسْيَانِ</span> [<i>I remembered the thing after forgetting</i>]: (S:) and <span class=\"ar\">ذَكَرْتُ</span> <span class=\"ar\">المَنْسِىَّ</span> and <span class=\"ar\"> <span class=\"ar\">تَذَكَّرْتُهُ</span></span> [<i>I remembered the thing forgotten,</i> and <i>I became reminded of it,</i> or <i>I recollected it</i>]: (A:) and <span class=\"ar\"> <span class=\"ar\">ادّكر</span>بَعْدَ أَمَهٍ</span>, occurring in the Kur [xii. 45, accord. to one reading of the last word], means <i>He remembered</i> [or <i>became reminded</i>] <i>after forgetting.</i> (S) And <span class=\"ar\">رَبَطَ فِى إِصْبَعِهِ خَيْطًا <span class=\"ar\">يَسْتَذْكِرُ</span> بِهِ حَاجَتِهِ</span> [<i>He tied upon his finger a thread</i> or <i>string, seeking to remember,</i> or <i>recollect,</i> or <i>call to mind, thereby the thing that he wanted:</i> such a thread or string is commonly called <span class=\"ar\">رَتِيمَةٌ</span>:]: (AZ:) and <span class=\"ar\"> <span class=\"ar\">استذكر</span></span> is used alone with the like signification [i. e. <i>He sought to remember</i>]: and also signifies <i>He studied</i> a book <i>and preserved it in his memory,</i> accord. to the K; but accord. to other lexicons, <i>he studied</i> a thing <i>in order to remember it,</i> or <i>preserve</i> it <i>in his memory:</i> (TA:) you say, <span class=\"ar\"> <span class=\"ar\">استذكر</span>بِدِرَاسَتِهِ</span> <i>He sought to remember by his studying</i> of a book. (A.) -b2- <span class=\"ar\">ذَكَرَ حَقَّهُ</span>, (K,) inf. n. <span class=\"ar\">ذِكْرٌ</span> (TA,) <i>He was mindful of his right,</i> or <i>claim; and did not neglect it.</i> (K.) Agreeably with this explanation, the words in the Kur [ii. 231, &amp;c.,] <span class=\"ar\">وَٱذْكُرُوا نِعْمَةَ ٱللّٰهِ عَلَيْكُمْ</span> have been rendered <i>And be ye mindful of, and neglect not to be thankful for, the favour of God conferred upon you:</i> like as an Arab says to his companion, <span class=\"ar\">اُذْكُرْ حَقِّىعَلَيْكَ</span> <i>Be thou mindful of my claim upon thee; and neglect it not.</i> (TA.) -b3- [In like manner also are explained the words] <span class=\"ar\">وَٱذْكُرُوا مَا</span> <span class=\"ar\">فِيهِ</span> in the Kur [ii. 60], <i>And study ye what is in it, and forget it not:</i> or <i>think ye upon what is in it:</i> or <i>do ye what is in it.</i> (Bd.) -b4- One says, <span class=\"ar\">مَا ٱسْمُكَ أَذْكُرْ</span>, (Fs and Lb, and so in a copy of the K,) or <span class=\"ar\">أَذْكُرْهُ</span>, (so in another copy of the K, and in the TA,) the hemzeh of <span class=\"ar\">أَذْكُرْ</span> being disjunctive, (Lb, K,) [in the CK we find <span class=\"ar\">مَا اسمُكَ</span> <span class=\"ar\">اَذْكِرْهُ بقطعِ الهَمْزَةِ مِنْ اَذْكَر</span>, as though the reading were <span class=\"ar\">أَذْكَرْهُ</span> with a disjunctive hemzeh from <span class=\"ar\">أَذْكَرَ</span>, which is manifestly wrong,] and with fet-h, because it is the hemzeh of the first person of a triliteral [unaugmented] verb, and with the <span class=\"ar\">ر</span> mejzoom, because it is the complement of an interrogative phrase: (Lb:) it is expressive of disapprobation, (Lb, K,) and means, <i>Acquaint me with thy name:</i> [or, lit., <i>what is thy name?</i>] <i>I will remember it,</i> or <i>I will bear it in mind</i> (<span class=\"ar\">اذكره</span>): the conditional phrase [if thou tell it to me] is suppressed because unnecessary, on account of frequent usage of the saying, and because what remains is indicative of it: (Lb, MF:) the saying is a prov.; and is also related with the conjunctive hemzeh, [<span class=\"ar\">ٱذْكُرْ</span>, or <span class=\"ar\">ٱذْكُرْ</span>; in which case it is most appropriately rendered, <i>What is thy name? Say:</i> or <i>Tell it</i>] but the reading with the disjunctive hemzeh is that which is commonly known: (TA:) [for] -A2- <span class=\"ar\">ذَكَرَهُ</span>, aor. <b class=\"ar\">ذَكُرَ</b> , (TA,) inf. n. <span class=\"ar\">ذِكْرَى</span>, fem., [and imperfectly decl,] (Msb,) and <span class=\"ar\">ذِكْرٌ</span> and <span class=\"ar\">ذُكْرٌ</span>, (TA,) [or the former of these two (which is the most common of all) but not the latter, or, as is said in the Msb, both are properly substs., and a distinction is made between them, as will be shown below,] also signifies <i>He mentioned it; told it; related it; said it;</i> (TA;) and so <span class=\"ar\">ذَكَرَهُ بِلِسَانِهِ</span> [to distinguish it from <span class=\"ar\">ذَكَرَ</span> in the first sense explained above]. (S, Msb.) You say <span class=\"ar\">ذَكَرْتُ لِفُلَانٍ حَدِيثَ</span> <span class=\"ar\">كَذَاوَكَذَا</span> <i>I mentioned,</i> or <i>told,</i> or <i>related, to such a one the story of such and such things.</i> (TA.) And <span class=\"ar\">ذَكَرَ ٱمْرَأُ بِمَا لَيْسَ فِيهِ</span> [<i>He mentioned,</i> or <i>spoke of, a man as having that attribute which was not in him</i>]. (El-Jámi' es-Sagheer voce <span class=\"ar\">مَنْ</span>) -b2- And <span class=\"ar\">ذَكَرَهُ</span> (assumed tropical:) <i>He magnified Him,</i> namely, God; <i>celebrated, lauded,</i> or <i>praised, Him; asserted his unity;</i> (Zj;) [saying <span class=\"ar\">سُبْحَانَ ٱللّٰهِ</span>, and <span class=\"ar\">الحَمْدُ لِلّٰهِ</span>, and <span class=\"ar\">اَللّٰهُ أَكْبَرُ</span>; or <span class=\"ar\">لَاإِلَاهَ إِلَّاٱللّٰهُ</span>; or <span class=\"ar\">هُوَٱللّٰهُ</span>; or the like.] -b3- [And, in like manner, (assumed tropical:) <i>He spoke well of him,</i> namely, a man; <i>mentioned him with approbation; eulogized, praised,</i> or <i>commended, him:</i> for <span class=\"ar\">ذَكَرَهُ بِالجَمِيلِ</span>, or <span class=\"ar\">بِخَيْرٍ</span> See <span class=\"ar\">ذِكْرٌ</span> below.] -b4- Also, contr., [for <span class=\"ar\">ذَكَرَهُ</span> <span class=\"ar\">بِالقَبِيحِ</span> or <span class=\"ar\">بِشَرٍّ</span>] (assumed tropical:) <i>He spoke evil of him; men-</i> <i>tioned him with evil words;</i> (Fr;) <i>mentioned his vices,</i> or <i>faults; spoke evil of him behind his back,</i> or <i>in his absence, saying of him what would grieve him if he heard it, but saying what was true;</i> or merely <i>said of him what would grieve him:</i> an elliptical expression in this and in the contrary sense; what is meant being known. (Zj.) One says to a man, <span class=\"ar\">لَئِنْ ذَكَرْتَنِى لَتَنْدَمَنَّ</span>, meaning [<i>Verily, if thou mention me</i>] <i>with evil words</i> [<i>thou will assuredly repent</i>]: and in like manner the verb is used in the Kur xxi. 37 and 61: and 'Antarah says, <span class=\"ar\">لَاتَذْكُرِى فَرَسِى وَمَا أَطْعَمْتُهُ</span> <span class=\"ar\">فَيَكُونَ جِلْدُكَ مِثْلَ جِلْدِ الأَجْرَبِ</span> meaning <i>Mention thou not reproachfully</i> [<i>my horse, and what I have given him for food, for,</i> if thou do, <i>thy skin will be like the skin of the scabby</i>]: (Fr, T:) but AHeyth disallows this signification of the verb, and explains the saying of 'Antarah as meaning, <i>Be not thou fond of mentioning my horse,</i> and my preferring him before the family. (T, TA.) -b5- <span class=\"ar\">ذَكَرَ فُلَانَةَ</span>, inf. n <span class=\"ar\">ذِكْرٌ</span>, [expressly said to be] with kesr, [so in the CK, and I think it the right reading,] or <span class=\"ar\">ذَكْرٌ</span>, [so in a MS. copy of the K, and in the TA,] with fet-h, [so in the TA,] <i>He demanded such a one in marriage:</i> or <i>he addressed himself to demand her in marriage:</i> (K:) [as though the mentioning a woman implied a desire to demand her in marriage:] it occurs in one of these two senses in a trad. (TA.) -A3- <span class=\"ar\">ذَكَرَهُ</span>, inf. n. <span class=\"ar\">ذَكْرٌ</span>, with fet-h, <i>He struck him upon his penis.</i> (K.)</p><p><b>2.</b> <b class=\"ar\">ذكّرهُ إِيَّاهُ</b> , (S, A, * Msb, K,) and <span class=\"ar\">ذكّرهُ بِهِ</span>, (Kur xiv. 5, &amp;c.,) inf. n. <span class=\"ar\">تَذْكِرَةٌ</span> (A, TA) and <span class=\"ar\">تَذْكِيرٌ</span>, (K, TA,) and quasi-inf. n. <span class=\"ar\"> <span class=\"ar\">ذِكْرَى</span></span> imperfectly decl.; (A, * K, * TA;) and <span class=\"ar\"> <span class=\"ar\">اذكرهُ</span>ايّاهُ</span>; (S, Msb, K;) <i>He reminded him of,</i> or <i>caused him to remember, him,</i> or <i>it.</i> (S, Msb, K.) -b2- And <span class=\"ar\">ذكّر</span>, (TA,) inf. n. <span class=\"ar\">تَذْكِيرٌ</span> (K) [and <span class=\"ar\">تَذْكِرَةٌ</span> also, as in the Kur xx. 2], <i>He exhorted; admonished; exhorted to obedience; gave good advice, and reminded of the results of affairs; reminded of what might soften the heart, by the mention of rewards and punishments.</i> (K, TA.) Thus the verb is used in the Kur lxxxviii. 21. (TA.) -A2- Also <span class=\"ar\">ذكّرهُ</span>, inf. n. <span class=\"ar\">تَذْكِيرُ</span>, <i>He made it</i> (a word) <i>masculine; contr. of</i> <span class=\"ar\">أَنَّثَهُ</span>. (S, * Msb, K. *) -b2- In the Kur [ii. 282], <span class=\"ar\">فَتُذَكِّرَ إِحْدَاهُمَا</span> <span class=\"ar\">الأُخْرَى</span> is said by some to signify (assumed tropical:) <i>That one of them may make the other to be in the legal predicament of a male:</i> [meaning that both of them together shall be as one man:] or, accord. to others, <i>one of them may remind the other.</i> (TA.) -b3- It is said in a trad., <span class=\"ar\">القُرْآنُ <span class=\"ar\">ذَكَرٌ</span>فَذَكِّرُوهُ</span> (tropical:) <i>The Kur-án is eminently excellent</i> [lit., <i>masculine</i>]: <i>therefore do ye hold it and know it and describe it as such.</i> (K, TA. [In the CK, for <span class=\"ar\">ذَكَرٌ</span> is put <span class=\"ar\">ذِكْرٌ</span>.]) -b4- [Hence,] <span class=\"ar\">ذكّرهُ</span>, (TA,) inf. n. <span class=\"ar\">تَذْكِيرٌ</span>, (K,) <i>He put to it,</i> namely a sword, (TA,) and the head of an axe &amp;c., (K,) <i>an edge of steel.</i> (K, * TA.) [See <span class=\"ar\">ذُكْرَةٌ</span>.]</p><p><b>3.</b> <b class=\"ar\">ذاكرهُ</b> , (MA,) inf. n. <span class=\"ar\">مُذَاكَرَةٌ</span>, (KL;) <i>He called to mind with him</i> (MA, KL) a story, or discourse, or the like, (MA,) or a thing. (KL.) -b2- [And hence, <i>He conferred with him.</i>]</p><p><b>4.</b> <b class=\"ar\">أَذْكَرَ</b> see 2. -A2- <span class=\"ar\">اذكر</span> also signifies <i>He</i> (a man [or other]) <i>begat a male.</i> (TA from a trad.) And <span class=\"ar\">اذكرت</span> <i>She</i> (a woman, S, A, or other female, TA) <i>brought forth a male,</i> (S, A, K,) or <i>males.</i> (Mgh.) It is said in a prayer for a woman in labour, <span class=\"ar\">أَيْسَرَتْ وَأَذْكَرَتْ</span> <i>May she have an easy birth, and may she bring forth a male child.</i> (A.) And you say also, <span class=\"ar\">اذكرت بِهِ</span> (assumed tropical:) <i>She brought him forth a male, and hardy:</i> (TA from a trad.:) or <i>a male, and sharp and cunning.</i> (Mgh.)</p><p><b>5.</b> <b class=\"ar\">تَذَكَّرَ</b> see 1, in five places, in the first and second sentences. -b2- [Also <i>It</i> (a word) <i>was,</i> or <i>became,</i> or <i>was made, of the masculine gender; contr. of</i> <span class=\"ar\">تأنّث</span>.]</p><p><b>6.</b> <b class=\"ar\">تذاكروا</b> <i>They called to mind</i> [a story, or discourse, or the like, or a thing,] <i>one with another.</i> (KL. [See 3.]) -b2- [And hence, <i>They conferred together.</i>]</p><p><b>8.</b> <b class=\"ar\">اِدَّكَرَ</b> and <b class=\"ar\">اِذَّكَرَ</b> and <span class=\"ar\">اِذْدَكَرَ</span>: see 1, in three places, in the first and second sentences.</p><p><b>10.</b> <b class=\"ar\">إِسْتَذْكَرَ</b> see 1, in six places, in the first and third sentences.</p><p><b class=\"ar\">ذَكْرٌ</b> : see <span class=\"ar\">ذِكْرٌ</span>: -A2- and <span class=\"ar\">ذَكِيرٌ</span>.</p><p><b class=\"ar\">ذُكْرٌ</b> : see <span class=\"ar\">ذِكْرٌ</span>, in six places. -A2- <span class=\"ar\">سَيْفٌ ذُو ذُكْرٍ</span>, or <span class=\"ar\"> <span class=\"ar\">ذُكُرٍ</span></span>, (as in different copies of the S,) and <span class=\"ar\">أَذْكِرَةٍ</span>, [which is the pl.,] (A,) (tropical:) <i>A cutting,</i> or <i>sharp, sword.</i> (S, A.) [See <span class=\"ar\">ذُكْرَةٌ</span>.]</p><p><b class=\"ar\">ذِكْرٌ</b> (Yoo, A'Obeyd, Yaakoob, S, M, A, Msb, K) and <span class=\"ar\"> <span class=\"ar\">ذُكْرٌ</span></span>, (Yoo, A'Obeyd, Yaakoob, S, A, Msb, K, TA,) or the latter only in the first of the senses here to be explained, (Fr, Msb, TA,) and the latter only is mentioned in this sense in the Fs, (TA,) and is said by El-Ahmar to be of the dial. of Kureysh, (TA,) [both said in the Msb to be simple substs., though many hold them to be inf. ns.,] and <span class=\"ar\"> <span class=\"ar\">ذَكْرٌ</span></span>, accord. to one of the expositors of the Fs, but this is strange, (TA,) and <span class=\"ar\"> <span class=\"ar\">ذِكْرَةٌ</span></span> (S, M) and <span class=\"ar\"> <span class=\"ar\">ذُكْرَةٌ</span></span> (M, TA) and <span class=\"ar\"> <span class=\"ar\">ذِكْرَى</span></span>, (S, M, [see 1, first sentence,]) and also <span class=\"ar\">دِكْرٌ</span> (S) and <span class=\"ar\">دُكْرٌ</span>, mentioned by ISd as of the dial. of Rabee'ah, but held by him to be of weak authority, (TA,) <i>Remembrance;</i> (S, M, A, Msb, K, &amp;c.;) the <i>presence</i> of a thing <i>in the mind:</i> (Er-Rághib:) also termed <span class=\"ar\">ذِكْرٌ بِالقَلْبِ</span>, (Msb, TA,) to distinguish it from <span class=\"ar\">ذِكْرٌ</span> in another sense, to be explained below: (TA:) he pl. of <span class=\"ar\"> <span class=\"ar\">ذِكْرَةٌ</span></span> is <span class=\"ar\">ذِكَرٌ</span>, (M,) also said to be pl. of <span class=\"ar\"> <span class=\"ar\">ذِكْرَى</span></span>. (MF, art. <span class=\"ar\">احد</span>.) You say, <span class=\"ar\">اِجْعَلْهُ مِنْكَ عَلَى <span class=\"ar\">ذُكْرٍ</span></span> and <span class=\"ar\">ذِكْرٍ</span> in the same sense, <i>Place thou him,</i> or <i>it, in thy remembrance.</i> (S.) And <span class=\"ar\">عَلَى <span class=\"ar\">ذُكْرٍ</span>أَجْعَلَهُ مِنِّى</span>, and <span class=\"ar\">ذِكْرٍ</span>, <i>I will not forget him,</i> or <i>it.</i> (A.) And <span class=\"ar\">مَا زَالَ مِنِّى عَلَى <span class=\"ar\">ذُكْرٍ</span></span>, and <span class=\"ar\">ذِكْرٍ</span> (K,) or the former only, (Fr, Msb, TA,) <i>He,</i> or <i>it, did not cease to be in my remembrance;</i> (K;) <i>I did not forget him,</i> or <i>it.</i> (Fr, TA.) And <span class=\"ar\">أَنْتَ مِنِّى عَلَى <span class=\"ar\">ذُكْرٍ</span></span> <i>Thou art in my mind.</i> (ISd, Lb.) -b2- The words in the Kur [xxix. 44] <span class=\"ar\">وَلَذِكْرُ ٱللّٰهِ أَكْبَرُ</span> admit of two explanations: <i>The remembrance of God is better</i> for a man than a man's remembrance of a man: and <i>the remembrance of God is better</i> as more efficacious in forbidding evil conduct than is prayer. (TA.) -b3- <span class=\"ar\">ذِكْرٌ</span> also signifies <i>Memory; a certain quality of the mind, by which a man is able to remember what he cares to know;</i> like <span class=\"ar\">حِفُظٌ</span>, except that this latter term is used with regard to the preservation of a thing [in the mind], whereas the former is used with regard to calling it to mind. (Er-Rághib.) -A2- Also <span class=\"ar\">ذِكْرٌ</span> (Er-Rághib, Msb, TA) and <span class=\"ar\"> <span class=\"ar\">ذُكْرٌ</span></span>, (Msb, TA,) or the former only accord. to Fr, (Msb, TA,) and <span class=\"ar\"> <span class=\"ar\">ذِكْرَى</span></span> (Msb,) The <i>mention, telling, relating,</i> or <i>saying,</i> of a thing: said by some to be <i>contr. of</i> <span class=\"ar\">صَمْتٌ</span>: (TA:) and also termed <span class=\"ar\">ذِكْرٌ بِاللِّسَانِ</span> (Msb, TA,) to distinguish it from <span class=\"ar\">ذِكْرٌ</span> in the sense first explained above. (TA.) -b2- Also <span class=\"ar\">ذِكْرٌ</span> (assumed tropical:) The <i>praise,</i> and <i>glorification, of God;</i> the <i>celebration,</i> or <i>declaration, of his remoteness,</i> or <i>freedom, from every impurity</i> or <i>imperfection,</i> or <i>from everything derogatory from his glory;</i> or the <i>saying</i> <span class=\"ar\">سُبْحَانَ</span>, <span class=\"ar\">ٱللّٰهِ</span>, [<i>and</i> <span class=\"ar\">الحَمْدُ لِلّٰهِ</span>, <i>and</i> <span class=\"ar\">أَللّٰهُ أَكْبَرُ</span>,] <i>and</i> <span class=\"ar\">لَا إِلَاهَ إِلَّا</span> <span class=\"ar\">ٱللّٰهُ</span>, [&amp;c., see 1,] <i>and uttering all the forms of his praise: a reading,</i> or <i>reciting, of the Kur-án: a thanking</i> [<i>God</i>]: <i>obedience</i> [<i>to God</i>]: (Abu-l- 'Abbás:) <i>prayer to God;</i> (K;) <i>supplication.</i> (Abu-l-'Abbás, K.) -b3- Also (tropical:) <i>Praise,</i> or <i>eulogy,</i> or <i>good speech,</i> of another. (S, * K, * TA.) -b4- [And, accord. to some, (tropical:) <i>Dispraise,</i> or <i>evil speech.</i> See 1.] -b5- Also (assumed tropical:) <i>A thing that is current upon the tongue.</i> (K.) -b6- (tropical:) <i>Fame; renown; report; reputation;</i> (S, A, K;) <i>whether good or evil;</i> (ISd;) as also <span class=\"ar\"> <span class=\"ar\">ذُكْرَةٌ</span></span>. (AZ, ISd, K.) Thus in the saying, <span class=\"ar\">لَهُ ذِكْرٌ فِى النَّاسِ</span> (tropical:) <i>He has fame among the people:</i> in which it has also the signification next following. (A.) -b7- (tropical:) <i>Eminence; nobility; honour.</i> (S, A, Msb, K.) So in the Kur [xciv. 4], <span class=\"ar\">وَرَفَعْنَا</span> <span class=\"ar\">لَكَ ذِكْرَكَ</span> (tropical:) <i>And We have raised for thee thine eminence,</i> or <i>thy nobility,</i> or <i>thine honour:</i> as some say, it means, when I am mentioned, thou art mentioned with Me: and again, in the Kur [xliii. 43], <span class=\"ar\">وَ إِنَّهُ لَذِكْرٌ لَكَ وَ لِقَوْمِكَ</span> (tropical:) <i>And verily it</i> (the Kur-án) <i>is an honour to thee and to thy people.</i> (TA.) Also, in the Kur [xxxviii. 1], <span class=\"ar\">وَ القُرْآنِ ذِى الذِّكْرِ</span> (tropical:) <i>By the Kur-án possessed of eminence, &amp;c.</i> (S) -b8- Also (assumed tropical:) <i>A book containing an exposition of religion, and an institution of religious laws:</i> (K:) <i>any book of the prophets:</i> (TA:) and especially the <i>Kur-án:</i> (MF, TA:) and the <span class=\"ar\">تَوْرَاةٌ</span> [or <i>Book of the Law revealed to Moses</i>]: (Aboo-Hureyreh, TA in art. <span class=\"ar\">زبر</span>:) and that [<i>law</i>] <i>which is</i> [<i>recorded</i>] <i>in heaven.</i> (Sa'eed Ibn-Jubeyr, TA ubi suprà.) -b9- (assumed tropical:) <i>An exhortation; an admonition,</i> or <i>a warning.</i> (Bd in xxxviii. 1.) -b10- <span class=\"ar\">ذِكْرُ حَقٍّ</span> (tropical:) <i>A written obligation;</i> syn. <span class=\"ar\">صَكٌّ</span>: (A, K:) pl. <span class=\"ar\">ذُكُورُ حَقٍّ</span>, (A,) or <span class=\"ar\">ذُكُورُ حُقُوقٍ</span>. (TA.) You say, <span class=\"ar\">لِى عَلَى هٰذَا الأَمْرِ</span> <span class=\"ar\">ذِكْرُ حَقٍّ</span> (tropical:) [<i>I have a written obligation to insure this thing</i>]. (A.) -A3- See also the next paragraph, in the latter half.</p><p><b class=\"ar\">ذَكَرٌ</b> [probably originally signifying “ mentioned, ” or “ talked of, ” of the measure <span class=\"ar\">فَعَلٌ</span> in the sense of the measure <span class=\"ar\">مَفْعُولٌ</span>, like <span class=\"ar\">نَفَضٌ</span> in the sense of <span class=\"ar\">مَنْفُوضٌ</span>, and <span class=\"ar\">خَبَطٌ</span> in the sense of <span class=\"ar\">مَخْبُوطٌ</span>, and <span class=\"ar\">قَبَضٌ</span> in the sense of <span class=\"ar\">مَقْبُوضٌ</span>, &amp;c.; and hence the first, and perhaps most others, of the significations here following:] <i>Male; masculine; of the male,</i> or <i>masculine, sex,</i> or <i>gender; contr. of</i> <span class=\"ar\">أُنْثَى</span>: (S, A, Msb, K, &amp;c.:) [the corresponding word in Hebrew () has been supposed to have this signification because a male is much “ mentioned, ” or “ talked of; ” and it is well known that the Arabs make comparatively little account of a female:] pl. <span class=\"ar\">ذُكُورٌ</span> (S, A, Msb, K) and <span class=\"ar\">ذُكُورَةٌ</span> (A, Msb, K) and <span class=\"ar\">ذِكَارٌ</span> (K) and <span class=\"ar\">ذِكَارَةٌ</span> and <span class=\"ar\">ذُكْرَانٌ</span> (S, A, Msb, K) and <span class=\"ar\">ذِكَرَةٌ</span>: (S, K:) [the last, in one copy of the S, I find written <span class=\"ar\"> <span class=\"ar\">ذِكْرَةٌ</span></span>, which, if correct, is a pl. of pauc.: and in the TA, in the same phrase in which it occurs in the S, it is written <span class=\"ar\"> <span class=\"ar\">ذُكْرَةٌ</span></span>, and expressly said to be with damm, so that it is a quasi-pl. n.:] the pl. form with <span class=\"ar\">و</span> and <span class=\"ar\">ن</span> is not allowable. (Msb.) One says, <span class=\"ar\">كَمِ الذِّكَرَةُ مِنْ</span> <span class=\"ar\">وَلَدِكَ</span>, or <span class=\"ar\"> <span class=\"ar\">الذِّكْرَةُ</span></span>, (accord. to different copies of the S,) or <span class=\"ar\"> <span class=\"ar\">الذُّكْرَةُ</span></span>, with damm, (accord. to the TA,) <i>How many are the males of thy children?</i> (S, TA.) -b2- The <i>male organ of generation;</i> the <i>penis;</i> syn. <span class=\"ar\">عَوْفٌ</span>; (S, K, &amp;c.;) of a man: (TA:) or the <span class=\"ar\">فَرْج</span> [an equivocal term, but here evidently used in the above-mentioned sense,] of an animal: (Msb:) pl. <span class=\"ar\">ذُكُورٌ</span>, (K,) or <span class=\"ar\">ذِكَرَةٌ</span>, like <span class=\"ar\">عِنَبَةٌ</span>, (Msb,) or <span class=\"ar\">ذِكَارَةٌ</span>, (T, TA,) and <span class=\"ar\"> <span class=\"ar\">مَذَاكِيرُ</span></span>: (S, Msb, K:) the last contr. to analogy, (S, Msb,) as though used for the sake of distinction between this signification and the one immediately preceding: (S:) or of the same class as <span class=\"ar\">مَحَاسِنُ</span> [with respect to <span class=\"ar\">حُسْنٌ</span>] and <span class=\"ar\">مَلَامِحُ</span> [with respect to <span class=\"ar\">لَمْحَةٌ</span>]: (ISd:) Akh says that it is a pl. without a [proper] sing., like <span class=\"ar\">عَبَابِيدُ</span> and <span class=\"ar\">أَبَابِيلُ</span>: accord. to the T, it has no sing.; or if it have a sing., it is <span class=\"ar\"> <span class=\"ar\">مُذْكِرٌ</span></span>, like <span class=\"ar\">مُقْدِمٌ</span>, of which the pl. is <span class=\"ar\">مَقَادِيمُ</span>; and signifies the <i>parts next to the penis:</i> (TA:) or it signifies the <i>penis with what is around it;</i> [or the <i>genitals;</i>] and is similar to <span class=\"ar\">مَفَارِقُ</span> in the phrase <span class=\"ar\">شَابَتْ مَفَارِقُ</span> <span class=\"ar\">رَأْسِهِ</span>: and <span class=\"ar\">قَطَعَ مَذَاكِيرَهُ</span> signified <i>He extirpated his penis.</i> (Mgh.) -b3- Applied to a man, (A, K,) it also signifies (tropical:) <i>Strong; courageous; acute and ardent; vigorous and effective in affairs;</i> [and also] <i>stubborn; and disdainful:</i> (TA:) or [<i>masculine,</i> meaning] <i>perfect;</i> like as <span class=\"ar\">أُنْثَى</span> is applied to a woman. (T and A in art. <span class=\"ar\">انث</span>.) The signification of “ strong, courageous, and stubborn, ” and the significations which the same word has when applied to rain and to a saying, are assigned in the K to <span class=\"ar\"> <span class=\"ar\">ذِكْرٌ</span></span>; but [SM says,] I know not how this is; for in the other lexicons they are assigned to <span class=\"ar\">ذَكَرٌ</span>. (TA.) You say, <span class=\"ar\">لَا يَفْعَلُهُ إِلَّا</span> <span class=\"ar\">ذُكُورَةُ الرِّجَالِ</span> (tropical:) [<i>None will do it but such as are strong,</i> &amp;c., <i>of men</i>]. (A.) -b4- Applied to iron, (tropical:) <i>Of the toughest and best quality,</i> (K,) <i>and strongest;</i> (TA;) <i>contr. of</i> <span class=\"ar\">أَنِيثٌ</span>; (S;) [iron <i>converted into steel;</i>] as also <span class=\"ar\"> <span class=\"ar\">ذَكِيرٌ</span></span>. (K.) [See also <span class=\"ar\">ذُكْرَةٌ</span>.] -b5- Applied to a sword, (tropical:) <i>Having</i> <span class=\"ar\">مَآء</span> [i. e., <i>diversified wavy marks, streaks,</i> or <i>grain</i>]; (S;) as also <span class=\"ar\"> <span class=\"ar\">مُذَّكَّرٌ</span></span>: (S, K:) or <i>of which the edge is of steel</i> (<span class=\"ar\">حَدِيدٌ ذَكَرٌ</span>) <i>and the</i> <span class=\"ar\">مَتْن</span> [or <i>middle of the broad side</i>] <i>of soft iron;</i> of which the people say that they are of the fabric of the Jinn, or Genii: (A'Obeyd, S:) or <span class=\"ar\"> <span class=\"ar\">مُذَكَّرُ</span></span> signifies <i>having a sharp iron blade or edge:</i> (As:) the pl. of the former is <span class=\"ar\">ذُكُورٌ</span>. (Ham p. 168.) -b6- <span class=\"ar\">ذُكُورُ البُقُولِ</span> (tropical:) <i>Herbs,</i> or <i>leguminous plants, that are hard and thick:</i> (TA voce <span class=\"ar\">عُشْبٌ</span>:) or <i>that are thick, and inclining to bitterness:</i> (S, TA:) like as <span class=\"ar\">أَحْرَارُهَا</span> signifies such as are slender and sweet: (TA:) or the former signifies <i>such as are thick and rough.</i> (AHeyth.) -b7- <span class=\"ar\">ذُكُورَةُ الطِّيبِ</span>, (K,) and <span class=\"ar\">ذُكُورُهُ</span>, and <span class=\"ar\">ذِكَارَتُهُ</span>, (TA,) (tropical:) <i>Perfume proper for men, exclusively of women:</i> i. e., (TA,) <i>that leaves no stain;</i> (K, * TA;) <i>that becomes dissipated;</i> such as musk, and aloes-wood, and camphire, and <span class=\"ar\">غَالِيَة</span>, and <span class=\"ar\">ذَرِيرَة</span>. (TA.) [See the contr., <span class=\"ar\">طِيبٌ مُؤَنَّثٌ</span>, in art. <span class=\"ar\">انث</span>.] -b8- <span class=\"ar\">ذَكَرٌ</span> applied to the Kur-án signifies (tropical:) <i>Eminently excellent.</i> (K.) See 2. -b9- Applied to a saying, (tropical:) <i>Strong and firm:</i> and in like manner to poetry. (A.) -b10- The Arabs disliked a she-camel's bringing forth a male; and hence they applied the term <span class=\"ar\">ذَكَرٌ</span>, met., to (tropical:) Anything <i>disliked.</i> (A.) -b11- [Thus,] applied to rain, it signifies (tropical:) <i>Violent;</i> (A, K;) <i>falling in large drops.</i> (K.) They said, <span class=\"ar\">أَصَابَتِ الأَرْضَ ذُكُورُ الأَسْمِيَةِ</span> (tropical:) <i>Rains bringing intense cold and torrents fell upon the earth.</i> (A.) -b12- Applied to a day, (tropical:) [<i>Severe; distressing; hard to be borne:</i> see also <span class=\"ar\">مُذَكَّرٌ</span>]. (A.) -b13- IDrd says, I think that the name <span class=\"ar\">الذكر</span> [so in the TA, without any syll. signs; app. <span class=\"ar\">الذَّكَرُ</span>] is applied by some of the Arabs to <span class=\"ar\">السِّمَاكُ الرَّامِحُ</span> [or the star <i>Arcturus</i>]. (TA.)</p><p><b class=\"ar\">ذَكُرٌ</b> : see <span class=\"ar\">ذَكِيرٌ</span>.</p><p><b class=\"ar\">ذَكِرٌ</b> : see <span class=\"ar\">ذَكِيرٌ</span>.</p><p><b class=\"ar\">سَيْفٌ ذُو ذُكُرٍ</b> : see <span class=\"ar\">ذُكْرٌ</span>.</p><p><b class=\"ar\">ذَكْرَةٌ</b> : see <span class=\"ar\">مُذَكَّرٌ</span>.</p><p><b class=\"ar\">ذُكْرَةٌ</b> : see <span class=\"ar\">ذِكْرٌ</span>, in two places: -A2- and <span class=\"ar\">ذَكَرٌ</span>, in two places. -A3- Also (tropical:) <i>A piece of steel that is added</i> [<i>to the edge of a sword and</i>] <i>to the head of an axe &amp;c.</i> (K, * TA.) -b2- And (tropical:) <i>Sharpness</i> of a sword: [see also <span class=\"ar\">ذُكْرٌ</span>:] and of a man. (S, A, K.) You say, <span class=\"ar\">ذَهَبَتْ ذُكْرَةُ السَّيْفِ</span>, and <span class=\"ar\">ذُكْرَةُ الرَّجُلِ</span>, (tropical:) <i>The sharpness of the sword,</i> and <i>the sharpness of the man, went.</i> (S, A.)</p><p><b class=\"ar\">ذِكْرَةٌ</b> : see <span class=\"ar\">ذِكْرٌ</span>, in two places: -A2- and <span class=\"ar\">ذَكَرٌ</span>, in two places.</p><p><b class=\"ar\">ذَكَرَةٌ</b> : see <span class=\"ar\">مُذَكَّرٌ</span>.</p><p><b class=\"ar\">ذَكِرَةٌ</b> : see <span class=\"ar\">مُذَكَّرٌ</span>.</p><p><b class=\"ar\">ذِكْرَى</b> : see <span class=\"ar\">ذِكْرٌ</span>, in three places. -b2- <i>Remembrance with the reception of exhortation:</i> so in the following passage of the Kur [xlvii. 20], <span class=\"ar\">فَأَنَّى لَهُمْ إِذَا جَآءَتْهُمْ ذِكْرَاهُمْ</span> [<i>Then how,</i> that is, of what avail, <i>will be to them their remembrance with the reception of exhortation when it</i> (the hour of the resurrection) <i>cometh to them:</i> or] <i>how will it be to them when it</i> (the hour) <i>cometh to them with their remembrance and their reception of exhortation:</i> (K, * TA:) i. e., this will not profit them. (TA.) -b3- <i>Repentance:</i> so in the Kur [lxxxix. 24], <span class=\"ar\">وَأَنَّى لَهُ الذِّكْرَى</span>, i. e. <i>And how shall he have repentance?</i> (K, TA.) -b4- <i>A reminding,</i> or <i>causing to remember:</i> so in the Kur viii. 1, and xi. 121, (K,) and li. 55. (Fr.) See 2. -b5- <i>An admonition:</i> so in the Kur xxxviii. 42, and xl. 56. (K.) -b6- <i>A being reminded,</i> or <i>caused to remember:</i> so in the Kur [xxxviii. 46], in the phrase <span class=\"ar\">ذِكْرَى الدَّارِ</span> Their <i>being reminded of,</i> or <i>caused to remember, the</i> latter <i>abode,</i> and being made to relinquish worldly things, or not to desire them: (K:) or it may mean their <i>remembering much the latter abode.</i> (B, TA.)</p><p><b class=\"ar\">ذَكِيرٌ</b> A man <i>possessing an excellent memory.</i> (S.) -b2- Also, (AZ, K,) and <span class=\"ar\"> <span class=\"ar\">ذَكْرٌ</span></span>, (accord. to a MS. copy of the K, and so, as is said in the TA, accord. to the method of the author of the K,) or <span class=\"ar\"> <span class=\"ar\">ذَكِرٌ</span></span>, (accord. to the CK,) and <span class=\"ar\"> <span class=\"ar\">ذَكُرٌ</span></span> and <span class=\"ar\"> <span class=\"ar\">ذِكِّيرٌ</span></span>, (K,) (tropical:) A man <i>possessing</i> <span class=\"ar\">ذِكْر</span>, (K,) i. e., <i>fame,</i> or <i>renown:</i> or <i>glory,</i> or <i>boastfulness.</i> (TA.) -A2- See also <span class=\"ar\">ذَكَرٌ</span>, in the latter half of the paragraph.</p><p><b class=\"ar\">ذِكِّيرٌ</b> : see the next preceding paragraph.</p><p><b class=\"ar\">ذُكَّارَةٌ</b> The <i>males</i> of palm-trees. (K.)</p><p><b class=\"ar\">ذَاكِرٌ</b> [act. part. n. of 1]. -b2- <span class=\"ar\">مَا حَلَفْتُ بِهِ ذَاكِرًا وَلَا</span> <span class=\"ar\">آثِرًا</span>: see art. <span class=\"ar\">اثر</span>.</p><p><b class=\"ar\">أَذْكَرُ</b> (tropical:) <i>More,</i> and <i>most, sharp,</i> (S, TA,) <i>acute and ardent, vigorous and effective in affairs.</i> (TA.) Mohammad used to go round to his wives in one night, and to perform the ablution termed <span class=\"ar\">غُسْل</span> for his visit to every one of them; and being asked wherefore he did so, he answered, <span class=\"ar\">إِنَّهُ أَذْكَرُ</span> (tropical:) <i>It is more,</i> or <i>most, sharp</i> [or <i>effective</i>]; syn. <span class=\"ar\">أَحَدُّ</span>. (S, TA, from a trad.) And it was said to Ibn-Ez-Zubeyr, when he was prostrated, <span class=\"ar\">وَٱللّٰهِ مَا وَلَدَتِ النِّسَآءُ أَذْكَرَ مِنْكَ</span> (tropical:) <i>By God, women have not brought forth one more acute and ardent and vigorous and effective in affairs than thou.</i> (TA from a trad.)</p><p><b class=\"ar\">تَذْكِرَةٌ</b> an inf. n. of 2. (A, TA.) -b2- [And hence,] <i>A thing by means of which something that one wants</i> [or <i>desires to remember</i>] <i>is called to mind; a memorandum.</i> (S, K, TA.) -b3- [<i>A biographical memoir.</i> -b4- And, in the present day, <i>Any official note;</i> such as <i>a passport; a permit;</i> and <i>the like.</i>]</p><p><b class=\"ar\">مَذْكَرٌ</b> <i>A place of remembrance:</i> pl. <span class=\"ar\">مَذَاكِرُ</span>: whence <span class=\"ar\">المَذَاكِرُ</span> in a trad., app. meaning <i>The black corner</i> or <i>stone</i> [<i>of the Kaabeh</i>]. (TA.)</p><p><b class=\"ar\">مُذْكَرٌ</b> : see its fem., with <span class=\"ar\">ة</span>, voce <span class=\"ar\">مُذَكَّرٌ</span>.</p><p><b class=\"ar\">مُذْكِرٌ</b> A woman [or other female (see 4)] <i>bringing forth a male:</i> (S, K:) or a woman <i>that brings forth men-children.</i> (TA in art. <span class=\"ar\">رجل</span>.) -b2- And (tropical:) A desert <i>that produces herbs,</i> or <i>leguminous plants, of the kind called</i> <span class=\"ar\">ذُكُور</span>. (As. [See <span class=\"ar\">ذَكَرٌ</span>: and see also <span class=\"ar\">مِذْكَارٌ</span>.]) -b3- And (tropical:) A road <i>that is feared.</i> (A, K.) -b4- See also <span class=\"ar\">مَذَكَّرٌ</span>, in two places. -b5- And see <span class=\"ar\">ذَكَرٌ</span>, in the former half of the paragraph.</p><p><b class=\"ar\">مُذَكَّرٌ</b> [A <i>masculine</i> word; a word <i>made mas-</i> <i>culine</i>]. -b2- <span class=\"ar\">مُذَكَّرَةٌ</span> A she-camel <i>resembling a hecamel in make and in disposition.</i> (S.) And also, (K, TA,) or <span class=\"ar\"> <span class=\"ar\">مُذْكَرَةٌ</span></span>, (accord. to the CK,) A woman <i>who makes herself like a male;</i> (K;) as also <span class=\"ar\"> <span class=\"ar\">ذَكَرَةٌ</span></span>, (L, and so in a copy of the K,) or <span class=\"ar\"> <span class=\"ar\">ذَكِرَةٌ</span></span>, (so in another copy of the K, and in the TA,) or <span class=\"ar\"> <span class=\"ar\">ذَكْرَةٌ</span></span>, (so in the CK,) and <span class=\"ar\"> <span class=\"ar\">مُتَذَكِّرَةٌ</span></span>. (K.) -b3- <span class=\"ar\">مُذَكَّرَةُ الثُّنْيَا</span> A she-camel <i>having a large head,</i> (K, TA,) <i>like that of a he-camel:</i> (TA:) because her head is one of the parts that are excepted in the game of chance [called <span class=\"ar\">المَيْسِر</span>] for the man who has sold her: [therefore those parts are termed <span class=\"ar\">الثُّنْيَا</span>:] (K:) or <i>resembling the make of the male in</i> [<i>the largeness of</i>] <i>the head and legs.</i> (Th, M in art. <span class=\"ar\">ثنى</span>.) -b4- And <span class=\"ar\">يَوْمٌ مُذَكَّرٌ</span> (tropical:) <i>A day that is severe, distressing,</i> or <i>hard to be borne;</i> as also <span class=\"ar\"> <span class=\"ar\">مُذْكِرٌ</span></span>: (K, TA:) or <i>in which a severe fight,</i> or <i>slaughter, has taken place.</i> (A, TA.) [See also <span class=\"ar\">ذَكَرٌ</span>, last sentence but one.] -b5- And <span class=\"ar\">دَاهِيَةٌ مُذَكَّرَةٌ</span> (tropical:) <i>A severe calamity</i> or <i>misfortune;</i> (A, K;) and so <span class=\"ar\"> <span class=\"ar\">مُذْكِرٌ</span></span> [without <span class=\"ar\">ة</span> because it is from this epithet applied to a she-camel as meaning \"bringing forth a male;\" for her doing so was disliked, as has been mentioned voce <span class=\"ar\">ذَكَرٌ</span>]: (K:) or the latter means <i>which none can withstand but strong, courageous, stubborn men.</i> (TA.) -A2- See also <span class=\"ar\">ذَكَرٌ</span>, in two places, in the latter half of the paragraph.</p><p><b class=\"ar\">مِذْكَارٌ</b> A woman [or other female] <i>that usually brings forth males.</i> (S, K.) And A man <i>who usually begets male children.</i> (TA.) -b2- Also (tropical:) Land <i>that produces herbs,</i> or <i>leguminous plants, such as are termed</i> <span class=\"ar\">ذُكُور</span>: (A, TA: [see <span class=\"ar\">مُذْكِرٌ</span>, and <span class=\"ar\">ذَكَرٌ</span>:]) or <i>that does not produce</i> [<i>anything</i>]: but the former signification is the more common. (TA.) -b3- And <span class=\"ar\">فَلَاةٌ مِذْكَارٌ</span> (tropical:) <i>A terrible desert;</i> (As, A, K;) <i>that is not traversed but by strong, courageous, stubborn men.</i> (As, K.)</p><p><b class=\"ar\">مَذْكُورٌ</b> [pass. part. n. of 1]. -b2- (assumed tropical:) A man <i>praised,</i> or <i>spoken of well.</i> (TA.) -b3- <span class=\"ar\">لَمْ يَكُنْ شَيْئًا مَذْكُورًا</span>, in the Kur [lxxvi. 1], means [accord. to some] <i>When he was not a thing existing by itself,</i> though existing in the knowledge of God. (TA.)</p><p><b class=\"ar\">مَذَاكِيرُ</b> said to be an anomalous pl. of <span class=\"ar\">ذَكَرٌ</span> in a sense pointed out above: see the latter word. (S, Msb, K. *)</p><p><b class=\"ar\">مُتَذَكّرَةٌ</b> : see <span class=\"ar\">مُذَكَّرٌ</span>.</p>"},"ذنب":{"mf":"ذَنَبُ الدّابة وغيرها معروف، ويعبّر به عن المتأخّر والرّذل، يقال: هم أذناب القوم، وعنه استعير: مَذَانِبُ التّلاع، لمسائل مياهها.<br>والمُذَنِّبُ <strong>«٤»</strong> : ما أرطب من قبل ذنبه، والذَّنُوبُ:<br>الفرس الطويل الذنب، والدّلو التي لها ذنب، واستعير للنّصيب، كما استعير له السّجل <strong>«٥»</strong>. قال تعالى: فَإِنَّ لِلَّذِينَ ظَلَمُوا ذَنُوباً مِثْلَ ذَنُوبِ أَصْحابِهِمْ [الذاريات/ ٥٩]، والذَّنْبُ في الأصل: الأخذ بذنب الشيء، يقال: ذَنَبْتُهُ:<br>أصبت ذنبه، ويستعمل في كلّ فعل يستوخم عقباه اعتبارا بذنب الشيء، ولهذا يسمّى الذَّنْبُ تبعة، اعتبارا لما يحصل من عاقبته، وجمع الذّنب ذُنُوب، قال تعالى: فَأَخَذَهُمُ اللَّهُ بِذُنُوبِهِمْ [آل عمران/ ١١]، وقال: فَكُلًّا أَخَذْنا بِذَنْبِهِ [العنكبوت/ ٤٠]، وقال: وَمَنْ يَغْفِرُ الذُّنُوبَ إِلَّا اللَّهُ [آل عمران/ ١٣٥]، إلى غير ذلك من الآي.","mq":[["احدها الجرم","موخر الشي"],"الذال والنون والباء أصول ثلاثة: أحدها الجُرم، والآخر مؤخَّر الشئ، والثالث كالحظِّ والنّصيب.<br>فالأوّل الذّنب والجُرم. يقال أذْنَبَ يُذْنِبُ. والاسم الذّنْب، وهو مُذْنِبٌ.<br>والأصل الآخر الذّنَب، وهو مؤخر الدوابّ (١)<br>، ولذلك سُمِّى الأتباعُ الذُّنَابَي.<br>والمَذَانب: مَذانب التِّلاع، وهى مَسَايل الماء فيها"],"ln":"<p><b>1.</b> <b class=\"ar\">ذَنَبَهُ</b> , (M, K,) aor. <b class=\"ar\">ذَنُبَ</b> (S, M, A, K) and <b class=\"ar\">ذَنِبَ</b> , (M, K,) inf. n. <span class=\"ar\">ذَنْبٌ</span>; (TK;) and <span class=\"ar\"> <span class=\"ar\">استذنبهُ</span></span>; (M, K;) [properly signifies] <i>He followed his tail, not quitting his track:</i> (M:) [and hence, tropically,] (assumed tropical:) <i>he followed him</i> [<i>in any case</i>], <i>not quitting his track.</i> (K.) You say, <span class=\"ar\">ذَنَبَ الإِبِلَ</span> and <span class=\"ar\"> <span class=\"ar\">استذنبها</span></span> <i>He followed the camels.</i> (A: there mentioned among proper significations.) ElKilábee says, <span class=\"ar\">وَجَآءَتِ الخَيْلُ جَمِيعَا تَذْنُبُهْ</span> [<i>And the horses,</i> or <i>horsemen, came all together, following him</i>]. (S [in which the meaning is indicated by the context; but whether it be proper or tropical in this instance is not shown].) And Ru-beh says, <span class=\"ar\">مِثْلُ الأَجِيرِ <span class=\"ar\">ٱسْتَذْنَبَ</span>الرَّوَاحِلَا</span> [<i>Like the hired man,</i>] <i>he was at the tails of the ridden camels.</i> (T, S.) <span class=\"ar\">ذَنَبَتِ القَوْمُ</span>, and [<span class=\"ar\">ذَنَبَتِ</span>] <span class=\"ar\">الطَّرِيقُ</span>, and <span class=\"ar\">الأَمْرُ</span> [<span class=\"ar\">ذَنَبَ</span>], and <span class=\"ar\">السَحَابُ يَذْنُبُ بَعْضُهُ</span> <span class=\"ar\">بَعْضًا</span>, are tropical phrases [meaning (tropical:) <i>The people followed one another,</i> and (tropical:) <i>The road followed on uninterruptedly,</i> and (tropical:) <i>The affair,</i> or <i>case,</i> or <i>event, proceeded by successive steps, uninterruptedly,</i> and (tropical:) <i>The clouds follow one another</i>]. (A.) -b2- See also 2.</p><p><b>2.</b> <b class=\"ar\">ذنّب</b> , (T, M, A,) inf. n. <span class=\"ar\">تَذْنِيبٌ</span>, (T, A,) said of the locust, <i>It stuck its tail into the ground to lay its eggs:</i> (A:) or, said of the [lizard called] <span class=\"ar\">ضبّ</span>, (Lth, T, M,) and of the locust, (M,) and of the [locust in the stage in which it is termed] <span class=\"ar\">فَرَاش</span>, (Lth, T, M,) and the like, (Lth, T,) <i>it desired to copulate,</i> (Lth, T, M,) or <i>to lay eggs, and therefore stuck its tail into the ground:</i> (M:) or, said of the <span class=\"ar\">ضَبّ</span>, it signifies only <i>it struck with its tail a hunter or serpent desiring to catch it:</i> (T:) or, said of the <span class=\"ar\">ضَبّ</span>, it signifies also <i>it put forth its tail</i> (M, A) <i>from the nearest part of its hole, having its head within it, as it does in hot weather,</i> (M,) or <i>when an attempt was made to catch it:</i> (A:) [or <i>it put its tail foremost</i> in coming forth from its hole; <i>contr. of</i> <span class=\"ar\">رَأَّسَ</span>.] -b2- <span class=\"ar\">ذَنَّبَتِ البُسْرَةُ</span>, (T, S, M, K,) or <span class=\"ar\">ذَنَّبَ البُسْرُ</span>, (As, A, Mgh,) or <span class=\"ar\">الرُّطَبُ</span>, (Msb,) inf. n. <span class=\"ar\">تَذْنِيبٌ</span>, (Msb, K,) (tropical:) [<i>The full-grown unripe date</i> or <i>dates,</i> or <i>the ripening dates,</i>] <i>began to ripen,</i> (Mgh, and so in a copy of the S,) or <i>showed ripening,</i> (Msb, and so in a copy of the S,) or <i>became speckled by reason of ripening,</i> (As, T, M, K,) or <i>ripened,</i> (A,) <i>at the</i> <span class=\"ar\">ذَنَب</span>, (As, T, S, M, A, Mgh, K,) i. e. the <i>part next the base and stalk.</i> (Mgh.) The dates in this case are termed <span class=\"ar\"> <span class=\"ar\">تَذْنُوبٌ</span></span> (Fr, T, S, M, A, K) in the dial. of Benoo-Asad, (Fr, T,) and <span class=\"ar\"> <span class=\"ar\">تُذْنُوبٌ</span></span> (Fr, T, K) in the dial. of Temeem (Fr, T) and <span class=\"ar\"> <span class=\"ar\">مُذَنِّبٌ</span></span>; (A, Mgh;) and a single date is termed <span class=\"ar\"> <span class=\"ar\">تَذْنُوبَةٌ</span></span> (T, M, * K) and <span class=\"ar\"> <span class=\"ar\">مُذَنِّبَةٌ</span></span>. (T, S.) -A2- <span class=\"ar\">ذنّب الضَّبَّ</span>, [or, probably, <span class=\"ar\"> <span class=\"ar\">ذَنَبَ</span></span>, being similar to <span class=\"ar\">رَأَسَ</span> and <span class=\"ar\">جَنَبَ</span> and <span class=\"ar\">فَأَدَ</span> &amp;c., or perhaps both,] <i>He seized the tail of the</i> <span class=\"ar\">ضبّ</span>; said of one endeavouring to catch it. (A.) -b2- <span class=\"ar\">ذنّب الأَفْعَى</span>, said of a <span class=\"ar\">ضَبّ</span>, <i>It turned its tail towards the viper,</i> or <i>met the viper tail-foremost,</i> in coming forth from its hole; <i>contr. of</i> <span class=\"ar\">رَأَّسَ الأَفْعَى</span>. (TA in art. <span class=\"ar\">رأس</span>.) -b3- <span class=\"ar\">ذنّب عِمَامَتَهُ</span> (tropical:) [<i>He made a tail to his turban;</i>] (S, K, TA;) i. e. (tropical:) <i>he made a portion of his turban to hang down like a tail:</i> (S, TA:) you say of him who has done this, <span class=\"ar\"> <span class=\"ar\">تَذَنَّبَ</span></span>. (S, A, K, TA.) -b4- <span class=\"ar\">ذَنَّبْتُ كَلَامَهُ</span> [and <span class=\"ar\">كِتَابَهُ</span> (tropical:) <i>I added an appendix to his discourse</i> and <i>his writing,</i> or <i>book;</i> like <span class=\"ar\">ذَيَّلْتُهُ</span>]. (A, TA.) [Hence, the inf. n. <span class=\"ar\">تَذْنِيبٌ</span> is used to signify (assumed tropical:) <i>An appendix;</i> like <span class=\"ar\">تَذْيِيلٌ</span>.] -b5- <span class=\"ar\">ذَنَّبُوا خُشْبَانَهُ</span> (assumed tropical:) <i>They made channels for water</i> (which are termed <span class=\"ar\">مَذَانِب</span>) <i>in its rugged ground.</i> (TA from a trad.)</p><p><b>3.</b> <b class=\"ar\">ذَانَبَتْ</b> , (AO, T, K,) written by Sgh, with his own hand, with <span class=\"ar\">ء</span>, but by others without, (MF,) said of a mare [in parturition], <i>She was in such a state that her fœtus came to her</i> <span class=\"ar\">قُحْقُح</span> [or <i>ischium</i> (here described by MF as <i>the place of meeting of the two hips</i>)], <i>and the</i> <span class=\"ar\">سِقْى</span> [q. v. (here explained by MF as <i>a skin containing yellow water</i>]) <i>was near to coming forth,</i> (AO, T, K,) <i>and the root of her tail rose, and the part thereof that is bare of hair, and she did not</i> [or <i>could not</i>] <i>lower it.</i> (AO, T.) In this case, she is said to be <span class=\"ar\"> <span class=\"ar\">مُذَانِبٌ</span></span>, (AO, T, K.)</p><p><b>4.</b> <b class=\"ar\">اذنب</b> <i>He committed a sin, crime, fault, misdemeanour,</i> &amp;c.; (S, * M, * A, * MA, K; *) <i>he became chargeable with a</i> <span class=\"ar\">ذَنْب</span> [or <i>sin,</i> &amp;c.]: (Msb:) it is an instance, among others, of a verb of which no proper inf. n. has been heard; [<span class=\"ar\">ذَنْبٌ</span> being used instead of such, as a quasi-inf. n.;] for <span class=\"ar\">إِذْنَابٌ</span>, like <span class=\"ar\">إِكْرَامٌ</span>, [though mentioned in the KL, as signifying the <i>committing of a sin</i> or <i>the like,</i> and also in the TK,] has not been heard. (MF.)</p><p><b>5.</b> <b class=\"ar\">تذنّب عَلَى فُلَانٍ</b> <i>He accused such a one of a sin, crime, fault, misdemeanour,</i> or <i>the like, which he had not committed,</i> or <i>though he had not committed any.</i> (A, TA.) -A2- See also 2, near the end of the paragraph. -b2- <span class=\"ar\">تَذَنَّبْتُ الوَادِىَ</span> (tropical:) <i>I came to the valley from the direction of its</i> <span class=\"ar\">ذَنَب</span> [q. v.]. (A.) And <span class=\"ar\">تذنّب الطَّرِيقَ</span> (tropical:) <i>He took the road;</i> (K, TA;) as though he took its <span class=\"ar\">ذِنَابَة</span>, or came to it from [the direction of] its <span class=\"ar\">ذَنَب</span>. (TA.)</p><p><b>10.</b> <b class=\"ar\">استذنبهُ</b> <i>He found him to be committing</i> [or <i>to have committed</i>] <i>a sin, crime, fault, misdemeanour,</i> or <i>the like:</i> and <i>he attributed,</i> or <i>imputed, to him a sin,</i> &amp;c. (Har p. 450.) -A2- See also 1, in three places. -A3- <span class=\"ar\">استذنب الأَمْرُ</span> (assumed tropical:) <i>The affair was,</i> or <i>became, complete,</i> [as though it assumed a tail,] <i>and in a right state.</i> (K, * TA.)</p><p><b class=\"ar\">ذَنْبٌ</b> <i>A sin, a crime, a fault, a misdemeanour, a misdeed, an unlawful deed, an offence, a transgression,</i> or <i>an act of disobedience;</i> syn. <span class=\"ar\">إِثْمٌ</span>, (T, M, A, Msb,) or <span class=\"ar\">جُرْمٌ</span>, (S,) or both, (TA,) and <span class=\"ar\">مَعْصِيَةٌ</span>: (T, TA:) or it differs from <span class=\"ar\">إِثْمٌ</span> in being <i>either intentional or committed through inadvertence;</i> whereas the <span class=\"ar\">اثم</span> is peculiarly intentional: (Kull p. 13:) or <i>a thing that precludes one from</i> [<i>the favour of</i>] <i>God:</i> or <i>a thing for which he is blamable who does it intentionally:</i> (KT:) pl. <span class=\"ar\">ذُنُوبٌ</span> (M, Msb, K) and pl. pl. <span class=\"ar\">ذُنُوبَاتٌ</span>. (M, K.) <span class=\"ar\">وَلَهُمْ عَلَىَّ ذَنْبٌ</span> [in the Kur xxvi. 13, said by Moses, meaning <i>And they have a crime</i> to charge <i>against me,</i>] refers to the speaker's slaughter of him whom he struck, who was of the family of Pharaoh. (M.)</p><p><b class=\"ar\">ذَنَبٌ</b> and <span class=\"ar\"> <span class=\"ar\">ذُنَابَى</span></span> (T, S, M, A, Msb, K) and <span class=\"ar\"> <span class=\"ar\">دِنِبَّى</span></span> and <span class=\"ar\"> <span class=\"ar\">ذُنُبَّى</span></span> (El-Hejeree, M, K) signify the same; (T, S, M, &amp;c.;) i. e. The <i>tail;</i> syn. <span class=\"ar\">ذَيْلٌ</span>: (TA: [in the CK, <span class=\"ar\">الذِّنْبِىُّ</span> is erroneously put for <span class=\"ar\">الذِّنْبِىَّ</span>:]) but accord. to Fr, one uses the first of these words in relation to the horse, and the second in relation to the bird: (T:) or the first is used in relation to the horse (S, A) and the ass [and the like] (S) more commonly than the second; (S, A; *) and the second is used in relation to a bird (S, M, A, Msb) more commonly than the first, (S, M, *) or more chastely: (M, * Msb:) or the second is [properly] of a winged creature; and the first is of any other; but the second is sometimes, metaphorically, of the horse: (Er-Riyáshee, TA:) or, as some say, the second signifies the <i>place of growth of the</i> <span class=\"ar\">ذَنَب</span> [or <i>tail</i>]: (M:) the pl. of <span class=\"ar\">ذَنَبٌ</span> is <span class=\"ar\">أَذْنَابٌ</span>. (S, M, A, Msb, K.) [Hence the following phrases &amp;c.] -b2- <span class=\"ar\">رَكِبَ ذَنَبَ البَعِيرِ</span> [lit. <i>He rode on the tail of the camel,</i> meaning] (tropical:) <i>he was content with a deficient lot.</i> (T, A, K.) -b3- <span class=\"ar\">ضَرَبَ بِذَنِبِهِ</span> [lit. <i>He smote</i> the earth <i>with his tail,</i> <span class=\"ar\">الأَرْضَ</span> being understood, meaning] (assumed tropical:) <i>he</i> (a man) <i>stayed,</i> or <i>abode, and remained fixed.</i> (K.) [See also another explanation of this phrase below.] And <span class=\"ar\">أَقَامَ بِأَرْضِنَا وَ غَرَزَ ذَنَبَهُ</span>, meaning (tropical:) [<i>He stayed,</i> or <i>abode, in our land, and remained fixed,</i> or] <i>did not quit it;</i> [lit., <i>and stuck his tail into the ground;</i>] originally said of the locust. (A, TA. [See art. <span class=\"ar\">غرز</span>.]) -b4- <span class=\"ar\">بَيْنِى</span> <span class=\"ar\">وَ بَيْنَهُ ذَنبُ الضَّبِّ</span> [lit. <i>Between me and him is the tail of the</i> <span class=\"ar\">ضبّ</span>,] means (tropical:) <i>between me and him is opposition</i> or <i>competition</i> [<i>as when two persons are endeavouring to seize the tail of the</i> <span class=\"ar\">ضبّ</span>]. (A, TA.) -b5- <span class=\"ar\">اِسْتَرْخَى ذنَبُ الشَّيْخِ</span> (tropical:) <i>The old man's</i> <span class=\"ar\">شَىْء</span> <i>became lax,</i> or <i>languid.</i> (Á, TA.) -b6- <span class=\"ar\">رَكِبَ</span> <span class=\"ar\">ذَنَبَ الرِّيحِ</span> [lit. <i>He rode upon the tail of the wind,</i>] means (tropical:) <i>he outwent,</i> or <i>outstripped, and was not reached,</i> or <i>overtaken.</i> (T, A, K.) -b7- <span class=\"ar\">وَلَّى خَمْسِينَ ذَنَبا</span> Original text has missing initial characters in the last word: the ذَنَ have been added. [lit. <i>He turned</i> his <i>tail upon the fifty,</i>] means (tropical:) <i>he passed the</i> [<i>age of</i>] <i>fifty</i> [<i>years</i>]: (M, TA:) and so <span class=\"ar\">وَلَتْهُ الخَمْسُونَ ذَنَبَهَا</span> [lit. <i>the fifty turned their tail upon him</i>]: (A, TA:) the former accord. to Yaakoob: accord. to IAar, El-Kilábee, being asked his age, said, <span class=\"ar\">قَدْ وَلَّتْ لِىَ الخَمْسُونَ ذَنَبَهَا</span> [lit. <i>The fifty have turned their tail to me</i>]. (M, TA.) -b8- <span class=\"ar\">اِتَّبَعَ ذَنَبَ</span> <span class=\"ar\">أَمْرٍ مُدْبِرٍ</span> [lit. <i>He followed the tail of an event retreating,</i>] means (tropical:) <i>he regretted an event that had passed.</i> (T, A, * TA. *) -b9- [The <span class=\"ar\">ذَنَب</span> of a man is (assumed tropical:) The <i>part corresponding to the tail:</i> and hence,] <span class=\"ar\">رَجُلٌ وَقَاحُ الذَّنَبِ</span> (assumed tropical:) [<i>A man hard in the caudal extremity;</i>] meaning (assumed tropical:) <i>a man very patient in enduring riding.</i> (IAar, M, and K in art. <span class=\"ar\">وقح</span>.) -b10- [And of a garment, The <i>skirt:</i>] you say, <span class=\"ar\">تَعَلَّقْتُ بِأَذْنَابِهِ</span> (tropical:) [<i>I clung to his skirts</i>]. (A.) -b11- The <span class=\"ar\">ذَنَبَ</span> of a ship or boat is (assumed tropical:) The <i>rudder.</i> (Lth and S * and L in art. <span class=\"ar\">سكن</span>. [See also <span class=\"ar\">خَيْزُرَانٌ</span>.]) -b12- <span class=\"ar\">ذَنَبٌ</span> also signifies [(assumed tropical:) <i>Anything resembling a tail.</i> -b13- Hence,] (assumed tropical:) The <i>extremity</i> of a whip. (Mgh, Msb.) -b14- And, of an unripe date, (M, Mgh,) and of any date, (M,) (assumed tropical:) The <i>kinder part;</i> (M;) the <i>part next the base and stalk.</i> (Mgh.) -b15- (tropical:) And (tropical:) The <i>outer extremity</i> of the eye, <i>next the temple;</i> as also <span class=\"ar\"> <span class=\"ar\">ذِنَابٌ</span></span> and <span class=\"ar\"> <span class=\"ar\">ذِنَابَةٌ</span></span> (M, A) and <span class=\"ar\"> <span class=\"ar\">ذُنَابَةٌ</span></span> (A) [and <span class=\"ar\"> <span class=\"ar\">ذُنَابَى</span></span>, as used in the K voce <span class=\"ar\">اِزْدَجَّ</span>, in art. <span class=\"ar\">زج</span>]. -b16- See also <span class=\"ar\">ذَنُوبٌ</span>, third sentence. -b17- Also (assumed tropical:) The <i>end;</i> or <i>last,</i> or <i>latter, part;</i> of anything: pl. <span class=\"ar\">ذِنَابٌ</span> (T) [and <span class=\"ar\">أَذْنَابٌ</span>]: and <span class=\"ar\"> <span class=\"ar\">ذِنَابٌ</span></span> [as a sing.], (K,) or <span class=\"ar\"> <span class=\"ar\">ذُنَابٌ</span></span>, (so in the TT as from the M,) has this meaning. (M, K.) You say, <span class=\"ar\">كَانَ ذٰلِكَ فِى ذَنَبِ الدَّهْرِ</span> (assumed tropical:) <i>That was in the end of the time</i> [<i>past</i>]. (M.) And <span class=\"ar\">ذَنَبُ الوَادِى</span> and <span class=\"ar\"> <span class=\"ar\">الذُنَابَةُ</span></span>: both signify the same [i. e. (assumed tropical:) <i>The end of the valley</i>]: (A 'Obeyd, M, TA:) or <span class=\"ar\"> <span class=\"ar\">ذُنَابَةٌ</span></span> and <span class=\"ar\"> <span class=\"ar\">ذِنَابَةٌ</span></span> and <span class=\"ar\"> <span class=\"ar\">ذَنَبَةٌ</span></span> signify the (tropical:) <i>last,</i> or <i>latter, parts,</i> (K, TA,) in some copies of the K, the <i>last,</i> or <i>latter, part,</i> (TA, [and so in the TT as from the M, and this meaning seems to be indicated in the A,]) of a valley, (A, K, TA,) and of a river, (A, TA,) and of time; (K, TA;) [and <span class=\"ar\"> <span class=\"ar\">ذِنَابٌ</span></span> app. has the former of these two significations in relation to a valley, accord. to Az; for he says,] it seems that <span class=\"ar\">ذِنَابٌ</span> and <span class=\"ar\"> <span class=\"ar\">ذِنَابَةٌ</span></span> in relation to a valley are pls. of <span class=\"ar\">ذَنَبٌ</span>, like as <span class=\"ar\">جِمَالٌ</span> and <span class=\"ar\">جِمَالَةٌ</span> are pls. of <span class=\"ar\">جَمَلٌ</span>: (T:) or <span class=\"ar\"> <span class=\"ar\">ذِنَابَةٌ</span></span> and <span class=\"ar\"> <span class=\"ar\">ذَنَبَةٌ</span></span>, (S, Msb,) the former of which is more common than the latter, (Th, S, Msb,) signify (assumed tropical:) the <i>place to which finally comes the torrent</i> of a valley: (S, Msb:) the pl. of <span class=\"ar\"> <span class=\"ar\">ذِنَابَةٌ</span></span> is <span class=\"ar\">ذَنَائِبُ</span>: (T:) the <span class=\"ar\">ذَنَب</span> of a valley and its <span class=\"ar\"> <span class=\"ar\">مِذْنَبَ</span></span> are the same; [i. e. (assumed tropical:) the <i>lowest,</i> or <i>lower, part</i> thereof;] (T;) [for the pls.] <span class=\"ar\">أَذْنَابٌ</span> (T, TA) and <span class=\"ar\">مَذَانِبُ</span> (TA) signify (assumed tropical:) the <i>lowest,</i> or <i>lower, parts</i> of valleys: (T, TA:) and <span class=\"ar\">أَذْنَابٌ</span> signifies [in like manner] (assumed tropical:) the <i>last,</i> or <i>latter, parts,</i> of [water-courses such as are termed] <span class=\"ar\">تِلَاع</span>. (T, TA. See also <span class=\"ar\">مِذْنَبٌ</span>.) It is said in a trad, <span class=\"ar\">لَا يَمْنَعُ فُلَانٌ ذَنَبَ تَلْعَةٍ</span> [(assumed tropical:) <i>Such a one will not impede the last part of a water-course</i>]; applied to the abject, weak, and contemptible. (T.) And <span class=\"ar\">أَذْنَابُ أُمُورٍ</span> means (tropical:) <i>The last,</i> or <i>latter, parts of affairs</i> or <i>events.</i> (M.) You say also, <span class=\"ar\">حَدِيثٌ طَوِيلُ الذَّنَبِ</span> (tropical:) [<i>A long-tailed story;</i>] <i>a</i> <i>story that hardly,</i> or <i>never, comes to an end.</i> (M.) And <span class=\"ar\">يَوْمٌ طَوِيلُ الذَّنَبِ</span> (assumed tropical:) <i>A day of which the evil does not come to an end:</i> (TA:) and <span class=\"ar\">يَوْمٌ <span class=\"ar\">ذَنُوبٌ</span></span> has this meaning; (T, M, TA;) as though it were long in the tail; (M;) or means (assumed tropical:) <i>a day of long-continued evil.</i> (K.) And <span class=\"ar\">اِتَّبَعَ <span class=\"ar\">ذِنَابَةَ</span> القَوْمِ</span>, and <span class=\"ar\">الإِبِلِ</span>, (tropical:) <i>He followed</i> [<i>the last of</i>] <i>the people,</i> and <i>the camels, not quitting their track.</i> (A.) -b18- Also (tropical:) The <i>followers,</i> or <i>dependants,</i> of a man: (T, TA:) and <span class=\"ar\"> <span class=\"ar\">ذَانِبٌ</span></span> and <span class=\"ar\"> <span class=\"ar\">ذُنَابَةٌ</span></span> (assumed tropical:) <i>a</i> [<i>single</i>] <i>follower,</i> or <i>dependant:</i> (S, K:) and <span class=\"ar\">أَذْنَابٌ</span> (M, A, K) and <span class=\"ar\"> <span class=\"ar\">ذُنَابَى</span></span> (S) and <span class=\"ar\">دَنَائِبُ</span> [pl. of <span class=\"ar\"> <span class=\"ar\">ذُنَابَةٌ</span></span>] (A) and <span class=\"ar\"> <span class=\"ar\">ذُنُبَاتٌ</span></span>, (so in the TT as from the M,) or <span class=\"ar\"> <span class=\"ar\">ذَنَبَاتٌ</span></span>, (K,) but some state that this last is not said of men, (Ham p. 249,) (tropical:) <i>followers,</i> or <i>dependants,</i> (S, M, A, K,) of a people or party; (M, K;) and the <i>lower,</i> or <i>lowest, sort,</i> or the <i>rabble,</i> or <i>refuse,</i> thereof; (M, A, K;) and <i>such as are below the chiefs.</i> (TA.) <span class=\"ar\">ضَرَبَ</span> <span class=\"ar\">يَعْسُوبُ الدِّينِ بِذَنَبِهِ</span>, in a trad. of 'Alee, means, [accord. to some, (assumed tropical:) <i>The leader of the religion</i>] <i>shall go away through the land with followers,</i> or <i>dependants,</i> (T, * TA,) <i>and those holding his opinions.</i> (T. [But see arts. <span class=\"ar\">ضرب</span> and <span class=\"ar\">عسب</span>.]) And <span class=\"ar\">عُقَيْلٌ طَوِيلَةٌ الذَّنَبِ</span>, a phrase mentioned by IAar, but not explained by him, app. means (assumed tropical:) [The tribe of] '<i>Okeyl have numerous horsemen.</i> (M.) -b19- [Also <span class=\"ar\">ذَنَبٌ</span> (as will be shown by the use of its pl. in the verse here following) and] <span class=\"ar\"> <span class=\"ar\">ذِنَابٌ</span></span>, (S, K, TA,) or <span class=\"ar\"> <span class=\"ar\">ذُنَابٌ</span></span>, (so in the TT as from the M,) (assumed tropical:) The <i>sequel, consequence,</i> or <i>result,</i> syn. <span class=\"ar\">عَقِبٌ</span>, of anything. (S, M, K.) A poet says, <span class=\"ar\">تَعَلَّقْتَ مِنْ أَذْنَابِ لَوٍّ بَلَيْتَنِى</span> <span class=\"ar\">وَلَيْتَ كَلَوٍّ خَيْبَةٌ لَيْسَ يَنْفَعُ</span> [<i>From</i> considering what might be <i>the sequels of</i> “ <i>if,</i> ” (i. e. <i>of the word</i> <span class=\"ar\">لَوْ</span>,) <i>Thou clungest to</i> the reflection “ <i>Would that I</i> had done so and so: ” <i>but</i> “ <i>would that,</i> ” <i>like</i> “ <i>if,</i> ” <i>is disappointment: it does not profit</i>]. (TA.) And one says, <span class=\"ar\">مَنْ لَكَ <span class=\"ar\">بِذِنَابِ</span> لَوٍّ</span> i. e. [<i>Who will be responsible to thee for</i>] <i>the sequel</i> [<i>of the word</i> <span class=\"ar\">لَوْ</span>]? (TA:) [or, as in the Proverbs of El-Meydánee, <span class=\"ar\"> <span class=\"ar\">بِذُنَابَةِ</span>لَوٍّ</span>, which means the same.] -b20- <span class=\"ar\">ذَنَبُ السِّرْحَانِ</span>: see art. <span class=\"ar\">سرح</span>. -b21- <span class=\"ar\">ذَنَبُ الفَرَسِ</span> (assumed tropical:) <i>A certain asterism</i> (<span class=\"ar\">نَجْمٌ</span>, M, K, TA) <i>in the sky,</i> (TA,) <i>resembling the</i> <span class=\"ar\">ذَنَب</span> [or <i>tail</i>] <i>of the horse.</i> (M, K.) [<span class=\"ar\">الذَّنَبُ</span> is a name applied to each of several stars or asterisms: as (assumed tropical:) <i>The star a of Cygnus;</i> also called <span class=\"ar\">ذَنَبُ الدَّجَاجَةِ</span>, and <span class=\"ar\">الرِّدْفُ</span>: and (assumed tropical:) <i>The star beta of Leo;</i> also called <span class=\"ar\">ذَنَبُ الأَسَدِ</span>. And <span class=\"ar\">الرَّأْسُ وَالذَّنَبُ</span> signifies (assumed tropical:) <i>The two nodes</i> of a planet: see <span class=\"ar\">تِنِّينٌ</span>.] -b22- <span class=\"ar\">ذَنَبُ الخَيْلِ</span>, (K,) or <span class=\"ar\">أَذْنَابُ الخَيْلِ</span>, (M,) (assumed tropical:) <i>A certain herb,</i> (M, K,) <i>of which the expressed juice concretes:</i> so called by way of comparison [to horses' tails: the latter name is now applied to the <i>equisetum,</i> or <i>horse-tail</i>]. (M.) [Accord. to Forskål, (Flora Aegypt. Arab., p. cxii.,) the <i>Portulaca oleracea</i> (or <i>garden-purslane</i>) is called in some parts of El-Yemen <span class=\"ar\">ذَنَبُ الفَرَسِ</span>.] <span class=\"ar\">ذَنَبُ</span> <span class=\"ar\">الثَّعْلَبِ</span> (assumed tropical:) <i>A certain plant, resembling the</i> <span class=\"ar\">ذَنَب</span> [or <i>tail</i>] <i>of the fox;</i> (M, K;) a name applied by some of the Arabs <i>to the</i> <span class=\"ar\">ذَنَبَان</span> [q. v.] (T.) -b23- [<span class=\"ar\">ذَنَبُ السَّبُعِ</span> (assumed tropical:) <i>Cauda leonis,</i> i. e. <i>circium</i> (or <i>cirsium</i>): (Golius, from Diosc. iv. 119:) now applied to <i>the common creeping way-thistle.</i> -b24- <span class=\"ar\">ذَنَبُ الفَأْرَةِ</span> (assumed tropical:) <i>Cauda muris,</i> i. e. <i>plantago.</i> (Golius, from Ibn-Beytár.) -b25- <span class=\"ar\">ذَنَبَ الثَوْرِ</span> (assumed tropical:) <i>A species of aristida,</i> supposed by Forskål (Flora Aegypt. Arab. p. civ,) to be the <i>aristida adscensionis.</i> -b26- <span class=\"ar\">ذَنَبُ العَقْرَبِ</span> (assumed tropical:) <i>Scorpioides,</i> or <i>scorpion-grass:</i> so called in the present day.]</p><p><b class=\"ar\">ذَنَبَةٌ</b> , and its pl. <span class=\"ar\">ذَنَبَاتٌ</span>: see the next preceding paragraph, in three places.</p><p><b class=\"ar\">ذُنُبَاتٌ</b> : see <span class=\"ar\">ذَنَبٌ</span>, in the latter half of the paragraph.</p><p><b class=\"ar\">ذَنَبَانٌ</b> <i>A certain plant,</i> (T, S,) <i>well known, called by some of the Arabs</i> <span class=\"ar\">ذَنَبُ الثَّعْلَبِ</span>: (T:) <i>a certain plant having long branches, somewhat dust-coloured</i> (M, TA) <i>in its leaves, growing in plain,</i> or <i>soft, land, upon the ground, not rising high, approved as pasture,</i> (TA,) <i>and not growing except in fruitful years:</i> (M, TA:) or <i>a certain herb,</i> or <i>plant, like</i> <span class=\"ar\">ذُرَة</span> [or <i>millet</i>]; (K;) or <i>a certain herb having ears at its extremities like the ears of</i> <span class=\"ar\">ذُرَة</span>, (M, TA, *) <i>and having reeds,</i> (<span class=\"ar\">قصب</span> [i. e. <span class=\"ar\">قَصَب</span>], M,) or <i>twigs,</i> (<span class=\"ar\">قضب</span> [i. e. <span class=\"ar\">قُضُب</span>], TA,) <i>and leaves, growing in every place except in unmixed sand,</i> [for <span class=\"ar\">حُرَّ الرَّمْلِ</span> in the TA, I find in the M <span class=\"ar\">حَوَّ الرُملِ</span>,] <i>and growing upon one stem and two stems:</i> (M, TA:) or, accord. to AHn, <i>a certain herb, having a</i> <span class=\"ar\">جزرة</span> [app. meaning <i>rhizoma like the carrot</i>], <i>which is not eaten, and twigs bearing a fruit from the bottom thereof to the top thereof, having leaves like those of the</i> <span class=\"ar\">طُرْخُون</span>, <i>agreeing well with the pasturing cattle, and having a small dust-coloured blossom upon which bees feed;</i> (M, TA;) <i>rising about the height of a man,</i> (TA,) or <i>half the height of a man;</i> (M;) <i>two whereof suffice to satiate a camel:</i> (M, TA:) [a coll. gen. n.:] n. un. with <span class=\"ar\">ة</span>. (M, K.)</p><p><b class=\"ar\">ذُنُبَّى</b> and <span class=\"ar\">ذِنِبَّى</span>: see <span class=\"ar\">ذَنَبٌ</span>, first sentence.</p><p><b class=\"ar\">ذُنَابٌ</b> : see <span class=\"ar\">ذَنَبٌ</span>, in two places.</p><p><b class=\"ar\">ذِنَابٌ</b> : see <span class=\"ar\">ذَنَبٌ</span>, in five places: -b2- and see also <span class=\"ar\">مِذْنَبٌ</span>. -b3- Also <i>A small cord with which a camel's tail is tied to his hind girth, lest he should swing about his tail and so dirt his rider.</i> (M, K.)</p><p><b class=\"ar\">ذَنُوبٌ</b> A horse (T, S, &amp;c.) <i>having a long tail:</i> (T, S:) or <i>having a full,</i> or <i>an ample, tail.</i> (M, A, K.) [See also <span class=\"ar\">أَذْنَبٌ</span>.] -b2- Hence applied to a day: see <span class=\"ar\">ذَنَبٌ</span>, in the latter half of the paragraph. -b3- Also <i>A great</i> <span class=\"ar\">دَلْو</span> [or <i>bucket</i>]: (Fr, T, Msb:) or <i>one that has a</i> <span class=\"ar\"> <span class=\"ar\">ذَنَب</span></span> [or <i>tail</i>]: (TA:) or <i>one that is full</i> (S, M, Msb, K) <i>of water;</i> (S, Msb;) not applied to one that is empty: (S, TA:) or <i>one that is nearly full of water:</i> (ISk, S:) or <i>one containing less than fills it:</i> or <i>one containing water:</i> or a <span class=\"ar\">دَلْو</span> (M, K) in any case: (M:) or <i>a bucketful of water:</i> (A:) masc. and fem.; (Fr, Lh, T, S, M, Msb;) sometimes the latter: (Lh, M:) pl. (of pauc., S) <span class=\"ar\">أَذْنِبَةٌ</span> and (of mult., S) <span class=\"ar\">ذَنَائِبُ</span> (S, M, K) and <span class=\"ar\">ذِنَابٌ</span>. (M, A, * Msb, K.) Fr. cites as an ex., <span class=\"ar\">لَنَا ذَنُوبٌ وَلَكُمْ ذَنُوبُ</span> <span class=\"ar\">فَإِنْ أَبَيْتُمْ فَلَنَا القَلِيبُ</span> [as meaning <i>For you</i> shall be <i>a great bucket, and for us a great bucket: or, if ye refuse</i> this, <i>for us</i> shall be <i>the well</i>]. (T.) [Accord. to the K, it also signifies <i>A grave:</i> but this is evidently a mistake, which seems to have arisen from a misunderstanding of a statement by ISd, who says,] Aboo-Dhu-eyb uses it metaphorically in relation to a grave, calling it [i. e. the grave] a well, in his saying, <span class=\"ar\">فَكُنْتُ ذَنُوبَ البِئْرَ لَمَّا تَبَسَّلَتْ</span> <span class=\"ar\">وَسُرْبِلْتُ أَكْفَانِى وَوُسِّدْتُ سَاعِدِى</span> [app. meaning (tropical:) <i>And I was</i> as though I were <i>the corpse of the grave</i> (lit. <i>the bucket of the well</i>) <i>when she frowned, and clad with my grave-clothes, and made to recline upon my upper arm:</i> for the corpse is laid in the grave upon its right side, or so inclined that the face is turned towards Mekkeh]. (M.) [And Umeiyeh Ibn-Abee- 'Áïdh El-Hudhalee, describing a wild he-ass and she-asses, likens to it a certain rate of running which he contrasts with another rate likened by him to a well such as is termed <span class=\"ar\">خَسِيفٌ</span>: see Kosegarten's “ Carmina Hudsailitarum, ” p. 189.] -b4- Hence metaphorically applied to (tropical:) <i>Rain.</i> (Ham p. 410.) -b5- [Hence, also,] (tropical:) <i>A lot, share,</i> or <i>portion:</i> (Fr, T, S, M, A, Msb, K:) [see the former of the two verses cited in this paragraph:] in this sense masc.: (Msb:) and in this sense it is used in the Kur li. last verse but one. (Fr, T, M.) -A2- Also (tropical:) The <i>flesh of the</i> [<i>portion of the back next the back-bone, on either side, which is called the</i>] <span class=\"ar\">مَتْن</span>: (M, K:) or the <i>part where the <span class=\"ar\">مَتْن</span> ends;</i> (M;) the <i>flesh of the lower,</i> or <i>lowest, part of the</i> <span class=\"ar\">مَتْن</span>: (S:) or the [<i>buttocks,</i> or <i>parts called</i>] <span class=\"ar\">أَلْيَة</span> <i>and</i> <span class=\"ar\">مَأْكِم</span>: (M, K:) or the <i>flesh of the</i> <span class=\"ar\">أَلْيَة</span> <i>and</i> <span class=\"ar\">مَآكِم</span>: (CK:) and the <span class=\"ar\">ذَنُوبَانِ</span> are the [<i>two parts called the</i>] <span class=\"ar\">مَتْنَانِ</span>, (M, K,) <i>on this side and on that</i> [<i>of the back-bone</i>]: (M:) or <span class=\"ar\">ذَنُوبُ المَتْنِ</span> means <i>the flesh that is called</i> <span class=\"ar\">يَرَابِيعُ</span> <span class=\"ar\">المَتْنِ</span> [which are <i>the portions of flesh next the back-bone, on either side thereof</i>]. (A.)</p><p><b class=\"ar\">ذُنَيْبٌ</b> [dim. of <span class=\"ar\">ذَنَبٌ</span>: -A2- and] <i>i. q.</i> <span class=\"ar\">ذُنَيْبِىٌّ</span>, q. v. (TA.)</p><p><b class=\"ar\">دُنَابَةٌ</b> The <span class=\"ar\">أَلْف</span> [i. e. <i>toe,</i> or <i>foremost extremity,</i> also called the <span class=\"ar\">أَسَلَة</span>,] of a sandal. (K.) -b2- See also <span class=\"ar\">ذَنَبٌ</span>, in six places. -b3- And see <span class=\"ar\">مِذْنَبٌ</span>.</p><p><b class=\"ar\">ذِنَابَةٌ</b> : see <span class=\"ar\">ذَنَبٌ</span>, in six places: -b2- and see <span class=\"ar\">مِذْنَبٌ</span>, in two places. -b3- <span class=\"ar\">ذِنَابَةٌ الطَّرِيقِ</span> (assumed tropical:) <i>The point,</i> or <i>place, to which the way,</i> or <i>road, leads;</i> syn. <span class=\"ar\">وَجْهُهُ</span>. (IAar, M, K.) So in the saying of Abu-l-Jarráh, to a certain man, <span class=\"ar\">إِنَّكَ لَمْ تَرْشَدْ ذِنَابَةَ الطَّرِيقِ</span> [(assumed tropical:) <i>Verily thou didst not follow a right course in</i> <i>respect of the point,</i> or <i>place, to which the way</i> that thou tookest <i>leads</i>]. (IAar, M.) -A2- Also (assumed tropical:) <i>Relationship; nearness with respect to kindred;</i> or <i>near relationship.</i> (K.)</p><p><b class=\"ar\">ذُنَابَى</b> : see <span class=\"ar\">ذَنَبٌ</span>, in three places. -b2- It is also applied to <i>Four</i> [<i>feathers</i>] <i>in the wing of a bird, after what are called</i> <span class=\"ar\">الخَوَفِى</span>. (S.) -b3- It is said in a trad., <span class=\"ar\">مَنْ مَاتَ عَلَى ذُنَابَى طَرِيقٍ فَهُوَ مِنْ أَهْلِهِ</span>, meaning [(assumed tropical:) <i>Whosoever dies</i>] <i>purposing to pursue a way leading to some particular end,</i> [<i>he is</i> to be reckoned as one <i>of the people thereof.</i>] (TA.) -A2- Accord. to Fr and the S, it signifies also <i>A fluid like mucus that falls from the noses of camels:</i> but this is a mistake: the right word, as stated by IB and others, is <span class=\"ar\">ذُنَانَى</span>. (L, MF, TA.)</p><p><b class=\"ar\">ذُنَيْبَآءُ</b> <i>A certain grain that is found in wheat, whereof the latter is cleared</i> [<i>by winnowing or other means</i>]. (M, K.) [See also <span class=\"ar\">ذُنَيْنَآءُ</span>, in art. <span class=\"ar\">ذن</span>.]</p><p><b class=\"ar\">ذُنَيْبِىٌّ</b> (assumed tropical:) <i>A certain kind of</i> [<i>the striped garments called</i>] <span class=\"ar\">بُرُود</span> [pl. of <span class=\"ar\">بُرْدٌ</span>]; (AHeyth, K;) as also <span class=\"ar\"> <span class=\"ar\">ذُنَيْبٌ</span></span>. (TA.)</p><p><b class=\"ar\">ذَانِبٌ</b> (tropical:) <i>Following in the track</i> of a thing. (TA.) See also <span class=\"ar\">ذَنَبٌ</span>, in the latter half of the paragraph.</p><p><b class=\"ar\">أَذْنَبُ</b> A [lizard of the kind called] <span class=\"ar\">ضَبّ</span> <i>having a long tail.</i> (T, L.) [See also <span class=\"ar\">ذَنُوبٌ</span>.]</p><p><b class=\"ar\">تَذْنُوبٌ</b> and <span class=\"ar\">تُذْنُوبٌ</span>, and with <span class=\"ar\">ة</span>: see 2.</p><p><b class=\"ar\">مَذْنَبٌ</b> : see the next paragraph.</p><p><b class=\"ar\">مِذْنَبٌ</b> <i>A long tail.</i> (IAar, T, K.) -b2- And [hence, app. for <span class=\"ar\">ذُو مِذْنَبٍ</span>], (T,) or <span class=\"ar\"> <span class=\"ar\">مُذَنِّبٌ</span></span>, (TA, [but see this latter below,]) <i>A</i> [<i>lizard of the kind called</i>] <span class=\"ar\">ضَبّ</span>. (T, TA.) -b3- Also, (S, K,) or <span class=\"ar\"> <span class=\"ar\">مَذْنَبٌ</span></span>, like <span class=\"ar\">مَقْعَدٌ</span>, (A,) and <span class=\"ar\"> <span class=\"ar\">مِذْنَبَةٌ</span></span>, (M, TA,) (assumed tropical:) <i>A ladle;</i> (S, M, A, K;) because it has a tail, or what resembles a tail: (M:) pl. <span class=\"ar\">مَذَانِبُ</span>. (S, M.) -b4- And (assumed tropical:) <i>A water-course,</i> or <i>channel of a torrent, in a tract at the foot of a mountain;</i> (Lth, T, S, M, A, K;) <i>not wide;</i> (A;) or <i>not very wide;</i> (M;) or <i>not very long and wide;</i> (Lth, T;) as also <span class=\"ar\"> <span class=\"ar\">ذِنَابَةٌ</span></span>: (S:) the <span class=\"ar\">تَلْعَة</span> is in the lower part of a mountain (Lth, T, A) or in an acclivity: (Lth, T, S, A:) also <i>a water-course</i> or <i>channel of a torrent, between what are termed</i> <span class=\"ar\">تَلْعَتَانِ</span>; (TA; [see <span class=\"ar\">تَلْعَةٌ</span>, and see also <span class=\"ar\">مَدْفَعٌ</span>;]) or this is termed <span class=\"ar\"> <span class=\"ar\">ذَنَبُ</span>تَلْعَة</span>; (T;) or it is termed <span class=\"ar\"> <span class=\"ar\">ذِنَابٌ</span></span>, of which the pl. is <span class=\"ar\">ذَنَائِبُ</span>: (M, K:) also <i>a water-course,</i> or <i>channel of a torrent,</i> [<i>running</i>] <i>to a tract of land:</i> (M, K:) and <i>a rivulet,</i> or <i>streamlet,</i> (K,) or the <i>like thereof,</i> (AHn, T, M,) <i>flowing from one</i> <span class=\"ar\">رَوْضَة</span> [or <i>meadow</i>] <i>to another,</i> (AHn, T, M, K,) and separating <i>therein;</i> (T;) as also <span class=\"ar\"> <span class=\"ar\">ذُنَابَةٌ</span></span> and <span class=\"ar\"> <span class=\"ar\">ذِنَابَةٌ</span></span>; (K;) and the <i>tract over which this flows</i> is also called <span class=\"ar\">مِذْنَبٌ</span>. (T.) See also <span class=\"ar\">ذَنَبٌ</span>, in the middle of the paragraph.</p><p><b class=\"ar\">مِذْنَبَةٌ</b> : see the next preceding paragraph.</p><p><b class=\"ar\">مُذَنِّبٌ</b> [app. applied to a she-camel, accord. to the K, or perhaps to a lizard of the kind called <span class=\"ar\">ضَبّ</span>, as seems to be indicated in the TA,] <i>Finding difficulty in parturition, and therefore stretching out her tail:</i> (K:) [but accord. to Az,] it is applied to a <span class=\"ar\">ضَبّ</span> only when he is <i>striking with his tail a hunter or a serpent desiring to catch him.</i> (T.) See also <span class=\"ar\">مِذْنَبٌ</span>. -b2- See also 2, in two places.</p><p><b class=\"ar\">مَذْنُوبٌ</b> (tropical:) A man <i>followed</i> [<i>by dependants</i>]. (A.)</p><p><b class=\"ar\">مُذَانِبٌ</b> A camel <i>that is at the rear of other camels;</i> (K;) as also <span class=\"ar\"> <span class=\"ar\">مُسْتَذْنِبٌ</span></span>. (TA.) -b2- See also 3.</p><p><b class=\"ar\">سَحَابٌ مُتَذَانِبٌ</b> (tropical:) <i>Clouds following one another.</i> (A.)</p><p><b class=\"ar\">مُسْتَذْنِبٌ</b> : see <span class=\"ar\">مُذَانِبٌ</span>. -b2- Also One <i>who is at the tails of camels,</i> (S, TA,) <i>not quitting their track.</i> (TA.)</p>"},"ذوق":{"mf":"الذّوق: وجود الطعم بالفم، وأصله فيما يقلّ تناوله دون ما يكثر، فإنّ ما يكثر منه يقال له:<br>الأكل، واختير في القرآن لفظ الذّوق في العذاب، لأنّ ذلك- وإن كان في التّعارف للقليل- فهو مستصلح للكثير، فخصّه بالذّكر ليعمّ الأمرين، وكثر استعماله في العذاب، نحو:<br>لِيَذُوقُوا الْعَذابَ<br>[النساء/ ٥٦]، وَقِيلَ لَهُمْ ذُوقُوا عَذابَ النَّارِ<br>[السجدة/ ٢٠]، فَذُوقُوا الْعَذابَ بِما كُنْتُمْ تَكْفُرُونَ [الأنفال/ ٣٥]، ذُقْ إِنَّكَ أَنْتَ الْعَزِيزُ الْكَرِيمُ<br>[الدخان/ ٤٩]، إِنَّكُمْ لَذائِقُوا الْعَذابِ الْأَلِيمِ<br>[الصافات/ ٣٨]، ذلِكُمْ فَذُوقُوهُ [الأنفال/ ١٤]، وَلَنُذِيقَنَّهُمْ مِنَ الْعَذابِ الْأَدْنى دُونَ الْعَذابِ الْأَكْبَرِ<br>[السجدة/ ٢١]، وقد جاء في الرّحمة نحو: وَلَئِنْ أَذَقْنَا الْإِنْسانَ مِنَّا رَحْمَةً<br>[هود/ ٩]، وَلَئِنْ أَذَقْناهُ نَعْماءَ بَعْدَ ضَرَّاءَ مَسَّتْهُ [هود/ ١٠]، ويعبّر به عن الاختبار، فيقال: أَذَقْتُهُ كذا فذاق، ويقال: فلان ذاق كذا، وأنا أكلته <strong>«١»</strong>، أي: خبرته فوق ما خبر، وقوله: فَأَذاقَهَا اللَّهُ لِباسَ الْجُوعِ وَالْخَوْفِ<br>[النحل/ ١١٢]، فاستعمال الذّوق مع اللّباس<br><br>من أجل أنه أريد به التّجربة والاختبار، أي:<br><strong>فجعلها بحيث تمارس الجوع والخوف، وقيل:</strong><br>إنّ ذلك على تقدير كلامين، كأنه قيل: أذاقها طعم الجوع والخوف، وألبسها لباسهما. وقوله:<br>وَإِنَّا إِذا أَذَقْنَا الْإِنْسانَ مِنَّا رَحْمَةً<br>[الشورى/ ٤٨]، فإنه استعمل في الرّحمة الإذاقة، وفي مقابلتها الإصابة، فقال: وَإِنْ تُصِبْهُمْ سَيِّئَةٌ [الشورى/ ٤٨]، تنبيها على أنّ الإنسان بأدنى ما يعطى من النّعمة يأشر ويبطر، إشارة إلى قوله:<br>كَلَّا إِنَّ الْإِنْسانَ لَيَطْغى أَنْ رَآهُ اسْتَغْنى [العلق/ ٦- ٧].","mq":[["اختبار الشي من جهة تطعم، ثم يشتق منه مجازا فيقال: ذقت الماكول اذوقه ذوقا"],"الذال والواو والقاف أصلٌ واحد، وهو اختبار الشئ من جِهَةِ تَطَعُّمٍ، ثم يشتق منه مجازاً فيقال: ذُقْت المأكولَ أذُوقه ذَوْقاً. وذُقْت ما عند فلانٍ: اختبرتُه. وفى كتاب الخليل: كلُّ ما نزَلَ بإنسانٍ مِنْ مكروه فقد ذَاقَه (٣)<br>. ويقال ذاقَ القوسَ، إذا نظَرَ ما مقدارُ إعطائها وكيف قُوّتُها. قال:<br>فذَاق فأعط"],"ln":"<p><b>1.</b> <b class=\"ar\">ذَاقَهُ</b> , (K,) first pers. <span class=\"ar\">ذُقْتُهُ</span>, aor. <span class=\"ar\">أَذُوقْهُ</span>, (S, Msb,) inf. n. <span class=\"ar\">ذَوْقٌ</span> and <span class=\"ar\">ذَوَاقٌ</span> and <span class=\"ar\">مَذَاقٌ</span> (S, Msb, K) and <span class=\"ar\">مَذَاقَةٌ</span>, (S, K,) <i>He tasted it;</i> i. e., <i>perceived its taste, by means of the moisture of the tongue:</i> (Msb:) or <i>he tried,</i> or <i>knew, its taste:</i> (K:) it is originally said of that of which little is taken: when much is taken, the term <span class=\"ar\">أَكْلٌ</span> is used [and one says <span class=\"ar\">أَكَلَهُ</span>]: and <span class=\"ar\"> <span class=\"ar\">تذاوقهُ</span></span> signifies the same as <span class=\"ar\">ذَاقَهُ</span>. (TA.) You say, <span class=\"ar\">ذُقْتُ الشَّىْءَ</span> [<i>I tasted the thing</i>], (S,) or <span class=\"ar\">الطَّعَامَ</span> [<i>the food</i>]. (Msb.) And <span class=\"ar\">يَوْمٌ مَا ذُقْتُهُ طَعَامًا</span>, meaning <span class=\"ar\">مَا ذُقْتُ فِيهِ</span> [i. e. <i>A day in which I tasted not food</i>]. (TA.) -b2- By amplification, <span class=\"ar\">الذَّوْقُ</span> is used to signify (assumed tropical:) <i>The perceiving,</i> beside tastes, all other objects of the senses, and states or conditions: (Bd in iii. 177:) it is not restricted to the sense of the mouth [or tongue] in the language of the Kur-án nor in the [genuine or classical] language of the [Pagan] Arabs. (TA.) Hence, in the Kur iii. 177, <span class=\"ar\">ذُوقُوا عَذَابَ الحَرِيقِ</span> (assumed tropical:) [<i>Taste ye the punishment of burning</i>]: (Bd, TA:) for, although, in the common conventional acceptation, the verb relates to what is little in quantity, it is regarded as suitable to be used in relation to what is much. (TA.) One says also, <span class=\"ar\">فُلَانٌ ذَاقَ كَذَا وَأَنَا أَكَلْتُهُ</span> [lit. <i>Such a one tasted such a thing, and I ate it;</i>] meaning (assumed tropical:) <i>such a one knew,</i> or <i>tried</i> or <i>tested, such a thing, and I knew it,</i> or <i>tried it</i> or <i>tested it, more.</i> (TA.) <span class=\"ar\">ذُقْتُ الشَّىْءَ</span> means (assumed tropical:) <i>I tried,</i> or <i>tested, the thing.</i> (Msb.) And hence one says, <span class=\"ar\">ذاق فُلَانٌ البَأْسَ</span> (assumed tropical:) <i>Such a one experienced harm,</i> &amp;c.; i. e., <i>knew it by its befalling him.</i> (Msb.) And <span class=\"ar\">ذُقْتُ مَا عِنْدَ فُلَانٍ</span> (assumed tropical:) <i>I knew,</i> or <i>tried</i> or <i>tested, what</i> [qualities &amp;c.] <i>such a one possessed;</i> (S, TA;) and so <span class=\"ar\">ذُقْتُ فُلَانًا</span>. (TA.) And <span class=\"ar\">ذَاقَ</span> <span class=\"ar\">الرَّجُلُ عُسَيْلَةَ المَرْأَةِ وَ ذَاقَتْ عُسَيْلَتَهُ</span> (assumed tropical:) <i>The man</i> [<i>tasted</i> or] <i>experienced the sweetness of the carnal enjoyment of the woman, and she</i> in like manner. (Msb.) And <span class=\"ar\">ذاق طَعْمَ الإِيمَانِ</span> (assumed tropical:) <i>He tasted,</i> or <i>experienced, the savour of faith with his heart,</i> like as the mouth tastes, or experiences, the savour of food and drink. (TA from a trad.) And <span class=\"ar\">ذُقْتُ كَذِبَهُ وَخَبَرْتُ حَالَهُ</span> (tropical:) [<i>I experienced his lying, and knew his condition</i>]. (TA.) And <span class=\"ar\">ذَاقَتْهَا يَدِى</span>, and <span class=\"ar\">ذَاقَتْ فُلَانَةَ</span>, (tropical:) <i>My hand felt her, and felt such a female.</i> (TA.) -b3- <span class=\"ar\">ذاق القَوْسَ</span>, (S, K,) inf. n. <span class=\"ar\">ذَوْقٌ</span>; (TA;) [and <span class=\"ar\"> <span class=\"ar\">ذَوَّقَهَا</span></span>; (so in Freytag's Lex. from the Deewán el-Hudhaleeyeen;)] (tropical:) <i>He pulled the string of the bow</i> (S, K, TA) <i>for the purpose of trial,</i> (K, TA,) <i>that he might see what was its strength.</i> (S, TA.) -b4- <span class=\"ar\"> <span class=\"ar\">الذَّوْقُ</span></span> is also employed to signify (assumed tropical:) [<i>Taste,</i> as meaning <i>intellectual discernment</i> and <i>relish;</i> i. e.] <i>the faculty that is adapted to the acquisition of matters of knowledge, considered as being, in its perfection of perception, like sensation, regarded as a natural property;</i> and particularly <i>that</i> [<i>faculty</i>] <i>which concerns the niceties of language;</i> because it [i. e. nice language] is, to the soul of man, like delicious intellectual food. (Kull. [When used as a subst in this sense, its pl. is <span class=\"ar\">أَذْوَاقٌ</span>.]) One says, <span class=\"ar\">هُوَحَسَنُ الذَّوْقِ لِلشِّعْرِ</span>, meaning (tropical:) <i>He has a good</i> [<i>taste</i> or] <i>natural faculty for poetry.</i> (TA.) -b5- [Also (assumed tropical:) <i>Voluptuousness; sensuality:</i> see <span class=\"ar\">ذَوَّاقٌ</span>.]</p><p><b>2.</b> <b class=\"ar\">ذوّقهُ</b> [<i>He gave him something to taste</i>]: it is like <span class=\"ar\">لَمَّجَهُ</span>. (M and TA in art. <span class=\"ar\">لمظ</span>.) -b2- See also 1, in the latter half of the paragraph.</p><p><b>4.</b> <b class=\"ar\">أَذَقْتُهُ الطَّعَامَ</b> , (Msb, K, *) inf. n. <span class=\"ar\">إِذَاقَةٌ</span>, (TA,) <i>I made him to taste the food;</i> i. e., <i>to perceive its taste by means of the moisture of the tongue:</i> (Msb:) or <i>I made him to try,</i> or <i>know, the taste</i> [<i>of the food</i>]. (K.) -b2- [Hence,] <span class=\"ar\">أَذَاقَهُ ٱللّٰهُ</span> <span class=\"ar\">وَبَالَ أَمْرِهِ</span> (assumed tropical:) [<i>God made him to taste,</i> or <i>experience, the evil result of his affair</i>]. (S.) It is said in the Kur [xvi. 113], <span class=\"ar\">فَأَذَاقَهَاٱللّٰهُ لِبَاسَ الجُوْعِ</span> <span class=\"ar\">وَالخَوْفِ</span> (assumed tropical:) [<i>So God made her to taste,</i> or <i>experience, the utmost degree of hunger and of fear</i>]: the verb is here used with <span class=\"ar\">لِبَاس</span> because meant to convey the meaning of experiencing: or the sentence is elliptical, and means, <i>made them to taste,</i> or <i>experience, hunger and fear, and clad them with the clothing thereof.</i> (TA.) And in the same [xlii. 47], <span class=\"ar\">إِذَا أَذَقْنَا الإِنْسَانُ مِنَّا رَحْمَةً</span> (assumed tropical:) [<i>When we make man to taste,</i> or <i>experience, mercy from us</i>]; where, afterwards, <span class=\"ar\">الإِصَابَةٌ</span> is opposed to <span class=\"ar\">الإِذَاقَةٌ</span>, in the words <span class=\"ar\">وَإِنْ تُصِبْهُمْ سَيِّئَةٌ</span>. (TA.) -b3- <span class=\"ar\">أَذَاقَ زَيْدٌ بَعْدَكَ كَرَمًا</span> means (tropical:) <i>Zeyd became generous</i> [<i>after thee,</i> i. e. <i>after thou knewest him,</i> or <i>sawest him,</i> or <i>wast with him</i>]: (Aboo-Hamzeh, K, TA:) [lit., <i>made</i> people <i>to taste generosity:</i>] and <span class=\"ar\">اذاق</span> <span class=\"ar\">الفَرَسُ بَعْدَكَ عَدْوًا</span> (tropical:) <i>The horse became a good runner</i> [<i>after thee,</i> i. e. <i>after thou knewest him,</i> &amp;c.] (Aboo-Hamzeh, TA.)</p><p><b>5.</b> <b class=\"ar\">تذوّقهُ</b> <i>He tasted it</i> (<span class=\"ar\">ذَاقَهُ</span>, S, K) <i>by degrees,</i> (S,) or <i>repeatedly.</i> (K.) -b2- [Hence,] <span class=\"ar\">دَعْنِى أَتَذَوَّقُ</span> <span class=\"ar\">طَعْمَ فُلَانٍ</span> (tropical:) [<i>Let me try,</i> or <i>test, the character of such a one</i>]. (TA.) And <span class=\"ar\">تَذَوَّقْتُ طَعْمَ فِرَاقِهِ</span> (tropical:) [<i>I tasted,</i> or <i>experienced, the savour of his separation</i>]. (TA.)</p><p><b>6.</b> <b class=\"ar\">تَذَاْوَقَ</b> see 1, first sentence. [The primary signification of <span class=\"ar\">تَذَاوُقٌ</span> seems to be The <i>tasting</i> a thing <i>one with another.</i> -b2- And hence,] <span class=\"ar\">تذاوقوا الرِّمَاحَ</span> <i>i. q.</i> <span class=\"ar\">تَنَاوَلُوهَا</span> (tropical:) [<i>They took the spears, one from another,</i> app. <i>to test their qualities:</i> see <span class=\"ar\">ذَاقَ القَوْسَ</span>, above]. (K, TA.) Ibn-Mukbil says, <span class=\"ar\">أَوْ كَٱهْتِزَازِ رُدَيْنِىٍّ تَذَاوَقَهُ</span> <span class=\"ar\">أَيْدِى التِجَارِ فَزَادُوا مَتْنَهُ لِينَا</span> (tropical:) [<i>Or like the quivering of a well-straightened spear</i> (lit. a <i>spear of Rudeyneh,</i> a woman famous for the straightening of spear-shafts, accord. to the explanation commonly received,) <i>which the hands of the dealers have taken, one from another, to test its quality, so that they have made the middle of it to increase in suppleness</i>]. (TA.)</p><p><b>10.</b> <b class=\"ar\">اِسْتَذَاقَ فُلَانًا خُبْرَهُ فَلَمْ يَحْمَدْ مَخْبَرَتَهُ</b> (tropical:) [app. <i>He endeavoured to test such a one,</i> to ascertain <i>the knowledge of his internal state, and did not approve his internal state:</i> see the pass, part. n. below]. (TA, in which <span class=\"ar\">خبره</span> is without any syllabical signs.) -b2- <span class=\"ar\">استذاق الأَمْرُ لِفُلَانٍ</span> (tropical:) <i>The</i> <i>affair was,</i> or <i>became, easy,</i> or <i>feasible, to such a one.</i> (JK, TA.) You say, <span class=\"ar\">لَا يَسْتَذِيقُ لِىَ الشِّعْرُ</span> <span class=\"ar\">إِلَّ فِى فُلَانِ</span> (tropical:) [<i>Poetry,</i> or <i>versification, will not be easy,</i> or <i>feasible, to me, except in relation to such a one</i>]. (TA.)</p><p><b class=\"ar\">ذَوْقٌ</b> an inf. n. used as a simple subst.; pl. <span class=\"ar\">أَذْوَاقٌ</span>: see 1, in the latter part of the paragraph.</p><p><b class=\"ar\">ذَوَاقٌ</b> an inf. n.: and also a subst. signifying <i>A thing that is tasted;</i> (JM, TA; *) of the measure <span class=\"ar\">فَعَالٌ</span> in the sense of the measure <span class=\"ar\">مَفْعُولٌ</span>. (TA.) It is said of Mohammad, <span class=\"ar\">لَمْ يَكُنْ يَذُمُّ ذَوَاقًا وَلَا</span> <span class=\"ar\">يَمْدَحُهُ</span>, i. e. [<i>He used not to praise</i>] <i>what was tasted</i> [by him <i>nor to dispraise it</i>]. (JM.) And one says, <span class=\"ar\">مَا ذُقْتُ ذَوَاقًا</span>, meaning <i>I tasted not anything.</i> (S, K. *) -b2- Hence it is said in a trad., <span class=\"ar\">كَانُوا إِذَا خَرَجُوا مِنْ عِنْدِهِ لَا يَتَفَرَّقُونَ إِلَّا عَنْ ذَوَاقٍ</span>, i. e. (assumed tropical:) [<i>They used, when they went forth from his</i> (Mohammad's) <i>presence, not to disperse themselves save after</i> receiving] <i>knowledge and discipline that were, to their minds and souls, as food and drink to their bodies.</i> (JM.)</p><p><b class=\"ar\">ذَوَّاقٌ</b> (assumed tropical:) <i>That contracts new marriages time after time:</i> (JM:) <i>quick in marrying and quick in divorcing:</i> (TA:) <i>that conceives frequent disgust</i> (<span class=\"ar\">مَلُولٌ</span>, S, JM, and Har p. 569), <i>not remaining</i> [<i>long</i>] <i>in one state with respect to marriage &amp;c.:</i> fem. with <span class=\"ar\">ة</span>. (Har ubi suprà.) Hence the saying, in a trad., <span class=\"ar\">إِنَّ ٱللّٰهَ لَا يُحِبُّ الذَّوَّاقِينَ وَلَا الذَّوَّقَاتِ</span> (assumed tropical:) [<i>Verily God will not love those men who frequently contract new marriages, nor those women who do so</i>]. (JM, and Har ubi suprà.)</p><p><b class=\"ar\">مَذَاقٌ</b> an inf. n.: and also a subst. (TA) signifying <i>A place,</i> or <i>time, of tasting.</i> (KL.)</p><p><b class=\"ar\">أَمْرٌ مُسْتَذَاقٌ</b> (assumed tropical:) <i>A thing,</i> or <i>an affair, tried,</i> or <i>tested, and known:</i> (S:) and in like manner <span class=\"ar\">رَجُلٌ</span> [<i>a man</i>]. (JK.)</p>"},"ذهب":{"mf":"الذَّهَبُ معروف، وربما قيل ذَهَبَةٌ، ورجل ذَهِبٌ: رأى معدن الذّهب فدهش، وشيء<br><br>مُذَهَّبٌ: جعل عليه الذّهب، وكميت مُذْهَبٌ:<br>علت حمرته صفرة، كأنّ عليها ذهبا، والذَّهَابُ:<br>المضيّ، يقال: ذَهَبَ بالشيء وأَذْهَبَهُ، ويستعمل ذلك في الأعيان والمعاني، قال الله تعالى:<br>وَقالَ إِنِّي ذاهِبٌ إِلى رَبِّي<br>[الصافات/ ٩٩]، فَلَمَّا ذَهَبَ عَنْ إِبْراهِيمَ الرَّوْعُ [هود/ ٧٤]، فَلا تَذْهَبْ نَفْسُكَ عَلَيْهِمْ حَسَراتٍ [فاطر/ ٨]، كناية عن الموت، وقال: إِنْ يَشَأْ يُذْهِبْكُمْ وَيَأْتِ بِخَلْقٍ جَدِيدٍ [إبراهيم/ ١٩]، وقال: وَقالُوا الْحَمْدُ لِلَّهِ الَّذِي أَذْهَبَ عَنَّا الْحَزَنَ [فاطر/ ٣٤]، وقال: إِنَّما يُرِيدُ اللَّهُ لِيُذْهِبَ عَنْكُمُ الرِّجْسَ أَهْلَ الْبَيْتِ [الأحزاب/ ٣٣]، وقوله تعالى: وَلا تَعْضُلُوهُنَّ لِتَذْهَبُوا بِبَعْضِ ما آتَيْتُمُوهُنَّ [النساء/ ١٩]، أي:<br>لتفوزوا بشيء من المهر، أو غير ذلك مما أعطيتموهنّ وقوله: وَلا تَنازَعُوا فَتَفْشَلُوا وَتَذْهَبَ رِيحُكُمْ [الأنفال/ ٤٦]، وقال: ذَهَبَ اللَّهُ بِنُورِهِمْ [البقرة/ ١٧]، وَلَوْ شاءَ اللَّهُ لَذَهَبَ بِسَمْعِهِمْ<br>[البقرة/ ٢٠]، لَيَقُولَنَّ: ذَهَبَ السَّيِّئاتُ عَنِّي [هود/ ١٠].","mq":[["حسن ونضارة"],"الذال والهاء والباء أصَيْلٌ يدلُّ على حُسْنٍ ونَضارة. من ذلك الذَّهبُ معروف، وقد يؤنَّث فيقال. ذَهَبة، ويجمع على الأذْهَاب (١)<br>.<br>والمَذَاهب: سُيُورٌ تُمَوَّهُ بالذّهَب، أو خِلَلٌ من سُيوف. وكلُّ شئِ مموَّهٍ بذَهَبٍ فهو مُذْهَبٌ. قال قيس:<br>أتعرِف رسماً كاطّرادِ المَذَاهِبِ … لعَمْرَة وَحْشاً غيرَ مَوْ"],"ln":"<p><b>1.</b> <b class=\"ar\">ذَهَبَ</b> , (S, A, &amp;c.,) aor. <b class=\"ar\">ذَهَبَ</b> , (A, K,) inf. n. <span class=\"ar\">ذَهَابٌ</span> (S, A, Msb, K) and <span class=\"ar\">ذِهَابٌ</span> (TA) and <span class=\"ar\">ذُهُوبٌ</span> (S, A, K) and <span class=\"ar\">مَذْهَبٌ</span>, (A, K,) <i>He</i> (a man, S, [and a beast,]) <i>went</i> [<i>in any manner,</i> or <i>any pace</i>]; <i>went,</i> or <i>passed, along; marched; journeyed; proceeded: went,</i> or <i>passed, away; departed:</i> syn. <span class=\"ar\">مَشَى</span>, (A,) or <span class=\"ar\">سَارَ</span>, (K,) or <span class=\"ar\">مَرّ</span>: (S, A, K:) and said of a mark or trace or the like [as meaning <i>it went away</i>]. (Msb.) [And hence, (assumed tropical:) <i>It wasted away; became consumed, destroyed, exhausted, spent,</i> or <i>expended.</i>] -b2- <span class=\"ar\">ذَهَبَ إِلَيْهِ</span> <i>He went, repaired, betook himself,</i> or <i>had recourse, to him,</i> or <i>it.</i> (TA.) And they say also, <span class=\"ar\">ذَهَبَ الشَّأْمَ</span> [<i>He went to Syria</i>]; making the verb trans. without a particle; for although <span class=\"ar\">الشأم</span> is here a special adv. n., they liken it to a vague locality. (TA.) -b3- <span class=\"ar\">ذَهَبَ عَنْهُ</span> <i>He,</i> or <i>it, went from, quitted, relinquished,</i> or <i>left, him,</i> or <i>it.</i> (TA.) -b4- <span class=\"ar\">ذَهَبَ فِىالأَرْضِ</span>, (A, Msb,) inf. n. <span class=\"ar\">ذَهَابٌ</span> and <span class=\"ar\">ذُهُوبٌ</span> and <span class=\"ar\">مَذْهَبٌ</span>, <i>He went away</i> [<i>into the country,</i> or <i>in the land</i>]: (Msb:) [but it often means (assumed tropical:) <i>he went into the open country,</i> or <i>out of doors, to satisfy a want of nature:</i> or simply] (tropical:) <i>he voided his excrement,</i> or <i>ordure.</i> (A.) -b5- <span class=\"ar\">ذَهَبَ بِهِ</span> <i>He went,</i> or <i>went away, with him,</i> or <i>it:</i> (A:) and <i>he made him,</i> or <i>it, to go, go away, pass away,</i> or <i>depart;</i> (A, Msb, K;) as also <span class=\"ar\"> <span class=\"ar\">اذهبهُ</span></span>, (S, A, Msb, K,) and <span class=\"ar\"> <span class=\"ar\">اذهب</span>بِهِ</span>, (K,) but this is rare; (Zj, TA;) and <span class=\"ar\"> <span class=\"ar\">ذهّبهُ</span></span>, inf. n. <span class=\"ar\">تَذْهِيبٌ</span>: (MF:) [all may likewise be rendered <i>he removed, dispelled, put away,</i> or <i>banished, it;</i> properly and tropically: and (assumed tropical:) <i>he made it to cease; made away with it, did away with it, made an end of it; wasted, consumed, destroyed, exhausted, spent,</i> or <i>expended, it;</i> and these meanings may perhaps be intended by <span class=\"ar\">أَزَالَهُ</span>, whereby the first is explained in the A and K, as are also the second and third in the K:] or, accord. to some, when <span class=\"ar\">ذَهَبَ</span> is trans. by means of <span class=\"ar\">بِ</span>, accompaniment is necessarily signified; but not otherwise; so that if you say <span class=\"ar\">ذَهَبَ بِهِ</span>, the meaning is, <i>he went away with him,</i> or <i>it;</i> i. e., <i>accompanying him,</i> or <i>it;</i> [<i>he took away,</i> or <i>carried off</i> or <i>away, him,</i> or <i>it;</i>] but if you say <span class=\"ar\"> <span class=\"ar\">اذهبهُ</span></span> or <span class=\"ar\"> <span class=\"ar\">ذهّبهُ</span></span>, the meaning is, <i>he made him,</i> or <i>it, to go, go away, pass away,</i> or <i>depart, alone, without accompanying him,</i> or <i>it:</i> this, however, is not agreeable with the phrase in the Kur [ii. 16], <span class=\"ar\">ذَهَبَ ٱللّٰهُ بِنُورِهِمْ</span> [though this may be well rendered <i>God taketh away their light</i>]. (MF, TA.) [Hence,] one says, <span class=\"ar\">أَيْنَ</span> <span class=\"ar\">يُذْهَبُ بِكَ</span>, which may mean (assumed tropical:) <i>Where,</i> or <i>whither, wilt thou be taken away, and what will be done with thee and made to come to pass with thee,</i> if this be thine intellect? or, accord. to Mtr, it is a saying of the people of Baghdád, addressed to him whom they charge with foolish judgment or opinion, as meaning <span class=\"ar\">أَيْنَ يُذْهَبُ بِعَقْلِكَ</span> (assumed tropical:) [<i>Where,</i> or <i>whither, is thine intellect taken away?</i>]. (Har p. 574.) [In like manner one says, <span class=\"ar\">ذَهَبَ عَقْلُهُ</span> (assumed tropical:) <i>His reason,</i> or <i>intellect, quitted him,</i> or <i>forsook him; he became bereft of his reason,</i> or <i>intellect.</i> And <span class=\"ar\">ذَهَبَ فُؤَادُهُ</span> (assumed tropical:) <i>His heart forsook him,</i> or <i>failed him,</i> by reason of fear or the like.] And <span class=\"ar\">ذَهَبَ لَحْمُهُ</span> (assumed tropical:) [<i>His flesh wasted away</i>]. (K in art. <span class=\"ar\">بحر</span>, &amp;c.) And <span class=\"ar\">ذَهَبَ الرَّجُلُ فِى القَوْمِ</span> (tropical:) <i>The man became lost</i> [or <i>he disappeared</i>] <i>among the people,</i> or <i>party.</i> (A.) And <span class=\"ar\">ذَهَبَ المَآءَ فِى اللَّبَنِ</span> (tropical:) <i>The water became lost</i> [or <i>it disappeared</i>] <i>in the milk.</i> (A.) -b6- <span class=\"ar\">ذَهَبَ عَلَيْهِ</span> (tropical:) <i>It escaped his memory; he forgot it.</i> (A, TA.) And (assumed tropical:) <i>It was,</i> or <i>became, dubious, confused,</i> or <i>vague, to him.</i> (MA.) -b7- <span class=\"ar\">ذَهَبَ مَذْهَبًا حَسَنًا</span> (S, A, TA) (tropical:) <i>He pursued a good way, course, mode,</i> or <i>manner, of acting</i> or <i>conduct</i> or <i>the like.</i> (TA.) And <span class=\"ar\">ذَهَبَ فِى الدِّينِ مَذْهَبًا</span> (assumed tropical:) <i>He formed,</i> or <i>held, an opinion,</i> or <i>a persuasion,</i> or <i>a belief, respecting religion:</i> or, accord. to Es-Sarakustee, <i>he introduced an innovation in religion.</i> (Msb.) And <span class=\"ar\">ذَهَبَ مَذْهَبَ فُلَانٍ</span> (assumed tropical:) <i>He pursued the way, course, mode,</i> or <i>manner, of acting</i> &amp;c. <i>of such a one.</i> (Msb.) And <span class=\"ar\">ذَهَبَ لِذَهْبِهِ</span> and <span class=\"ar\">لِمَذْهَبِهِ</span> (tropical:) <i>He pursued his way, course, mode,</i> or <i>manner, of acting</i> &amp;c. (JK, TA.) And <span class=\"ar\">ذَهَبَ إِلَى مَذْهَبٍ</span> (tropical:) <i>He betook himself to</i> [or <i>took to</i> or <i>held</i>] <i>a belief, a creed, a persuasion, a doctrine, an opinion, a tenet,</i> or <i>a body of tenets</i> or <i>articles of belief.</i> (K, TA.) And <span class=\"ar\">فُلَانٌ يَذْهَبُ</span> <span class=\"ar\">إِلَى قَوْلِ أَبِى حَنِيفَةَ</span> (tropical:) <i>Such a one takes to,</i> or <i>holds,</i> [<i>the saying,</i> or] <i>the belief, creed, persuasion, doctrine,</i> &amp;c., <i>of Aboo-Haneefeh.</i> (A.) [And <span class=\"ar\">ذَهَبَ إِلَى أَنَّ الأَمْرَ كَذَا</span> (assumed tropical:) <i>He held,</i> or <i>was of opinion, that the thing,</i> or <i>affair,</i> or <i>case, was so.</i> And <span class=\"ar\">ذَهَبَ بِلَفْظٍ إِلَىلَفْظٍ آخَرَ</span> (assumed tropical:) <i>He regarded a word,</i> or <i>an expression,</i> in his manner of using it, <i>as equivalent to another word,</i> or <i>expression;</i> as, for instance, when one makes a fem. noun masc. because it is syn. with a noun that is masc., or makes a verb trans. by means of a certain perticle because it is syn. with a verb that is trans. by means of that same particle: and also (assumed tropical:) <i>he regarded a word,</i> or <i>an expression,</i> as <i>etymologically relating,</i> or <i>traceable, to another word,</i> or <i>expression.</i> And <span class=\"ar\">ذَهَبَ بِهِ إِلَى مَعْنَى كَذَا</span> (assumed tropical:) <i>He regarded it,</i> or <i>used it,</i> (i. e. a word, or an expression,) <i>as relating to such a meaning,</i> or <i>as</i> <i>meaning such a thing.</i>] -b8- <span class=\"ar\">ذَهَبَ فِى طَلَبِ الشَّىْءِ</span> <span class=\"ar\">كُلَّ مَذْهَبٍ</span> (assumed tropical:) [<i>He tried every way,</i> or <i>did his utmost, in seeking the thing</i>]. (K in art. <span class=\"ar\">موت</span>.) And <span class=\"ar\">ذَهَبَ فِىاللِّينِ كُلَّ مَذْهَبٍ</span> (assumed tropical:) [<i>It attained the utmost degree of softness</i>]: said of the skin. (TA in that art.) -b9- <span class=\"ar\">اِذْهَبْ إِلَيْكَ</span> (assumed tropical:) <i>Betake,</i> or <i>apply, thyself to thine own affairs;</i> or <i>occupy thyself therewith.</i> (T and K * voce <span class=\"ar\">إِلَى</span>.) -b10- <span class=\"ar\">ذَهَبَ إِلَى أَبِيهِ فِى الشَّبَهِ</span> <i>i. q.</i> <span class=\"ar\">نَزَعَ</span> (assumed tropical:) [<i>He inclined to his father in likeness; resembled him;</i> or <i>had a natural likeness to him</i>]. (S in art. <span class=\"ar\">نزع</span>.) -A2- <span class=\"ar\">ذَهِبَ</span>, (S, K,) aor. <b class=\"ar\">ذَهَبَ</b> , (K,) inf. n. <span class=\"ar\">ذَهَبٌ</span>; (TA;) and <span class=\"ar\">ذِهِبَ</span>, with two kesrehs, (IAar, K,) of the dial. of Temeem, held by AM to be a variation generally allowable in the case of a verb of which the medial radical letter is a faucial and with kesr; (TA;) <i>He</i> (a man) <i>saw gold in the mine,</i> (S,) or <i>came suddenly, in the mine, upon much gold, and his reason departed in consequence thereof,</i> (K,) <i>and his eyes became dazzled, so as not to close,</i> or <i>move, the lids,</i> or <i>became confused, so as not to see,</i> (S, K,) <i>by reason of the greatness thereof in his eye:</i> (S:) it is derived from <span class=\"ar\">ذَهَبٌ</span>: and the epithet applied to a man in this case is <span class=\"ar\"> <span class=\"ar\">ذَهِبٌ</span></span>. (TA.)</p><p><b>2.</b> <b class=\"ar\">ذَهَّبَ</b> see 1, in the former half of the paragraph, in two places: -A2- and see also 4.</p><p><b>4.</b> <b class=\"ar\">أَذْهَبَ</b> see 1, in the former half of the paragraph, in three places. -A2- Also <span class=\"ar\">اذهبهُ</span>, (Msb, K,) inf. n. <span class=\"ar\">إِذْهَابٌ</span>; (S;) and <span class=\"ar\"> <span class=\"ar\">ذهّبهُ</span></span>, (K,) inf. n. <span class=\"ar\">تَذْهِيبٌ</span>; (S;) <i>He gilded it; did it over with gold.</i> (S, Msb, K.)</p><p><b>Q. Q. 2.</b> [ <b class=\"ar\">تَمَذْهَبَ</b> , from <span class=\"ar\">مَذْهَبٌ</span>, is used by late writers as meaning (assumed tropical:) <i>He followed,</i> or <i>adopted, a certain religious persuasion</i> or <i>the like.</i>]</p><p><b class=\"ar\">ذَهْبٌ</b> : see <span class=\"ar\">مَذْهَبٌ</span>: -A2- and see also the last sentence of the paragraph here following.</p><p><b class=\"ar\">ذَهَبٌ</b> [<i>Gold;</i>] <i>a certain thing well known;</i> (S, Msb, &amp;c.;) accord. to several of the leading lexicologists, (TA,) <i>i. q.</i> <span class=\"ar\">تِبْرٌ</span>; (A, L, K, &amp;c.;) but it seems to have a more general meaning; for <span class=\"ar\">تِبْرٌ</span> is specially applied to <i>such</i> [<i>gold</i>] <i>as is in the mine,</i> or <i>such as is uncoined and unwrought:</i> (TA:) [it is a coll. gen. n.; and therefore] it is masc. and fem.: (S, * Msb, K, * TA:) or it is fem. in the dial. of El-Hijáz: or, accord. to Az, it is masc., and not to be made fem. unless regarded as pl. of <span class=\"ar\"> <span class=\"ar\">ذَهَبَةٌ</span></span>, (Msb, TA,) [or rather as a coll. gen. n., for] <span class=\"ar\">ذَهَبَةٌ</span> is the n. un., (K,) signifying <i>a piece of</i> <span class=\"ar\">ذَهَب</span> [or <i>gold</i>]: (S, A, L, TA:) or, accord. to El-Kurtubee, it is fem., and sometimes masc., but more commonly fem.: <span class=\"ar\"> <span class=\"ar\">ذُهَيْبَةٌ</span></span> is the dim. of <span class=\"ar\">ذَهَبٌ</span>, the <span class=\"ar\">ة</span> being added because the latter word is fem., like as it is in <span class=\"ar\">قُوَيْسَةٌ</span> and <span class=\"ar\">شُمَيْسَةٌ</span>; or it is the dim. of <span class=\"ar\">ذَهَبَةٌ</span>, and signifies <i>a little piece of</i> <span class=\"ar\">ذَهَب</span> [or <i>gold</i>]: (TA:) the pl. of <span class=\"ar\">ذَهَبٌ</span> is <span class=\"ar\">أَذْهَابٌ</span> [a pl. of pauc.] (S, A, Msb, K) and <span class=\"ar\">ذُهُوبٌ</span> (S, K) and <span class=\"ar\">ذُهْبَانٌ</span> (Nh, Msb, K) and <span class=\"ar\">ذِهْبَانٌ</span>. (Nh, TA.) [<span class=\"ar\">مَآءُ الذَّهَبِ</span> means <i>Water-gold; goldpowder mixed with size, for ornamental writing &amp;c.</i>] -b2- The <i>yolk,</i> or the <i>entire contents,</i> i. e. <i>yolk and white,</i> (<span class=\"ar\">مُحّ</span>, K, TA, with the unpointed <span class=\"ar\">ح</span>, TA, [in the CK and in my MS. copy of the K <span class=\"ar\">مُخّ</span>,]) <i>of an egg.</i> (K.) -A2- Also, (S, K,) in a copy of the T written <span class=\"ar\"> <span class=\"ar\">ذَهْبٌ</span></span>, (TA,) <i>A certain measure of capacity, for corn, used by the people of ElYemen,</i> (S, K,) <i>well known:</i> (S:) pl. <span class=\"ar\">ذِهَابٌ</span> (K) and <span class=\"ar\">أَذْهَابٌ</span>, [the latter a pl. of pauc.,] (S, K,) and pl. pl. [i. e. pl. of the latter of the pls. above] <span class=\"ar\">أَذَاهِبُ</span>, (S, and so in the K accord. to the TA,) mentioned by A' Obeyd, (S,) or <span class=\"ar\">أَذَاهِيبُ</span>. (So in the CK.)</p><p><b class=\"ar\">ذَهِبٌ</b> : see 1, last sentence.</p><p><b class=\"ar\">ذِهْبَةٌ</b> <i>A rain:</i> (S:) or <i>a weak rain:</i> or <i>a copious rain:</i> (A'Obeyd, K:) pl. <span class=\"ar\">ذِهَابٌ</span>. (A'Obeyd, S, K.)</p><p><b class=\"ar\">ذَهَبَةٌ</b> : see <span class=\"ar\">ذَهَبٌ</span>, first sentence.</p><p><b class=\"ar\">ذَهُوبٌ</b> : see <span class=\"ar\">ذَاهِبٌ</span>.</p><p><b class=\"ar\">ذَهِيبٌ</b> : see <span class=\"ar\">مُذْهَبٌ</span>, first sentence.</p><p><b class=\"ar\">ذُهَيْبَةٌ</b> : see <span class=\"ar\">ذَهَبٌ</span>, first sentence.</p><p><b class=\"ar\">ذَاهِبٌ</b> [part. n. of <span class=\"ar\">ذَهَبَ</span>;] <i>Going</i> [<i>in any manner,</i> or <i>any pace</i>]; <i>going,</i> or <i>passing, along; marching; journeying; proceeding: going,</i> or <i>passing, away; departing:</i> [&amp;c.:] (A, K:) and <span class=\"ar\"> <span class=\"ar\">ذَهُوبٌ</span></span> signifies the same [in an intensive manner]. (K.) -b2- [<span class=\"ar\">ذَاهِبٌ فِى الطُّولِ</span> means (assumed tropical:) <i>Excessive in length</i> or <i>tallness.</i>]</p><p><b class=\"ar\">مَذْهَبٌ</b> is an inf. n.: (JK, A, K:) -b2- and also signifies <i>A place of</i> <span class=\"ar\">ذَهَاب</span> [or <i>going,</i> &amp;c.]: and <i>a time thereof.</i> (JK.) -b3- [Also <i>A place to which one goes:</i> see an ex. voce <span class=\"ar\">مَحْضَرٌ</span>. -b4- And hence,] (tropical:) <i>A place to which one goes for the purpose of satisfying a want of nature; a privy;</i> (TA;) <i>i. q.</i> <span class=\"ar\">مُتَوَضَّأٌ</span>; (JK, A, K, TA;) in the dial. of the people of El-Hijáz. (JK, A, TA.) -b5- [Also <i>A way by which one goes</i> or <i>goes away.</i> -b6- And hence, as in several exs. in the first paragraph of this art.,] (tropical:) <i>A way, course, mode,</i> or <i>manner, of acting</i> or <i>conduct</i> or <i>the like:</i> (Msb, K, TA:) (tropical:) [<i>a way that one pursues in respect of doctrines and practices</i> in religion &amp;c.; and particularly <i>a way of believing, opining, thinking,</i> or <i>judging;</i>] <i>a belief, a creed, a persuasion, a doctrine, an opinion, a tenet,</i> or <i>a body of tenets</i> or <i>articles of belief;</i> (K, TA;) <i>an opinion</i> in, or respecting, religion; and, accord. to Es-Sarakustee, <i>an innovation</i> in religion: (Msb:) and <span class=\"ar\"> <span class=\"ar\">ذَهْبٌ</span></span> signifies the same. (JK, TA.) [The pl. is <span class=\"ar\">مَذَاهِبُ</span>. Hence, <span class=\"ar\">ذَوُو مَذَاهِبُ</span> (assumed tropical:) <i>Persuasions,</i> as meaning <i>persons holding particular tenets in religion</i> or <i>the like.</i>] -b7- Also (assumed tropical:) <i>Origin:</i> (Ks, Lh, K:) so in the sayings, <span class=\"ar\">مَا يُدْرَى لَهُ أَيْنَ مَذْهَبَهُ</span> and <span class=\"ar\">لَا يُدْرَى لَهُ</span> <span class=\"ar\">مَذْهَبٌ</span>, i. e. (assumed tropical:) <i>It is not known whence is his origin.</i> (Ks, Lh, TA.)</p><p><b class=\"ar\">مُذْهَبٌ</b> <i>Gilt,</i> or <i>done over with gold;</i> (S, A, K;) as also <span class=\"ar\"> <span class=\"ar\">مُذَهَّبٌ</span></span> (A, K) and <span class=\"ar\"> <span class=\"ar\">ذَهِيبٌ</span></span>. (T, K.) -b2- Also sing. of <span class=\"ar\">مَذَاهِبُ</span>, which signifies <i>Skins gilt,</i> (ISk, JK, TA,) i. e. <i>having gilt tines,</i> or <i>stripes, regularly,</i> or <i>uniformly, succeeding one another:</i> (ISk, TA:) or <i>gilt straps</i> or <i>thongs:</i> (S, TA:) and <i>variegated,</i> or <i>figured,</i> [<i>garments of the kind called</i>] <span class=\"ar\">بُرُود</span>: (JK, TA:) [or it is applied as an epithet to such garments; for] you say <span class=\"ar\">بُرْدٌ مُذْهَبٌ</span>. (TA.) The pl. above mentioned is also applied [as an epithet] to swords [app. meaning <i>Adorned with gilding</i>]. (TA.) -b3- Applied to a horse, <i>Of a red colour tinged over with yellow;</i> (TA;) and so <span class=\"ar\">كُمَيْتٌ مُذْهَبٌ</span> [i. e. <i>of a gilded bay colour</i>]: (S, TA:) fem. with <span class=\"ar\">ة</span>: the mare thus termed is of a clearer colour and thinner skin. (TA.) -A2- <span class=\"ar\">المُذْهَبُ</span> is also a name of <i>The Kaabeh.</i> (K, TA.) -A3- See also the next paragraph, in three places.</p><p><b class=\"ar\">مُذْهِبٌ</b> <i>A gilder.</i> (S.) -b2- <span class=\"ar\"> <span class=\"ar\">المُذْهَبُ</span></span>, explained by Lth as the name of (assumed tropical:) <i>A certain devil, said to be of the offspring of Iblees, who tempts reciters of the Kur-án in the performance of</i> [<i>the ablution termed</i>] <span class=\"ar\">الوُضُوْء</span>, (K, * TA,) <i>and on other occasions,</i> (TA,) is [said to be] correctly [<span class=\"ar\">المُذْهِبُ</span>,] with kesr to the <span class=\"ar\">ه</span>: (K:) applied to <i>the devil,</i> (TA in art. <span class=\"ar\">شيط</span>,) as meaning (assumed tropical:) <i>he who embellishes,</i> or <i>renders goodly in appearance,</i> acts of disobedience [to God], as also <span class=\"ar\">المُهَذِّبُ</span>, (Fr, TA in art. <span class=\"ar\">هذب</span>,) IDrd thinks that it is not [genuine] Arabic. (TA.) And accord. to the S and El-Kurtubee and many others, <span class=\"ar\">بِهِ <span class=\"ar\">مُذْهَبٌ</span></span> means (assumed tropical:) [<i>In him is</i>] <i>a vain suggestion</i> [<i>of the devil</i>] <i>respecting the water, and</i> [<i>respecting</i>] <i>the using much thereof in the</i> <span class=\"ar\">وُضُوْء</span>: [i. e. a vain suggestion that may induce him to think that the water is unfit, or deficient in quantity, or the like:] but accord. to the K, it is correctly <span class=\"ar\">المُذْهِبُ</span>. (TA.) Az says that the people of Baghdád apply the appellation <span class=\"ar\">مُذْهِبٌ</span> to (assumed tropical:) A man <i>who inspires vain suggestions;</i> and that the vulgar among them pronounce it <span class=\"ar\"> <span class=\"ar\">مُذْهَبٌ</span></span>. (TA.)</p><p><b class=\"ar\">مَذْهَبَةٌ</b> [<i>A cause,</i> or <i>means, of doing away with, removing, dispelling,</i> or <i>banishing</i>]. Fasting is said, in a trad., to be <span class=\"ar\">مَذْهَبَةٌ لِلْأَشَرِ</span> [i. e. (assumed tropical:) <i>A cause,</i> or <i>means, of dispelling exultation,</i> or <i>excessive exultation, and resting the mind upon things agreeable with natural desire</i>]. (T and S voce <span class=\"ar\">مَحْسَمَةٌ</span>, q. v.)</p><p><b class=\"ar\">مُذَهَّبٌ</b> : see <span class=\"ar\">مُذْهَبٌ</span>.</p>"},"ذرر":{"mf":"الذّرّيّة، قال تعالى: وَمِنْ ذُرِّيَّتِي [البقرة/ ١٢٤]، وقال: وَمِنْ ذُرِّيَّتِنا أُمَّةً مُسْلِمَةً لَكَ [البقرة/ ١٢٨]، وقال: إِنَّ اللَّهَ لا يَظْلِمُ مِثْقالَ ذَرَّةٍ<br>[النساء/ ٤٠]، وقد قيل: أصله الهمز، وقد تذكر بعد في بابه.","mq":[["لطافة وانتشار"],"الذال والراء المشددة أصلٌ واحد يدلُّ على لطافة وانتشار.<br>ومن ذلك الذَّرُّ: صِغار النَّمل، الواحدة ذَرّةٌ. وذَرَرْتُ المِلْحَ والدّواءَ. والذرِيرة معروفة، وكلُّ ذلك قياسٌ واحد.<br>ومن الباب: ذرّت الشّمْسُ ذُروراً، إذا طَلَعَتْ، وهو ضوءٌ لطيفٌ منتشر.<br>وذلك قولُهم: «لا أفعله ما ذَرَّ شارقٌ»<br>، وما ذَرّ قرنُ"],"ln":"<p><b>1.</b> <b class=\"ar\">ذَرَّ</b> , (T, S, M, A, &amp;c.,) aor. <b class=\"ar\">ذَرُرَ</b> , (S, M, Msb,) inf. n. <span class=\"ar\">ذَرٌّ</span>, (S, M, K, &amp;c.,) <i>He sprinkled, or scattered,</i> salt (T, * S, A, Msb, K) upon flesh-meat, and pepper upon a mess of crumbled bread with broth, (A,) and a medicament (S, A) into the eye, (A,) and grain (S, A, K) upon the ground, (A,) &amp;c.; (T, Msb, K;) as also <span class=\"ar\"> <span class=\"ar\">ذَرْذَرَ</span></span>, inf. n. <span class=\"ar\">ذَرْذَرَةٌ</span>: (K:) <i>he took</i> a thing <i>with the ends of his fingers and sprinkled</i> it upon a thing. (M.) You say, <span class=\"ar\">ذَرَّ عَيْنَهُ</span>, (TA,) and <span class=\"ar\">ذَرَّ عَيْنَهُ بِالذَّرُورِ</span>, aor. <b class=\"ar\">ذَرُرَ</b> , (M, TA,) inf. n. <span class=\"ar\">ذَرٌّ</span>, (K, TA,) <i>He put the medicament called</i> <span class=\"ar\">ذَرُور</span> <i>into his eye.</i> (M, * K, * TA.) -b2- Also, (A,) inf. n. as above, (K,) <i>He spread.</i> (A, K.) You say, <span class=\"ar\">ذَرَّ ٱللّٰهُ عِبَادَهُ فِى الأَرْضِ</span> (tropical:) <i>God spread his servants,</i> or <i>mankind, upon the earth.</i> (M, * A.) Whence the word <span class=\"ar\">ذُرِّيَّةٌ</span>. (M, TA.) -b3- And <span class=\"ar\">ذَرَّتِ الأَرْضُ النَّبْتَ</span> <i>The ground put forth the plant,</i> or <i>plants.</i> (K.) -A2- <span class=\"ar\">ذَرَّ</span>, (T, S, M, K, &amp;c.,) aor. <b class=\"ar\">ذَرُرَ</b> , [contr. to analogy,] (T, M,) inf. n. <span class=\"ar\">ذُرُورٌ</span>, (M,) <i>It</i> (a herb, or leguminous plant,) <i>came up, or forth,</i> (IAar, AZ, T, S, K,) <i>from the ground:</i> (AZ, S:) or <i>it</i> (a herb, or leguminous plant, and a horn,) <i>began to come forth; put forth the smallest portion of itself.</i> (A.) -b2- <span class=\"ar\">ذَرَّتِ الشَّمْسُ</span>, (T, S, M, K,) aor. <span class=\"ar\">ذُرُورٌ</span>, inf. n. <span class=\"ar\">ذُرُورٌ</span>, (S, M,) (tropical:) <i>The sun rose;</i> (S, M, K;) and <i>appeared:</i> (M:) or <i>began to rise:</i> <span class=\"ar\">شُرُوقُهَا</span> is when its light first falls upon the earth and trees: (T, TA:) and <span class=\"ar\">ذَرَّ قَرْنُ الشَّمْس</span>, aor. and inf. n. as above, (assumed tropical:) <i>The upper limb of the sun rose:</i> (Msb:) or <i>began to rise.</i> (A, TA.) -A3- <span class=\"ar\">ذَرَّ</span> is also syn. with <span class=\"ar\">تَخَدَّدَ</span> [app. as meaning <i>His flesh became contracted, shrunk,</i> or <i>wrinkled</i>]. (K.) -A4- Also, (T, K,) aor. <b class=\"ar\">ذَرَرَ</b> , contr. to analogy, (K,) unless <span class=\"ar\">ذَرَّ</span> be for <span class=\"ar\">ذَرِرَ</span>, (MF,) said of a man, <i>The fore part of his head became white,</i> or <i>hoary.</i> (T, K.)</p><p><b>3.</b> <b class=\"ar\">ذَارَّتْ</b> , (aor. <span class=\"ar\">تُذَارُّ</span>, S,) inf. n. <span class=\"ar\">مُذَارَّةٌ</span> and <span class=\"ar\">ذِرَارٌ</span>, <i>She</i> (a camel) <i>became evil in her disposition.</i> (Fr, S, K.) Hence the saying of Hoteiäh, satirizing Ez-Zibrikán, and praising the family of Shemmás Ibn-Láy, <span class=\"ar\">وَكُنْتَ كَذَاتِ البَوِّ ذَارَتْ بِأَنْفِهَا</span> <span class=\"ar\">فَمِنْ ذَاكَ تَبْغِى بُعْدَهُ وَتُهَاجِرُهْ</span> i. e. [<i>And thou wast like her who has a stuffed skin of a young camel made for her and placed near her that she may incline to it and yield her milk,</i>] <i>that has inclined to the young one of another;</i> [<i>and on that account desires its distance</i> from <i>her, and severs herself from it:</i>] in the S we find, for <span class=\"ar\">البَوِّ</span>, <span class=\"ar\">البَعْلِ</span>; and for <span class=\"ar\">بُعْدَهُ</span>, <span class=\"ar\">غَيْرَهُ</span>; but the former are the correct readings: <span class=\"ar\">ذَارَتْ</span> is a contraction of <span class=\"ar\">ذَارَّتْ</span>: or, accord. to some, it is for <span class=\"ar\">ذَآءَرَتْ</span>: see art. <span class=\"ar\">ذأر</span>. (IB and TA.) -b2- One says also, <span class=\"ar\">فِى فُلَانٍ ذِرَارٌ</span>, meaning (assumed tropical:) <i>In such a one is aversion, arising from anger, like that of a she-camel:</i> (AZ, S:) or <i>anger and aversion</i> (Th, M, K, TA) <i>and disapprobation.</i> (Th, TA)</p><p><b>R. Q. 1.</b> <b class=\"ar\">ذَرْذَرَ</b> : see 1, first sentence.</p><p><b class=\"ar\">ذَرٌّ</b> The <i>young ones</i> [or <i>grubs</i>] <i>of ants:</i> (M, A, Msb, K:) accord. to Th, (M, TA,) one hundred of them weigh one barley-corn: (M, K:) or, accord. to En-Neysábooree, [who perhaps held <span class=\"ar\">ذَرٌّ</span> to signify <i>ant's eggs,</i>] seventy of them weigh a gnat's wing, and seventy gnat's wings weigh one grain: (MF:) or the <i>smallest of ants:</i> (S:) or <i>small red ants:</i> (TA:) or it signifies, (TA,) or signifies also, (A,) the <i>motes that are seen in a ray of the sun that enters through an aperture:</i> (A, * TA:) as though they were particles of a thing sprinkled: and in like manner <span class=\"ar\">ذَرَّاتُ الذَّهَبِ</span> [<i>minute particles of gold</i>]: (A:) the sing., (S,) or [rather] n. un., (Msb, K,) is <span class=\"ar\">ذَرَّةٌ</span>, (S, M, Msb, K,) [of which the pl. is <span class=\"ar\">ذَرَّاتٌ</span>.] [See an ex., from the Kur x. 62, voce <span class=\"ar\">مِثْقَالٌ</span>.] -b2- See also <span class=\"ar\">ذُرِّيَّةٌ</span>.</p><p><b class=\"ar\">ذَرُورٌ</b> <i>A thing sprinkled:</i> (M:) <i>a dry medicament,</i> (T, TA,) <i>such as is sprinkled in the eye,</i> (T, A, K,) <i>and upon a wound,</i> or <i>sore:</i> (T, TA:) or <i>a kind of</i> <span class=\"ar\">إِثْمِد</span> [q. v.]. [Har p. 86.) -b2- See also <span class=\"ar\">ذَرِيرَةٌ</span>.</p><p><b class=\"ar\">ذُرَارَةٌ</b> <i>What falls about,</i> (M, A, K,) <i>of perfume, when one sprinkles it,</i> (A,) or <i>of</i> <span class=\"ar\">ذَرُور</span>, (K, TA,) or <i>of what is sprinkled.</i> (M, and so accord. to the CK.)</p><p><b class=\"ar\">ذَرِيرَةٌ</b> (S, A, Msb, K) and <span class=\"ar\"> <span class=\"ar\">ذَرُورٌ</span></span> (S, Msb, K) <i>A kind of perfume,</i> (Msb, K,) <i>the particles of the</i> <span class=\"ar\">قَصَبُ الطِّيبِ</span> [or <i>calamus aromaticus,</i> also called <span class=\"ar\">قَصَبُ الذَّرِيرَةِ</span>, q. v., in art. <span class=\"ar\">قصب</span>], (T, M, A, Msb,) <i>which is brought from India,</i> (A, Msb,) <i>and resembles the reeds of which arrows are made:</i> (T, A, Msb:) <i>its internodal portions are filled with a white substance like spiders' webs; and when powdered, it is a perfume, inclining to yellowness and whiteness:</i> (Sgh, Msb:) or, as some say, it is <i>a mixed kind of perfume:</i> (TA:) [but this, if correct, seems to be a second application:] pl. of the latter, <span class=\"ar\">أَذِرَّةٌ</span>. (S, K.)</p><p><b class=\"ar\">ذَرِّىٌّ</b> a rel. n. from <span class=\"ar\">ذَرٌّ</span>, (T,) (tropical:) The <i>diversified wavy marks, streaks,</i> or <i>grain,</i> of a sword: (T, M, A, K:) likened to the track of young ants. (M, A.) It occurs in poetry, in which some read <span class=\"ar\">دُرِّىٌّ</span> [q. v.]. (M.) -b2- And (assumed tropical:) A sword <i>having much of such wavy marks,</i> &amp;c. (K.)</p><p><b class=\"ar\">ذُرِّيَّةٌ</b> , (S, Msb, K,) the most chaste form, (Msb,) and <span class=\"ar\">ذِرِّيَّةٌ</span>, (Msb, K,) and <span class=\"ar\">ذَرِيَّةٌ</span>, this last without a sheddeh to the <span class=\"ar\">ر</span> (Msb,) [respecting the derivation of which see art. <span class=\"ar\">ذرأ</span>,] (assumed tropical:) <i>Children,</i> or <i>offspring,</i> (S, Mgh, Msb, K,) as also <span class=\"ar\"> <span class=\"ar\">ذَرٌّ</span></span>, (Msb,) of a man, (S, K,) [and of genii: see art. <span class=\"ar\">ذرأ</span>,] male or female: (IAth:) <i>little ones,</i> or <i>young ones.</i> (Mgh, Msb.) -b2- Also (tropical:) <i>Progenitors, or ancestors.</i> (Msb, MF.) -b3- Also (assumed tropical:) <i>Women.</i> (Mgh, K.) -b4- Used in a sing. as well as a pl. sense. (Mgh, Msb, K.) -b5- Pl. <span class=\"ar\">ذُرِّيَّاتٌ</span> and (sometimes, Msb) <span class=\"ar\">ذَرَارِىُّ</span>. (S, Msb, K.) [In the CK, the latter pl., with the article, is written <span class=\"ar\">الذَّرَارِى</span>, without a sheddeh to the <span class=\"ar\">ى</span>. -b6- For examples, see art. <span class=\"ar\">ذرأ</span>.]</p><p><b class=\"ar\">مِذَرَّةٌ</b> <i>An instrument with which grain is scattered.</i> (K.)</p><p><b class=\"ar\">مُذَارٌّ</b> A she-camel <i>evil in disposition.</i> (Fr, S, K.) [See 3.]</p>"},"ذلل":{"mf":"الذُّلُّ: ما كان عن قهر، يقال: ذَلَّ يَذِلُّ ذُلًّا <strong>«٣»</strong>، والذِّلُّ، ما كان بعد تصعّب، وشماس من غير قهر <strong>«٤»</strong>، يقال: ذَلَّ يَذِلُّ ذِلًّا. وقوله تعالى: وَاخْفِضْ لَهُما جَناحَ الذُّلِّ مِنَ الرَّحْمَةِ<br>[الإسراء/ ٢٤]، أي: كن كالمقهور لهما، وقرئ (جناح الذِّلِّ) <strong>«٥»</strong> أي: لن وانقد لهما، يقال: الذُّلُّ والقُلُّ، والذِّلَّةُ والقِلَّةُ، قال تعالى: تَرْهَقُهُمْ ذِلَّةٌ [المعارج/ ٤٤]، وقال: ضُرِبَتْ عَلَيْهِمُ الذِّلَّةُ وَالْمَسْكَنَةُ [البقرة/ ٦١]، وقال: سَيَنالُهُمْ غَضَبٌ مِنْ رَبِّهِمْ وَذِلَّةٌ [الأعراف/ ١٥٢]، وذَلَّتِ الدّابة بعد شماس <strong>«٦»</strong>، ذِلًّا، وهي ذَلُولٌ، أي: ليست بصعبة، قال تعالى: لا ذَلُولٌ تُثِيرُ الْأَرْضَ [البقرة/ ٧١]، والذُّلُّ متى كان من جهة الإنسان نفسه لنفسه فمحمود، نحو قوله تعالى: أَذِلَّةٍ عَلَى الْمُؤْمِنِينَ<br>[المائدة/ ٥٤]، وقال: وَلَقَدْ نَصَرَكُمُ اللَّهُ بِبَدْرٍ وَأَنْتُمْ أَذِلَّةٌ [آل عمران/ ١٢٣]، وقال: فَاسْلُكِي سُبُلَ رَبِّكِ ذُلُلًا<br><br>[النحل/ ٦٩]، أي: منقادة غير متصعّبة، قال تعالى: وَذُلِّلَتْ قُطُوفُها تَذْلِيلًا<br>[الإنسان/ ١٤]، أي: سهّلت، وقيل: الأمور تجري على أذلالها <strong>«١»</strong>، أي: مسالكها وطرقها.","mq":[["الخضوع"],"الذال واللام فى التضعيف والمطابقة أصلٌ واحد يدلُّ على الخُضوع، والاستكانة، واللِّين. فالذُّل: ضِدّ العِزّ. وهذه مقابلةٌ فى التضادِّ صحيحة، تدلُّ على الحكمة التى خُصَّتْ بها العرب دون سائر الأمم؛ لأنّ العزّ من العَزَازِ، وهى الأرض الصُّلْبة الشديدة. والذِّلُّ خلاف الصُّعوبة. و<br>حُكى عن بعضهم (٢) أنَّه"],"ln":"<p><b>1.</b> <b class=\"ar\">ذَلَّ</b> , aor. <span class=\"ar\">يَذِلُّ</span>, (M, Msb, K,) inf. n. <span class=\"ar\">ذُلٌّ</span> and <span class=\"ar\">ذِلَّةٌ</span> and <span class=\"ar\">مَذَلَّةٌ</span>, (S, * M, MA, K,) or these three are simple substs., and the inf. n. is <span class=\"ar\">ذَلٌّ</span>, (Msb,) and <span class=\"ar\">ذَلَالَةٌ</span> (M, K) and <span class=\"ar\">ذُلَالَةٌ</span>, (K,) [<i>contr. of</i> <span class=\"ar\">عَزَّ</span>; (see <span class=\"ar\">ذُلٌّ</span> below;) i. e.] <i>He,</i> or <i>it, was</i> or <i>became, low, base, vile, abject, mean, paltry, contemptible, despicable, ignominious, inglorious, abased, humble,</i> and <i>weak;</i> (MA, Msb, K;) syn. <span class=\"ar\">هَانَ</span>, (Msb, K,) and <span class=\"ar\">ضَعُفَ</span>. (Msb.) -b2- <span class=\"ar\">ذَلَّ</span>, (M, K,) and <span class=\"ar\">ذَلَّتْ</span>, (M, Msb,) aor. as above, (M, K,) inf. n. <span class=\"ar\">ذِلٌّ</span>, (M, Msb, K,) said of a man, (M,) and of a beast, such as a horse and the like, (<span class=\"ar\">دَابَّة</span>, M, Msb,) <i>He,</i> or <i>it, was,</i> or <i>became, easy, tractable, submissive,</i> or <i>manageable;</i> (M, Msb, K;) and <span class=\"ar\">اِذْلَوْلَى</span> [which belongs to art. <span class=\"ar\">ذلى</span>] signifies the same as <span class=\"ar\">ذَلَّ</span> in this sense. (ISd, TA.) And <span class=\"ar\"> <span class=\"ar\">تذلّل</span>لَهُ</span> <i>He became lowly, humble,</i> or <i>submissive,</i> [or <i>he lowered, humbled,</i> or <i>submitted, himself,</i>] <i>to him;</i> (S, TA;) as also <span class=\"ar\">تَذَلَّى</span>, originally <span class=\"ar\">تَذَلَّلَ</span>. (TA.) -b3- [Hence,] <span class=\"ar\">ذَلَّ</span> is also said of a road [as meaning (assumed tropical:) <i>It was,</i> or <i>became, beaten,</i> or <i>trodden, so as to be rendered even,</i> or <i>easy to be travelled,</i> or <i>to walk or ride upon:</i> see <span class=\"ar\">ذَلِيلٌ</span>]. (A in art. <span class=\"ar\">تب</span>.) -b4- And <span class=\"ar\">ذَلَّتِ القَوَا فِى لِشَّاعِرِ</span> (assumed tropical:) <i>The rhymes were easy to the poet.</i> (T.) -b5- And <span class=\"ar\">ذَلَّ</span> said of a watering-trough or tank, (TA,) or of the upper part thereof, (M,) (assumed tropical:) <i>It was,</i> or <i>became, broken much,</i> or <i>in several places, in its edge, and much demolished.</i> (M, TA.)</p><p><b>2.</b> <b class=\"ar\">ذلّل</b> , (M, Msb,) inf. n. <span class=\"ar\">تَذْلِيلٌ</span>, (Msb,) <i>He made,</i> or <i>rendered,</i> (M, Msb,) a man, (M,) and a beast, such as a horse and the like, (M, Msb,) <i>easy, tractable, submissive,</i> or <i>manageable:</i> (M, Msb:) [said of the former, it may be rendered <i>he brought under,</i> or <i>into, subjection;</i> or <i>he subdued:</i> and said of the latter, <i>he broke,</i> or <i>trained:</i> and said of any animal, <i>he tamed.</i> -b2- Hence, (assumed tropical:) <i>He beat,</i> or <i>trod,</i> a road, <i>so as to render it even,</i> or <i>easy to be travelled,</i> or <i>to walk or ride upon:</i> see <span class=\"ar\">ذَلِيلٌ</span>.] -b3- And <span class=\"ar\">ذلّل لَهُ أَمْرًا</span> (assumed tropical:) <i>He made an affair easy to him;</i> syn. <span class=\"ar\">رَوَّضَهُ</span> and <span class=\"ar\">سَوَّسَهُ</span>. (TA in art. <span class=\"ar\">سوس</span>.) -b4- And <span class=\"ar\">ذِلِّلَ الكَرْمُ</span> (assumed tropical:) <i>The bunches of the grape-vine were made to hang down</i> [<i>so that they might be easily plucked</i>]: (M, K:) or <i>were evenly disposed</i> [<i>for the same purpose</i>]; syn. <span class=\"ar\">سُوِّيَتْ</span>: (K:) or, accord. to AHn, <span class=\"ar\">التَّذْلِيلُ</span> signifies <i>the disposing evenly the bunches</i> <i>of the grape-vine, and making them to hang down.</i> (M.) <span class=\"ar\">وَذُلِّلَتْ قُطُوفُهَا</span>, in the Kur [lxxvi. 14], means (assumed tropical:) <i>The bunches being evenly disposed, and made to hang down,</i> (S, JM,) <i>exposed to be plucked:</i> (JM:) or <i>being well disposed, and made near:</i> (IAmb, TA:) or <i>being within the reach of the seeker,</i> or <i>desirer:</i> (Ibn-'Arafeh, TA:) or <i>being easy to reach by those who will pluck them, in whatever manner they may desire to do so:</i> (Bd:) accord. to Mujáhid, it means that if one stand, the bunch will rise to him; and if one sit, it will hang down to him. (TA.) [In like manner,] <span class=\"ar\">التَّذْلِيلُ</span> also signifies (assumed tropical:) <i>The putting the raceme of the palm-tree upon the branch</i> [<i>near it</i>] <i>in order that it</i> [the branch] <i>may support it:</i> (AHn, M:) or <span class=\"ar\">تَذْلِيلُ العُذُوقِ</span>, as practised in the present world, is (assumed tropical:) <i>the</i> trimmer's <i>making straight, and fecundating before the usual time, the racemes of the palm-tree, when they come forth from their spathes that covered them, these having slit open and disclosed them, by which means one makes them to hang out from among the branches and prickles, so that the fruit is easily plucked when it ripens.</i> (T. [See also <span class=\"ar\">مُذَلَّلٌ</span>.]) [Hence it is said in the K that <span class=\"ar\">ذُلِّلَ النَّخْلُ</span> signifies <span class=\"ar\">وُضِعَ</span> <span class=\"ar\">عِذْقُهَا عَلَى الجَرِيدَةِ لِتَحْمِلَهُ</span>: the explanation should be <span class=\"ar\">وُضِعَتْ عُذُوقُهَا عَلَى الجَرِيدِ لِتَحْمِلَهَا</span>, i. e. (assumed tropical:) <i>The palm-trees had their racemes put upon the branches in order that these might support them.</i>] -b5- See also what next follows.</p><p><b>4.</b> <b class=\"ar\">اذلّهُ</b> , (M, Msb, K,) inf. n. <span class=\"ar\">إِذْلَالٌ</span>, (TA,) <i>He</i> (God, Msb) <i>lowered, abased,</i> or <i>humbled, him;</i> or <i>rendered him low, base, vile, abject, mean, paltry, contemptible, despicable, ignominious, inglorious, abased, humbled,</i> and <i>weak;</i> (M, * Msb K, TA;) as also <span class=\"ar\"> <span class=\"ar\">ذللّٰهُ</span></span> and <span class=\"ar\"> <span class=\"ar\">استذلّهُ</span></span>: (K, TA:) all these signify the same. (S.) -b2- See also 10 -A2- <span class=\"ar\">اذلّ</span> [as an intrans. verb] <i>He</i> (a man, S, M) <i>became one whose companions were low, base, vile,</i> &amp;c. (S, M, K.) -b2- <i>He became in a state,</i> or <i>condition, that was low, base, vile,</i> &amp;c. (S in art. <span class=\"ar\">قهر</span>.)</p><p><b>5.</b> <b class=\"ar\">تَذَلَّلَ</b> see 1.</p><p><b>10.</b> <b class=\"ar\">استذلّهُ</b> <i>He saw him to be</i> <span class=\"ar\">ذَلِيل</span> [i. e. <i>low, base, vile,</i> &amp;c.]: (M, K:) or <i>he found him to be so;</i> (TA;) as also <span class=\"ar\"> <span class=\"ar\">اذّلهُ</span></span>. (K.) -b2- See also 4. -b3- <span class=\"ar\">استذلّ البَعِيرَ الصَّعْبَ</span> <i>He plucked off the ticks from the refractory camel in order that he might experience pleasure</i> [or <i>relief</i>], <i>and so become at ease,</i> or <i>tranquil,</i> (M, K,) <i>with him.</i> (K.)</p><p>[ <b class=\"ar\">اذْلَوْلَى</b> , a verb of which one of the significations is mentioned in this art. in the K, belongs to art. <span class=\"ar\">ذلى</span>.]</p><p><b>R. Q. 2.</b> <b class=\"ar\">تَذَلْذَلَ</b> [app. from <span class=\"ar\">ذُلْذُلٌ</span>] <i>It was,</i> or <i>became, in a state of commotion,</i> or <i>agitation, and lax, slack,</i> or <i>pendulous.</i> (K.)</p><p><b class=\"ar\">ذُلٌّ</b> and <span class=\"ar\"> <span class=\"ar\">ذِلَّةٌ</span></span> and <span class=\"ar\"> <span class=\"ar\">مَذَلَّةٌ</span></span> [all mentioned in the M and MA and K as inf. ns.] <i>contr. of</i> <span class=\"ar\">عِزٌّ</span>; (S, M;) [i. e.] <i>Lowness, baseness, vileness, abjectness, meanness, paltriness, contemptibleness, despicableness, ignominiousness, ingloriousness, abasement, humiliation,</i> and <i>weakness.</i> (Msb, K. *) <span class=\"ar\">وَ لَمْ يَكُنْ</span> <span class=\"ar\">لَهُ وَلِىٌّ مِنَ الذُّلِّ</span>, in the Kur [xvii. last verse], means <i>Nor hath</i> taken to himself <i>any aider</i> to assist Him and league with Him <i>by reason of any lowness of condition</i> in Him, as is the custom of the Arabs to do: (K, TA: [in the CK, <span class=\"ar\">يُخالِفُهُ</span> is erroneously put for <span class=\"ar\">يُحَالِفُهُ</span>:]) for they used to league, one with another, seeking thereby to become strong and inaccessible. (TA.) See also <span class=\"ar\">ذَلِيلٌ</span>. -b2- And see the paragraph here following, in five places.</p><p><b class=\"ar\">ذِلٌّ</b> <i>Easiness, tractableness, submissiveness,</i> or <i>manageableness;</i> (S, M, K, and Ham p. 50; [mentioned in the M and Msb and K as an inf. n.;]) as also <span class=\"ar\"> <span class=\"ar\">ذُلٌّ</span></span>. (M, K, and Ham ubi suprà.) Hence the saying, <span class=\"ar\">بَعْضُ الذِّلِّ أَبْقَى لِلْأَهْلِ</span> <span class=\"ar\">وَالمَالِ</span> [<i>Somewhat of submissiveness is most preservative of the family and the property</i>]: (S:) or <span class=\"ar\"> <span class=\"ar\">الذُّلُّ</span>أَبْقَى لِلْأَهْلِ وَالمَالِ</span>, occurring in a trad. of Ibn-Ez-Zubeyr; meaning that <i>abjectness</i> betiding a man when he bears patiently an injury that has befallen him <i>is most preservative</i> of him and <i>of</i> his <i>family and</i> his <i>property.</i> (TA.) -b2- Also <i>Gentleness;</i> and <i>mercy;</i> and so <span class=\"ar\"> <span class=\"ar\">ذُلٌّ</span></span>: thus in the phrase, <span class=\"ar\">وَٱخْفِضْ لَهُمَا جَنَاحَ <span class=\"ar\">الذُّلِّ</span></span> or <span class=\"ar\">الذِّلِّ</span>, (M, K,) in the Kur [xvii. 25, lit. <i>And make soft to them</i> (thy two parents) <i>the side of gentleness;</i> meaning <i>treat them with gentleness</i>]: the former is the common reading: (TA:) or the latter means <i>easiness, tractableness,</i> or <i>submissiveness:</i> (K:) [and so the former, as has been stated above:] Er-Rághib says that <span class=\"ar\"> <span class=\"ar\">الذُّلُّ</span></span> is a consequence of subjection; and <span class=\"ar\">الذِّلُّ</span> is what is after refractoriness: so that the phrase means, [accord. to the former reading,] <i>be gentle like him who is subjected to them;</i> and accord. to the latter reading, <i>be gentle and tractable,</i> or <i>submissive, to them.</i> (TA.) -A2- Also The <i>beaten track,</i> (K,) or <i>part that is trodden and made even,</i> (M,) of a road. (M, K.) Its pl. <span class=\"ar\">أَذْلَال</span> occurs in the saying, <span class=\"ar\">أَجْرِ الأُمُورَعَلَى أَذْلَالِهَا</span> <i>Let events,</i> or <i>affairs, take their course in the ways,</i> or <i>manners, that are fit,</i> or <i>proper, for them, and easy.</i> (T.) El-Khansà says, <span class=\"ar\">لِتَجْرِ المَنِيَّةِ بَعْدَ الفَتَى ٱلْمُغَادَرِ بِٱلْمَحْوِ أَذْلَالَهَا</span> [<i>Let fate take its ways after the youth left behind in El-Mahw</i>]; (S, M;) meaning I mourn not for any thing after him: cited by AA: (S in the present art. and in art. <span class=\"ar\">محو</span>:) <span class=\"ar\">المحو</span> is here the name of a place. (S in the latter art.) And one says, <span class=\"ar\">أُمُورُ ٱللّٰهِ جَارِيَةُ عَلَى أَذْلَالِهَا</span>, (S, M, K,) and <span class=\"ar\">جَارِيَةٌ أَذْلَالَهَا</span>, (M, K,) <i>The decrees of God take their</i> [appointed] <i>courses:</i> (S, M, K:) here, also, <span class=\"ar\">اذلال</span> is pl. of <span class=\"ar\">ذِلٌّ</span>. (M, K.) And <span class=\"ar\">دَعْهُ عَلَى <span class=\"ar\">أَذْلَالِهِ</span></span> <i>Leave thou him,</i> or <i>it, in his,</i> or <i>its,</i> [present] <i>state,</i> or <i>condition:</i> (S, M, K:) in this case it has no sing. (M, K.) [And so in the saying,] <span class=\"ar\">جَآءَ عَلَى <span class=\"ar\">أَذْلَالِهِ</span></span> <i>It came in its</i> [proper] <i>manner.</i> (S, K.) -b2- See also another usage of <span class=\"ar\">أَذْلَال</span>, as a pl. having no sing. assigned to it, voce <span class=\"ar\">ذُلْذُلٌ</span>, last sentence.</p><p><b class=\"ar\">ذِلَّةٌ</b> : see <span class=\"ar\">ذُلٌّ</span>. -b2- In the following verse, <span class=\"ar\">لِيَهْنِئْ تُرَاثِى لِٱمْرِئٍ غَيْرِ ذِلَّةٍ</span> <span class=\"ar\">صَنَابِرُ أُحْدَانٌ لِهُنَّ حَفِيفُ</span> [<i>May my heritage give joy to a man not low,</i> or <i>base; slender arrows, singular of their kind, that have a whizzing sound</i>], the meaning is, <span class=\"ar\">غَيْرِ ذَلِيلٍ</span>, or <span class=\"ar\">غَيْرِ ذِى ذِلَّةٍ</span>; and <span class=\"ar\">صنابر</span> is put in the nom. case as a substitute for <span class=\"ar\">تراث</span>. (M.)</p><p><b class=\"ar\">ذَلُولٌ</b> <i>Easy, tractable, submissive,</i> or <i>manageable;</i> (S, M, Msb, K;) applied to a beast, such as a horse and the like, (<span class=\"ar\">دَابَّة</span>), (S, M, Msb,) and to a man [&amp;c.]; (M;) and so <span class=\"ar\"> <span class=\"ar\">ذَلُولِىٌّ</span></span>, applied to a man: (TA, as from the M: [but not found by me in the latter; and I believe that the right reading is <span class=\"ar\">ذَلَوْلًى</span>, belonging to art. <span class=\"ar\">ذلى</span>, q. v.:]) the former alike masc. and fem.: (M, TA:) pl. <span class=\"ar\">ذُلُلٌ</span> (S, M, Msb, K) and <span class=\"ar\">أَذِلَّةٌ</span>. (K.) A poet applies the epithet <span class=\"ar\">ذُلُل</span> to spear-heads, as meaning <i>Made easy</i> [<i>to pierce with</i>] <i>by being sharpened, and made thin and slender.</i> (M.) -b2- See also the next paragraph, in two places.</p><p><b class=\"ar\">ذَلِيلٌ</b> <i>Low, base, vile, abject, mean, paltry, contemptible, despicable, ignominious, inglorious, lowered, brought low, abased, humbled,</i> and <i>weak;</i> (T, S, M, Msb, K;) applied to a man; (T, S;) and <span class=\"ar\"> <span class=\"ar\">ذُلَّانٌ</span></span> signifies the same, as a sing.; (Ibn- 'Abbád, K:) or this latter is a pl. of the former, (T,) as also <span class=\"ar\">أَذِلَّآءُ</span> (S, M, Msb, K) and <span class=\"ar\">أَذِلَّةٌ</span> (T, S, Msb, K) and <span class=\"ar\">ذِلَالٌ</span>. (M, K.) -b2- [Also <i>Gentle;</i> and <i>merciful.</i> Hence,] <span class=\"ar\">أَذِلَّةٍ عَلَى المُؤْمِنِينَ أَعِزَّةٍ</span> <span class=\"ar\">عَلَى الكَافِرينَ</span>, in the Kur [v. 59], means <i>Gentle,</i> (Zj, T,) and <i>merciful,</i> (T,) <i>to the believers, rough in behaviour,</i> (Zj, T,) and <i>hard,</i> or <i>severe,</i> (T,) <i>to the unbelievers.</i> (Zj, T.) -b3- Also applied to a road, meaning (assumed tropical:) <i>Made even,</i> or <i>smooth, and easy to be travelled,</i> or <i>to walk or ride upon;</i> as also with <span class=\"ar\">ة</span>; being applied to <span class=\"ar\">طَرِيقٌ</span> [which is fem. as well as masc.] ; (M;) and so <span class=\"ar\"> <span class=\"ar\">ذَلُولٌ</span></span>: (T:) pl. of the latter, (T,) or of the former, (M,) <span class=\"ar\">ذُلُلٌ</span>: (T, M:) and [in like manner] <span class=\"ar\"> <span class=\"ar\">مُذَلَّلٌ</span></span>, so applied, <i>beaten,</i> or <i>trodden, and</i> [<i>made</i>] <i>even,</i> or <i>easy</i> [<i>to walk or ride upon</i>]: (T:) [in like manner also] <span class=\"ar\"> <span class=\"ar\">ذَلُولٌ</span></span> is applied to land or ground &amp;c. [as meaning <i>easy to be travelled,</i> or <i>to walk or ride upon,</i> &amp;c.]. (As, M voce <span class=\"ar\">تَرَبُوتٌ</span>.) -b4- Also (assumed tropical:) <i>Low,</i> applied to a wall, and to a house, or chamber; (T;) and [so] applied to a mountain: (S and K in art. <span class=\"ar\">دك</span>:) or (tropical:) <i>low and thin,</i> applied to a wall: (Mgh:) and (assumed tropical:) <i>short,</i> applied to a spear. (T.) -b5- You say also <span class=\"ar\"> <span class=\"ar\">ذُلٌّ</span>ذَلِيلٌ</span>, [meaning <i>Exceeding lowness</i> or <i>baseness</i> &amp;c.; or <i>lowering,</i> or <i>abasing, lowness</i> or <i>baseness</i> &amp;c.; i. e.,] using the latter word as an intensive epithet; or as signifying <span class=\"ar\">مُذِلٌّ</span>. (M, K.)</p><p><b class=\"ar\">ذَلُولِىٌّ</b> <i>Good and easy in respect of natural disposition:</i> pl. <span class=\"ar\">ذَلُولِيُّونَ</span>. (Ibn-' Abbád, K. [In the CK, <span class=\"ar\">الخَلْقِ</span> is erroneously put for <span class=\"ar\">الخُلُقِ</span>.]) See also <span class=\"ar\">ذَلُولٌ</span>.</p><p><b class=\"ar\">ذُلَّانٌ</b> : see <span class=\"ar\">ذَلِيلٌ</span>.</p><p><b class=\"ar\">ذُلْذُلٌ</b> is sing. of <span class=\"ar\">ذَلَاذِلُ</span>, which signifies The <i>lower,</i> or <i>lowest, parts,</i> (AZ, T, S,) <i>that are next the ground,</i> of a shirt, (S,) or of a long shirt; (AZ, T;) and IAar says that the sing. is <span class=\"ar\"> <span class=\"ar\">ذُلَذِلٌ</span></span>, and <span class=\"ar\"> <span class=\"ar\">ذِلْذِلَةٌ</span></span>, also; and they are also called <span class=\"ar\">ذَنَاذِنُ</span>, pl. of <span class=\"ar\">ذِنْذِنٌ</span>; (T;) and <span class=\"ar\">دَنَادِنُ</span>: (K in art. <span class=\"ar\">دن</span>:) or <span class=\"ar\">ذُلْذُلٌ</span> and <span class=\"ar\"> <span class=\"ar\">ذِلْذِلٌ</span></span> and <span class=\"ar\"> <span class=\"ar\">ذِلْذِلَةٌ</span></span> and <span class=\"ar\"> <span class=\"ar\">ذُلَذِلٌ</span></span> and <span class=\"ar\"> <span class=\"ar\">ذُلَذِلَةٌ</span></span> all signify the <i>lower,</i> or <i>lowest, parts</i> of a long shirt (M, K) when it dangles and becomes old and worn out; (M;) as also <span class=\"ar\">ذَلَاذِلُ</span>; (K;) [or rather] this last is pl. of all the foregoing words; (M;) and <span class=\"ar\"> <span class=\"ar\">ذَلَذِلُ</span></span> and <span class=\"ar\"> <span class=\"ar\">ذَلَذِلَةٌ</span></span> [in some copies of the K, erroneously, <span class=\"ar\">ذَلْذَل</span>, or <span class=\"ar\">ذَلْذُل</span>, and <span class=\"ar\">ذَلْذَلَة</span>,] signify the same; (K;) [or rather] the former of these two is a contraction of the pl. <span class=\"ar\">ذَلَاذِلُ</span> (S, M) [and the latter of them is the same contracted pl. with the addition of <span class=\"ar\">ة</span>]. -b2- [Hence,] <span class=\"ar\">ذَلَاذِلُ النَّاسِ</span> (assumed tropical:) <i>Those who are the last of the people;</i> (K;) or <i>the last of a few of the people;</i> so in the Moheet; (TA;) and <span class=\"ar\"> <span class=\"ar\">ذُلْذُلَانُهُمْ</span></span> and <span class=\"ar\"> <span class=\"ar\">ذُلَيْذِلَانُهُمْ</span></span>, (K, TA, [in the CK, erroneously, <span class=\"ar\">ذُلْذُلاتُهُمْ</span> and <span class=\"ar\">ذُلِيذَلاتُهُمْ</span>,]) the latter a dim., (TA,) and <span class=\"ar\"> <span class=\"ar\">أَذْلَالُهُمْ</span></span>, signify the same: (K:) or this last signifies <i>the lower, baser, viler,</i> or <i>meaner, of them.</i> (O, TA.)</p><p><b class=\"ar\">ذِلْذِلٌ</b> and <span class=\"ar\">ذُلَذِلٌ</span> and <span class=\"ar\">ذَلَذِلٌ</span> and see <span class=\"ar\">ذُلْذُلٌ</span>, in eight places.</p><p><b class=\"ar\">ذِلْذِلَةٌ</b> and <span class=\"ar\">ذُلَذِلَةٌ</span> and <span class=\"ar\">ذَلَذِلَةٌ</span> and see <span class=\"ar\">ذُلْذُلٌ</span>, in eight places.</p><p><b class=\"ar\">ذُلْذُلَانُ النَّاسِ</b> and <span class=\"ar\">ذُلَيْذِلَانُهُمْ</span>: see <span class=\"ar\">ذُلْذُلٌ</span>.</p><p><b class=\"ar\">أَذَلٌّ</b> [<i>More,</i> and <i>most, low, base, vile,</i> &amp;c.]: see <span class=\"ar\">أَخْنَعُ</span>.</p><p><b class=\"ar\">أَذْلَالٌ</b> as a pl. without a sing.: see <span class=\"ar\">ذِلٌّ</span> (of which it is also a pl.), in two places: -A2- and see <span class=\"ar\">ذُلْذُلٌ</span>, last sentence.</p><p><b class=\"ar\">مَذَلَّةٌ</b> : see <span class=\"ar\">ذُلٌّ</span>. -b2- [Hence,] <span class=\"ar\">غَيْرُالمَذَلَّةِ</span> (assumed tropical:) <i>The wooden pin, peg,</i> or <i>stake:</i> (S, K:) because its head is broken [or battered by beating]. (S.) [See <span class=\"ar\">عَيْرٌ</span>.]</p><p><b class=\"ar\">مُذَلَّلٌ</b> : see <span class=\"ar\">ذَلِيلٌ</span>. -b2- Also, [applied to palmtrees (<span class=\"ar\">نَخْل</span>),] (assumed tropical:) <i>Having the fruit thereof bent</i> [<i>down</i>] <i>in order that it may be</i> [<i>easily</i>] <i>gathered:</i> [see also its verb (2):] so in the following verse of Imra-el-Keys: (Sgh, TA:) <span class=\"ar\">وَكَشْحٍ لَطِيفٍ كَالجَدِيلِ مُخَصَّرٍ</span> <span class=\"ar\">وَسَاقٍ كَأُنْبُوبِ السَّقِىِّ المُذَلَّلِ</span> meaning <i>And a waist slender like the camel's nose-rein of</i> [<i>twisted</i>] <i>leather, thin; and a shank resembling,</i> in the clearness of its colour, <i>the stalk</i> (lit. internodal portion) of the papyrus (<span class=\"ar\">بَرْدِىّ</span>) growing <i>among irrigated palm-trees having their racemes bent down</i> (<span class=\"ar\">ذُلِّلَتْ</span>) by reason of the abundance of their fruit; so that their branches overshade these papyrus-plants: or, accord. to some, <i>and a shank resembling the stalk of the irrigated papyrus that is bent down</i> (<span class=\"ar\">مُذَلَّل</span>) by saturation: (EM pp. 28 and 29:) As says that it means, [agreeably with the former explanation,] <span class=\"ar\">سَاقٍ كَأُنْبُوبِ بَرْدِىٍّ بَيْنَ هٰذَا النَّخْلِ المُذَّلَلِ</span>: AO says that <span class=\"ar\">سَقِىّ</span> means <i>watered</i> [<i>naturally,</i>] <i>without occasioning one's taking any trouble to water:</i> IAar explained <span class=\"ar\">المُذَلَّل</span> as meaning <i>having the way of the water thereto made easy:</i> and some say that by <span class=\"ar\">السَّقِىّ</span> is meant <i>the tender, white, stalk of the</i> <span class=\"ar\">بَرْدِىّ</span>. (T.)</p>"},"ذرأ":{"mf":"الذَّرْءُ: إظهار الله تعالى ما أبداه، يقال: ذَرَأَ الله الخلق، أي: أوجد أشخاصهم. قال تعالى:<br>وَلَقَدْ ذَرَأْنا لِجَهَنَّمَ كَثِيراً مِنَ الْجِنِّ وَالْإِنْسِ [الأعراف/ ١٧٩]، وقال: وَجَعَلُوا لِلَّهِ مِمَّا ذَرَأَ مِنَ الْحَرْثِ وَالْأَنْعامِ نَصِيباً [الأنعام/ ١٣٦]، وقال: وَمِنَ الْأَنْعامِ أَزْواجاً يَذْرَؤُكُمْ فِيهِ [الشورى/ ١١]، وقرئ: (تذرؤه الرّياح) <strong>«٣»</strong>، والذُّرْأَة: بياض الشّيب والملح.<br>فيقال: ملح ذُرْآنيّ، ورجل أَذْرَأُ، وامرأة ذَرْآءُ، وقد ذَرِئَ شعره.","mq":[["لون الي البياض","كالشي يبذر ويزرع"],"الذال والراء والهمزة أصلان: أحدهما لونٌ إلى البياض، والآخر كالشَّئ يُبذَرُ ويُزْرَع.<br>فالأوّل الذُّرْأة، وهو البياضُ من شَيبٍ وغيرِه. ومنه ملح ذَرَآنِىٌّ وذَرْآنىّ. والذُّرْأة: البياض. ورجل أذرَأُ: أشيب، والمرأة ذَرْآء. وقال الشيبانىّ: شَعْرَةٌ ذَرْآءُ، على وزن ذرعاء، أى بيضاء. والفِعل منه ذَرِئَ يَذ"],"ln":"<p><b>1.</b> <b class=\"ar\">ذَرَأَ</b> , (T, S, M, &amp;c.,) aor. <b class=\"ar\">ذَرَاَ</b> , (S, M, Msb, K,) inf. n. <span class=\"ar\">ذَرْءٌ</span>, (S, M, Msb,) <i>He</i> (God) <i>created,</i> syn. <span class=\"ar\">خَلَقَ</span>, (T, S, M, Msb, K,) <span class=\"ar\">الخَلْقَ</span> [<i>the creation;</i> i. e. <i>the things that are created</i>]. (T, S, M, Msb.) <span class=\"ar\">وَلَقَدْ ذَرَأْنَا لِجَهَنَّمَ كَثِيرًا مِنَ ٱلْجِنِّ وَ ٱلْإِنْسِ</span>, in the Kur [vii. 178], means [<i>And verily</i>] <i>we have created</i> [<i>for Hell many of the jinn,</i> or <i>genii, and of mankind</i>]. (T.) -b2- <i>He multiplied,</i> or <i>made numerous.</i> (K.) <span class=\"ar\">يَذْرَؤُكُمْ فِيهِ</span>, in the Kur [xlii. 9], means <i>He multiplieth you thereby;</i> i. e., by making of you, and of the cattle, pairs, males and females: so says Zj; and Fr says the like; and this is a correct explanation. (T.) -b3- Also, (S, M, K,) and so <span class=\"ar\">ذَرَا</span>, (TA,) <i>He sowed</i> land: (S, M, K, TA:) but the latter verb is said to be the more chaste. (MF.) -A2- <span class=\"ar\">ذَرَأَ فُوهُ</span> <i>His teeth fell out from his mouth;</i> (K, TA;) as also <span class=\"ar\">ذَرَا</span> and <span class=\"ar\">ذَرَى</span>, without <span class=\"ar\">ء</span>: (TA:) but the most chaste is said to be without <span class=\"ar\">ء</span>: <span class=\"ar\">ذَرَأَ</span>, with <span class=\"ar\">ء</span>, is said to be of weak authority, or a mispronunciation. (MF.) -b2- <span class=\"ar\">ذَرِئَ</span>, (M, K,) or <span class=\"ar\">ذَرِئَ شَعَرَهُ</span>, (S,) aor. <b class=\"ar\">ذَرَاَ</b> , (K,) inf. n. <span class=\"ar\">ذَرَأٌ</span>; (S, * M, O;) and <span class=\"ar\">ذَرَأَ</span>, (S, K,) aor. <b class=\"ar\">ذَرَاَ</b> ; (K;) and <span class=\"ar\">ذَرُؤَ</span>, aor. <b class=\"ar\">ذَرُاَ</b> ; (Ktr, TA;) <i>His hair became white,</i> or <i>hoary, in the fore part of his</i> <i>head:</i> (S:) or <i>he had whiteness intermixed with blackness in the hair of his head:</i> (M:) or <i>his hair became white,</i> or <i>hoary:</i> (K:) or <i>he began to become white,</i> or <i>hoary,</i> (M, K,) <i>in the fore part of his head,</i> (K,) or <i>in the upper part of each side of the head.</i> (A, TA.) The epithet is <span class=\"ar\"> <span class=\"ar\">أَذْرَأُ</span></span>; fem. <span class=\"ar\">ذَرْآءٌ</span>. (S, M, K. [In some copies of the K, <span class=\"ar\">ذَرْأَى</span> is erroneously put for <span class=\"ar\">ذَرْآءُ</span>.])</p><p><b>4.</b> <b class=\"ar\">اذرأهُ</b> <i>He angered him; provoked him to anger.</i> (T, M, K.) -b2- <span class=\"ar\">اذرأهُ بِصَاحِبِهِ</span> <i>He incited him against his companion.</i> (AZ, T.) And <span class=\"ar\">اذرأهُ</span> <span class=\"ar\">بِالشَّىْءِ</span> <i>He incited him,</i> or <i>urged him, to do,</i> or <i>attempt, the thing.</i> (M, K.) And <span class=\"ar\">اذرأهُ إِلَىكَذَا</span> <i>He constrained him,</i> or <i>compelled him, to have recourse to,</i> or <i>to do, such a thing.</i> (K, * TA.) A 'Obeyd mentions <span class=\"ar\">أَذْرَى</span>, without <span class=\"ar\">ء</span>; but 'Alee Ibn-Hamzeh asserts that this is incorrect. (M.) -b3- <span class=\"ar\">اذرأ الدَّمْعَ</span> <i>He,</i> or <i>it, made tears to flow.</i> (K, * TA.) -b4- And <span class=\"ar\">اذرأه</span> <i>He frightened him.</i> (M, K.) -A2- <span class=\"ar\">أَذْرَأَتْ</span> <i>She</i> (a camel) <i>excerned</i> (<span class=\"ar\">أَنْزَلَتْ</span>) <i>the milk</i> (M, K, TA) <i>from</i> [app. a mistake for <i>into</i>] <i>her udder:</i> a dial. var. of <span class=\"ar\">أَدْرَأَتْ</span> [q. v.]. (TA.) The epithet applied to the she-camel so doing is <span class=\"ar\"> <span class=\"ar\">مُذْرِئٌ</span></span>. (M, K.)</p><p><b class=\"ar\">ذَرْءٌ</b> The act of <i>creating;</i> inf. n. of <span class=\"ar\">ذَرَأَ</span>. (S, M, Msb.) -b2- [And used in the sense of the pass. part. n. of that verb; and alike as sing. and pl. because originally an inf. n.] <span class=\"ar\">ذَرْءُ النَّارِ</span>, (S, K, TA,) [for <span class=\"ar\">ذَرْءٌ لِلنَّارِ</span>,] related as occurring in a trad. (S, TA) of 'Omar, (TA,) means <i>Created</i> [i. e. <i>destined</i>] <i>for the fire</i> [<i>of Hell</i>]: (S, K, TA:) but as some relate it, the phrase is <span class=\"ar\">ذَرْوُ النَّارِ</span>, meaning [either “ the children of the fire, ” agreeably with what next follows, or] “ to be scattered in the fire. ” (S, TA.) -b3- Also The <i>number of</i> [ones] <i>offspring:</i> one says, <span class=\"ar\">أَنْمَىٱللّٰهُ ذَرْأَكَ</span> <i>May God increase</i> [<i>the number of</i>] <i>thine offspring;</i> as also <span class=\"ar\">ذَرْوَكَ</span>. (T.) -A2- <i>Somewhat;</i> (M, K;) as in the saying, <span class=\"ar\">بَلَغَنِى ذَرْءٌ مِنْ خَبَرٍ</span> [<i>Somewhat of news,</i> or <i>information, reached me,</i> or <i>came to my knowledge</i>]: (K, TA:) or <span class=\"ar\">ذَرْءٌ مِنْ خَيْرٍ</span> [<i>somewhat of good</i>]: (so in some copies of the K and M:) thus <span class=\"ar\">ذرء</span> is written by IAth: in some copies of the K, <span class=\"ar\">ذُرْءٌ</span>, with damm: (TA:) or <span class=\"ar\">ذَرْءٌ</span> here means <i>a little;</i> and <span class=\"ar\">ذَرْوٌ</span> is a dial. var. thereof. (M in art. <span class=\"ar\">ذرو</span>.) Also <i>A little</i> of what is said. (TA.) -A3- <i>A thing intervening as a separation</i> or <i>an obstacle:</i> so in the saying, <span class=\"ar\">مَا بَيْنَنَا وَ بَيْنَهُ ذَرْءٌ</span> [<i>There is not anything intervening</i> &amp;c. <i>between us and him,</i> or <i>it</i>]. (K, * TA.)</p><p><b class=\"ar\">ذَرَأٌ</b> : see what next follows.</p><p><b class=\"ar\">ذُرْأَةٌ</b> (S, M, K) and <span class=\"ar\"> <span class=\"ar\">ذَرَأٌ</span></span>, (S,) the latter an inf. n. (M, [see 1,]) the former a simple subst., (S,) <i>Whiteness,</i> or <i>hoariness, in the fore part of the head:</i> (S:) or <i>whiteness intermixed with blackness in the hair of the head:</i> (M:) or <i>whiteness,</i> or <i>hoariness, of the hair:</i> (K:) or the <i>beginning of whiteness</i> or <i>hoariness</i> (M, K) <i>in the fore part of the head,</i> (K,) or <i>in the upper part of each side of the head.</i> (A, TA.)</p><p><b class=\"ar\">ذَرْآنِىٌّ</b> and <span class=\"ar\">ذَرَآنِىٌّ</span> <i>Intensely white</i> salt: (S, M, K:) derived from <span class=\"ar\">ذُرْأَةٌ</span>: one should not say <span class=\"ar\">أَنْذَرَانِىٌّ</span>; (S, K;) for this is a vulgarism: some pronounce it with the unpointed <span class=\"ar\">د</span>. (TA.)</p><p><b class=\"ar\">ذَرِىْءٌ</b> <i>Sown</i> seed. (S, M, K.)</p><p><b class=\"ar\">ذُرِّيَّةٌ</b> (T, S, M, Mgh, K) and <span class=\"ar\">ذِرِّيَّةٌ</span> (M, K) and <span class=\"ar\">ذَرِّيَّةٌ</span>, (K,) [or <span class=\"ar\">ذَرِيَّةٌ</span>, without a sheddeh to the <span class=\"ar\">ر</span>, accord. to the Msb in art. <span class=\"ar\">ذر</span>,] always pronounced by the Arabs without <span class=\"ar\">ء</span>: (S:) accord. to some, (TA,) from <span class=\"ar\">الذَّرْءُ</span>; (M, TA;) so says Th; (M;) the measure of the first being <span class=\"ar\">فُعُّولَةٌ</span> or <span class=\"ar\">فُعِّيلَةٌ</span>; [so that it is originally <span class=\"ar\">ذُرُّوءَةٌ</span> or <span class=\"ar\">ذُرِّيْئَةٌ</span>;] (TA;) but the <span class=\"ar\">ء</span> is suppressed because of frequency of usage: (M:) accord. to others, from <span class=\"ar\">الذَّرُّ</span>, signifying “ the act of scattering; ” because God scattered the <span class=\"ar\">ذرّيّة</span> upon the earth; and the measure is <span class=\"ar\">فُعْلِيَّةٌ</span> or <span class=\"ar\">فُعُّولَةٌ</span>, [if the latter,] the word being originally <span class=\"ar\">ذُرُّورَةٌ</span>, the last <span class=\"ar\">ر</span> being changed into <span class=\"ar\">ى</span>, in a manner similar to the case of <span class=\"ar\">تَقَضَّتِ العُقَابِ</span> [in which <span class=\"ar\">تَقَضَّضَت</span> becomes <span class=\"ar\">تَقَضَّيَت</span> and then <span class=\"ar\">تَقَضَّت</span>; so that <span class=\"ar\">ذُرُّورَةٌ</span> becomes <span class=\"ar\">ذُرُّويَةٌ</span> and then <span class=\"ar\">ذُرِّيَّةٌ</span>]: (TA:) <i>Children,</i> or <i>offspring,</i> (T, S, Mgh, K,) of a man, and used as a sing. also, (Mgh,) or of men and of jinn, or genii: (S, K:) pl. [<span class=\"ar\">ذُرِّيَّاتٌ</span> (see art. <span class=\"ar\">ذر</span>) and sometimes] <span class=\"ar\">ذَرَارِىُّ</span>. (S.) Hence, <span class=\"ar\">هَبْ لِى مِنْ لَدُنْكَ</span> <span class=\"ar\">ذُرِّيَّةً طَيِّبَةً</span> [in the Kur iii. 33, meaning <i>Give me, from Thee, a good offspring</i>]. (Mgh.) And in a trad. of Ibn-'Omar, <span class=\"ar\">فَجَعَلَنِى فِى الذُّرِّيَّةِ</span> means <i>And he put me among the little ones,</i> or <i>young ones.</i> (Mgh.) -b2- It is also applied to signify <i>Progenitors:</i> as in the saying, in the Kur [xxxvi. 41], <span class=\"ar\">حَمَلْنَا ذُرِّيَّتَهُمْ فِى ٱلْفُلْكِ المَشْحُونِ</span> [<i>We carried their progenitors in the laden ark</i>]. (T.) -b3- And it is used also to signify <i>Women;</i> [because they are the sources of offspring;] (T, Mgh, TA;) like as <span class=\"ar\">سَمَآءٌ</span> is used to signify “ rain: ” (TA:) as in the saying of 'Omar, <span class=\"ar\">حُجُّوا بِالذُّرِّيَّةِ</span> [<i>Perform ye the pilgrimage with the women</i>]. (T, Mgh, TA. [See his saying in full, voce <span class=\"ar\">رِبْقٌ</span>.])</p><p><b class=\"ar\">الذَّارِئُ</b> an epithet applied to God, <i>The Creator.</i> (T.)</p><p><b class=\"ar\">أَذْرَأُ</b> ; fem. <span class=\"ar\">ذَرْآءُ</span>: see 1, last sentence. Applied to a ram, <i>Having whiteness in the head;</i> (M, K;) and so the fem. applied to a ewe: (M:) or <i>having the ears variegated,</i> or <i>speckled, with black and white, and the rest black:</i> (K:) or it has this latter meaning when applied to a horse, and to a kid; and so the fem. applied to a female kid, (S, O,) or to a she-goat: (M:) and is not applied to the sheep-kind. (S, O.)</p><p><b class=\"ar\">مُذْرِئٌ</b> : see 4, last sentence.</p>"},"ذبح":{"mf":"أصل الذَّبْح: شقّ حلق الحيوانات. والذِّبْح:<br>المذبوح، قال تعالى: وَفَدَيْناهُ بِذِبْحٍ عَظِيمٍ [الصافات/ ١٠٧]، وقال: إِنَّ اللَّهَ يَأْمُرُكُمْ أَنْ تَذْبَحُوا بَقَرَةً<br>[البقرة/ ٦٧]، وذَبَحْتُ الفارة <strong>«٢»</strong> :<br>شققتها، تشبيها بذبح الحيوان، وكذلك: ذبح الدّنّ <strong>«٣»</strong>، وقوله: يُذَبِّحُونَ أَبْناءَكُمْ<br>[البقرة/ ٤٩]، على التّكثير، أي: يذبح بعضهم إثر بعض. وسعد الذّابح اسم نجم، وتسمّى الأخاديد من السّيل مذابح.","mq":[["يدل علي الشق"],"الذال والباء والحاء أصلٌ واحد، وهو يدلُّ على الشّقّ.<br>فالذَّبح: مصدِ ذبَحْت الشّاةَ ذبحاً. والذِّبح: المذبوح. والذُّبَّاح: شُقوقٌ فى أصول الأصابع. ويقال ذُبِحَ الدَّنُّ، إذا بُزِلَ. والمذابح: سيولٌ صغار تشقُّ الأرض شقًّا. وسعدٌ الذّابحُ: أَحد السُّعود (٣)<br>. والذِّبَح: نبتٌ، ولعله أن يكون شاذًّا من ال"],"ln":"<p><b>1.</b> <b class=\"ar\">ذُبَحَ</b> , (S, Msb, K, &amp;c.,) aor. <b class=\"ar\">ذَبَحَ</b> , (K,) inf. n. <span class=\"ar\">ذَبْحٌ</span> (S, Msb, K, &amp;c.) and <span class=\"ar\">ذُبَاحٌ</span>, (K,) <i>He cut,</i> or <i>divided, lengthwise; clave; split; slit; rent,</i> or <i>rent open; ripped,</i> or <i>ripped open.</i> (S, Msb, K.) [Accord. to Fei,] this is the primary signification. (Msb.) [But see what follows.] You say, <span class=\"ar\">ذَبَحَ</span> <span class=\"ar\">فَأْرَةَ المِسْكَ</span> (assumed tropical:) <i>He</i> (a perfumer, A) <i>ripped open the follicle,</i> or <i>vesicle, of mush,</i> (A, TA,) <i>and took forth the mush that was in it.</i> (TA.) [In the A and TA this is said to be tropical; the authors evidently holding it to be from <span class=\"ar\">ذَبَحَ</span> in the sense here next following.] -b2- <i>He slaughtered</i> [for food, or <i>sacrificed,</i>] (L, TA) and animal, (Msb,) or a sheep or goat, (S, TA,) or an ox or a cow, and a sheep or goat, and the like, (Mgh,) [<i>in the manner prescribed by the law,</i> i. e.,] <i>by cutting the</i> <span class=\"ar\">وَدَجَانِ</span> [or <i>two external jugular veins</i>], (Mgh,) or <i>by cutting the throat, from beneath, at the part next the head:</i> (L, TA:) accord. to the K, <i>i. q.</i> <span class=\"ar\">نَحَرَ</span>: but correctly, <span class=\"ar\">الذَّبْحُ</span> is in the throat; and <span class=\"ar\">النَّحْرُ</span> is in the pit above the breast, between the collar-bones, where camels are stabbed: the latter word is used in relation to camels and bulls and cows; and the former, in relation to other animals: or, not improbably, both may have originally signified <i>the causing the soul to depart by wounding the throat, or the pit above the breast, which is the stabbing-place in the camel;</i> and may then have been applied in peculiar [and different] senses by the lawyers. (MF. [See also <span class=\"ar\">ذَكَاةٌ</span>, in art. <span class=\"ar\">ذكو</span>.]) Also (assumed tropical:) <i>He slaughtered,</i> or <i>slew, in any manner.</i> (L.) [You say, <span class=\"ar\">ذَبَحَ عَنْهُ</span> <i>He slaughtered,</i> or <i>sacrificed, for him, by way of expiation.</i>] And <span class=\"ar\">ذَبَحَ بَعْضُهُمْ بَعْضًا</span> (assumed tropical:) [<i>They slaughtered,</i> or <i>slew, one another</i>]. (S, K.) And <span class=\"ar\">أَخَذَهُمْ بَنُو</span> <span class=\"ar\">فُلَانٍ بِالذُّبَاحِ</span> (assumed tropical:) <i>The sons of such a one slaughtered,</i> or <i>slew, them.</i> (TA.) And <span class=\"ar\"> <span class=\"ar\">ذبّح</span></span> (inf. n. <span class=\"ar\">تَذْبِيحٌ</span>, KL) signifies the same as <span class=\"ar\">ذَبَحَ</span>, except that it applies [only] to many objects; whereas the latter applies to few and to many: thus it is said in the Kur [ii. 46, and in like manner in xiv. 6], <span class=\"ar\">يُذَبِّحُونَ أَبْنَآءَكُمْ</span> (assumed tropical:) [<i>They slaughtering,</i> or <i>slaying, your sons</i>], accord. to the reading commonly obtaining. (Aboo-Is-hák, TA.) -b3- Hence, (tropical:) <i>He killed;</i> because <span class=\"ar\">الذَّبْحُ</span> [in its proper sense, when the object is an animal,] is one of the quickest modes of killing. (TA.) It is said in a trad., (Mgh, TA,) cautioning against accepting the office of a Kádee, (Mgh,) <span class=\"ar\">مَنْ جُعِلَ قَاضِيًا بَيْنَ</span> <span class=\"ar\">النَّاسِ فَكَأَنَّمَا ذُبِحَ بِغَيْرِ سِكِّينٍ</span> (tropical:) [<i>Whoso is made a Kádee among the people, he is as though he were slaughtered without a knife</i>]: (Mgh, TA: *) expl. by some as meaning, (tropical:) <i>he is as though he were killed</i> [&amp;c.]. (TA.) -b4- [Hence, also, because <span class=\"ar\">الذَّبْحُ</span> renders the flesh of an animal allowable, or lawful, as food,] (tropical:) <i>It rendered allowable,</i> or <i>lawful:</i> as salt and the sun and the fishes called <span class=\"ar\">نِينَان</span> (pl. of <span class=\"ar\">نُونٌ</span>) do wine, by changing its quality, as is said in a trad. (TA.) -b5- Also (tropical:) <i>He broached,</i> or <i>pierced,</i> a <span class=\"ar\">دَنّ</span> [or wine-jar, <i>making a hole in the mouth,</i> or <i>removing the clay that closed the mouth</i>], <i>so as to draw forth the contents.</i> (S, A, Msb, K.) -b6- And (tropical:) <i>He,</i> or <i>it, choked.</i> (K, TA.) You say, <span class=\"ar\">ذَبَحَتْهُ العَبْرَةُ</span> (tropical:) <i>Weeping choked him.</i> (A, TA.) -b7- And, said of thirst, (tropical:) <i>It affected him severely,</i> or <i>distressed him.</i> (A, TA.) -b8- <span class=\"ar\">ذَبَحَتِ اللِّحْيَةُ فُلَانًا</span> (tropical:) The <i>beard flowed down beneath the chin of such a one so that the anterior portion of the part beneath his lower jaw was apparent:</i> in which case, the man is said to be <span class=\"ar\"> <span class=\"ar\">مَذْبُوحٌ</span>بِلِحْيَتِهِ</span>. (K, TA.)</p><p><b>2.</b> <b class=\"ar\">ذَبَّحَ</b> see 1. -A2- <span class=\"ar\">تَذْبِيحٌ</span> is [said to be] syn. with <span class=\"ar\">تَذْبِيحٌ</span>, (K, TA,) in prayer: accord. to Hr, <span class=\"ar\">ذبّح</span> <span class=\"ar\">رَأْسَهُ</span> signifies <i>He lowered his head,</i> in inclining his body in prayer; like <span class=\"ar\">دبّح</span>: and accord. to Lth, <span class=\"ar\">ذبّح</span> signifies <i>he lowered his head,</i> in inclining his body in prayer, <i>so that it became lower than his back:</i> but Az says that this is a mistake, and that the correct word is <span class=\"ar\">دبّح</span>, with the unpointed <span class=\"ar\">د</span>. (TA.)</p><p><b>6.</b> <b class=\"ar\">تذابحوا</b> (assumed tropical:) <i>They slaughtered,</i> or <i>slew, one another.</i> (S, MA, K.) One says, <span class=\"ar\">التَّمَادُحُ التَّذَابُحُ</span> (tropical:) [<i>Mutual praising is mutual slaughtering</i>]. (S, A.)</p><p><b>8.</b> <b class=\"ar\">اِذَّبَحَ</b> <i>He took,</i> or <i>prepared, for himself a slaughtered</i> [or <i>sacrificed</i>] <i>animal.</i> (S, K.)</p><p><b class=\"ar\">ذِبْحٌ</b> <i>An animal prepared for slaughter</i> [or <i>sacrifice;</i> i. e. <i>an intended victim</i>]: (T, A, Msb, TA:) [see also <span class=\"ar\">ذَبِيحٌ</span>, which occurs in this sense in a trad. as applied to a human being:] or <i>an animal that is slaughtered</i> [or <i>sacrificed</i>]; (S, Mgh, K, TA;) and so <span class=\"ar\"> <span class=\"ar\">ذَبِيحَةٌ</span></span>; (Mgh, Msb;) or this signifies <i>a slaughtered</i> [or <i>sacrificed</i>] <i>sheep</i> or <i>goat;</i> (TA;) and is [nominally] fem. of <span class=\"ar\">ذَبِيحٌ</span>, but the <span class=\"ar\">ة</span> is affixed only because the quality of a subst. is predominant in it: (S:) or the <span class=\"ar\">ذَبِيحٌ</span> is added to denote that the word is applied to <i>a sheep,</i> or <i>goat,</i> [<i>to be slaughtered</i> or <i>sacrificed,</i>] <i>not yet slaughtered</i> [or <i>sacrificed</i>]; and when the act has been executed upon it, it is [said to be] <span class=\"ar\">ذَبِيحٌ</span>: (M, voce <span class=\"ar\">رَمِيَّةٌ</span>:) <span class=\"ar\">ذِبْحٌ</span> is applied to <i>an animal that is slaughtered</i> either <i>as a sacrifice on the occasion of the pilgrimage</i> or <i>otherwise;</i> and is like <span class=\"ar\">طِحْنٌ</span> in the sense of <span class=\"ar\">مَطْحُونٌ</span>, and <span class=\"ar\">عِطْفٌ</span> in the sense of <span class=\"ar\">مَعْطُوفٌ</span>, &amp;c.: (TA:) the pl. of <span class=\"ar\"> <span class=\"ar\">ذَبِيحَةٌ</span></span> is <span class=\"ar\">ذَبَائِحُ</span>. (Mgh, Msb.) It is said in the Kur [xxxvii. 107], <span class=\"ar\">وَفَدَيْنَاهُ بِدِبْحٍ عَظِيمٍ</span> [<i>And we ransomed him with a great victim</i>]. (S, A.) <span class=\"ar\"> <span class=\"ar\">ذَبَائِحُ</span>الجِنِّ</span> means <i>Animals sacrificed to the Jinn,</i> or <i>Genii:</i> for it was customary for a man, when he bought a house, or drew forth [for the first time] the water of a spring, and the like, to sacrifice an animal to the Jinn with the view of avoiding ill luck, (A, TA,) lest some disagreeable accident should happen to him from the Jinn thereof: (A:) and the doing this is forbidden. (A, TA.) -A2- See also <span class=\"ar\">ذُبَحَةٌ</span>.</p><p><b class=\"ar\">ذُبَحٌ</b> <i>A certain plant which ostriches eat:</i> (S:) this word and <span class=\"ar\"> <span class=\"ar\">ذِبَحٌ</span></span> signify the <i>plant called</i> <span class=\"ar\">الجَزَرُ</span> <span class=\"ar\">البَّرىُّ</span>, (K, TA,) <i>which is of a red colour:</i> and, accord. to the K, <i>another plant:</i> but correctly <i>a red plant</i> (<span class=\"ar\">نَبْتٌ أَحْمَرُ</span>, not <span class=\"ar\">نبت آخَرُ</span>,) <i>having a stem,</i> or <i>root,</i> (<span class=\"ar\">أَصْلٌ</span>) <i>from which is peeled off a black peel, whereupon there is taken forth a white substance, resembling a white</i> <span class=\"ar\">خزرة</span> [or <i>bead,</i> but perhaps this is a mistranscription for <span class=\"ar\">جَزَرَة</span>, i. e. a <i>carrot</i>], <i>which is sweet and good, and is eaten:</i> [each word is a coll. gen. n.;] and the n. un. is <span class=\"ar\">ذُبَحَةٌ</span> and <span class=\"ar\">ذِبَحَةٌ</span>: so says AHn, on the authority of Fr: and he says also, on the authority of AA, that the <span class=\"ar\">ذُبَحَة</span> is <i>a tree that grows upon a stem, and in a manner resembling the</i> <span class=\"ar\">كراث</span> [app. <span class=\"ar\">كَرَاث</span>, not <span class=\"ar\">كُرَّاث</span>], <i>and then has a yellow flower; its root is like a</i> <span class=\"ar\">جزرة</span> [i. e. <span class=\"ar\">جَزَرَة</span>, or <i>carrot</i>], <i>and it is sweet, and of a red colour:</i> (TA:) or the <span class=\"ar\">ذُبَح</span> is <i>a plant having a stem,</i> or <i>root,</i> (<span class=\"ar\">أَصْلٌ</span>,) <i>which is peeled, and there comes forth what resembles the</i> <span class=\"ar\">جِزر</span> [i. e. <span class=\"ar\">جِزَر</span> or <span class=\"ar\">جَزَر</span>, meaning <i>carrot</i>]; <i>and a black skin is peeled from it; and it is sweet, and is eaten; and has a red flower.</i> (Ham p. 777.) -b2- Also, and <span class=\"ar\"> <span class=\"ar\">ذِبَحٌ</span></span>, (K,) the former the more common, (Th, TA,) <i>A species of the</i> <span class=\"ar\">كَمْأَةٌ</span> [or <i>truffle</i>], (K,) <i>of a white colour.</i> (TA.) -b3- See also <span class=\"ar\">ذُبَاحٌ</span>.</p><p><b class=\"ar\">ذِبَحٌ</b> : see the next preceding paragraph, in two places.</p><p><b class=\"ar\">ذُبْحَةٌ</b> : see <span class=\"ar\">ذُبَحَةٌ</span>.</p><p><b class=\"ar\">ذِبْحَةٌ</b> <i>A mode,</i> or <i>manner, of</i> <span class=\"ar\">ذَبْح</span> [i. e. <i>slaughter, such as is described in the first paragraph of this art.</i>]. (Mgh.) -A2- See also what here next follows.</p><p><b class=\"ar\">ذُبَحَةٌ</b> (AZ, S, A, K) and <span class=\"ar\"> <span class=\"ar\">ذُبْحَهٌ</span></span>, (As, A, K,) but this latter, which is used by the vulgar, was unknown to AZ, (S,) and <span class=\"ar\"> <span class=\"ar\">ذُبَاحٌ</span></span> (A, K) and <span class=\"ar\"> <span class=\"ar\">ذِبَحَةٌ</span></span> and <span class=\"ar\"> <span class=\"ar\">ذِبْحَةٌ</span></span> and <span class=\"ar\"> <span class=\"ar\">ذِبَاحٌ</span></span> (K) and <span class=\"ar\"> <span class=\"ar\">ذِبْحٌ</span></span>, (TA,) <i>A disease,</i> (T, A,) or <i>pain,</i> (AZ, S, K,) <i>in the</i> <span class=\"ar\">حَلْق</span> [or <i>fauces</i>], (AZ, T, S, A, K,) <i>which sometimes kills:</i> (T:) or <i>blood which chokes and kills:</i> (K:) or <i>an ulcer that comes forth in the</i> <span class=\"ar\">حَلْق</span> [or <i>fauces</i>] <i>of a man, like the</i> <span class=\"ar\">ذِئْبَة</span> <i>that attacks the ass:</i> (ISh, TA:) or <i>an ulcer that appears in that part, obstructing it, and stopping the breath, and killing.</i> (TA.) One says, <span class=\"ar\">أَخَذَتْهُ</span> <span class=\"ar\">الذُّبَحَةُ</span> [<i>The</i> <span class=\"ar\">ذبحة</span> <i>attacked him</i>]. (S.) And <span class=\"ar\">الطَّمَعُ <span class=\"ar\">ذُبَاحٌ</span></span> (tropical:) <i>Covetousness is</i> [<i>like</i>] <i>a disease in the fauces:</i> or <i>a poisonous plant.</i> (A.) And <span class=\"ar\">كَانَ ذٰلِكَ مِثْلَ الذُّبَحَةِ عَلَى النَّحْرِ</span> [<i>That was like the disease called</i> <span class=\"ar\">ذبحة</span> <i>in the uppermost part of the breast</i>]: a prov., applied to the case of a man whom one imagines to be a sincere friend, and who proves to be an evident enemy: (TA:) or <span class=\"ar\">كَانَ مِثْلَ الذُّبَحَةِ الخ</span> <i>He was like the</i> <span class=\"ar\">ذبحة</span> &amp;c., a disease in the <span class=\"ar\">حَلْق</span>, which does not quit the patient externally, and hurts him internally: said by him to whom you complain of one whom you imagined to be a sincere friend, and whose affection was outward, when his deceit has become manifest. (Meyd.) -A2- <span class=\"ar\">دُبَحَةٌ</span> is also the n. un. of <span class=\"ar\">ذُبَحٌ</span> [q. v.]. (Fr, AHn.)</p><p><b class=\"ar\">ذِبَحَةٌ</b> : see the next preceding paragraph. -A2- It is also the n. un. of <span class=\"ar\">ذِبَحٌ</span> [q. v. voce <span class=\"ar\">ذَُبَحٌ</span>]. (Fr, AHn.)</p><p><b class=\"ar\">ذُبَاحٌ</b> <i>A certain poisonous plant,</i> (A, K, TA,) <i>that kills the eater of it;</i> as also <span class=\"ar\"> <span class=\"ar\">ذُبَحٌ</span></span>. (TA.) One says, <span class=\"ar\">الطَّمَعُ . ذُبَاحٌ</span>: see <span class=\"ar\">ذُبَحَةٌ</span>, in two places. -b2- [Hence,] <span class=\"ar\">مَوْتٌ ذُبَاحٌ</span> (assumed tropical:) <i>A quick,</i> or <i>sudden, death.</i> (L.) -A2- See also <span class=\"ar\">ذُبَّاحٌ</span>.</p><p><b class=\"ar\">ذِبَاحٌ</b> : see <span class=\"ar\">ذُبَحَةٌ</span>.</p><p><b class=\"ar\">ذَبِيحٌ</b> and <span class=\"ar\"> <span class=\"ar\">مَذْبُوحٌ</span></span> signify the same [i. e. <i>Cut,</i> or <i>divided, lengthwise;</i> &amp;c.: see 1]. (S, Msb, K, TA.) You say <span class=\"ar\">مِسْكٌ ذَبِيحٌ</span> [for <span class=\"ar\">ذَبِيحٌ فَأْرَتُهُ</span>], meaning (assumed tropical:) [<i>Musk of which the follicle,</i> or <i>vesicle, is</i>] <i>ripped open.</i> (A. [It is there said to be tropical: but see 1.]) -b2- Both are [also] applied to an animal, (Msb,) or a sheep or goat, (TA,) [or an animal of the ox-kind, and a sheep or goat, and the like, (see 1,)] as meaning <i>Slaughtered, in the manner described in the first paragraph of this art.:</i> (TA:) the fem. of <span class=\"ar\">ذَبِيحٌ</span> is with <span class=\"ar\">ة</span>: (S, TA: [see <span class=\"ar\">ذَبِيحَةٌ</span> below:]) but <span class=\"ar\">ذَبِيحٌ</span> is used as a fem. epithet without the addition of <span class=\"ar\">ة</span>: you say <span class=\"ar\">شَاةٌ ذَبِيحٌ</span> as well as <span class=\"ar\">كَبْشٌ ذَبِيحٌ</span>, because <span class=\"ar\">ذَبِيحٌ</span> is an instance of the measure <span class=\"ar\">فَعِيلٌ</span> in the sense of the measure <span class=\"ar\">مَفْعُولٌ</span>; though you say <span class=\"ar\">شاة ذَبِيحَةٌ</span> also; and in like manner <span class=\"ar\">نَاقَةٌ</span>: the pl. [of <span class=\"ar\">ذَبِيحٌ</span>] is <span class=\"ar\">ذَبْحَى</span> and <span class=\"ar\">ذَبَاحَى</span> and [that of <span class=\"ar\">ذَبِيحَةٌ</span> is] <span class=\"ar\">ذَبَائِحُ</span>. (TA.) Aboo-Dhu-eyb says, describing wine, <span class=\"ar\">يُقَالُ لَهَا دَمُ الوَدَجِ الذَّبِيحُ</span> meaning <span class=\"ar\">المَذْبُوحُ عَنْهُ</span>, i. e. [<i>One would call it the blood of the external jugular vein,</i>] <i>for which it had been slit</i> [to let it flow]. (AAF, TA.) And again he says, <span class=\"ar\">وَسِرْبٍ تَطَلَّى بِالعَبِيرِ كَأَنَّهُ</span> <span class=\"ar\">دِمَآءُ ظِبَآءُ بِالنُّحُورِ ذَبِيحُ</span> [app. meaning <i>And many a bevy of women rubbed over with perfume compounded with saffron, as though it were the blood of gazelles,</i> the gazelles whereof had been <i>slaughtered in the upper parts of the breasts</i>]: he applies <span class=\"ar\">ذبيح</span> as an epithet to <span class=\"ar\">دمآء</span>, meaning <span class=\"ar\">ذَبِيحٌ ظِبَاؤُهُ</span>; and he applies it as an epithet to a pl. n. because it is of the measure <span class=\"ar\">فَعِيلٌ</span> [in the sense of the measure <span class=\"ar\">مَفْعُولٌ</span>], for such an epithet is applicable to masc. and fem. and sing. and pl. nouns. (TA.) -b3- <span class=\"ar\">ذَبِيحٌ</span> also signifies <i>An animal that is fit,</i> or <i>proper, to be slaughtered as a sacrifice:</i> (ISk, S, K:) [or <i>that is destined, or prepared, for sacrifice;</i> i. e., <i>an intended victim;</i> like <span class=\"ar\">ذِبْحٌ</span>; as appears from the fact that] <span class=\"ar\">الذَّبِيحُ</span> is (assumed tropical:) a surname of <i>Ismá'eel,</i> or <i>Ishmael;</i> (K, * TA;) for, accord. to some [or rather the generality] of the Muslims, he was the son whom Abraham designed to sacrifice, though others say it was Isaac: (TA:) and <span class=\"ar\">أَنَا ٱبْنُ</span> <span class=\"ar\">الذَّبِيحَيْنِ</span> occurs in a trad. [as said by Mohammad, meaning (assumed tropical:) <i>I am the son of the two intended victims;</i> namely, <i>Ismá'eel and 'Abd-Allah</i>]; for 'Abd-El-Muttalib incurred the obligation to sacrifice his son 'Abd-Allah, the father of the Prophet, by reason of a vow, and ransomed him with a hundred camels. (K, * TA.) -b4- Also (tropical:) A <i>slain man.</i> (A.)</p><p><b class=\"ar\">ذَبِيحَةٌ</b> , and its pl. <span class=\"ar\">ذَبَائِحُ</span>: see <span class=\"ar\">ذِبْحٌ</span>, in three places.</p><p>[ <b class=\"ar\">ذَبَّاحٌ</b> One <i>whose occupation,</i> or <i>habit, is that of slaughtering sheep or the like.</i> -b2- And, in the present day, (assumed tropical:) <i>An executioner.</i>]</p><p><b class=\"ar\">ذُبَّاحٌ</b> (T, S, K) and sometimes <span class=\"ar\"> <span class=\"ar\">ذُبَاحٌ</span></span>, without teshdeed, (T, K,) the former the more common, (T, K,) but disallowed by AHeyth, who holds it to be one of the words of the measure <span class=\"ar\">فُعَالٌ</span> denoting diseases, (TA,) (tropical:) <i>Cracks in the inner</i> [i. e. <i>lower</i>] <i>sides of the toes,</i> (S, K, TA,) <i>next the fore part of the foot:</i> (TA:) or <i>a cut across the inner sides of the toes:</i> (Ibn-Buzurj, T:) or <i>a crack in the inner side,</i> or <i>sole, of the foot:</i> (IAar, TA voce <span class=\"ar\">نَكْبَةٌ</span>:) pl. <span class=\"ar\">ذَبَابِيحُ</span>. (TA.) Hence the saying, <span class=\"ar\">مَا دُونَهُ شَوْكَةٌ وَلَا ذُبَّاحٌ</span> (tropical:) [<i>There is not in the way of its attainment a thorn nor are</i> <i>there any cracks in the inner sides of the toes,</i> &amp;c.: see also <span class=\"ar\">نَكْبَةٌ</span>]. (S, TA.)</p><p><b class=\"ar\">ذَابِحٌ</b> [act. part. n. of 1]. <span class=\"ar\">سَعْدُ الذَّابِحِ</span>, (S, K,) or <span class=\"ar\">سَعْدٌ الذَّابِحُ</span>, (so in one copy of the S,) (assumed tropical:) <i>Two bright stars, between which is the space of a cubit</i> (<span class=\"ar\">ذِرَاع</span>), <i>over against one of which</i> (<span class=\"ar\">فِىنَحْرِ وَاحِدٍ</span> <span class=\"ar\">مِنْهُمَا</span>) <i>is a small star that, by reason of its nearness, is as though it</i> [app. meaning the bright star, or the pair of bright stars,] <i>were about to slaughter it;</i> (S, K;) whence the appellation of <span class=\"ar\">الذَّابِح</span>: (S:) <i>the two stars</i> [<i>alpha and beta</i>] <i>which are in one of the horns of Capricornus;</i> so called because of the small adjacent star, which is said to be the sheep or goat (<span class=\"ar\">شاة</span>) of <span class=\"ar\">الذابح</span>, which he is about to slaughter: (Kzw:) it is <i>one of the Mansions of the Moon;</i> (S, Kzw;) [namely, <i>the Twenty-second Mansion:</i> see also art. <span class=\"ar\">سعد</span>: some give this appellation to <i>the Twenty-third Mansion:</i> and some, to <i>the Twenty-fifth;</i> but the two stars above mentioned are clearly the Twenty-second, with the place of which they agree accord. to those who make <span class=\"ar\">النَّوءُ</span> to signify “ the auroral rising ” and those who make it to signify “ the auroral setting: ” see <span class=\"ar\">مَنَازِلُ القَمَرِ</span>, in art. <span class=\"ar\">نزل</span>.] The Arabs [used to] say, <span class=\"ar\">إِذَا طَلَعَ</span> <span class=\"ar\">الذَّابِحُ ٱنْجَحَرَ النَّابِحُ</span> (assumed tropical:) [<i>When</i> <span class=\"ar\">الذابح</span> <i>rises aurorally, the barker enters,</i> or <i>betakes itself to, its hole:</i> the period of its auroral rising, in Central Arabia, about the commencement of the era of the Flight, being the 16th of January, O. S.]. (TA.) -b2- (assumed tropical:) <i>A mark made with a hot iron across the throat:</i> or (assumed tropical:) the <i>instrument with which it is made.</i> (L, K.) -b3- (assumed tropical:) <i>Hair growing between the part immediately beneath the lower jaw and the part</i> [<i>of the throat</i>] <i>in which an animal is slaughtered.</i> (K.)</p><p><b class=\"ar\">ذَابِحَةٌ</b> , of the measure <span class=\"ar\">فَاعِلَةٌ</span> in the sense of the measure <span class=\"ar\">مَفْعُولَةٌ</span>, [with <span class=\"ar\">ة</span> affixed because the quality of a subst. is predominant in it,] <i>Any animal which it is allowable to slaughter, of camels, and bulls or cows, and sheep or goats, &amp;c.</i> (TA.)</p><p><b class=\"ar\">مَذْبَحٌ</b> The <i>place of</i> [<i>the slaughter termed</i>] <span class=\"ar\">الذَّبْح</span>: (K:) i. e. the <i>place,</i> or <i>spot of ground, where</i> <span class=\"ar\">الذبح</span> <i>is performed:</i> and the <i>part of the throat which is the place of</i> <span class=\"ar\">الذبح</span>, <i>which is that below the part beneath the lower jaw;</i> (MF, TA;) or the <span class=\"ar\">حُلْقُوم</span> [i. e. <i>windpipe</i>]. (Msb.) -b2- (tropical:) The <i>chancel</i> of a church; i. e. the <i>part</i> of a church <i>that is like the</i> <span class=\"ar\">مِحْرَاب</span> of a mosque: (A, * K, * Msb:) pl. <span class=\"ar\">مَذَابِحُ</span>: (A, Msb, K:) the <span class=\"ar\">مَذَابِح</span> are the <span class=\"ar\">مَحَارِيب</span> (S, A, K) of the Christians; (A;) so called because of the oblations (<span class=\"ar\">قَرَابِين</span>) there offered; (S, TA;) the <span class=\"ar\">مَقَاصِير</span> (K, TA) in churches, pl. of <span class=\"ar\">مَقْصُورَةٌ</span>; said to be the same as the <span class=\"ar\">محاريب</span>: (TA:) and the <i>places,</i> (A,) or <i>chambers,</i> (K,) <i>of the books</i> of the Christians. (A, K.) -b3- (tropical:) <i>A trench</i> (S, A, K) <i>in the earth, measuring a span or the like</i> [<i>in width</i>], (S, K,) <i>such as is made by a torrent:</i> (S, A:) the <i>channel of a torrent in the lower part of the face of a mountain,</i> or <i>in a plain depressed tract, in width equal to the space measured by the extension of the thumb and first finger or little finger;</i> and sometimes it is <i>a natural trench in a plain tract of land, like a river, in which flows the water of that land:</i> it is <i>in all descriptions of land; in valleys &amp;c., and in depressed tracts:</i> (L:) and <i>a kind of river;</i> as though it clave [the earth] or were cleft: (TA:) pl. <span class=\"ar\">مَذَابِحُ</span>. (S, A, L.) You say, <span class=\"ar\">غَادَرَ السَّيْلُ فِى الأَرْضِ مَذَابِحَ</span> (assumed tropical:) [<i>The torrent left in the ground trenches about a span wide</i>]. (S.)</p><p><b class=\"ar\">مِذْبَحٌ</b> <i>A knife with which</i> [<i>the slaughter termed</i>] <span class=\"ar\">الذَّبْح</span> <i>is performed:</i> (Msb:) or <i>a thing with which an animal is slaughtered in the manner termed</i> <span class=\"ar\">ذَبْح</span>, (T, K, *) <i>whether it be a knife or some other thing.</i> (T.)</p><p><b class=\"ar\">مَذْبُوحٌ</b> : see <span class=\"ar\">ذَبِيحٌ</span>. -b2- [Hence,] (assumed tropical:) <i>Clean,</i> or <i>pure; not requiring to be slaughtered;</i> [as though it had been already slaughtered;] an epithet applied in a trad. to everything in the sea. (TA.) -b3- See also 1, last sentence.</p>"},"ذرع":{"mf":"الذّراع: العضو المعروف، ويعبّر به عن المذروع، أي: الممسوح بالذّراع. قال تعالى: فِي سِلْسِلَةٍ ذَرْعُها سَبْعُونَ ذِراعاً فَاسْلُكُوهُ [الحاقة/ ٣٢]، يقال: ذراع من الثّوب والأرض، وذراع الأسد: نجم، تشبيها بذراع الحيوان، وذراع العامل: صدر القناة <strong>«٦»</strong>، ويقال: هذا على حبل ذراعك <strong>«٧»</strong>، كقولك: هو<br><br>في كفّك، وضاق بكذا ذرعي، نحو: ضاقت به يدي، وذَرَعْتُهُ: ضربت ذراعه، وذَرَعْتُ: مددت الذراع، ومنه: ذَرَعَ البعير في سيره، أي: مدّ ذراعه، وفرس ذريع وذروع: واسع الخطو، ومذرّع: أبيض الذّراع، وزِقٌّ ذراع، قيل: هو العظيم، وقيل: هو الصّغير، فعلى الأوّل هو الذي بقي ذراعه، وعلى الثاني هو الذي فصل ذراعه عنه. وذَرَعَهُ القيء: سبقه. وقولهم: ذَرَعَ الفرس، وتذرّعت المرأة الخوص <strong>«١»</strong>، وتذرّع في كلامه <strong>«٢»</strong>، تشبيها بذلك، كقولهم: سفسف في كلامه، وأصله من سفيف الخوص.","mq":[["امتداد وتحرك الي قدم"],"الذال والراء والعين أصلٌ واحدٌ يدلُّ على امتدادٍ وتحرُّك إلى قُدُم، ثم ترجع الفروعُ إلى هذا الأصل. فالذِّراع ذِراع الإنسان، معروفة.<br>والذَّرع: مصدر ذَرَعْتُ الثَّوبَ والحائطَ وغيرَه. ثمّ يقال: ضاق بهذا الأمر ذَرْعاً، إذا تكلَّفَ أكثَرَ ممّا يطيق فَعَجَز. ويقال ذَرَعَهُ القَئ: سبقَه. ومَذَارِعُ الدَّا"],"ln":"<p><b>1.</b> <b class=\"ar\">ذَرْعٌ</b> , [inf. n. of <span class=\"ar\">ذَرَعَ</span>,] in its primary acceptation, signifies The <i>stretching forth,</i> or <i>extending, the arm,</i> or <i>fore leg:</i> (S, TA:) [or rather, when said of a man, <i>the fore arm;</i> and of a beast, <i>the arm;</i> though the whole arm of a man is generally stretched forth with his fore arm, and the whole fore leg of a beast with his arm: and <span class=\"ar\"> <span class=\"ar\">تَذْرِيعٌ</span></span> and <span class=\"ar\"> <span class=\"ar\">إِذْرَاعٌ</span></span> and <span class=\"ar\"> <span class=\"ar\">تَذَرُّعٌ</span></span> signify the same, as will be shown by explanations of their verbs.] You say, <span class=\"ar\">ذَرَعَ البَعِيرُ يَدَهُ</span> <i>The camel stretched forth,</i> or <i>extended, his fore leg</i> in going: and <span class=\"ar\"> <span class=\"ar\">تذرّع</span>البَعِيرُ</span> <i>The camel stretched forth,</i> or <i>extended, his arm</i> (<span class=\"ar\">ذِرَاعَهُ</span>) in his going. (TA.) -b2- <span class=\"ar\">ذَرَعَهُ</span>, (S, Msb, K,) aor. <b class=\"ar\">ذَرَعَ</b> , (Msb, K,) inf. n. <span class=\"ar\">ذَرْعٌ</span>, (S, Msb,) <i>He measured it with the</i> <span class=\"ar\">ذِرَاعٌ</span> [or <i>cubit</i>]; (Msb, K;) namely, a garment, or piece of cloth, (S, Msb, K,) &amp;c.: (S:) and <span class=\"ar\">ذَرَعَهُ بِذِرَاعِهِ</span> <i>he measured it with his</i> <span class=\"ar\">ذراع</span>. (TA.) [See also 5.] -b3- You say of a she-camel, <span class=\"ar\">تَذْرَعُ الفَلَاةَ</span> (assumed tropical:) <i>She goes quickly,</i> or <i>swiftly, over the desert, as though measuring it;</i> as also <span class=\"ar\"> <span class=\"ar\">تُذَارِعُهَا</span></span>: and <span class=\"ar\"> <span class=\"ar\">تُذَارِعُ</span>بُعْدَالطَّرِيقِ</span> (tropical:) <i>She stretches forth her fore legs and so traverses the distance of the way.</i> (TA.) -b4- <span class=\"ar\">ذَرَعَ فُلَانًا</span> <i>He strangled,</i> or <i>throttled, such a one from behind him with the fore arm;</i> (Ibn-'Abbád, K;) as also <span class=\"ar\"> <span class=\"ar\">ذرّعهُ</span></span>: (K:) or the latter, inf. n. <span class=\"ar\">تَذْرِيعٌ</span>, signifies, simply, <i>he strangled,</i> or <i>throttled, him;</i> (S, L;) but more properly, <i>he put his neck between his fore arm and neck and upper arm, and so strangled,</i> or <i>throttled, him;</i> and <span class=\"ar\"> <span class=\"ar\">ذرّع</span>لَهُ</span>, also, has both of these significations. (L.) -b5- <span class=\"ar\">ذَرَعَ</span> <span class=\"ar\">البَعِيرَ</span>, (K,) aor. and inf. n. as above, (TA,) <i>He trod upon the arm</i> (<span class=\"ar\">ذراع</span>) <i>of the camel,</i> [<i>while the latter was lying with his breast upon the ground and his fore legs folded,</i>] <i>in order that a person might mount him.</i> (K.) -A2- <span class=\"ar\">ذَرَعَهُ القَىْءُ</span>, (S, Mgh, Msb, K,) aor. as above, (Mgh,) and so the inf. n., (Msb,) <i>Vomit overcame him, and came forth to his mouth before he was aware,</i> (S, * Mgh, Msb, * K, * TA,) <i>and issued from him:</i> (Mgh:) or <i>vomiting came upon him without his intending it.</i> (Mgh.) -A3- <span class=\"ar\">ذَرَعَ عِنْدَهُ</span>, (Ibn-'Abbád, K,) inf. n. as above, (Ibn-'Abbád,) (tropical:) <i>He made intercession with him.</i> (Ibn-'Abbád, K.) [Said in the TA to be tropical; I suppose because the stretching forth the arm is a common action of a person interceding.] You say, <span class=\"ar\">ذَرَعْتُ لِفُلَانٍ عِنْدَ</span> <span class=\"ar\">الأَمِيرِ</span> (tropical:) <i>I made intercession for such a one with the prince.</i> (Z, TA.) And <span class=\"ar\">ذَرِعَ إِلَيْهِ</span>, like <span class=\"ar\">فَرِحَ</span>, (Ibn-'Abbád, K,) inf. n. <span class=\"ar\">ذَرَعٌ</span>, (TK,) (assumed tropical:) <i>He made intercession to him.</i> (Ibn-'Abbád, K.) In the O, <span class=\"ar\">ذَرِعَ بِهِ</span> (assumed tropical:) <i>He made intercession</i> [<i>by him</i>]. (TA.) -A4- <span class=\"ar\">ذَرِعَ</span>, aor. <b class=\"ar\">ذَرَعَ</b> , <i>He drank from a skin</i> (<span class=\"ar\">زِقّ</span>) <i>such as is called</i> <span class=\"ar\">ذَارِعٌ</span>. (K.) -A5- <span class=\"ar\">ذَرِعَتْ رِجْلَاهُ</span> <i>His legs became tired,</i> or <i>fatigued.</i> (Ibn-'Abbád, K.) -A6- <span class=\"ar\">ذَرَاعَةٌ</span> [app. an inf. n., of which the verb is <span class=\"ar\">ذَرُعَ</span>,] <i>The being wide in step,</i> (S, TA,) <i>and light,</i> or <i>active, in pace,</i> or <i>going.</i> (TA.)</p><p><b>2.</b> <b class=\"ar\">ذرّع</b> , (S, K, &amp;c.,) inf. n. <span class=\"ar\">تَذْرِيعٌ</span>: (S:) see 1, first sentence. -b2- Also <i>He spread himself out widely,</i> (El-Moheet, L, K,) <i>and stretched forth his fore arms,</i> (El-Moheet, L,) in swimming: (El-Moheet, L, K:) said of a man. (El-Moheet, L.) -b3- <i>He</i> (a man) <i>raised his fore arms;</i> and particularly, in announcing good tidings or in warning: (TA:) or <i>he</i> (an announcer of good tidings) <i>made a sign with his arm,</i> or <i>hand.</i> (S, K.) -b4- <span class=\"ar\">ذرّع فِى المَشْىِ</span> <i>He moved about his fore arms in walking,</i> or <i>going along.</i> (S, K.) And <span class=\"ar\">ذرّع فى السَّعْىِ</span>, (L, TA,) in the O and Moheet and K, erroneously, <span class=\"ar\">فىالسَّقْىِ</span>, (TA,) <i>He helped himself with his arms, and moved them about,</i> (O, El-Moheet, L, K,) <i>in walking,</i> or <i>walking quickly,</i> or <i>running.</i> (L.) -b5- <span class=\"ar\">ذرّع لِى</span> <span class=\"ar\">شَيْئًا مِنْ خَبَرِهِ</span> (tropical:) <i>He acquainted me with somewhat of his tidings,</i> or <i>case;</i> (K, TA;) [as though he stretched forth his arm with his information;] said by one who has asked another respecting his case. (TA.) -b6- [And hence, app.,] <span class=\"ar\">ذرّع بِكَذَا</span> (assumed tropical:) <i>He acknowledged,</i> or <i>confessed, such a thing.</i> (K, TA.) -b7- <span class=\"ar\">ذرّع فُلَانًا</span> and <span class=\"ar\">ذرّع لَهُ</span>: see 1. -b8- [Hence, perhaps,] <span class=\"ar\">ذرّعهُ</span>, inf. n. as above. (assumed tropical:) <i>He killed him;</i> or <i>slew him.</i> (TA.) -b9- <span class=\"ar\">ذرّع البَعِيرَ</span>, and <span class=\"ar\">ذرّع لَهُ</span>, <i>He bound both of the arms of the camel</i> [<i>to the shanks</i>]: (K:) and the latter, <i>he</i> <i>bound the camel with the redundant part of his nose-rein upon his</i> [the camel's] <i>arm.</i> (K, TA.) [See also <span class=\"ar\">تَذْرِيعٌ</span> below.] -b10- <span class=\"ar\">تَذْرِيعٌ</span> also signifies The <i>tinging a captive's fore arm with crocus,</i> or <i>with</i> <span class=\"ar\">خَلُوق</span>, <i>as a sign of slaughter;</i> which was done in the time before Mohammad. (Meyd, cited by Freytag.) -b11- [See also the act. and pass. part. ns., below.]</p><p><b>3.</b> <b class=\"ar\">مُذَارَعَةٌ</b> signifies The <i>selling by measure with the cubit; not by number, and without knowing the measure.</i> (K.) [In the CK, <span class=\"ar\">والجُزافُ</span> is put by mistake for <span class=\"ar\">والجُزافِ</span>.] You say, <span class=\"ar\">بِعْتُهُ</span> <span class=\"ar\">الثَّوْبَ مُذَارَعَةٌ</span> <i>I sold to him the garment,</i> or <i>piece of cloth, by measure with the cubit.</i> (TA.) -b2- See also 1, in two places. -b3- <span class=\"ar\">ذَرَاعْتُهُ</span>, (TA,) inf. n. <span class=\"ar\">مُذَارَعَةٌ</span>, (K, TA,) (assumed tropical:) <i>I mixed with him in familiar,</i> or <i>social, intercourse;</i> or <i>became intimate with him:</i> or <i>I became copartner with him;</i> or <i>shared with him:</i> syn. <span class=\"ar\">خَالَطْتُهُ</span>. (K * TA.)</p><p><b>4.</b> <b class=\"ar\">اذرع</b> , (K,) inf. n. <span class=\"ar\">إِذْرَاعٌ</span>: (S:) see 1, first sentence. -b2- (tropical:) <i>He exceeded the due bounds,</i> or <i>just limits, in speech,</i> or <i>talk;</i> (S, K, TA;) <i>he talked much;</i> (S, TA;) as also <span class=\"ar\"> <span class=\"ar\">تذرّع</span></span>: (S, Msb, * K, TA:) J says, [in the S,] I am of opinion that it has originated from the stretching forth of the fore arm; for he who talks much sometimes does that; and ISd says the like. (TA.) -b3- <span class=\"ar\">أَذْرَعَ ذِرَاعَيْهِ</span> <span class=\"ar\">مِنْ تَحْتِ الجُبَّةِ</span> and <span class=\"ar\"> <span class=\"ar\">اِذَّرَعَهُمَا</span></span>, <i>He put forth,</i> (K, TA,) <i>and extended,</i> (TA,) <i>his fore arms from beneath the jubbeh:</i> (K, TA:) or <span class=\"ar\">أَذْرَعَ ذِرَاعَيْهِ</span>, and <span class=\"ar\"> <span class=\"ar\">اِدَّرَعَهُمَا</span></span>, [the latter with the <span class=\"ar\">د</span> unpointed,] <i>he drew forth his fore arms</i> from the sleeves of a narrow-sleeved jubbeh: (Mgh:) the latter verb being of the measure <span class=\"ar\">اِفْتَعَلَ</span>; (Mgh, K;) like <span class=\"ar\">اِذَّكَرَ</span>, (TA,) or <span class=\"ar\">اِدَّكَرَ</span>, (Mgh,) from <span class=\"ar\">الذِّكْرُ</span>: (Mgh, TA:) the former accord. to one relation, the latter accord. to another, occurring in a trad. (Mgh, TA.) -b4- <span class=\"ar\">اذرع</span> also signifies <i>He seized with the fore arm.</i> (K.) -b5- <span class=\"ar\">مَا أَذْرَعَهَا</span> [<i>How long,</i> or <i>large, is she in the fore arm!</i>] is [from <span class=\"ar\">الذِّرَاعُ</span>, being] of the same [anomalous] class as <span class=\"ar\">أَحْنَكُ</span> <span class=\"ar\">الشَّاتَيْنِ</span> [from <span class=\"ar\">الحَنَكُ</span>]. (TA.) -A2- <span class=\"ar\">اذرع قَيْئَهُ</span> <i>He</i> (a man) <i>emitted,</i> or <i>ejected, his vomit.</i> (TA.)</p><p><b>5.</b> <b class=\"ar\">تَذَرَّعَ</b> see 1; first and second sentences: -b2- and see also 4. -b3- <span class=\"ar\">تَذَرُّعٌ</span> also signifies The <i>measuring</i> a thing <i>with the fore arm.</i> (S, K.) [See also 1.] A poet says, (S,) namely Keys Ibn-El-Khateem El-Ansáree, (TA,) <span class=\"ar\">تَرَى قِصَدَ المُرَّانِ تُلْقَى كَأَنَّهَا</span> <span class=\"ar\">تَذَرُّعُ خِرْصَانٍ بِأَيْدِىالشَّوَاطِبِ</span> [<i>Thou seest the fragments of the hard and pliant spears thrown as though they were</i> what is seen in <i>the measuring, with the fore arm, of rods of palm-sticks in the hands of the females who pare them</i>]: (S, TA:) or, accord. to As, <span class=\"ar\">تَذَرَّعَ فُلَانٌ</span> <span class=\"ar\">الجَرِيدَ</span> signifies <i>Such a one put the palm-sticks upon his fore arm, and pared them:</i> and <span class=\"ar\">خِرْصَانٌ</span> means, originally, rods of palm-sticks: and <span class=\"ar\">شَوَاطِبُ</span> is pl. of <span class=\"ar\">شَاطِبَةٌ</span>; meaning a woman who peels the <span class=\"ar\">عَسِيب</span>, and then throws it to the <span class=\"ar\">مُنَقِّيَة</span>, who removes all that is upon it with her knife until she has left it slender, when she throws it back to the <span class=\"ar\">شاطبة</span>. (TA.) -b4- Also, The <i>splitting</i> (<span class=\"ar\">تَشَقُّق</span> [which is intrans., but I think it is a mistake for <span class=\"ar\">تَشْقِيق</span>, which is trans.,]) of a thing <i>into several oblong pieces of the measure of the cubit in length.</i> (Ibn-'Abbád, K.) -b5- <span class=\"ar\">تَذَرَّعَتِ المَرْأَةُ</span> <i>The woman split palm-leaves to make of them a mat.</i> (IDrd, K.) Thus some explain the saying of Ibn-El-Khateem, quoted above. (TA.) -b6- <span class=\"ar\">تَذَرَّعَتِ الإِبِلُ الكَرَعَ</span> <i>The camels came to drink of the rain-water and waded in it with their arms.</i> (K.) -A2- <span class=\"ar\">تذرّع بِذَرِيعَةٍ</span> (tropical:) <i>He obtained,</i> or <i>sought to obtain, access,</i> or <i>intimacy;</i> or <i>he ingratiated himself,</i> or <i>sought to ingratiate himself; by a means of doing so.</i> (S, K, TA.) You say, also, <span class=\"ar\">تذرّع إِلَيْهِ</span> (tropical:) <i>He obtained,</i> or <i>sought to obtain, access to him;</i> &amp;c. (TA.)</p><p><b>8.</b> <b class=\"ar\">اِذَّرَعَ</b> or <span class=\"ar\">إِدَّرَعَ</span>: see 4.</p><p><b>10.</b> <b class=\"ar\">استذرع بِهِ</b> <i>He concealed,</i> or <i>protected, himself by it,</i> (namely a thing, TA,) <i>and made it a</i> <span class=\"ar\">ذَرِيعَة</span> [q. v.] <i>for him.</i> (Ibn-'Abbád, K.)</p><p><b class=\"ar\">ذَرْعٌ</b> , in its primary acceptation, has the signification explained in the first sentence of this article. (S, TA.) -b2- [Hence, it is used in the sense of] (tropical:) <i>Power,</i> or <i>ability;</i> as also <span class=\"ar\"> <span class=\"ar\">ذِرَاعٌ</span></span>; (TA;) or a man's <i>reach,</i> or <i>extent of power</i> or <i>ability.</i> (Msb.) And hence the phrases, <span class=\"ar\">ضَاقَ بِالأَمْرِ ذَرْعُهُ</span>, and <span class=\"ar\"> <span class=\"ar\">ذِرَاعُهُ</span></span>, (K,) and <span class=\"ar\">ضَاقَ بِالأَمْرِ ذَرْعًا</span>, (S, Msb, K,) in which the last word is in the accus. case as an explicative, for the original form of the phrase is that first mentioned, (TA,) and sometimes they said <span class=\"ar\"> <span class=\"ar\">ذِرَاعًا</span></span>, (S, TA,) (tropical:) <i>He was unable to do,</i> or <i>accomplish, the thing,</i> or <i>affair;</i> as though meaning, he stretched forth his arm to it and it did not reach it; (S, TA; *) or these phrases are thus used because he who is short in the fore arm will not reach that which he who is long therein reaches, nor will the power of the former equal that of the latter; therefore they are proverbially applied to him whose power falls short of the attainment, or accomplishment, of an affair: (TA:) or <i>he lacked strength,</i> or <i>power,</i> or <i>ability, to do,</i> or <i>accomplish, the thing,</i> or <i>affair, and found not any way of escape from what was disagreeable therein:</i> (K:) or <i>he was unable to bear,</i> or <i>endure,</i> or <i>undertake, the thing,</i> or <i>affair.</i> (Msb.) You say also, <span class=\"ar\">مَا لِى بِهِ ذَرْعٌ</span>, and <span class=\"ar\"> <span class=\"ar\">ذِرَاعٌ</span></span>, (tropical:) <i>I have not power,</i> or <i>ability, to do it.</i> (TA.) And <span class=\"ar\">كَسَرَ ذٰلِكَ مِنْ ذَرْعِى</span> (tropical:) <i>That disabled, hindered, prevented,</i> or <i>withheld, me from doing that which I desired.</i> (TA.) And <span class=\"ar\">اِقْصِدْ بِذَرْعِكَ</span> (tropical:) <i>Deal thou gently with thyself; moderate thyself restrain thyself; i. q.</i> <span class=\"ar\">اِرْبَعْ عَلَى نَفْسِكَ</span>; (S, TA;) <i>and let not thy soul,</i> or <i>mind, carry thee beyond thy measure</i> or <i>extent</i> [<i>of power</i> or <i>ability</i>]. (TA.) And <span class=\"ar\">أَبْطَرْتُ فُلَانًا ذَرْعهُ</span> (tropical:) <i>I imposed upon such a one more than he was able to do:</i> (S, TA:) but <span class=\"ar\">ذَرْعٌ</span> also signifies (assumed tropical:) the <i>body:</i> and [accord. to IAar] <span class=\"ar\">أَبَطَرَنِى ذَرْعِى</span> means (tropical:) <i>He wasted my body, and cut off my means of subsistence.</i> (TA.) [See also art. <span class=\"ar\">بطر</span>.] You likewise say, <span class=\"ar\">رَحْبُ <span class=\"ar\">الذِّرَاعِ</span>رَجُلٌ</span> [and <span class=\"ar\">الذَّرْعِ</span>] (tropical:) <i>A man having ample strength, and power, and might in war or fight, courage, valour,</i> or <i>prowess.</i> (TA. [See also <span class=\"ar\">رَحْبٌ</span>.]) And <span class=\"ar\">ضَعِيفُ الذَّرْعِ</span> (tropical:) <i>Impotent.</i> (KL.) -b3- And hence, <span class=\"ar\">فُلَانٌ خَالِى الذَّرْعِ</span> (tropical:) <i>Such a one has his heart devoid of anxieties,</i> or <i>solicitudes, and griefs;</i> because the heart is sometimes one of the seats of power: or it may mean, agreeably with the original signification of <span class=\"ar\">ذَرْعٌ</span>, <i>such a one is free from the causes of occupation which require the stretching forth of the fore arm and extending of the hand.</i> (Har p. 131.) And <span class=\"ar\">رَجُلٌ وَاسِعٌ الذَّرْعِ</span>, and <span class=\"ar\"> <span class=\"ar\">الذِّرَاعِ</span></span>, (tropical:) <i>A man large,</i> or <i>liberal, in disposition.</i> (K.) And <span class=\"ar\">كَبُرَ فِى ذَرْعِى</span> (assumed tropical:) <i>Its occurrence,</i> or <i>befalling, was of great moment, momentous, grievous,</i> or <i>distressing, to me.</i> (TA.) -b4- <span class=\"ar\">ذَرْعٌ</span> also signifies The <i>measure</i> of anything: and <span class=\"ar\">نَخْلَةٌ ذَرْعُ رَجَلٍ</span>, <i>A palm-tree of the measure of the stature of a man.</i> (TA.)</p><p><b class=\"ar\">ذَرَعٌ</b> <i>A coveting; desiring eagerly;</i> or <i>lusting.</i> (S, K.) [Perhaps an inf. n. of which the verb is <span class=\"ar\">ذَرِعَ</span>.] -A2- See also <span class=\"ar\">ذَرِيعَةٌ</span>.</p><p><b class=\"ar\">ذَرِعٌ</b> : see <span class=\"ar\">ذَرِيعٌ</span>, in two places. -b2- (assumed tropical:) <i>That journeys by night and by day.</i> (K.) -b3- (assumed tropical:) <i>Longtongued with evil speech.</i> (K.) -A2- (assumed tropical:) <i>Good in social,</i> or <i>familiar, intercourse.</i> (K, TA.)</p><p><b class=\"ar\">ذُرْعَةٌ</b> : see <span class=\"ar\">ذَرِيعَةٌ</span>.</p><p><b class=\"ar\">ذَرَاعٌ</b> (S, K) and <span class=\"ar\"> <span class=\"ar\">ذِرَاعٌ</span></span> (ISd, K) (assumed tropical:) A woman (S) <i>light,</i> or <i>active, with the hands in spinning:</i> (S, K:) or one <i>who spins much; who has ability to do so.</i> (TA.)</p><p><b class=\"ar\">ذِرَاعٌ</b> , of a man, (Msb,) [The <i>part</i>] <i>from the elbow to the extremities of the fingers;</i> (Mgh, Msb;) the <i>fore arm;</i> syn. <span class=\"ar\">سَاعِدٌ</span> [q. v.; thus corresponding to the <span class=\"ar\">سَاق</span> of the leg]: (Lth, K:) and (tropical:) [the <i>space</i>] <i>from the extremity of the elbow to the extremity of the middle finger:</i> (M, Mgh, * K: [in the last of which, the space is plainly shown to be meant, like as the part is shown in the Msb to be meant in the explanation cited above from that work and the Mgh: see also <span class=\"ar\">جَرِيبٌ</span>:]) in both these senses, sometimes masc., (K,) accord. to Kh: (TA:) J says, (TA,) as relating to the arm, it is masc. and fem.; but Sb says that it is fem.: (S, TA:) [Mtr says,] it is fem.: (Mgh:) [Fei says,] the measure so called is in most instances fem.: accord. to ISk, it is fem.; but some of the Arabs make it masc.: Fr says that it is fem.; but that some of [the tribe named] 'Okl make it masc.: As did not know an instance of its being masc.: and Zj says that such an instance is extr.; not choice: (Msb:) the measure thus called, [i. e. the <i>cubit,</i>] (Msb,) the <span class=\"ar\">ذِرَاعٌ مُكَسَّرَة</span> [or <i>cubit which is divided into fractions</i>], (Mgh,) is <i>six</i> <span class=\"ar\">قَبَضَات</span> [or <i>fists</i>] (Mgh, Msb) <i>of middling measure;</i> (Msb;) <i>and this is</i> <i>called</i> <span class=\"ar\">ذِرَاعُ العَمَامَّةِ</span> [<i>the cubit of the common people,</i> or <i>the common cubit</i>], <i>because it wants one</i> <span class=\"ar\">قَبْضَة</span> [or <i>fist</i>] <i>of what is called</i> <span class=\"ar\">ذِرَاعُ المَلِكِ</span> [<i>the cubit of the king</i>], <i>namely one of the Kisràs,</i> (Mgh, Msb,) <i>not the last of them, whose</i> <span class=\"ar\">ذراع</span> <i>was seven</i> <span class=\"ar\">قَبَضَات</span>: (Mgh:) [see also <span class=\"ar\">مِيلٌ</span>: it is also an astronomical measure; and as such, it seems, from several instances in which it is mentioned by Kzw and other writers, to be, probably, by rule, <i>two degrees;</i> nearly the half, or quarter, of the length assigned in different instances to the measure termed <span class=\"ar\">رُمْحٌ</span>; but, like the latter, not precise nor uniform in every instance:] the dim. is <span class=\"ar\"> <span class=\"ar\">ذُرِيَّعَةٌ</span></span>, with <span class=\"ar\">ة</span> because it is fem.; (TA;) or <span class=\"ar\"> <span class=\"ar\">ذُرَيْعٌ</span></span> [or <span class=\"ar\"> <span class=\"ar\">ذُرَيِّعٌ</span></span>, without <span class=\"ar\">ة</span>, accord. to those who make it masc.]: (L voce <span class=\"ar\">حَرْبٌ</span>:) the pl. is <span class=\"ar\">أَذْرُعٌ</span> and <span class=\"ar\">ذُرْعَانٌ</span>; (O, Msb, K;) or, accord. to Sb, the former only; (S, Msb;) and Sb adds, they have given it this form of pl. because it is fem.; meaning, that <span class=\"ar\">فِعَالٌ</span> and <span class=\"ar\">فُعَالٌ</span> and <span class=\"ar\">فَعِيلٌ</span>, when fem., have the pl. of the measure <span class=\"ar\">أَفْعُلٌ</span>. (TA.) In the phrase <span class=\"ar\">الثَّوْبُ سَبْعٌ فِى ثَمَانِيَةٍ</span> [<i>The garment,</i> or <i>piece of cloth, is seven</i> cubits <i>by eight</i> spans], they say <span class=\"ar\">سبع</span> because <span class=\"ar\">أَذْرُع</span> is fem., and <span class=\"ar\">ثمانية</span> because <span class=\"ar\">أَشْبَار</span> is masc.; (S; [and the like is said in the Mgh;]) and because the length is measured by the <span class=\"ar\">ذراع</span>, and the breadth by the <span class=\"ar\">شِبْر</span>. (S in art. <span class=\"ar\">ثمن</span>.) <span class=\"ar\">ذِرَاعٌ</span> is also used as an epithet, applied to a masc. n.: thus they say, <span class=\"ar\">هٰذَا ثَوْبٌ ذِرَاعٌ</span> [<i>This is a garment,</i> or <i>piece of cloth, a cubit in length</i>]. (Kh.) You say also, <span class=\"ar\">هُوَ مِنِّى عَلَى حَبْلِ الذِّرَاعِ</span> <i>It is prepared,</i> or <i>made ready, on my part:</i> (S:) and <span class=\"ar\">هُوَ لَكَ عَلَى حَبْلِ الذِّرَاعِ</span> <i>I will pay it to thee in ready money:</i> or <i>it is prepared,</i> or <i>made ready, for thee:</i> the <span class=\"ar\">حبل</span> being <i>a certain vein in the</i> <span class=\"ar\">ذراع</span>. (TA.) -b2- [Hence several tropical significations:] see <span class=\"ar\">ذَرْعٌ</span>, in six places: and see also <span class=\"ar\">ذَرَاعٌ</span>. -b3- Hence also, (Z, TA,) (tropical:) The <i>instrument with which one measures the length of the</i> <span class=\"ar\">ذراع</span> [or <i>cubit</i>], (S, Z, O, Mgh, K,) <i>made of a piece of wood,</i> (Mgh,) or <i>whether it be iron or a rod of wood.</i> (O, K.) -b4- [Hence also,] (assumed tropical:) <i>A sleeve:</i> as in the phrase <span class=\"ar\">ثَوْبٌ مُوَشَّى الذِّرَاعِ</span> (assumed tropical:) [<i>a garment,</i> or <i>piece of cloth, variegated,</i> or <i>figured, in the sleeve</i>]: pl. <span class=\"ar\"> <span class=\"ar\">مَذَارِعُ</span></span>, a pl. not agreeing with its sing., like <span class=\"ar\">مَلَامِحُ</span> and <span class=\"ar\">مَحَاسِنُ</span>. (TA.) -b5- Of the fore legs of bulls or cows, and of sheep or goats, [The <i>arm;</i> i. e.] the <i>part above the</i> <span class=\"ar\">كُرَاع</span>: and of the fore legs of camels and horses and mules and asses, [likewise the <i>arm;</i> i. e.] the <i>part above the</i> <span class=\"ar\">وَظِيف</span>: (K:) [also the <i>arm-bone</i> of any of the animals here mentioned:] accord. to Lth, (TA,) of any animal, [but this is by synecdoche, (assumed tropical:) the <i>fore leg;</i>] <i>i. q.</i> <span class=\"ar\">يَدٌ</span>; (Msb, TA;) applying to the whole of whatever is called thus: (TA:) [thus, again, corresponding to <span class=\"ar\">سَاقٌ</span>; this latter term, in like manner, having a proper and a synecdochical acceptation. Hence the prov.] <span class=\"ar\">لَا تُطْعِمِ العَبْدَ</span> <span class=\"ar\">الكُرَاعَ فَيَطْمَعَ فِى الذِّرَاعِ</span> [<i>Feed not thou the slave with the shank, lest he covet the arm</i>]. (K.) -b6- [Hence,] <span class=\"ar\">الذِّرَاعُ</span>, also called <span class=\"ar\">ذِرَاعُ الأَسَد</span> (assumed tropical:) <i>Two bright stars, which are one of the Mansions of the Moon:</i> (S:) [there are two asterisms thus called; together, <span class=\"ar\">الذِّرَعَانِ</span>: one of them is] <span class=\"ar\">الذِّرَاعُ المَبْسُوطَةُ</span>, [also called <span class=\"ar\">ذِرَاعُ الأَسَدِ المَبْسُوطَةُ</span>,] <i>the two bright stars</i> [<i> <b class=\"ar\">α</b> and <b class=\"ar\">β</b> </i>] <i>in the heads of Gemini:</i> (Kzw in his description of Gemini:) [the other is called <span class=\"ar\">الذِّرَاعُ المَقْبُوضَةُ</span>, and] <span class=\"ar\">ذِرَاعُ الأَسَدِ المَقْبُوضَةُ</span>, <i>the two bright stars</i> [<i> <b class=\"ar\">α</b> and <b class=\"ar\">β</b> </i>] <i>of Canis Minor:</i> (Kzw in his description of Canis Minor:) [hence it appears that the ancient Arabs, or many of them, extended the figure of Leo (as they did also that of Scorpio) far beyond the limits which we assign to it: the former <span class=\"ar\">ذراع</span> accord. to those who make <span class=\"ar\">النَّوْءُ</span> to signify “ the auroral rising, ” but the latter accord. to those who make it to signify “ the auroral setting, ” is <i>the Seventh Mansion of the Moon:</i> the following descriptions in Kzw's account of the Mansions of the Moon, and in the O and K and TA, are obscure and inaccurate:] <span class=\"ar\">الذِّرَاعُ</span> is <i>one of the Mansions of the Moon,</i> (O, Kzw, K,) <i>and is called</i> <span class=\"ar\">ذراع الاسد</span> <span class=\"ar\">المقبوضة</span>, (O, Kzw,) or <span class=\"ar\">ذراع الاسد المبسوطة</span>: (K:) <i>the lion has a</i> <span class=\"ar\">ذراع</span> <i>which is</i> <span class=\"ar\">مبسوطة</span> <i>and a</i> <span class=\"ar\">ذراع</span> <i>which is</i> <span class=\"ar\">مقبوضة</span>, (O, Kzw, K,) <i>and this is the one next to Syria,</i> (O, K,) or <i>on the left,</i> (Kzw,) <i>and in it the moon has a mansion; the</i> <span class=\"ar\">مبسوطة</span> <i>being next to El-Yemen,</i> (O, K,) or <i>on the right;</i> (Kzw;) [but this description of their relative positions should be reversed, as is shown by what precedes and by what follows;] <i>each being two stars, between which is the measure of a</i> <span class=\"ar\">سَوْط</span> [or <i>whip</i>]; (O;) <i>and the latter is higher in the sky, and more extended, than the other,</i> (O, K,) <i>wherefore it is called</i> <span class=\"ar\">مبسوطة</span>; (O;) <i>and sometimes the moon deviates, and so has a mansion in it:</i> (O, K:) [it is said in the TA that <span class=\"ar\">الذراع</span> is also a name of <i>one of the asterisms</i> (<span class=\"ar\">نُجُوم</span>) <i>of</i> <span class=\"ar\">الجَوْزَآء</span>; but this is the same that is called the <span class=\"ar\">مبسوطة</span>:] <i>it rises</i> [<i>at dawn</i>] <i>on the fourth of</i> <span class=\"ar\">تَمُّوز</span> [or <i>July O. S.</i>], <i>and sets</i> [<i>at dawn</i>] <i>on the fourth of</i> <span class=\"ar\">كَانُون الآخِر</span> [or <i>January, O. S.</i>]: (O, Kzw: [and so in the K, except that in this last, it is erroneously said to set in <span class=\"ar\">كَانُون الأَوَّل</span>:]) so says IKt: but Ibráheem El-Harbee says that it rises on the seventh of <span class=\"ar\">تمّوز</span>, and sets on the sixth of <span class=\"ar\">كانون</span> <span class=\"ar\">الآخر</span>. (O, TA.) [See <span class=\"ar\">مَنَازِلُ القَمَرِ</span>, in art. <span class=\"ar\">نزل</span>; and see also <span class=\"ar\">نَوْءٌ</span>, and <span class=\"ar\">نَكْبَآءُ</span>.] The rhyming prosaist of the Arabs says, <span class=\"ar\">إِذَا طَلَعَتِ الذِّرَاعْ حَسَرَتِ الشَّمْسُ</span> <span class=\"ar\">القِنَاعْ وَٱسْتَعْلَتْ فِى الأُفُقِ الشُّعَاعْ وَ تَرَقْرَقَ السَّرَابُ فِى</span> <span class=\"ar\">كُلِّ قَاعْ</span> [<i>When the Dhiráa rises</i> at dawn, <i>the sun puts off the veil, and the rays ascend in the horizon, and the mirage flickers,</i> or <i>glistens, in every plain</i>]. (TA.) And the Arabs assert that when there is no rain [at any other season] in the year, the <span class=\"ar\">ذراع</span> does not break its promise, though it be but a <span class=\"ar\">بَغْشَة</span> [or weak shower of rain]: (Kzw, TA:) [or] its <span class=\"ar\">نَوْء</span> is approved, and seldom does it break its promise. (Kzw.) -b7- <span class=\"ar\">ذِرَاعٌ</span> also signifies (assumed tropical:) <i>A certain mark made with a hot iron upon the arm</i> (<span class=\"ar\">ذراع</span>) <i>of a camel:</i> (S, K:) and is <i>a mark of the Benoo-Thaalebeh in El-Yemen, and of some persons of the Benoo-Málik-Ibn-Saad.</i> (K.) -b8- Also (tropical:) The <i>fore part of a spear</i> or <i>spear-shaft:</i> (K, TA:) this is called (S, TA) also (TA) <span class=\"ar\">ذِرَاعُ الَعَامِلِ</span>. (S, TA.)</p><p><b class=\"ar\">ذَرُوعٌ</b> : see what next follows.</p><p><b class=\"ar\">ذَرِيعٌ</b> <i>Wide in step,</i> (S, K,) <i>and light,</i> or <i>active, in pace,</i> or <i>going;</i> (K;) applied to a horse, (S, K,) and to a camel; as also <span class=\"ar\"> <span class=\"ar\">ذَرُوعٌ</span></span>: (K:) and <i>quick:</i> (S, Msb, K:) [and so <span class=\"ar\"> <span class=\"ar\">ذَرِعٌ</span></span>; for] <span class=\"ar\"> <span class=\"ar\">ذَرِعَاتٌ</span></span>, (S, O, K,) applied to the legs of a quadruped (<span class=\"ar\">قَوَائِمٌ</span>), (S, TA,) signifies <i>quick,</i> (S, K,) <i>wide in step, taking much of the ground:</i> (O, K:) or, as some say, this last word signifies the <i>legs</i> of a beast, (TA,) like <span class=\"ar\"> <span class=\"ar\">مَذَارِعُ</span></span>, (S, K,) pl. of <span class=\"ar\">مِذْرَاعٌ</span>. (K.) It is said of Mohammad, in a trad., <span class=\"ar\">كَانَ</span> <span class=\"ar\">ذَرِيعَ المَشْىِ</span> (assumed tropical:) <i>He was quick, and wide of step, in walking.</i> (TA.) And you say, <span class=\"ar\">رَجُلٌ ذَرِيعٌ بِالِكِتَابَةِ</span> (assumed tropical:) <i>A man quick in writing.</i> (TA.) And <span class=\"ar\">أَكَلَ</span> <span class=\"ar\">أَكْلًا ذَرِيعًا</span> (assumed tropical:) <i>He ate quickly and much.</i> (TA.) And <span class=\"ar\">قَتْلٌ ذَرِيعٌ</span> (assumed tropical:) <i>Quick slaughter.</i> (S.) And <span class=\"ar\">مَوْتٌ ذَرِيعٌ</span> (tropical:) <i>Spreading death:</i> (K:) or <i>quick, spreading death, such that the people can hardly,</i> or <i>can in no wise, bury one another.</i> (TA.) -b2- (assumed tropical:) An <i>ample</i> thing, affair, or state. (K.) -A2- (assumed tropical:) <i>An intercessor.</i> (Ibn-'Abbád, K.)</p><p><b class=\"ar\">ذُرَيْعٌ</b> a dim. of <span class=\"ar\">ذِرَاعٌ</span>, q. v.</p><p><b class=\"ar\">ذَرِيعَةٌ</b> <i>A she-camel by which the archer,</i> or <i>the like, conceals himself from the game,</i> (S, K, TA,) <i>walking by her side, and shooting,</i> or <i>casting, when the object puts itself in his power, having first left the she-camel to roam at pleasure with the wild animals in order that they may become familiar with her;</i> (TA;) like <span class=\"ar\">دَرِيْئَةٌ</span>; (S;) as also <span class=\"ar\"> <span class=\"ar\">ذَرَعٌ</span></span>: (K:) pl. <span class=\"ar\">ذُرُعٌ</span>. (IAar.) -b2- Hence, (tropical:) <i>Anything that brings one near to a thing;</i> (IAar;) <i>a means of access, nearness, intimacy, ingratiation, attachment,</i> or <i>connexion;</i> syn. <span class=\"ar\">وَسِيلَةٌ</span>; (S, Msb, K, TA;) and <span class=\"ar\">سَبَبٌ</span>; and <span class=\"ar\">وُصْلَةٌ</span>; (TA;) as also <span class=\"ar\"> <span class=\"ar\">ذُرْعَةٌ</span></span>: (Ibn-'Abbád, K:) pl. <span class=\"ar\">ذَرَائِعُ</span>. (S, Msb.) You say, <span class=\"ar\">فُلَانٌ ذَرِيعَتِى إِلَيْكَ</span> (tropical:) <i>Such a one is my means of access to thee,</i> and <i>of attachment to thee,</i> or <i>connexion with thee.</i> (TA.) -b3- Also, [like <span class=\"ar\">دَرِيْئَةٌ</span>,] <i>A ring by aiming at which one learns the art of shooting,</i> or <i>casting</i> [<i>the lance &amp;c.</i>]. (TA.)</p><p><b class=\"ar\">ذُرَيِّعٌ</b> : dims. of <span class=\"ar\">ذِرَاعٌ</span>, q. v.</p><p><b class=\"ar\">ذُرَيِّعَةٌ</b> : dims. of <span class=\"ar\">ذِرَاعٌ</span>, q. v.</p><p><b class=\"ar\">ذَرَّاعٌ</b> <i>A measurer with the</i> <span class=\"ar\">ذِرَاع</span> [or <i>cubit</i>]. (T in art. <span class=\"ar\">أبر</span>.) -b2- A he-camel <i>that drives the she-camel with his arm and so makes her lie down that he may cover her.</i> (Ibn-'Abbád, K.)</p><p><b class=\"ar\">ذَارِعٌ</b> [so in a copy of the S and of the K and in the TA: in one copy of S and in one of the K, <span class=\"ar\">ذِرَاع</span>: in the CK, <span class=\"ar\">ذَرّاع</span>: but the right reading is <span class=\"ar\">ذَارِعٌ</span>, as is shown by verses in which it occurs, cited in the TA, and by its pl.,] <i>A small</i> [<i>skin of the kind called</i>] <span class=\"ar\">زِقّ</span>, <i>which is stripped off from the part next to the</i> <span class=\"ar\">ذِرَاع</span> [or <i>arm</i>], (S, K,) <i>and</i> <i>which is for</i> <span class=\"ar\">شَرَاب</span> [or <i>wine</i>]; (S;) and <span class=\"ar\"> <span class=\"ar\">مِذْرَعٌ</span></span> signifies [the same; or simply] <i>a small</i> <span class=\"ar\">زِقّ</span>: (TA:) or, as some say, <span class=\"ar\">زِقٌّ ذَارِعٌ</span> signifies <i>a</i> <span class=\"ar\">زقّ</span> <i>that takes much water:</i> (TA:) the pl. is <span class=\"ar\">ذَوَارِعُ</span>. (S, TA.) -A2- <span class=\"ar\">نَاقَةٌ ذَارَعَةٌ</span> <i>An excellent she-camel.</i> (TA.)</p><p><b class=\"ar\">أَذْرَعُ</b> [<i>More,</i> and <i>most, light,</i> or <i>active,</i> and <i>quick, with the arms,</i> or <i>hands,</i> or (assumed tropical:) <i>otherwise</i>]. It is said in a trad., <span class=\"ar\">خَيْرُ كُنَّ أَذْرَعُكُنَّ لِلْغَزْلِ</span> <i>The best of you females is the most light,</i> or <i>active, of hand, of you, in spinning:</i> or, <i>the most able of you to spin.</i> (TA.) And <span class=\"ar\">قَتَلُوهُمْ أَذْرَعَ قَتْلٍ</span> (assumed tropical:) <i>They slew them with the quickest slaughter.</i> (S.) -b2- (assumed tropical:) <i>More,</i> and <i>most, chaste in speech.</i> (K.) You say, <span class=\"ar\">هُوَ أَذْرَعُ مِنْهُ</span> (assumed tropical:) <i>He is more chaste of speech than he.</i> (TA.) -A2- (assumed tropical:) One <i>whose mother is Arabian but not his father;</i> syn. <span class=\"ar\">مُقْرِفٌ</span>: or the <i>son of an Arabian man by an emancipated slavewoman:</i> (K:) the former is the more correct. (TA.) [See also <span class=\"ar\">مُذَرَّعٌ</span>.]</p><p><b class=\"ar\">تَذْرِيعٌ</b> The <i>redundant part of the cord with which the arm</i> [<i>of a camel</i>] <i>is bound:</i> [see 2, latter part:] a subst. like [<span class=\"ar\">تَصْدِيرٌ</span> and] <span class=\"ar\">تَنْبِيتٌ</span>; not an inf. n. (TA.)</p><p><b class=\"ar\">مِذْرَعٌ</b> : see <span class=\"ar\">ذَارِعٌ</span>.</p><p><b class=\"ar\">مُذَرَّعٌ</b> , an epithet applied to an ass, and to a mule, meaning <i>Having what are termed</i> <span class=\"ar\">رَقْمَتَانِ</span> [q. v.] <i>upon his arms.</i> (L.) -b2- Hence, (L,) (tropical:) A man (TA) <i>whose mother is more noble than his father:</i> (S, L, K:) as though, (K,) or said to be, (S,) so called because of the <span class=\"ar\">رَقْمَتَانِ</span> upon the arm [or arms] of the mule, for they come to him from the side of the ass; (S, K;) or so called as being likened to the mule, because he has upon his arms <span class=\"ar\">رقمتان</span> like those of the arm of the ass, thereby resembling the ass; and the mother of the mule is more noble than his father. (L.) [See also <span class=\"ar\">أَذْرَعُ</span>.] -b3- A lion <i>having upon his arms the blood of his prey.</i> (IAar.) -b4- [A beast] <i>struck in the uppermost part of his breast so that the blood has flowed upon his arms.</i> (K.) -b5- A horse <i>that outstrips:</i> or (originally, TA) <i>that overtakes the wild animal and has his arms smeared by his rider's piercing the latter so as to make the blood flow forth;</i> (K, TA;) this blood upon his arms being the sign of his having outstripped. (TA,) -b6- A bull <i>having black spots,</i> or <i>black places, upon his shanks.</i> (S, K.) -b7- <span class=\"ar\">مُذَرَّعَةٌ</span> <i>A hyena having stripes upon its arms:</i> (K:) an epithet in which the quality of a subst. predominates: or applied to the hyena because of blackness on its arms. (TA.)</p><p><b class=\"ar\">مُذَرِّعٌ</b> Rain <i>that sinks into the earth to the depth of a cubit.</i> (S, K.)</p><p><b class=\"ar\">مِذْرَاعٌ</b> sing. of <span class=\"ar\">مَذَارِعٌ</span>, [which is contr. to rule,] (S, K,) in a sense pointed out below, (S,) or in all the senses explained below, and of <span class=\"ar\">مَذَارِيعٌ</span>, (K,) which is agreeable to rule. (TA.) -b2- <span class=\"ar\">مَذَارِعُ</span> signifies <i>The legs</i> of a beast; (S, K;) as also <span class=\"ar\">مَذَارِيعُ</span>, and <span class=\"ar\">ذَرِعَاتٌ</span>; see <span class=\"ar\">ذَرِيعٌ</span>; because the beast measures with them the ground: or, as some say, [like the pl. of <span class=\"ar\">ذِرَاعٌ</span>,] the <i>parts</i> of a beast <i>between the knee and the arm-pit.</i> (TA.) -A2- <span class=\"ar\">مَذَارِعُ</span> also signifies The <i>towns</i> (<span class=\"ar\">قُرَى</span>, S, or <span class=\"ar\">بِلَاد</span>, K) <i>that are between the cultivated land and the desert;</i> (S, K;) such as El-Kádiseeyeh and El-Ambár; (TA;) in this sense, (S,) as in others, (K,) pl. of <span class=\"ar\">مِذْرَاعٌ</span>; (S, K;) as also <span class=\"ar\">مَذَارِيعُ</span>; (K;) syn. with <span class=\"ar\">مَزَالِفُ</span>; (S;) and <span class=\"ar\">بَرَاغِيلُ</span>: (TA:) El-Hasan El-Basree speaks of the <span class=\"ar\">مَذَارِعُ</span> of El-Yemen. (TA.) [Freytag says, without mentioning his authority, that <span class=\"ar\">مَذَارِعُ</span> has the same signification with the inhabitants of Nejd as <span class=\"ar\">مَخَالِيفُ</span> with the inhabitants of El-Yemen and <span class=\"ar\">مَزَالِفُ</span> in the region of El-Hijáz: but this is at variance with all that I have found, in respect of the term <span class=\"ar\">مخاليف</span>.] -b2- Also <i>Parts, regions, quarters,</i> or <i>tracts,</i> syn. <span class=\"ar\">نَوَاحٍ</span>, (Ibn-'Abbád, K,) of a land. (Ibn-'Abbád.) -b3- And The <i>places of bending</i> of a valley. (Kh.) -b4- And <i>Palm-trees that are near to houses</i> or <i>tents.</i> (S, K.)</p><p><b class=\"ar\">مَذَارِعُ</b> a pl. [contr. to rule] of <span class=\"ar\">مِذْرَاعٌ</span>, q. v.: (S, K:) and of <span class=\"ar\">ذِرَاعٌ</span> as signifying (assumed tropical:) <i>A sleeve.</i> (TA.) See the last of these words, near the middle of the paragraph.</p>"},"ذأب":{"mq":[["قلة استقرار"],"الذال والهمزة والباء أصلٌ واحد يدلُّ على قِلّةِ استقرارٍ، وألاّ يكونَ للشّئ فى حركته جهةٌ واحدة. من ذلك الذِّئب، سمِّى بذلك لتذَؤُّبِه من غير جهةٍ واحدة. ويقال ذُئِبَ الرّجُل، إذا وقَع فى غنَمه [الذئب]<br>. ويقال تذأَّبت الرِّيح: أتت من كل جانب. وأرض مَذْأَبَةٌ: كثيرة الذئاب. وذَؤُب الرّجُل، إذا صار ذئ"],"ln":"<p><b>1.</b> <b class=\"ar\">ذُئِبَ</b> <i>He</i> (a man, M) <i>was frightened by the wolf;</i> (M, K;) as also <span class=\"ar\">ذَئِبَ</span>, aor. <b class=\"ar\">ذَأََ</b> ; and <span class=\"ar\">ذَؤُبَ</span>, aor. <b class=\"ar\">ذَأَُ</b> : (K:) <i>or he</i> (a man) <i>was assailed, fallen upon, come upon,</i> or <i>overtaken, by the wolf.</i> (Ibn-Buzurj, T.) And [hence, in the opinion of ISd, as he says in the M,] (tropical:) <i>He was frightened by anything;</i> (M, K;) and so <span class=\"ar\"> <span class=\"ar\">اذأب</span></span>, (AA, T, S, M, K,) inf. n. <span class=\"ar\">إِذْآبٌ</span>; (TA;) said of a man. (S.) [Hence also,] <span class=\"ar\">ذَأَبَهُ</span>, (M, K,) aor. <b class=\"ar\">ذَأََ</b> , (K,) [inf. n. <span class=\"ar\">ذَأْبٌ</span>,] (tropical:) <i>He frightened him</i> [<i>like as does a wolf</i>]: (M, A, K, TA:) and <span class=\"ar\">ذَأَبَتْهُ الجِنُّ</span> (A, TA) and <span class=\"ar\"> <span class=\"ar\">تذأّبتهُ</span></span>, as also <span class=\"ar\">تذعّبتهُ</span>, (T, TA,) (tropical:) <i>The jinn,</i> or <i>genii, frightened him.</i> (T, A, TA.) [And hence, app.,] <span class=\"ar\">ذَأَبْتُهُ الرِّيحُ</span> (tropical:) <i>The wind came to him from every side, like the wolf; when guarded against from one direction, coming from another direction:</i> (A:) and <span class=\"ar\"> <span class=\"ar\">تذآءبتِ</span>اِلرِّيحُ</span>, (T, S, M, K,) and <span class=\"ar\"> <span class=\"ar\">تذأّبت</span></span>, (S, M, K,) (tropical:) <i>The wind varied,</i> (T, S, M,) or <i>came now from one direction and now from another direction,</i> (S, M, K,) so says As, (S,) <i>feebly:</i> (M, K:) accord. to As, from <span class=\"ar\">الذِّئْبُ</span>, (S,) [i. e.] it is likened to the wolf, (M,) because his motions are of the like description: (S:) or, accord. to some, <span class=\"ar\">الذِّئْبُ</span> is derived from <span class=\"ar\"> <span class=\"ar\">تذآءبت</span> الريح</span> meaning <i>the wind blew from every direction;</i> because the wolf comes from every direction. (MF, TA.) -b2- Also, (i. e. <span class=\"ar\">ذُئِبَ</span>) <i>He</i> (a man) <i>had his sheep,</i> or <i>goats, fallen upon by the wolf.</i> (S, K.) -b3- And <span class=\"ar\">ذَؤُبَ</span>, (T, S, M, A, K,) aor. <b class=\"ar\">ذَأَُ</b> , (T, S, K,) inf. n. <span class=\"ar\">ذَآبَةٌ</span>; (S, M, K;) and <span class=\"ar\">ذَئِبَ</span>; (M, A, K;) and <span class=\"ar\"> <span class=\"ar\">تذأّب</span></span>; (M, K;) (tropical:) <i>He</i> (a man, T, S, M) <i>was,</i> or <i>became, bad, wicked, deceitful,</i> or <i>crafty,</i> (T, S, M, A, K,) <i>like the wolf,</i> (S, M, A, K,) or <i>as though he became a wolf.</i> (T.) -b4- And <span class=\"ar\">ذَأَبَ</span>, aor. <b class=\"ar\">ذَأََ</b> , (tropical:) <i>He acted like the wolf; when guarded against from one direction, coming from another direction.</i> (TA.) [And probably (assumed tropical:) <i>He howled like the wolf;</i> for,] accord. to Kr, (M,) <span class=\"ar\">ذَأْبٌ</span> signifies the <i>uttering a loud,</i> or <i>vehement, cry</i> or <i>sound.</i> (M, K.) -b5- And (assumed tropical:) <i>He hastened,</i> or <i>was quick, in pace,</i> or <i>journeying;</i> (K;) as also <span class=\"ar\"> <span class=\"ar\">اذأب</span></span>. (TA.) -A2- <span class=\"ar\">ذَأَبَهُ</span>, [aor. <b class=\"ar\">ذَأََ</b> ,] inf. n. <span class=\"ar\">ذَأْبٌ</span>, also signifies <i>He despised him;</i> and so <span class=\"ar\">ذَأَمَهُ</span>: (T:) or <i>he drove him away, and despised him:</i> (ISk, T, S, M, K:) or <i>he drove him away,</i> (Lh, M, TA,) <i>and beat him;</i> (Lh, TA;) and so <span class=\"ar\">ذَأَمَهُ</span>: (M, TA:) [or <i>he blamed,</i> or <i>dispraised, him;</i> like <span class=\"ar\">ذَأَمَهُ</span>; for,] accord. to Kr, (M,) <span class=\"ar\">ذَأْبٌ</span> signifies the act of <i>blaming,</i> or <i>dispraising.</i> (M, K.) -b2- And <i>He drove him,</i> or <i>urged him on:</i> (K:) or <span class=\"ar\">ذَأَبَ الإِبِلَ</span>, inf. n. <span class=\"ar\">ذَأْبٌ</span>, <i>he drove,</i> or <i>urged on, the camels.</i> (S, M.) -A3- <i>He collected it;</i> (T, K;) namely, a thing. (T.) -b2- <i>He made it even;</i> syn. <span class=\"ar\">سَوَّاهُ</span>. (CK: omitted in other copies of the K and in the TA.) One says of the woman who makes even (<span class=\"ar\">تُسَوِّى</span>) her vehicle, [meaning the part of her camel-vehicle upon which she sits,] <span class=\"ar\">مَا أَحْسَنَ</span> <span class=\"ar\">مَا ذَأَبَتْهُ</span> [<i>How well has she made it even!</i>] (T.) -b3- <i>He made it;</i> namely, a [camel's saddle such as is called] <span class=\"ar\">قَتَب</span> (K) and [such as is called] a <span class=\"ar\">رَحْل</span> (TA.) -A4- <i>He made,</i> [or <i>disposed,</i>] <i>for him,</i> (namely, a boy,) <i>a</i> <span class=\"ar\">ذُؤَابَة</span> [q. v.]; as also <span class=\"ar\"> <span class=\"ar\">اذأبهُ</span></span> and <span class=\"ar\"> <span class=\"ar\">ذأّبهُ</span></span>. (K.) -A5- <span class=\"ar\">ذُئِبَ</span> said of a horse, <i>He was,</i> or <i>became, affected with the disease termed</i> <span class=\"ar\">ذِئْبَة</span>. (T, Mgh.)</p><p><b>2.</b> <b class=\"ar\">ذَأََّ</b> see 1, last sentence but one. -A2- <span class=\"ar\">ذأّب الرَّحْلَ</span>, (inf. n. <span class=\"ar\">تَذْئِيبٌ</span>, K,) <i>He made, to the</i> <span class=\"ar\">رحل</span> [or <i>camel's saddle</i>], <i>what is termed a</i> <span class=\"ar\">ذِئْبَة</span>, (M, K,) or <span class=\"ar\">ذِئْب</span>. (TA.) [See also <span class=\"ar\">مُذَأَّبٌ</span>.]</p><p><b>4.</b> <b class=\"ar\">أَذْأَبَتِ الأَرْضُ</b> (A, TA) <i>The land abounded with wolves.</i> (TA.) -b2- See also 1, in three places.</p><p><b>5.</b> <b class=\"ar\">تَذَأََّ</b> see 6, in two places: -b2- and see also 1, in three places.</p><p><b>6.</b> <b class=\"ar\">تذآءب لِلنّاقَةِ</b> (S, M, K) and <span class=\"ar\"> <span class=\"ar\">تذأّب</span>لَهَا</span> (M, K) (assumed tropical:) <i>He disguised himself like a wolf to the she-camel, and, by so frightening her, made her to incline to,</i> or <i>affect, her young one:</i> (S:) or <i>he cloaked,</i> or <i>disguised, himself to the she-camel, making himself to seem like a wolf, in order to cause her to affect a young one that was not her own</i> [<i>by moving her with pity by the supposed danger of the latter</i>]. (M, K) -b2- See also 1, in two places. -A2- <span class=\"ar\">تذآءب شَيْئًا</span> and <span class=\"ar\"> <span class=\"ar\">تذأّبهُ</span></span> (assumed tropical:) <i>He did a thing by turns;</i> syn. <span class=\"ar\">تَدَاوَلَهُ</span>: (M, K, TA: [in the CK, erroneously, <span class=\"ar\">تَناوَلَهُ</span>:]) from <span class=\"ar\">الذِّئْبُ</span> [the wolf], which, when guarded against from one direction, comes from another direction. (M, TA.)</p><p><b>10.</b> <b class=\"ar\">استذأب النَّقَدُ</b> <i>The</i> <span class=\"ar\">نقد</span> [or <i>ugly sheep</i>] <i>became like wolves:</i> a prov., applied to low, mean, or ignominious, persons, when they obtain ascendancy. (T, K.)</p><p><b class=\"ar\">غَرْبٌ ذَأْبٌ</b> (assumed tropical:) <i>A large bucket with which one goes to and fro;</i> thought by As to be from <span class=\"ar\">تَذَاؤُبُ</span> <span class=\"ar\">الرِّيحِ</span>: (M:) or <i>in much</i> [or <i>quick</i>] <i>motion, ascending and descending.</i> (M, K.)</p><p><b class=\"ar\">ذِئْبٌ</b> , also pronounced <span class=\"ar\">ذِيبٌ</span>, without <span class=\"ar\">ء</span>, (S, Msb, K,) originally with <span class=\"ar\">ء</span>, (T, S,) The <i>wolf, wild dog,</i> or <i>dog of the desert;</i> <span class=\"ar\">كَلْبُ البَرِّ</span>: (M, A, K:) applied to the <i>male</i> and the <i>female;</i> (Msb;) and sometimes, also, (Msb,) the female is called <span class=\"ar\">ذِئْبَةٌ</span>: (S, M, Msb, K:) pl. (of pauc., S, Msb) <span class=\"ar\">أَذْؤُبٌ</span>, and (of mult., S, Msb) <span class=\"ar\">ذِئَابٌ</span>, (S, M, Msb, K,) which may also be pronounced <span class=\"ar\">ذِيَابٌ</span>, with <span class=\"ar\">ى</span>, because of the kesreh, (Msb,) and <span class=\"ar\">ذُؤبَانٌ</span> (S, M, Msb, K) and <span class=\"ar\">ذِئْبَانٌ</span>. (TA.) -b2- You say, <span class=\"ar\">الذِّئْبُ</span> <span class=\"ar\">يُكَنَّى أَبَا جَعْدَةَ</span> [<i>The wolf is surnamed Aboo-Jaadeh</i>]: i. e. its surname is good, but its actions are foul. (TA. [See art. <span class=\"ar\">جعد</span>; and see also Freytag's Arab. Prov., i. 449.]) -b3- And <span class=\"ar\">الذِّئْبُ</span> <span class=\"ar\">يَأْذُو الغَزَالَ</span> [<i>The wolf lies in wait for the young gazelle</i>]: a prov. alluding to perfidy. (TA.) -b4- And <span class=\"ar\">هُوَ ذِئْبٌ فِى ثَلَّةٍ</span> (tropical:) [<i>He is a wolf among a flock of sheep</i>]. (A.) -b5- And <span class=\"ar\">ذِئْبَةُ مِعْزًى وَظَلِيمٌ فِى</span> <span class=\"ar\">الخُبْرِ</span> [<i>A she-wolf among the goats, and a heostrich when tried</i>]: i. e., in his evil nature he is like a [she-] wolf that attacks a herd of goats; and when tried, like a he-ostrich, which, if one say to it “ Fly, ” says “ I am a camel, ” and when one says to it “ Carry a burden, ” says “ I am a bird: ” a prov. applied to a crafty and deceitful person. (TA.) -b6- And <span class=\"ar\">أَكَلَهُمْ الضَّبُعُ وَ الذِّئْبُ</span> [<i>The hyena and the wolf devoured them</i>]; meaning (tropical:) <i>dearth,</i> or <i>drought:</i> and <span class=\"ar\">أَصَابَتْهُمْ سَنَةٌ ضَبُعٌ وَذِئْبٌ</span>, meaning (tropical:) <i>A year that was one of dearth,</i> or <i>drought, befell them.</i> (A.) -b7- <span class=\"ar\">ذِئْبُهُ لَا يَشْبَعُ</span> [<i>His wolf will not be satiated</i>], a phrase used by a poet, means (assumed tropical:) <i>his tongue</i> [<i>will not be satisfied</i>]; i. e. he devours the reputation of another like as the wolf devours flesh. (M.) -b8- <span class=\"ar\">ذِئْبُ يُوسُفَ</span> [<i>The wolf of Joseph</i>] is a prov. applied to him who is charged with the crime of another. (TA.) -b9- <span class=\"ar\">ذُؤْبَانُ العَرَبِ</span>, (S, M, A, K,) also pronounced <span class=\"ar\">ذُوبَان</span>, without <span class=\"ar\">ء</span>, (TA,) [<i>The wolves of the Arabs,</i>] means (tropical:) <i>the thieves,</i> (M, K,) or <i>sharpers,</i> (A,) <i>and paupers,</i> (A, K,) <i>of the Arabs;</i> (M, A, K;) or <i>the paupers of the Arabs, who practise thieving:</i> (T, S:) because they act like wolves. (TA.) -b10- <span class=\"ar\">ذِئَابُ الغَضَا</span> <i>The wolves of the ghadà,</i> that frequent the trees so called, (TA,) is an appellation of the sons of Kaab Ibn-Málik Ibn-Handhalah; (M, K;) because of their bad character; (M;) for the wolf that frequents those trees is the worst of wolves. (TA.) -b11- <span class=\"ar\">دَآءُ الذِّئْبِ</span> [<i>The wolf's disease</i>] means (assumed tropical:) <i>hunger;</i> for they assert that the wolf has no other disease than hunger; (K, TA;) and they say <span class=\"ar\">أَجْوَعُ مِنْ ذِئْبٍ</span> [<i>More hungry than a wolf</i>]; because he is always hungry: or (assumed tropical:) <i>death;</i> because [it is said that] the wolf has no other sickness than that of death; and hence they say <span class=\"ar\">أَصَحُّ مِنَ الذِّئْبِ</span> [<i>More sound than the wolf</i>]. (TA.) [Hence the prov., <span class=\"ar\">رَمَاهُ ٱللّٰهُ بِدَآءِ الذِّئْبِ</span>: see 1 in art. <span class=\"ar\">رمى</span>.] -b12- <span class=\"ar\">الذِّئْبَانِ</span>, in the dual form, [<i>The two wolves,</i>] is the name of (assumed tropical:) <i>two white stars</i> [app. <b class=\"ar\">ζ</b> <i>and</i> <b class=\"ar\">η</b> <i>of Draco</i>] <i>between those called</i> <span class=\"ar\">العَوَائِذُ</span> <i>and those called</i> <span class=\"ar\">الفَرْقَدَانِ</span>: and <span class=\"ar\">أَظْفَارُ الذِّئْبِ</span> [<i>The claws of the wolf</i>] is the name of (assumed tropical:) <i>certain small stars before those called</i> <span class=\"ar\">الذِّئْبَانِ</span>. (K.) -b13- <span class=\"ar\">عِنَبُ الذِّئْبِ</span>: see <span class=\"ar\">ثَعْلَبٌ</span>. -b14- See also the next paragraph.</p><p><b class=\"ar\">ذِئْبَةٌ</b> fem. of <span class=\"ar\">ذِئْبٌ</span>. (S, M, Msb, K.) -b2- Also (assumed tropical:) The [<i>angular</i>] <i>intervening space between the</i> <span class=\"ar\">دَفَّتَانِ</span> [or <i>two boards</i>] <i>of the</i> [<i>kinds of saddle called</i>] <span class=\"ar\">سَرْج</span> <i>and</i> <span class=\"ar\">رَحْل</span> (S, K, TA) <i>and</i> <span class=\"ar\">غَبِيط</span>, (TA,) <i>beneath the place of juncture of the two curved pieces of wood;</i> (S;) [or] <i>what is beneath the fore part of the place of juncture of the two curved pieces of wood</i> (M, K) <i>of the</i> [<i>kinds of saddle called</i>] <span class=\"ar\">رَحْل</span> <i>and</i> <span class=\"ar\">قَتَب</span> <i>and</i> <span class=\"ar\">إِكَاف</span> <i>and the like;</i> (M;) <i>which falls,</i> or <i>lies, upon,</i> (S,) or <i>bites,</i> or <i>compresses,</i> (M, K,) <i>the part called the</i> <span class=\"ar\">مَنْسِج</span> (S, M, K) <i>of the beast.</i> (M, K.) A poet says, <span class=\"ar\">وَقَتَبٌ ذِئْبَتُهُ كَٱلْمِنْجَلِ</span> [<i>And a</i> <span class=\"ar\">قتب</span> <i>of which the</i> <span class=\"ar\">ذئبة</span> <i>is like the reapinghook</i>]. (M.) [See <span class=\"ar\">قَرَبُوسٌ</span>.] Accord. to IAar, the <span class=\"ar\"> <span class=\"ar\">ذِئْب</span></span> [a coll. gen. n. of which <span class=\"ar\">ذِئْبَةٌ</span> is the n. un.] of the [saddle called] <span class=\"ar\">رَحْل</span> are The <i>curved pieces of wood in the fore part</i> thereof. (TA.) -A2- Also (assumed tropical:) <i>A certain disease of horses</i> (T, M, Mgh, K) <i>or similar beasts, that attacks them in their fauces;</i> (M, K;) <i>for which the root of the beast's ear is perforated with an iron instrument, and there are extracted from it small, white, hard nodous substances,</i> (T, Mgh, K, *) <i>like the grains of the</i> [<i>species of millet called</i>] <span class=\"ar\">جَاوَرْس</span>, (K,) or <i>smaller than those grains.</i> (T, Mgh.)</p><p><b class=\"ar\">ذِئْبَانٌ</b> a pl. of <span class=\"ar\">ذِئبٌ</span>. (TA.) -A2- Also, accord. to AA, (S,) The <i>hair upon the neck and lip of the camel:</i> (S, K;) and accord. to Fr, who says that it is a sing. [in this sense], (S,) the <i>remains of the</i> [<i>fur,</i> or <i>soft hair, called</i>] <span class=\"ar\">وَبَر</span> [<i>after the greater part has fallen off or been shorn</i>]. (S, K. [See also <span class=\"ar\">ذُوبَانٌ</span> in art. <span class=\"ar\">ذوبْ</span>, and <span class=\"ar\">ذِيبَانٌ</span> in art. <span class=\"ar\">ذيب</span>.])</p><p><b class=\"ar\">ذُؤَابٌ</b> : see the next paragraph.</p><p><b class=\"ar\">ذُؤَابَةٌ</b> (also pronounced <span class=\"ar\">ذُوَابَةٌ</span>, T and K in art. <span class=\"ar\">ذوب</span>,) <i>A portion</i> [or <i>lock</i>] <i>of hair,</i> (S, A,) <i>hanging down loosely from the middle of the head to the back:</i> (A:) or the <i>hair of the fore part of the head;</i> the <i>hair over the forehead;</i> syn. <span class=\"ar\">نَاصِيَةٌ</span>; (M, K;) so called because, hanging down, it moves to and fro, or from side to side: (M:) or the <i>place whence that hair grows:</i> (M, K:) or the <i>hair that surrounds the</i> <span class=\"ar\">دُوَّارَة</span> [or <i>round part</i>] <i>of the head:</i> (AZ, T:) or <i>plaited hair of the head:</i> and the <i>part of the head which is the place thereof:</i> (Lth, T:) or <i>a plait of hair hanging down:</i> if twisted, it is called <span class=\"ar\">عَقِيصَةٌ</span>: (Msb:) and [a horse's <i>forelock;</i> or] <i>hair</i> (M, K) <i>of the head,</i> (M,) <i>in the upper part of the</i> <span class=\"ar\">نَاصِيَة</span>, of the horse: (M, K:) pl. (in all its senses, M, TA) <span class=\"ar\">ذَوَائِبُ</span>, (T, S, M, Msb, K,) originally, (S, K,) or regularly, (T,) <span class=\"ar\">ذَآئِبُ</span>, changed to render it more easy of pronunciation, (T, S, K,) and <span class=\"ar\">ذُؤَابَاتٌ</span> also. (Msb.) Hence, <span class=\"ar\">فُتِلَ ذَوَائِبُهُ</span> [<i>His pendent locks of hair were twisted;</i>] meaning (tropical:) <i>he was made to abandon,</i> or <i>relinquish, his opinion</i> or <i>idea</i> or <i>judgment.</i> (A.) -b2- (assumed tropical:) <i>Anything that hangs down loosely.</i> (TA.) (tropical:) The <i>end of a turban,</i> (A, Msb,) <i>that hangs down between the shoulders.</i> (A.) (assumed tropical:) The <i>end of a whip.</i> (Msb.) (tropical:) Of a sandal. The <i>thing,</i> or <i>portion, that hangs down from,</i> or <i>of,</i> [<i>the upper part of</i>] <i>the</i> <span class=\"ar\">قِبَال</span> [or <i>thong that passes, from the sole, between two of the toes;</i> it is generally <i>a prolongation of the</i> <span class=\"ar\">قِبَال</span>]: (T:) or the <i>part that touches the ground, of the thing that is made to fall down upon the foot,</i> (M, A, K,) <i>attached to the</i> <span class=\"ar\">شِرَاك</span> [or <i>thong extending from the</i> <span class=\"ar\">قِبَال</span> <i>above mentioned towards the ankle</i>]; (A;) so called because of its waggling. (M.) (tropical:) Of a sword, The <i>thong</i> [or <i>cord</i>] <i>which is attached to the hilt,</i> (T, A,) <i>and which</i> [<i>is sometimes also made fast to the guard, and at other times</i>] <i>hangs loose and dangles.</i> (A.) (assumed tropical:) <i>A skin,</i> or <i>piece of skin, that is hung upon the</i> <span class=\"ar\">آخِرَة</span> [or <i>hinder part</i>] <i>of the</i> [<i>camel's saddle called</i>] <span class=\"ar\">رَحْل</span>; (S, M, K;) also termed <span class=\"ar\">عَذَبَةٌ</span>. (TA.) A poet speaks, metaphorically, of the <span class=\"ar\">ذَوَائِب</span> of palmtrees [app. meaning (tropical:) <i>Hanging clusters of dates</i>]. (M.) And one says <span class=\"ar\">نَارٌ سَاطِعَةٌ الذَّوَائِبِ</span> (tropical:) [<i>A fire of which the flames rise and spread</i>]. (A.) -b3- Also (assumed tropical:) The <i>higher,</i> or <i>highest, part</i> of anything: (M, K:) and <span class=\"ar\"> <span class=\"ar\">ذُؤَابٌ</span></span> is used as its pl., or [as a coll. gen. n., i. e.] as bearing the same relation to <span class=\"ar\">ذُؤَابَةٌ</span> that <span class=\"ar\">سَلٌّ</span> does to <span class=\"ar\">سَلَّةٌ</span>. (M.) You say, <span class=\"ar\">عَلَوْتٌ ذُؤَابَةَ الجَبَلِ</span> (tropical:) [<i>I ascended upon the summit of the mountain</i>]. (A.) And <span class=\"ar\">ذُؤَابَةُ العِزِّ وَ الشَّرَفِ</span> (tropical:) <i>The highest degree of might and of nobility.</i> (T, * M.) And <span class=\"ar\">هُوَ فِى ذُؤَابَةِ قَوْمِهِ</span> (assumed tropical:) <i>He is among the highest of his people;</i> taken from the <span class=\"ar\">ذؤابة</span> of the head. (M.) And <span class=\"ar\">هُمْ ذُؤَابَةُ قَوْمِهِمْ</span> (T, A) and <span class=\"ar\">ذَوَائِبُهُمْ</span> (A) (tropical:) <i>They are the nobles of their people:</i> (A, T:) and <span class=\"ar\">مِنْ ذَوَائِبِ قُرَيْشٍ</span> (tropical:) <i>of the nobles of Kureysh.</i> (TA.) And <span class=\"ar\">فُلَانٌ مِنَ الذَّنَائِبِ لَا مِنَ</span> <span class=\"ar\">الذَّوَائِبِ</span> (tropical:) [<i>Such a one is of the lowest of the people, not of the highest</i>]. (A.) -b4- <span class=\"ar\">ذَوَائِبُ الجَوْزَآءُ</span> is a name of (assumed tropical:) <i>Nine stars disposed in a bowed,</i> or <i>curved, form, in the sleeve of Orion; also called</i> <span class=\"ar\">تَاجُ الجَوْزَآءِ</span>. (Kzw in his description of Orion.) -b5- <span class=\"ar\">ذَوائِبُ لَيْلَةٍ</span> (assumed tropical:) <i>The last,</i> or <i>latter, parts,</i> or <i>portions, of a night.</i> (Har p. 58.)</p><p><b class=\"ar\">أَرْضٌ مَذْأَبَةٌ</b> <i>A land containing,</i> (S,) or <i>abounding with,</i> (M, K,) <i>wolves:</i> (S, M, K:) in the dial. of some of the tribe of Keys, <span class=\"ar\">مَذَيْبَةٌ</span>, agreeing with <span class=\"ar\">ذِيبٌ</span>. (M.)</p><p><b class=\"ar\">مُذَأَّبٌ</b> A boy <i>having a</i> <span class=\"ar\">ذُؤَابَة</span>. (T, S, A, K.) -b2- And (assumed tropical:) A [camel's saddle such as is called] <span class=\"ar\">غَبِيط</span> [&amp;c.] <i>having</i> [<i>a</i> <span class=\"ar\">ذُؤَابَة</span>, i. e.] <i>a skin,</i> or <i>piece of skin, hung upon its</i> <span class=\"ar\">آخِرَة</span> [or <i>hinder part</i>]: (S:) or <i>having a</i> <span class=\"ar\">ذِئْبَة</span> [q. v.]. (TA.)</p><p><b class=\"ar\">مَذْؤُوبٌ</b> A man <i>frightened by wolves:</i> (A, TA:) or <i>whose sheep,</i> or <i>goats, have been fallen upon by the wolf.</i> (S, M, A, K.) -b2- [And hence,] (tropical:) <i>Frightened</i> [<i>as though by a wolf</i>]. (T, TA.) -A2- Also A horse, (Mgh,) or such as is called <span class=\"ar\">بِرْذَوْنٌ</span>, (Lth, T, M, K,) and, accord. to the Tekmileh, an ass, and so <span class=\"ar\">مَذْبُوبٌ</span>, as though from <span class=\"ar\">ذِيبَةٌ</span> for <span class=\"ar\">ذِئْبَةٌ</span>, (Mgh,) <i>Affected with the disease termed</i> <span class=\"ar\">ذِئْبَةٌ</span>. (Lth, T, M, Mgh, K.)</p><p><b class=\"ar\">مُتَذَائِبٌ</b> (assumed tropical:) A man <i>in a state of commotion,</i> or <i>fluctuation;</i> from <span class=\"ar\">تَذَآءَبَتِ الرِّيحُ</span>. (TA from a trad.)</p>"},"ذمم":{"mf":"يقال: ذَمَمْتُهُ أَذُمُّهُ ذَمّاً، فهو مَذْمُومٌ وذَمِيمٌ، قال تعالى: مَذْمُوماً مَدْحُوراً [الإسراء/ ١٨]، وقيل: ذَمَّتُّهُ أَذُمُّهُ على قلب إحدى الميمين تاء.<br>والذِّمَام: ما يذّمّ الرّجل على إضاعته من عهد، وكذلك المَذَمَّةُ والمَذِمَّة. وقيل: لي مَذَمَّة فلا تهتكها، وأذهب مَذَمَّتَهُمْ بشيء، أي: أعطهم شيئا لما لهم من الذّمام. وأَذَمَّ بكذا: أضاع ذمامه، ورجل مُذِمٌّ: لا حراك <strong>«٢»</strong> به، وبئر ذَمَّةٌ:<br><strong>قليلة الماء، قال الشاعر:</strong><br><span class=\"num\">١٧٠-</span><table class=\"poem\"><tr><td>وترى الذّميم على مراسنهم </td><td> يوم الهياج كمازن الجثل</td></tr></table><strong>«٣»</strong> الذَّمِيم: شبه بثور صغار. يقال: أصله الذنة والذنين.","mq":[["ذميم ومذموم"],"الذال والميم فى المضاعف أصلٌ واحد يدلُّ كلُّه على خلافِ الحمد. يقال ذَمَمْتُ فلاناً أذُمُّه، فهو ذميمٌ ومذموم، إذا كان غير حميد. ومن هذا الباب الذّمَّة، وهى البئر القليلةُ الماء. و<br>فى الحديث: «أنّه أتى على بئرٍ ذَمَّةٍ»<br>.<br>وجمع الذَّمَّة ذِمام. قال ذو الرُّمّة:<br>على حِمَيرِيّاتٍ كأنَّ عيونَها … ذِمامُ"],"ln":"<p><b>1.</b> <b class=\"ar\">ذَمَّهُ</b> , (T, S, M, &amp;c.,) aor. <b class=\"ar\">ذَمُمَ</b> , (T, M, Msb,) inf. n. <span class=\"ar\">ذَمٌّ</span> (T, S, M, Mgh, Msb, K) and <span class=\"ar\">مَذَمَّةٌ</span>, (M, K,) <i>He blamed, dispraised, discommended, found fault with, censured,</i> or <i>reprehended, him, in respect of evil conduct;</i> <span class=\"ar\">الذَّمُّ</span> signifying <span class=\"ar\">اللَّوْمُ</span> (T, Mgh) <span class=\"ar\">فِى الإِسَآءَةِ</span>; (T;) <i>contr. of</i> <span class=\"ar\">المَدْحُ</span>, (S, M, Mgh, Msb, K,) or <i>of</i> <span class=\"ar\">الحَمْدُ</span>: (Mgh:) and <span class=\"ar\"> <span class=\"ar\">ذمّمهُ</span></span>, (MA,) inf. n. <span class=\"ar\">تَذْمِيمٌ</span>, (KL,) signifies the same: (MA, KL:) [or this has an intensive meaning: see its pass. part. n., below.] Hence the saying, <span class=\"ar\">اِفْعَلْ كَذَا وخَلَاكَ ذَمٌّ</span>, (T, S, K,) i. e. <span class=\"ar\">خَلَا مِنْكَ ذَمٌّ</span>, meaning [<i>Do thou such a thing, and</i>] <i>thou wilt not be blamed;</i> (ISk, S, K;) or <i>thou wilt have an excuse;</i> [lit.] <i>blame will full from thee:</i> (S in art. <span class=\"ar\">خلو</span>:) one should not say <span class=\"ar\">خَلَاكَ ذَنْبٌ</span>. (ISk, S in the present art.) <span class=\"ar\">ذُمَّ</span>, also, signifies <i>He was satirized,</i> particularly <i>in verse.</i> (IAar, T.) And <i>He was made to suffer loss</i> or <i>diminution</i> [app. <i>in respect of his reputation</i>]. (IAar, T.) -b2- <span class=\"ar\">ذَمَّ المَكَانُ</span> (tropical:) <i>The place was,</i> or <i>became, affected with drought,</i> or <i>barrenness, and its good things</i> [or <i>produce</i>] <i>became scanty.</i> (TA.) [But perhaps <span class=\"ar\">ذَمَّ</span> is here a mistranscription for <span class=\"ar\">ذُمَّ</span>; for] you say of a land, <span class=\"ar\">ذَمَّ مَرْعَاهَا</span> [<i>He dispraised,</i> or <i>discommended, its pasture,</i> when its pasture is scanty]. (S and M and K in art. <span class=\"ar\">بذأ</span>.) -A2- <span class=\"ar\">ذَمَّ</span>, [aor. <b class=\"ar\">ذَمِمَ</b> ,] said of the nose, (S, K,) <i>It flowed</i> [<i>with</i> <span class=\"ar\">ذَمِيم</span>, i. e. <i>mucus</i>]; (K;) like <span class=\"ar\">ذَنَّ</span>. (S, K.) And [the aor.] <span class=\"ar\">يَذِمُّ</span> is said of <span class=\"ar\">ذَمِيم</span>; (S, K;) like <span class=\"ar\">يَذِنُّ</span>; (S, TA;) meaning <i>It flows.</i> (TA.)</p><p><b>2.</b> <b class=\"ar\">ذَمَّمَ</b> see 1, first sentence.</p><p><b>3.</b> <b class=\"ar\">فُلَانٌ يُذَامُّ عَيْشَهُ</b> (assumed tropical:) <i>Such a one passes his life contended with scantiness.</i> (TA.)</p><p><b>4.</b> <b class=\"ar\">اذمّ</b> <i>He</i> (a man) <i>did</i> [or <i>said</i>] <i>that for which he should be blamed, dispraised, discommended, found fault with, censured,</i> or <i>reprehended;</i> (S;) <i>contr. of</i> <span class=\"ar\">أَحْمَدَ</span>. (A in art. <span class=\"ar\">حمد</span>.) And <span class=\"ar\"> <span class=\"ar\">استذمّ</span>إِلَيْهِ</span>, (M, K,) or <span class=\"ar\">إِلَى النَّاسِ</span>, (S,) <i>He did to him,</i> or <i>to the people, that for which he should be blamed,</i> &amp;c. (S, M, K.) -b2- [Hence,] <span class=\"ar\">أَذَمَّتْ</span> <span class=\"ar\">رَاحِلَتُهُ</span> (tropical:) <i>His riding-camel ceased going on;</i> as though she made the people to blame her. (TA.) And <span class=\"ar\">أَذَمَّتْ رِكَابُهُمْ</span> (tropical:) <i>Their camels upon which they were riding became jaded, and lagged behind,</i> (S, M, K, TA,) <i>not keeping up with the main body of camels;</i> (S, TA;) [as though they made their riders to blame them; or] as though [the idea of] their strength in journeying were derived from <span class=\"ar\">ذَمَّةٌ</span> meaning “ a well having little water. ” (TA.) And <span class=\"ar\">اذمّ بِهَ بَعِيرُهُ</span> (tropical:) [<i>His camel became jaded, and lagged behind with him</i>]. (S, TA.) And <span class=\"ar\">أَذَمَّتْ بِالرَّكْبِ</span>, said of a she-ass, (tropical:) <i>She kept back the company of riders upon camels by her weakness and her ceasing to go on.</i> (TA from a trad.) -A2- <span class=\"ar\">اذمّهُ</span> <i>He found him,</i> or <i>it, to be such as is blamed, dispraised,</i> &amp;c.; (S, M, K, TA;) <i>contr. of</i> <span class=\"ar\">أَحْمَدَهُ</span>. (TA.) One says, <span class=\"ar\">أَتَيْتُ مَوْضِعَ</span> <span class=\"ar\">كَذَا فَأَذْمَمْتُهُ</span>, i. e. [<i>I came to such a place, and</i>] <i>I found it to be such as is discommended.</i> (S) -b2- <span class=\"ar\">اذّم بِهِ</span>, (S,) or <span class=\"ar\">بِهِمْ</span>, (M, K,) He held <i>him,</i> or <i>them, in little,</i> or <i>light,</i> or <i>mean, estimation,</i> or <i>in contempt:</i> (S, K:) or <i>he left</i> [<i>him</i> or] <i>them blamed, dispraised,</i> &amp;c., <i>among the people.</i> (IAar, M, K.) -A3- Also, <span class=\"ar\">اذمّهُ</span>, <i>He protected him; granted him protection,</i> or <i>refuge.</i> (S, K.) -b2- And <span class=\"ar\">اذمّ لَهُ</span> <span class=\"ar\">عَلَيْهِ</span> <i>He took,</i> or <i>obtained, a promise,</i> or <i>an</i> <i>assurance, of security</i> or <i>safety,</i> and <i>a compact,</i> or <i>covenant, for him,</i> or <i>in his favour, of,</i> or <i>against, him</i> [i. e. another person, <i>making the latter responsible for his</i> (the former's) <i>security,</i> or <i>safety,</i> &amp;c.]. (M, * K, * TA.) -A4- See also the next paragraph.</p><p><b>5.</b> <b class=\"ar\">تذمّم</b> <i>He shunned,</i> or <i>avoided,</i> (T, * Mgh,) or <i>he preserved,</i> or <i>guarded, himself from,</i> (MA,) <i>blame, dispraise,</i> &amp;c.: (T, * MA, Mgh:) this is the proper meaning; and hence, (Mgh,) <i>he felt disdain,</i> or <i>scorn,</i> and <i>shame.</i> (S, MA, Mgh, K, KL.) One says, <span class=\"ar\">لَوْ لَمْ أَتْرُكِ الكَذِبَ تَأَثُّمًا لَتَرَكْتُهُ</span> <span class=\"ar\">تَذَمُّمَا</span> [<i>If I did not refrain from lying for the purpose of abstaining from sin, I would refrain from it from a feeling of disdain,</i> or <i>scorn,</i> or <i>shame</i>]. (S, K.) And <span class=\"ar\">تذمّم مِنْهُ</span> [<i>He abstained,</i> or <i>refrained, from it to avoid blame,</i> or <i>through disdain,</i> or <i>scorn,</i> or <i>shame; disdained,</i> or <i>scorned, it;</i> or <i>was ashamed of it</i>]. (K in art. <span class=\"ar\">حشم</span>.) And Aboo-'Amr Ibn-El-'Alà mentions his having heard an Arab of the desert use the expression <span class=\"ar\">لا</span> <span class=\"ar\">يذمّون</span> [app. <span class=\"ar\">لَا <span class=\"ar\">يُذِمُّونَ</span></span>, for the <span class=\"ar\">ا</span> in the measure <span class=\"ar\">أَفْعَلَ</span> sometimes has a privative property,] meaning <i>They do not shun,</i> or <i>avoid, blame;</i> (<span class=\"ar\">لَا يَتَذَمَّمُونَ</span>;) and <i>are not affected with shame.</i> (TA.) It is said in a trad., <span class=\"ar\">مِنْ خِلَالِ المَكَارِمِ</span> <span class=\"ar\">التَّذَمُّمُ لِلصَّاحِبِ</span>, meaning [<i>Of the properties of generous,</i> or <i>honourable, practices, is</i>] <i>the being regardful of everything that is entitled to reverence, respect, honour,</i> or <i>defence, in the character and appertenances of the companion,</i> or <i>friend, and dispelling from oneself the blame that he would incur from men if he were not regardful thereof.</i> (TA.) And one says, <span class=\"ar\">لِلْجَارِ عِنْدَكَ تَذَمُّمٌ</span> and <span class=\"ar\"> <span class=\"ar\">مُسْتَذَمٌّ</span></span> [<i>To the neighbour, with thee, is</i> shown <i>regard of everything that is entitled to reverence, respect, honour,</i> or <i>defence, in his character and appertenances:</i> <span class=\"ar\">مُسْتَذَمٌّ</span> being app. an inf. n. of <span class=\"ar\"> <span class=\"ar\">استذمّ</span></span>, and this being syn. with <span class=\"ar\">تذمّم</span>]. (TA.)</p><p><b>6.</b> <b class=\"ar\">تذامّوا</b> <i>They blamed, dispraised, discommended, found fault with, censured,</i> or <i>reprehended, one another.</i> (M, K.)</p><p><b>10.</b> <b class=\"ar\">استذمّ</b> [<i>He required blame,</i> &amp;c.; as though he called for it; or] <i>he was blamed,</i> or <i>dispraised,</i> &amp;c. (KL.) See also 4, second sentence. -b2- And see 5, last sentence. -b3- [<span class=\"ar\">استذمّ بِذِمَامِهِ</span> is used by post-classical writers, and is perhaps a classical phrase, meaning <i>He begged,</i> or <i>implored, his protection.</i> See an instance in “ Abulfedæ Annales, ” vol. iii. p. 170.]</p><p><b>R. Q. 1.</b> <b class=\"ar\">ذَمْذَمَ</b> <i>He made his gift small,</i> or <i>scanty.</i> (IAar, T, K.)</p><p><b class=\"ar\">ذَمٌّ</b> inf. n. of <span class=\"ar\">ذَمَّهُ</span>. (T, S, M, &amp;c.) [As a simple subst., <i>Blame, dispraise,</i> or <i>censure.</i>] -b2- And [the pl.] <span class=\"ar\">ذُمُومٌ</span> signifies <i>Vices, faults, defects,</i> or <i>the like.</i> (M, K. [See <span class=\"ar\">ذَامٌّ</span>.]) -A2- See also <span class=\"ar\">ذَمِيمٌ</span>. -A3- And see <span class=\"ar\">ذَمَّةٌ</span>.</p><p><b class=\"ar\">ذِمٌّ</b> : see <span class=\"ar\">ذَمِيمٌ</span>. -b2- Also <i>Excessively lean</i> or <i>emaciated;</i> and <i>perishing:</i> (K:) or <i>like him who is perishing.</i> (T, TA.) -b3- See also <span class=\"ar\">ذِمَّةٌ</span>.</p><p><b class=\"ar\">ذَمَّةٌ</b> [as a subst.]; (T, Mgh;) and <span class=\"ar\">بِئْرٌ ذَمَّةٌ</span>, (T, S, M, Mgh, K,) in which the latter word is an epithet, (Mgh,) and <span class=\"ar\"> <span class=\"ar\">ذِمَّةٌ</span></span> also, with kesr, (so in one of my copies of the S,) and <span class=\"ar\"> <span class=\"ar\">ذَمِيمٌ</span></span>, and <span class=\"ar\">ذَمِيمَةٌ</span>; (M, K;) <i>A well containing little water;</i> (T, S, M, Mgh, K;) because discommended: (M, Mgh:) and, (M, K,) as some say, (M,) <i>containing much water:</i> thus having two contr. significations: (M, K:) pl. <span class=\"ar\">ذِمَامٌ</span> (T, S, M, K) and <span class=\"ar\"> <span class=\"ar\">ذَمٌّ</span></span>, (T, TA,) [or rather the latter is a coll. gen. n., of which <span class=\"ar\">ذَمَّةٌ</span> is the n. un.] A poet says, (S,) namely, Dhu-r-Rummeh, describing camels whose eyes were sunk in their sockets by reason of fatigue, (T,) <span class=\"ar\">عَلَى حِمْيَرِيَّاتٍ كَأَنَّ عُيُونَهَا</span> <span class=\"ar\">ذِمَامُ الرَّكَايَا أَنْكَزَتْهَا المَوَاتِحُ</span> [<i>Upon camels of Himyer</i> that were <i>as though their eyes were wells containing little water which the camels employed to draw it had exhausted</i>]. (T, S.)</p><p><b class=\"ar\">ذِمَّةٌ</b> <i>A compact, a covenant, a contract, a league, a treaty, an engagement, a bond,</i> or <i>an obligation;</i> (T, S, M, Mgh, Msb, K;) because the breaking thereof necessitates blame: (Mgh:) and <i>a right,</i> or <i>due,</i> (<span class=\"ar\">حَقٌّ</span>,) <i>for the neglect of which one is to be blamed:</i> (Bd in ix. 8:) [<i>an inviolable right</i> or <i>due:</i>] and <span class=\"ar\"> <span class=\"ar\">ذِمَامٌ</span></span> and <span class=\"ar\"> <span class=\"ar\">مَذِمَّةٌ</span></span> and <span class=\"ar\"> <span class=\"ar\">مَذَمَّةٌ</span></span> signify in like manner <i>a compact, a covenant,</i> &amp;c. as above, <i>for the neglect,</i> or <i>nonobservance, of which a man is to be blamed:</i> (Msb:) or these three words [in the CK the first and last only] signify <i>a right,</i> or <i>due;</i> syn. <span class=\"ar\">حَقٌّ</span>: (M, K:) or so the first of them: (T, * S:) and each of them, (M, K,) or the first of them, i. e. <span class=\"ar\">ذِمَامٌ</span>, (T, S, Mgh,) <i>i. q.</i> <span class=\"ar\">حُرْمَةٌ</span> [which includes all the significations of <span class=\"ar\">ذِمَّةٌ</span> likewise, those above and those which follow, but appears here to be used as meaning especially <i>a thing that should be sacred,</i> or <i>inviolable;</i> or <i>which one is under an obligation to reverence, respect,</i> or <i>honour, and defend; everything that is entitled to reverence, respect, honour,</i> or <i>defence. in the character and appertenances</i> of a person]; (S, M, Mgh, K;) <i>every</i> <span class=\"ar\">حُرْمَة</span> <i>for the neglect,</i> or <i>non-observance, of which one is to be blamed:</i> (T:) <span class=\"ar\"> <span class=\"ar\">ذَمَامَةٌ</span></span>, also, and <span class=\"ar\"> <span class=\"ar\">ذِمَامَةٌ</span></span>, are <i>syn. with</i> <span class=\"ar\">حَقٌّ</span> and <span class=\"ar\">حُرْمَةٌ</span>: (TA:) and <span class=\"ar\">ذِمَّةٌ</span> signifies also <i>i. q.</i> <span class=\"ar\">أَمَانٌ</span> [as meaning <i>security,</i> or <i>safety; security of life and property; protection,</i> or <i>safeguard; a promise,</i> or <i>an assurance, of security, safety, protection,</i> or <i>safeguard; indemnity;</i> or <i>quarter</i>]; (S, Mgh, Msb, KL, TA;) and so <span class=\"ar\"> <span class=\"ar\">ذِمَامٌ</span></span>: (MA, KL: [explained in both by the Pers. <span class=\"ar\">زِنْهَارْ</span>; and in the latter by <span class=\"ar\">حُرْمَةٌ</span> and <span class=\"ar\">حَقٌّ</span> also:]) and <i>responsibility</i> [<i>for the fulfilment of an obligation, for the payment of a sum of money, for the restitution of a thing,</i> or <i>for the safety,</i> or <i>safe-keeping, of a thing</i> or <i>person</i>]; <i>suretiship;</i> (M, Mgh, Msb, K;) as also <span class=\"ar\"> <span class=\"ar\">ذَمَامَةٌ</span></span> and <span class=\"ar\"> <span class=\"ar\">ذِمَامَةٌ</span></span>; (M, K; [in the former of which, these two words are said to be <i>syn. with</i> <span class=\"ar\">ذِمَّةٌ</span>, app. meaning, <i>in all the senses mentioned above;</i>]) and <span class=\"ar\"> <span class=\"ar\">ذِمٌّ</span></span>: (M, K: [said in the M to be <i>syn. with</i> <span class=\"ar\">ذِمَّةٌ</span> <i>in the first</i> only <i>of the senses mentioned above in this paragraph:</i> in the CK, <span class=\"ar\">والذِّمُّ</span> is erroneously put for <span class=\"ar\">وَ الذِّمِّ</span>:]) the pl. of <span class=\"ar\">ذِمَّةٌ</span> is <span class=\"ar\">ذِمَمٌ</span> (T, Msb) and <span class=\"ar\">ذِمَامٌ</span>: (T:) and the pl. of <span class=\"ar\"> <span class=\"ar\">ذِمَامٌ</span></span> as [a sing.] syn. with [<span class=\"ar\">ذِمَّةٌ</span> and] <span class=\"ar\">مَذَمَّةٌ</span> and <span class=\"ar\">مَذِمَّةٌ</span> is <span class=\"ar\">أَذِمَّةٌ</span>. (M, K.) Hence, i. e. from <span class=\"ar\">ذِمَّةٌ</span> in the first of the senses explained above, <span class=\"ar\">أَهلُ الذِّمَّةِ</span>, (S, Mgh, TA.) and <span class=\"ar\">الذِّمِّةُ</span>, (T, M, * Mgh, K, TA,) with the prefixed noun <span class=\"ar\">اهل</span> suppressed, (TA,) <i>The people with whom a compact,</i> or <i>covenant,</i> &amp;c., <i>has been made;</i> (T, S, M, K, TA;) [and particularly] <i>those, of the believers in a plurality of Gods,</i> [by which are here meant <i>the Christians, Jews, and Sabians,</i> but no others,] <i>who pay the</i> [<i>tax called</i>] <span class=\"ar\">جِزْيَة</span>; (T, TA;) [i. e. <i>the free non-Muslim subjects of a Muslim government, who pay a poll-tax for which the Muslims are responsible for their security and freedom and toleration:</i> see <span class=\"ar\">أَهْلٌ</span>:] the appellation <span class=\"ar\"> <span class=\"ar\">ذِمِّىٌّ</span></span>, (Mgh, Msb,) a rel. n. from <span class=\"ar\">الذِّمَّةُ</span>, (Msb;) is applied to <i>a person of this class;</i> (Mgh, Msb;) because he is rendered secure, or free from fear, for his property and his blood, by means of the <span class=\"ar\">جِزْيَة</span>. (Mgh.) <span class=\"ar\">جَعَلَ عُمَرُ أَهْلَ السَّوَادِ ذِمَّةً</span> means <i>'Omar treated</i> [lit. <i>made</i>] <i>the people of the Sawád as those who are termed</i> <span class=\"ar\">أَهْلُ الذِّمَّةِ</span>. (Mgh.) And <span class=\"ar\">أَقْبِلْنَا بِذِمَّةٍ</span> [or <span class=\"ar\">أَقْلِبْنَا</span>?], in the prayer of the traveller, means <i>Restore us to our family in safety.</i> (TA.) It is related in a trad. of 'Alee, that he said, <span class=\"ar\">ذِمَّتِى بِمَا</span> <span class=\"ar\">أَقُولُ رَهِينَةٌ وَ أَنَا بِهِ زَعِيمٌ</span>, meaning <i>My responsibility is pledged for</i> [the truth of] <i>what I say, and I am answerable for it;</i> (Mgh, TA; *) i. e. this my saying is true, and I am responsible for it. (Mgh.) And it is said in another trad., <span class=\"ar\">فَقَدْ</span> <span class=\"ar\">بَرِئَتْ مِنْهُ الذِّمَّة</span> [<i>Then the responsibility</i> of God <i>is clear,</i> or <i>quit, of him</i>]; i. e. there is given to every one, by God, a covenant whereby He binds Himself to preserve and protect him; and when he throws himself into destruction, or does that which is unlawful for him to do, or acts at variance with that which he is commanded to do, the covenant of God fails to aid him. (TA.) <span class=\"ar\">فِى ذِمَّتِى كَذَا</span> means <span class=\"ar\">فى ضَمَانِى</span> [virtually <i>I am responsible for such a thing;</i> i. e. for paying it, or restoring it, &amp;c.; but lit. <i>in my responsibility is such a thing;</i> or <i>on my responsibility rests,</i> or <i>lies,</i> or <i>be, such a thing;</i> for <span class=\"ar\">فى</span> may be here used, as it is in many other instances, in the sense of <span class=\"ar\">عَلَى</span>]: (Msb:) [or,] in the saying <span class=\"ar\">ثَبَتَ فِى ذِمَّتِى كَذَا</span>, [which means <i>Such a thing became,</i> or <i>has become, binding, obligatory,</i> or <i>incumbent, on me,</i>] the term <span class=\"ar\">ذِمَّة</span> is applied to designate [the <i>moral sense considered as</i>] <i>the seat</i> [<i>of the sense</i>] <i>of obligation to fulfil what is</i> [<i>properly</i>] <i>termed</i> <span class=\"ar\">ذِمَّة</span> [i. e. <i>a compact,</i> or <i>covenant,</i> or <i>the like</i>]. (Mgh.) <span class=\"ar\">مَا يُذْهِبُ عَنِّى <span class=\"ar\">مَذِمَّةَ</span>الرَّضَاعِ</span> (T, S, Mgh, *) or <span class=\"ar\"> <span class=\"ar\">مَذَمَّةَ</span>الرَّضَاعِ</span>, (T, Mgh,) meaning [<i>What will put away from me the obligation of</i>] <i>the right,</i> or <i>due,</i> of the woman who has suckled <i>for the sucking?</i> is a question occurring in a trad., (T, S, Mgh, *) as put by a man to the Prophet: (T:) and the answer was, “ A slave, male or female: ” (T, S, Mgh:) En-Nakha'ee says, (S,) they liked, on the occasion of the weaning of a child, to give the woman who had suckled it something beside the hire: (S, Mgh:) <span class=\"ar\"> <span class=\"ar\">مَذَمَّةٌ</span></span> in this case is a dial. var. of <span class=\"ar\"> <span class=\"ar\">مَذِمَّةٌ</span></span>: (Mgh:) or, as IAth says, the former is from <span class=\"ar\">الذَّمُّ</span>; and the latter, from <span class=\"ar\">الذِّمَّهُ</span>. (TA.) You say also, <span class=\"ar\">أَذْهِبْ عَنْكَ <span class=\"ar\">مَذَمَّ</span>الرَّضَاعِ بِشَّىْءٍ تُعْطِيهِ الظِّئْرَ</span> and <span class=\"ar\"> <span class=\"ar\">مَذِمَّ</span>الرَّضَاعِ</span>, meaning [<i>Put away from thee the obligation of</i>] <i>the right,</i> or <i>due,</i> that is incumbent on thee to render her <i>for the sucking</i> of thy child [<i>by something that thou shalt give to her who has suckled</i>]. (T.) And <span class=\"ar\">أَذْهِبْ عَنْكَ <span class=\"ar\">مَذِمَّتَهُمْ</span> بِشَىْءٍ</span> and <span class=\"ar\"> <span class=\"ar\">مَذَمَّتَهُمْ</span></span>, (T, and so accord. to different copies of the S and K, in which <span class=\"ar\">عنك</span> is omitted,) <span class=\"ar\">مَذَمَّة</span> being a dial. var., (T,) i. e. [<i>Put away from thee the obligation of their right,</i> or <i>due, by something;</i> meaning] <i>feed them with something,</i> (T,) or <i>give to them something,</i> (S, K,) <i>for they have a right,</i> or <i>due.</i> (T, S, K.) And <span class=\"ar\">قَضَى <span class=\"ar\">مَذِمَّتَهُ</span></span> and <span class=\"ar\"> <span class=\"ar\">مَذَمَّتَهُ</span></span> [<i>He paid his right,</i> or <i>due;</i>] meaning <i>he did good to him,</i> or <i>conferred upon him a benefit</i> or <i>benefits, in order that he might not be blamed.</i> (M, K.) And <span class=\"ar\">ذُو <span class=\"ar\">مَذِمَّةٍ</span>رَجُلٌ</span> and <span class=\"ar\"> <span class=\"ar\">مَذَمَّةٍ</span></span> [in the CK the latter only, <i>A man who has a right,</i> or <i>due,</i>] meaning <span class=\"ar\">كَلٌّ</span> <span class=\"ar\">عَلَى النَّاسِ</span> (tropical:) [<i>a man who is a burden upon people, to be maintained,</i> or <i>supported, by them</i>]. (M, K, TA.) -A2- Also (i. e. <span class=\"ar\">ذِمَّةٌ</span>) <i>A repast,</i> or <i>banquet, to which guests are invited,</i> [<i>simply</i>] <i>for food,</i> or <i>for a wedding.</i> (K.) -A3- See also <span class=\"ar\">ذَمَّةٌ</span>.</p><p><b class=\"ar\">ذِمَامٌ</b> : see <span class=\"ar\">ذِمَّةٌ</span>, in three places. It is also a pl. of <span class=\"ar\">ذِمَّةٌ</span> [as well as syn. therewith]. (T.)</p><p><b class=\"ar\">ذَمِيمٌ</b> <i>Blamed, dispraised, discommended, found fault with, censured,</i> or <i>reprehended;</i> (S, M, Mgh, Msb, K;) <i>i. q.</i> <span class=\"ar\"> <span class=\"ar\">مَذْمُومٌ</span></span>; (T, M, Msb, K;) as also <span class=\"ar\"> <span class=\"ar\">ذِمٌّ</span></span> (T, K, TA) and <span class=\"ar\"> <span class=\"ar\">ذَمٌّ</span></span>, (M, K, TA,) which last is an inf. n. used as an epithet, and, like [its contr.] <span class=\"ar\">حَمْدٌ</span>, is applied to a man and to a place of alighting or sojourning or abiding. (TA.) [See <span class=\"ar\">مُذِمٌّ</span>] -b2- See also <span class=\"ar\">ذَمَّةٌ</span>. -b3- Also, applied to water, <i>Disliked,</i> or <i>disapproved.</i> (S, K. *) -A2- [As a subst.,] <i>Urine and mucus,</i> (K,) so in the copies of the K, but correctly, (TA,) <i>mucus,</i> and <i>urine</i> (S, TA) <i>that flows from the penis of the goat:</i> (S, K, TA:) or <i>a fluid that flows from the nose.</i> (IAar, T.) -b2- And in like manner, <i>Milk</i> [<i>that flows</i>] <i>from the teats of sheep</i> or <i>goats;</i> (K;) or, as in some copies of the S, <i>form the teats of the she-camel;</i> (TA;) or <i>from the teats of the sheep</i> or <i>goat:</i> (so in one of my copies of the S: in the other of those copies omitted:) or <i>milk that becomes sprinkled upon the udders:</i> (Th, M:) or <i>milk that flows upon the thighs and udders of camels and sheep</i> or <i>goats.</i> (M.) -b3- Also <i>Dew,</i> (M, K,) absolutely; (TA;) accord. to IDrd: (M:) or <i>dew that falls in the night upon the trees, and upon which dust lights, so that it becomes like bits of clay</i> or <i>mud.</i> (M, K.) -b4- And <i>A thing</i> [meaning the <i>sebaceous matter</i>] <i>that comes forth from the pores of the soft part of the nose, like the eggs of ants:</i> (S:) or <i>pimples,</i> or <i>small pustules,</i> (<span class=\"ar\">بَثْرٌ</span>, T, K,) or <i>a thing resembling</i> <span class=\"ar\">بَثْر</span>, <i>black,</i> or <i>red,</i> (M,) <i>like the eggs of ants,</i> (T, M,) <i>coming forth upon the nose,</i> (T,) or <i>arising upon the faces</i> (M, K) <i>and the noses,</i> (M,) <i>from heat</i> (T, M, K) or <i>from the scab:</i> (M, K:) or the <i>dirty matter that comes forth upon the nose:</i> n. un. with <span class=\"ar\">ة</span>. (TA.) -b5- And <i>Whiteness upon the nose of a kid.</i> (Kr, M, K.)</p><p><b class=\"ar\">ذَمَامَةٌ</b> : see <span class=\"ar\">ذِمَّةٌ</span>, in two places. -b2- Also <i>Shame, and fear of blame:</i> whence the saying, <span class=\"ar\">أَخَذَتْهُ مِنْ صَاحِبِهِ ذَمَامَةٌ</span> [<i>Shame, and fear of blame, with respect to his companion, seized him</i>]: and <span class=\"ar\">أَصَابَتْهُ مِنْهُ ذَمَامَةٌ</span>, i. e. <i>Shame and disgrace affected him on account of him,</i> or <i>it.</i> (TA.) One says also, <span class=\"ar\">أَخَذَتْنِى مِنْهُ <span class=\"ar\">مَذَمَّةٌ</span></span> and <span class=\"ar\"> <span class=\"ar\">مَذِمَّةٌ</span></span>, meaning <i>Shame and disgrace by reason of the neglect of that which should be sacred</i> or <i>inviolable,</i> or <i>of that which was entitled to reverence, respect, honour,</i> or <i>defence,</i> or <i>of the obligation</i> or <i>duty,</i> or <i>the right</i> or <i>due, that should be regarded as sacred</i> or <i>inviolable,</i> (<span class=\"ar\">مِنْ تَرْكِ الحُرْمَةِ</span>,) [<i>seized me on account of him,</i> or <i>it.</i>] (S, K.)</p><p><b class=\"ar\">ذُمَامَةٌ</b> (assumed tropical:) <i>A remain, remainder, remaining portion, remnant,</i> or <i>relic.</i> (K.) [See also <span class=\"ar\">ذَمَّآء</span>, below.]</p><p><b class=\"ar\">ذِمَامَةٌ</b> : see <span class=\"ar\">ذِمَّةٌ</span>, in two places.</p><p><b class=\"ar\">بِهِ ذَمِيمَةٌ</b> <i>In him is a crippleness,</i> or <i>a chronic disease,</i> (K, [in the CK <span class=\"ar\">ذَمانَةٌ</span> is erroneously put for <span class=\"ar\">زَمَانَةٌ</span>,]) or <i>an infirmity arising therefrom</i> or <i>from some evil affection,</i> (M,) <i>that prevents him from going forth.</i> (M, K.)</p><p><b class=\"ar\">أَبْقَى ذَمَّآءَ الصُّبِّ</b> (tropical:) [<i>He left</i>] <i>the last remains</i> [<i>of what was poured out,</i> or <i>forth, at once</i>]: so in the A. (TA. [But the last word is there written without any syll. signs.]) [See also <span class=\"ar\">ذُمَامَةٌ</span>.]</p><p><b class=\"ar\">ذِمِّىٌّ</b> : see <span class=\"ar\">ذِمَّةٌ</span>, in the former half of the paragraph.</p><p><b class=\"ar\">ذَمَّامٌ</b> One <i>who blames, dispraises, discommends,</i> &amp;c., <i>much,</i> or <i>often.</i> (TA.)</p><p><b class=\"ar\">ذَامٌّ</b> and <span class=\"ar\">ذَامٌ</span>, with and without teshdeed, [the latter belonging to art. <span class=\"ar\">ذيم</span>,] <i>A vice, fault, defect,</i> or <i>the like.</i> (As, T.) [See also <span class=\"ar\">ذَمٌّ</span>.]</p><p><b class=\"ar\">أَذَمُّ</b> A horse <i>fatigued, and standing still.</i> (TA.)</p><p><b class=\"ar\">مَذَمٌّ</b> and <span class=\"ar\">مَذِمٌّ</span>: see <span class=\"ar\">ذِمَّةٌ</span>, in the latter part of the paragraph.</p><p><b class=\"ar\">مُذِّمٌّ</b> A thing <i>blamed, dispraised,</i> &amp;c.; [like <span class=\"ar\">ذَمِيمٌ</span>;] or <i>made,</i> or <i>caused, to be faulty,</i> or <i>defective,</i> or <i>to have a vice, fault, defect,</i> or <i>the like;</i> (S. K;) as also <span class=\"ar\"> <span class=\"ar\">مِذَمٌّ</span></span>. (K.) -b2- And A man (S) <i>in whom is no motion.</i> (S, K.)</p><p><b class=\"ar\">مِذَمٌّ</b> : see the next preceding paragraph.</p><p><b class=\"ar\">مَذَمَّةٌ</b> , with fet-h only [to the <span class=\"ar\">ذ</span>, <i>A cause of blame, dispraise, discommendation, censure,</i> or <i>reprehension; a blamable,</i> or <i>discommendable, quality</i> or <i>action;</i>] <i>a thing for which one is,</i> or <i>is to be, blamed, dispraised, discommended, found fault with, censured,</i> or <i>reprehended:</i> contr. of <span class=\"ar\">مَحْمَدَةٌ</span>: (S:) [pl. <span class=\"ar\">مَذَامٌّ</span>.] You say, <span class=\"ar\">البُخْلُ مَذَمَّةٌ</span>, (S, K,) i. e. [<i>Niggardliness is</i>] <i>one of the things for which one is,</i> or <i>is to be, blamed,</i> &amp;c. (S.) And <span class=\"ar\">إِيَّاكَ وَ المَذَامَّ</span> [<i>Beware thou of,</i> or <i>avoid thou,</i> or <i>remove thyself far from, causes of blame,</i> &amp;c.]. (TA.) -b2- See also <span class=\"ar\">ذِمَّةٌ</span>, in six places. -b3- And see <span class=\"ar\">ذَمَامَةٌ</span>.</p><p><b class=\"ar\">مَذِمَّةٌ</b> : see <span class=\"ar\">ذِمَّةٌ</span>, in six places. -b2- And see also <span class=\"ar\">ذَمَامَةٌ</span>.</p><p><b class=\"ar\">مُذَمَّمٌ</b> A man <i>blamed, dispraised, discommended, found fault with, censured,</i> or <i>reprehended, much.</i> (S, K.) -b2- And A place <i>held in reverence, respect,</i> or <i>honour.</i> (TA.)</p><p><b class=\"ar\">مَذْمُومٌ</b> : see <span class=\"ar\">ذَمِيمٌ</span>, first sentence.</p><p><b class=\"ar\">مُسْتَذَمٌّ</b> : see 5, last sentence.</p>"},"ذقن":{"mf":"قوله تعالى: وَيَخِرُّونَ لِلْأَذْقانِ يَبْكُونَ<br>[الإسراء/ ١٠٩]، الواحد: ذَقَنٌ، وقد ذَقَنْتُهُ:<br>ضربت ذقنه، وناقة ذَقُونٌ: تستعين بذقنها في سيرها، ودلو ذَقُونٌ: ضخمة مائلة تشبيها بذلك.","mq":[[],"الذال والقاف والنون كلمةٌ واحدة إليها يرجع سائرُ ما يشتقّ من الباب. فالذَّقَنُ ذَقَن الإنسان وغيرِه (١)<br>: مَجمَع لَحْيَيه. ويقال ناقةٌ ذَقُونٌ: تحرَّك رأسَها إِذا سارت. والذّاقنة: طرَف الحلقومِ الناتئُ. وهو<br>فى حديث عائشة: «تُوفِّى رسولُ اللّه ﵌ بين سَحْرِى ونَحْرى وحاقِنَتِى وذاقِنَتِى»<br>. وتقول: ذَق"],"ln":"<p><b>1.</b> <b class=\"ar\">ذَقَنَهُ</b> , (JK, S, A, K,) aor. <b class=\"ar\">ذَقُنَ</b> , (JK,) inf. n. <span class=\"ar\">ذَقْنٌ</span>, (TK,) <i>He struck his</i> <span class=\"ar\">ذَقَن</span> [or <i>chin</i>]: (JK, S, A, K:) or <i>he struck him on the back of his neck, or on his head at the part next the back of the neck, with the inside of his hand;</i> syn. <span class=\"ar\">قَفَدَهُ</span>. (K, TA. [In the CK, erroneously, <span class=\"ar\">فَقَدَهُ</span>.]) And <i>He struck him,</i> or <i>beat him,</i> with a staff, or stick. (JK.) -b2- <span class=\"ar\">ذَقَنَ عَلَى يَدِهِ</span>, (K,) or <span class=\"ar\">على عَصَاهُ</span>, (JK, K,) <i>He put his</i> <span class=\"ar\">ذَقَن</span> [or <i>chin</i>] <i>upon his hand,</i> or <i>upon his staff,</i> or <i>stick,</i> (JK, K, TA,) <i>and leaned</i> [<i>upon it</i>]: (TA:) and <span class=\"ar\">ذَقَنَ بِسَوْطِهِ</span> [<i>He leaned his chin upon his whip</i>]: (TA:) as also <span class=\"ar\"> <span class=\"ar\">ذَقَّنَ</span></span>. (K.) -A2- <span class=\"ar\">ذَقِنَتِ الدَّلْوُ</span>, (JK, S, K,) aor. <b class=\"ar\">ذَقَنَ</b> , (JK, K,) inf. n. <span class=\"ar\">ذَقَنٌ</span>, (JK,) <i>The bucket was,</i> or <i>became, such as is termed</i> <span class=\"ar\">ذَقُونٌ</span> (S, K) or <span class=\"ar\">ذَقْنَآءُ</span>. (JK.)</p><p><b>2.</b> <b class=\"ar\">ذَقَّنَ</b> see the preceding paragraph.</p><p><b>3.</b> <b class=\"ar\">ذاقنهُ</b> <i>He straitened him.</i> (K.)</p><p><b>4.</b> <b class=\"ar\">اذقن</b> is said by Golius, as on the authority of the KL, to signify <i>Opem tulit in tollenda re:</i> but the word explained in the KL as signifying the doing this is the inf. n. of <span class=\"ar\">ازقن</span>, not of <span class=\"ar\">اذقن</span>.]</p><p><b class=\"ar\">ذِقْنٌ</b> A <i>decrepit, old and weak, or extremely aged,</i> man. (K.)</p><p><b class=\"ar\">ذَقَنٌ</b> [The <i>chin;</i>] the <i>place where the</i> <span class=\"ar\">لَحْيَانٌ</span> [here meaning the <i>two lateral portions of the lower jaw</i>] <i>combine,</i> (JK, S, Msb, K,) <i>at their lower part:</i> (K:) it is of a man (S, Msb) [and of a beast]: also pronounced with kesr (ISd, K) to the <span class=\"ar\">ذ</span> [i. e. <span class=\"ar\"> <span class=\"ar\">ذِقَنٌ</span></span>]: (TK:) of the masc. gender, (Lh, K,) only: (Lh, TA:) pl. <span class=\"ar\">أَذْقَانٌ</span>, (Msb, K,) a pl. of pauc.; and the pl. of mult. is <span class=\"ar\">ذُقُونٌ</span>. (Msb.) Hence, (K,) <span class=\"ar\">مُثْقَلٌ ٱسْتَعَانَ بِذَقَنِهِ</span> [<i>A heavily-burdened,</i> or <i>overburdened,</i> camel <i>sought to help himself</i> to rise <i>by means of his chin</i>]: (S, M, K:) a prov., applied to a low, base, or mean, and weak man, who seeks to help himself by means of another man like himself; (S;) or to him who seeks to help himself by means of one who has no power of defending, and by means of one more low, base, or mean, and weak, than he: (M:) or to him who seeks to help himself by means of one less than he: (K:) originating from the fact that a camel laden with a heavy load, and unable to rise, bears with his chin upon the ground. (S, K.) You say also, <span class=\"ar\">خِرُّوا لِأَذْقَانِهِمْ</span> [<i>They fell down prostrate, with their chins to the ground:</i> see the Kur xvii. 108 and 109]: and [hence,] <span class=\"ar\">عَصَفَتْ رِيحٌ فَخَرَّتِ الأَشْجَارُ</span> <span class=\"ar\">لِلْأَذْقَانِ</span> (tropical:) [<i>A wind blew violently, so that the trees fell,</i> or <i>bent themselves down to the ground</i>]: (A in art. <span class=\"ar\">خر</span>:) and <span class=\"ar\">هَبّتِ الرِّيحُ فَكَبَّتِ الشَّجَرَ عَلَى</span> <span class=\"ar\">أَذْقَانِهَا</span> (tropical:) [<i>The wind blew, and overturned,</i> or <i>threw down,</i> or <i>bent down, the trees</i>]: and, of a stone, <span class=\"ar\">كَبَّهُ السَّيْلُ لِذَقَنِهِ</span> (tropical:) <i>The torrent overturned it.</i> (TA.) -b2- The <i>hair that grows upon the chin:</i> used in this sense by the vulgar; and said by Esh-Shiháb El-Khafajee, in the “ Shifá el-Ghaleel, ” to be post-classical: Z says, in the “ Rabeea el-Abrár, ” that it signifies the <i>beard</i> in the language of the Nabathæans. (TA.)</p><p><b class=\"ar\">ذِقَنٌ</b> : see the next preceding paragraph, first sentence.</p><p><b class=\"ar\">ذَقَنَى</b> : see the paragraph next following.</p><p><b class=\"ar\">ذَقُونٌ</b> A she-camel <i>that relaxes her chin</i> [<i>so as to make her lower lip hang down</i>] <i> in going along:</i> (S, K:) or <i>that moves about her head in going along:</i> (JK:) or <i>that stretches her steps, and moves about her head, by reason of strength, and briskness, liveliness,</i> or <i>sprightliness, in going along:</i> (A, TA:) pl. <span class=\"ar\">ذُقُنٌ</span>: (TA:) and <span class=\"ar\"> <span class=\"ar\">ذَاقِنَةٌ</span></span>, applied to a she-camel, signifies the same as <span class=\"ar\">ذَقُونٌ</span>. (IAar, TA.) -b2- <span class=\"ar\">دَلْوٌ ذَقُونٌ</span> (assumed tropical:) <i>A bucket</i> [<i>of leather</i>] <i>which one has sewed in such a manner that its lip inclines on one side:</i> (S, K:) or <i>a large bucket inclining on one side:</i> (Er-Rághib, TA:) and <span class=\"ar\">ذَلْوٌ <span class=\"ar\">ذَقَنَى</span></span> <i>a bucket with an inclining lip:</i> (IB, TA:) and <span class=\"ar\">دَلْوٌ <span class=\"ar\">ذَقْنَآءُ</span></span> <i>a bucket that has had an addition made to one of its two sides, and consequently inclines on one side.</i> (JK.)</p><p><b class=\"ar\">الذَّاقِنَةُ</b> <i>The part beneath the</i> <span class=\"ar\">ذَقَن</span> [or <i>chin</i>]: (K:) or <i>the part, of the breast, that is reached by the</i> <span class=\"ar\">ذَقَن</span>: or <i>the</i> <span class=\"ar\">ذَقَن</span> [<i>itself</i>]: (TA:) or <i>the head of the</i> <span class=\"ar\">حُلْقُوم</span> [or <i>windpipe</i>]: (K:) or <i>the prominent extremity of the</i> <span class=\"ar\">حلقوم</span>: (S, K:) thus explained by A'Obeyd and AA in the saying of 'Áïsheh, “ [The Prophet died] between my <span class=\"ar\">حَاقِنَة</span> and my <span class=\"ar\">ذَاقِنَة</span>: ” (TA: [see <span class=\"ar\">الحَاقِنَةُ</span>:]) or <i>the</i> <span class=\"ar\">تَرْقُوٓة</span> [ or <i>collar-bone;</i> or <i>it may here mean the fore part of the throat, next the chest;</i> or <i>the uppermost part of the chest</i>]: (K:) but this, in the M, is an explanation of <span class=\"ar\">الحَاقِنَةُ</span>: (TA:) or <i>the lower part of the belly, next the navel:</i> (K:) but this, also, is given as an explanation of <span class=\"ar\">الحاقنة</span>, by ISd and by Z: (TA:) or <i>the pit of the uppermost part of the breast,</i> or <i>chest:</i> or <i>the upper part of the belly:</i> (K:) and <i>the stomach:</i> (JK:) pl. <span class=\"ar\">ذَوَاقِنُ</span>. (S, TA.) [See also <span class=\"ar\">الحَاقِنَةُ</span>.] Hence the prov., <span class=\"ar\">لَأُلْحِقَنَّ حَوَاقِنَكَ بَذَوَاقِنِكَ</span> [explained in art. <span class=\"ar\">حقن</span>]: <span class=\"ar\">الذَّوَاقِنُ</span>, accord. to Az, means <i>the lower part of the belly.</i> (S.) -A2- See also <span class=\"ar\">ذَقُونٌ</span>.</p><p><b class=\"ar\">أَذْقَنٌ</b> A man <i>long in the</i> <span class=\"ar\">ذَقَن</span> [or <i>chin</i>]: and so [the fem.] <span class=\"ar\">ذَقْنَآءُ</span> applied to a woman. (K.) -b2- And A man <i>having the two sides of the mouth inclining,</i> or <i>wry.</i> (JK.) -b3- And [hence, app.,] <span class=\"ar\">ذَقْنَآءُ</span>, (K, TA,) applied to a woman, by way of comparison, (TA,) (tropical:) <i>Having the</i> <span class=\"ar\">جَهَاز</span> [or <i>pudendum</i>] <i>inclining,</i> or <i>wry.</i> (K, TA.) -b4- <span class=\"ar\">دَلْوٌ ذَقْنَآءُ</span>: see <span class=\"ar\">ذَقُونٌ</span>.</p>"},"ذبب":{"mf":"الذباب يقع على المعروف من الحشرات الطائرة، وعلى النّحل، والزنابير ونحوهما. قال الشاعر:<br><span class=\"num\">١٦٦-</span><table class=\"poem\"><tr><td>فهذا أوان العرض حيّا ذبابه </td><td> زنابيره والأزرق المتلمّس</td></tr></table><strong>«١»</strong> وقوله تعالى: وَإِنْ يَسْلُبْهُمُ الذُّبابُ شَيْئاً [الحج/ ٧٣]، فهو المعروف، وذباب العين:<br>إنسانها، سمّي به لتصوّره بهيئته، أو لطيران شعاعه طيران الذّباب. وذباب السّيف تشبيها به في إيذائه، وفلان ذباب: إذا كثر التأذّي به.<br>وذبّبت عن فلان: طردت عنه الذّباب، والمِذَبّة: ما يطرد به، ثمّ استعير الذّبّ لمجرّد الدّفع، فقيل: ذببت عن فلان، وذُبَّ البعيرُ: إذا دخل ذباب في أنفه. وجعل بناؤه بناء الأدواء نحو:<br>زكم. وبعير مذبوب، وذَبَّ جِسْمُهُ: هزل فصار كذباب، أو كذباب السّيف، والذَّبْذَبَةُ: حكاية صوت الحركة للشيء المعلّق، ثم استعير لكلّ اضطراب وحركة، قال تعالى: مُذَبْذَبِينَ بَيْنَ ذلِكَ<br>[النساء/ ١٤٣]، أي: مضطربين مائلين تارة إلى المؤمنين، وتارة إلى الكافرين، قال الشاعر:<br><span class=\"num\">١٦٧-</span><br>ترى كلّ ملك دونها يتذبذب<br><strong>«٢»</strong> وذَبَّبْنَا إِبِلَنَا: سقناها سوقا شديدا بتذبذب، قال الشاعر:<br><br><span class=\"num\">١٦٨-</span><br>يذبّب ورد على إثره<br><strong>«١»</strong>","mq":[["احدها طويير"],"الذال والباء فى المضاعف أصولٌ ثلاثة: أحدها طُوَيئرٌ، ثم يُحمَل عليه ويشبَّه به غيرُه، والآخَر الحَدُّ والحِدّة، والثالث الاضطرابُ والحرَكة.<br>فالأوّل الذُّباب، معروف، وواحدته ذُبابة، وجمع الجمع أذِبّة. وممّا يشبّه به ويُحمَل عليه ذُباب العَين: إِنسانُها. ويقال ذَبَبْتُ عنه، إذا دفَعْتَ عنه، كأنّك طردت"],"ln":"<p><b>1.</b> <b class=\"ar\">ذَبَّ عَنْهُ</b> , (T, S, M, &amp;c.,) aor. <b class=\"ar\">ذَبُبَ</b> , (T, M, Msb,) inf. n. <span class=\"ar\">ذَبٌّ</span>, (T, S, M, Msb,) <i>He repelled from him: he defended him.</i> (T, S, M, Msb, K.) You say, <span class=\"ar\">يَذُبُّ عَنْ حَرِيمِهِ</span> <i>He repels from,</i> or <i>defends, his wife,</i> or <i>wives,</i> or <i>the like.</i> (T, Msb.) [See also R. Q. 1.] -b2- And <span class=\"ar\">ذَبٌّ</span> signifies also The act of <i>driving away.</i> (T, TA.) You say, <span class=\"ar\">ذَبَّ الذُّبَابَ</span>, and <span class=\"ar\"> <span class=\"ar\">ذبّبهُ</span></span>, <i>He drove away the fly,</i> or <i>flies.</i> (M, TA.) And <span class=\"ar\">الوَحْشُ تَذُبُّ البَقَّ بِأَذْنَابِهَا</span> [<i>The wild animals drive away the gnats with their tails</i>]. (A.) -b3- And [hence,] <span class=\"ar\">أَتَاهُمْ خَاطِبٌ فَذَبُّوهُ</span> (tropical:) <i>One demanding a woman in marriage came to them, and they rejected him,</i> or <i>turned him back.</i> (A, TA.) -A2- <span class=\"ar\">ذُبَّ</span> (assumed tropical:) <i>He</i> (a man, TA) <i>was,</i> or <i>became, possessed;</i> or <i>mad,</i> or <i>insane.</i> (K, TA.) -A3- <span class=\"ar\">ذَبَّ</span>, (M, K,) aor. <b class=\"ar\">ذَبُبَ</b> , [irreg., (the verb being intrans.,) unless the first pers. be <span class=\"ar\">ذَبُبْتُ</span>, like <span class=\"ar\">لَبُبْتُ</span> &amp;c.,] inf. n. <span class=\"ar\">ذَبٌّ</span>, (M,) <i>He</i> (a man, K) <i>went hither and thither, not remaining in one place.</i> (M, K. *) -A4- <span class=\"ar\">ذَبَّ</span>, [aor. <b class=\"ar\">ذَبِبَ</b> ,] <i>It dried; dried up;</i> or <i>became dry.</i> (T.) You say, <span class=\"ar\">ذَبَّتْ شَفَتُهُ</span>, (S, M, K,) aor. <b class=\"ar\">ذَبِبَ</b> , inf. n. <span class=\"ar\">ذَبٌّ</span> and <span class=\"ar\">ذَبَبٌ</span> and <span class=\"ar\">ذُبُوبٌ</span>, (M, K,) <i>His lip became dry,</i> (M, K,) or <i>lost its moisture,</i> (S,) <i>by reason of thirst,</i> (S, K,) or <i>by reason of vehement thirst,</i> (M,) &amp;c.; (M, K;) as also <span class=\"ar\"> <span class=\"ar\">ذَبَّبَتْ</span></span>. (M, K.) And <span class=\"ar\">ذَبَّ لِسَانُهُ</span> (S, M) in like manner [<i>His tongue became dry</i> &amp;c.]. (M.) And <span class=\"ar\">ذَبَّ</span> said of a plant, <i>It withered,</i> or <i>lost its moisture.</i> (S, K.) And said of a pool of water left by a torrent, <i>It dried up in the end of the hot season.</i> (IAar, M, K.) And <span class=\"ar\">ذَبَّ جِسْمُهُ</span> <i>His body became lean,</i> or <i>emaciated,</i> (S, K, TA,) <i>and lost its moisture.</i> (TA.) And <span class=\"ar\">ذَبَّ</span>, (T, K,) aor. <b class=\"ar\">ذَبِبَ</b> , inf. n. <span class=\"ar\">ذَبٌّ</span>, (T,) <i>His colour,</i> or <i>complexion, became altered, by reason of emaciation</i> or <i>hunger</i> or <i>travel</i> &amp;c. (T, K.) -b2- See also 2.</p><p><b>2.</b> <b class=\"ar\">ذبّب عَنْهُ</b> <i>He repelled from him,</i> or <i>defended him, much,</i> or <i>often.</i> (S.) -b2- <span class=\"ar\">ذبّب الذُّبَابَ</span>: see 1. -A2- <span class=\"ar\">ذَبَّبَتْ شَفَتُهُ</span>: see 1. -A3- [<span class=\"ar\">ذَبَّبَ</span>, inf. n. <span class=\"ar\">تَذْبِيبٌ</span>, also signifies <i>It left a</i> <span class=\"ar\">ذُبَابَة</span>, i. e. <i>somewhat remaining.</i> Hence,] <span class=\"ar\">ذبّب النَّهَارُ</span> (S, A, TA,) or <span class=\"ar\"> <span class=\"ar\">ذَبَّ</span></span>, (so in the K, but corrected in the TA,) (tropical:) <i>The day passed so as to leave thereof only a</i> <span class=\"ar\">ذُبَابَة</span>; (A, TA; *) i. e. (TA) <i>the day had only a</i> [<i>small</i>] <i>remainder of it left.</i> (S, K, TA.) And <span class=\"ar\">طَعْنٌ</span> <span class=\"ar\">وَرَمْىٌ غَيْرُ تَذْبِيبٍ</span> (tropical:) <i>A thrusting,</i> or <i>piercing, and a shooting,</i> or <i>casting, with energy</i> [<i>so as not to leave any force unexerted</i>]. (S, * A, TA.) -b2- [Also <i>It left not a</i> <span class=\"ar\">ذُبَابَة</span>, i.e. <i>anything remaining:</i> thus bearing two contr. significations. Hence,] <span class=\"ar\">ذبّب فِى السَّيْرِ</span> (tropical:) <i>He strove, laboured, toiled,</i> or <i>exerted himself, in going,</i> or <i>journeying, so that he left not a</i> <span class=\"ar\">ذُبَابَة</span> [or <i>any part of his journey remaining unaccomplished</i>]: (A, TA:) [or] <span class=\"ar\">ذبّب</span> signifies (assumed tropical:) <i>he hastened, made haste,</i> or <i>sped;</i> syn. <span class=\"ar\">أَسْرَعَ</span>: (M:) [and, accord. to Et-Tebreezee, this is the primary signification: for he says,] <span class=\"ar\">التَّذْبِيبٌ</span> is like <span class=\"ar\">الطِّرَادُ</span> [app. as meaning (assumed tropical:) <i>the act of charging,</i> by a horse or a horseman]: but the primary meaning is <span class=\"ar\">الإِسْرَاعُ</span>. (Ham p. 207.) And <span class=\"ar\">ذَبَّبْنَا لَيْلَتَنَا</span>, (S, K,) inf. n. <span class=\"ar\">تَذْبِيبٌ</span>, (K,) (assumed tropical:) <i>Our beasts became fatigued,</i> or <i>jaded, by journeying</i> [<i>during</i> that <i>our night</i>]. (S, K.)</p><p><b>R. Q. 1.</b> <b class=\"ar\">ذَبْذَبٌ</b> , (T,) inf. n. <span class=\"ar\">ذَبْذَبَةٌ</span>, (K,) <i>He defended</i> his neighbours and family. (T, K.) [See also 1.] -A2- And <i>He annoyed, molested, harmed,</i> or <i>hurt,</i> (T, K,) people. (K.) -A3- And <i>He made</i> a thing <i>to dangle,</i> or <i>move to and fro;</i> (L;) and <i>made</i> it <i>to be in a state of motion, commotion,</i> or <i>agitation.</i> (L, K. *) -b2- [Hence,] <span class=\"ar\">ذَبْذَبَهُ</span>, inf. n. as above, (assumed tropical:) <i>He left him,</i> or <i>made him to be, confounded,</i> or <i>perplexed, not knowing his right course; wavering, vacillating,</i> or <i>going to and fro.</i> (Msb.) -A4- <span class=\"ar\">ذَبْذَبَةٌ</span> also signifies The <i>dangling,</i> or <i>moving to and fro,</i> of a thing suspended in the air: (S, M:) and <span class=\"ar\"> <span class=\"ar\">تَذَبْذُبٌ</span></span> the <i>being in a state of motion</i> or <i>commotion:</i> (S, L:) [or the latter has both these meanings; for] you say, <span class=\"ar\"> <span class=\"ar\">تَذَبْذَبَ</span>الشَّىْءُ</span> <i>the thing dangled,</i> or <i>moved to and fro,</i> (M, A, L,) <i>in the air;</i> (A;) and <i>was in a state of commotion</i> or <i>agitation.</i> (M, L.) It is said in a trad., <span class=\"ar\">فَكَأَنِّىأَنْظُرُ إِلَى يَدَيْهِ تُذَبْذِبَانِ</span>, meaning <i>And it was as though I looked at his two sleeves in a state of commotion,</i> or <i>shaking.</i> (TA.) And you say, <span class=\"ar\"> <span class=\"ar\">تذَبْذَبَ</span>بَيْنَ أَمْرَيْنِ</span> (assumed tropical:) <i>He wavered,</i> or <i>vacillated, between two affairs.</i> (MA.) And <span class=\"ar\"> <span class=\"ar\">تَذَبْذَبَ</span>أَمْرُهُمْ</span> (assumed tropical:) [<i>Their state of affairs was,</i> or <i>became, fluctuating,</i> or <i>unsteady</i>]. (Lh, T in art. <span class=\"ar\">دل</span>.)</p><p><b>R. Q. 2.</b> <b class=\"ar\">تَذَبْذَبَ</b> , inf. n. <span class=\"ar\">تَذَبْذُبٌ</span>: see the next preceding paragraph, in four places.</p><p><b class=\"ar\">ذَبٌّ</b> <i>Repelling:</i> fem. with <span class=\"ar\">ة</span>: hence <span class=\"ar\">ذَبَّاتُ</span> <span class=\"ar\">السَّبِيبِ</span>, a phrase used by Dhu-r-Rummeh, meaning <i>repelling with their tails:</i> or this may be from the signification next following. (Ham p. 510.) -A2- <i>Much in motion.</i> (Ham ubi suprà.) <span class=\"ar\">ذَبٌّ</span>, (M, L,) or <span class=\"ar\"> <span class=\"ar\">ذَابٌّ</span></span>, (K,) [the former correct, and perhaps the latter also,] applied to a camel, <i>That does not,</i> or <i>will not, remain still,</i> or <i>motionless, in a place.</i> (M, L, K.) A poet says, <span class=\"ar\">فَكَأَنَّنَا فِيهِمْ جِمَالٌ ذَبَّةٌ</span> [<i>And it was as though we were, among them, camels that would not remain still in a place</i>]: which shows that <span class=\"ar\">ذَبٌّ</span> is not an inf. n. used as an epithet; for, were it so, he had said <span class=\"ar\">جِمَالٌ ذَبٌّ</span>. (M, L.) -b2- <span class=\"ar\">الذَّبُّ</span> (tropical:) <i>The wild bull;</i> [<i>a species of bovine antelope;</i>] also called <span class=\"ar\">ذَبُّ الرِّيَادِ</span>; (T, S, M, K;) so called because he goes to and fro, not remaining in one place; (M;) or because he pastures going to and fro; (T, S, * M;) or because his females pasture with him, going to and fro: (T:) and called also <span class=\"ar\"> <span class=\"ar\">الأَذَبُّ</span></span>, (T, K,) by poetic license, for <span class=\"ar\">الذَّبُّ</span>; (T;) and <span class=\"ar\"> <span class=\"ar\">الذُّنْبُبُ</span></span>. (K.) -b3- <span class=\"ar\">ذَبُّ الرِّيَادِ</span> is also applied to (tropical:) A man <i>who goes and comes.</i> (Kr, M, TA.) And (tropical:) A man <i>who is in the habit of visiting women.</i> (AA, T, K.)</p><p><b class=\"ar\">ذُبَابٌ</b> [The <i>common fly;</i>] the <i>black thing that is in houses, that falls into the vessel and into food;</i> (M;) <i>well known:</i> (S, K:) so called, accord. to Ed-Demeeree, because of its fluttering about, or because it returns as often as it is driven away: (TA:) and likewise applied to the <i>bee;</i> (M, K;) which is also called <span class=\"ar\">ذُبَابُ الغَيْثِ</span> [<i>the fly of the rain</i>], (IAth, TA,) or <span class=\"ar\">ذُبَابُ غَيْثٍ</span> [<i>the fly of rain</i>]; because the rain is the means of producing herbage, and by herbage it is fed; (Mgh;) or because it accompanies rain, and lives upon that which the rain causes to grow: (IAth, TA:) [accord. to some, it is a coll. gen. n.; and] the n. un. is <span class=\"ar\"> <span class=\"ar\">ذُبَابَةٌ</span></span>: (S, Msb, K:) one should not say <span class=\"ar\">ذِبَّانَةٌ</span> [as the vulgar do in the present day]: (S:) or one should not say <span class=\"ar\"> <span class=\"ar\">ذُبَابَةٌ</span></span>, though El-Ahmar and Ks are related to have used this word [as meaning <i>a kind of fly</i>]; for <span class=\"ar\">ذُبَابٌ</span> is a sing. [properly speaking], and is used as such in the Kur xxii. 72: (M:) the pl. (of pauc., S, Msb) is <span class=\"ar\">أَذِبَّهٌ</span> and (of mult., S, Msb) <span class=\"ar\">ذِبَّانٌ</span> (S, M, Msb, K) and <span class=\"ar\">ذُبٌّ</span>, (M, K,) the last mentioned by Sb, accord. to the dial. of Temeem. (M.) One says, <span class=\"ar\">إِنَّهُ لَأَوْهَى مِنَ الذُّبَابِ</span> [<i>Verily he is more frail than the fly</i>]. (A.) And <span class=\"ar\">هُوَ أَهْوَنُ عَلَىَّ مِنْ طَنِينِ</span> <span class=\"ar\">الذُّبَابِ</span> [<i>He is more contemptible to me than the buzzing of the fly</i>]. (A.) <span class=\"ar\">مَنْجَى الذُّبَابِ</span> [<i>The refuge of the fly</i>] is a prov., applied to him who is protected by his ignobleness. (Har p. 332: there written <span class=\"ar\">مَنْجَا</span>; and in two places, <span class=\"ar\">منجأ</span>.) And <span class=\"ar\">أَبُو الذُّبَابِ</span> [<i>The father of the fly</i>] is an appellation used as meaning (assumed tropical:) <i>He who has stinking breath;</i> and some say <span class=\"ar\">أَبُو الذِّبَّانِ</span> [<i>the father of the flies</i>]: (M, TA:) and is especially applied to 'Abd-El-Melik Ibn-Marwán: (M, A, TA:) whence the saying, <span class=\"ar\">أَبْخَرُ مِنْ أَبِى الذُّبَابِ</span> (A, TA) and <span class=\"ar\">أَبِى الذِّبَّانِ</span> (TA) [<i>More stinking in breath than Abu-dh-Dhubáb</i> and <i>Abu-dh-Dhibbán</i>]. -b2- [Hence,] (tropical:) <i>Evil,</i> or <i>mischief;</i> (A, K;) and <i>annoyance,</i> or <i>harm;</i> as in the saying, <span class=\"ar\">أَصَابَنِى ذُبَابٌ</span> (tropical:) [<i>Evil, &amp;c., befell me</i>]; (A;) and <span class=\"ar\">أَصَابَ فُلَانًا مِنْ</span> <span class=\"ar\">فُلَانٍ ذُبَابٌ لَاذِعٌ</span> (assumed tropical:) <i>Evil,</i> or <i>mischief,</i> [lit. <i>a hurting fly</i>] <i>fell upon such a one from such a one:</i> (T:) or (tropical:) <i>continual evil,</i> as in the saying, <span class=\"ar\">أَصَابَكَ ذُبَابٌ</span> <span class=\"ar\">مِنْ هٰذَا الأَمْرِ</span> (tropical:) [<i>Continual evil hath befallen thee from this thing,</i> or <i>event</i>]; and <span class=\"ar\">شَرُّهَا ذُبَابٌ</span> (tropical:) [<i>Her,</i> or <i>its,</i> or <i>their, evil is a continual evil</i>]. (TA.) -b3- (assumed tropical:) <i>Ill luck.</i> (T, K.) Fr relates that the Prophet saw a man with long hair; and said <span class=\"ar\">ذُبَابٌ</span>, meaning (assumed tropical:) This is <i>ill luck:</i> and hence, <span class=\"ar\">رَجُلٌ <span class=\"ar\">ذُبَابِىٌّ</span></span> (assumed tropical:) [<i>An unlucky man</i>]. (T.) -b4- (assumed tropical:) <i>Plague,</i> or <i>pestilence.</i> (TA.) -b5- (assumed tropical:) <i>Diabolical possession;</i> or <i>madness,</i> or <i>insanity.</i> (K.) -b6- (assumed tropical:) <i>Ignorance:</i> so in the phrase <span class=\"ar\">رَجُلٌ مَحْشِىٌّ الذُّبَابِ</span> (assumed tropical:) [<i>A man stuffed with ignorance</i>]. (M.) -b7- (tropical:) The <span class=\"ar\">إِنْسَان</span> [as meaning the <i>pupil,</i> or <i>apple,</i>] of the eye: (AZ, T, S, M, A, K:) so in the saying, <span class=\"ar\">هُوَ أَعَزُّ عَلَىَّ مِنْ</span> <span class=\"ar\">ذُبَابِ العَيْنِ</span> (tropical:) [<i>He is dearer to me than the apple of the eye</i>]: (A:) [ISd says,] I think it to be so termed as being likened to the <span class=\"ar\">ذُبَاب</span> [properly so called; i.e. the fly]. (M.) And <span class=\"ar\">الذُّبَابُ</span> also signifies (assumed tropical:) <i>A black speck,</i> or <i>spot, in the interior of the</i> <span class=\"ar\">حَدَقَة</span> [or <i>dark part</i>] <i>of the eye of the horse.</i> (M, K.) The pl. is as above. (M.) -b8- <span class=\"ar\">ذُبَابُ السَّيْفِ</span> (T, S, M, A, Msb, K) and <span class=\"ar\"> <span class=\"ar\">ذُبَابَةٌ</span> السَّيْفِ</span> (TA) (tropical:) <i>The</i> <span class=\"ar\">حَدّ</span>, (M, K,) or <span class=\"ar\">طَرَف</span>, (S, Msb,) [each app. here meaning the <i>point,</i> or <i>extremity,</i> though the former also means the <i>edge,</i>] <i>of the sword,</i> (S, M, Msb, K,) <i>which is the part wherewith one strikes:</i> (S, Msb:) or <i>its extremity with which one is pierced,</i> or <i>transpierced;</i> and the <span class=\"ar\">حَدّ</span> [here meaning edge] with which one strikes is called its <span class=\"ar\">غِرَار</span>: (En-Nadr, T:) or <i>its tapering,</i> or <i>pointed, extremity;</i> expl. by <span class=\"ar\">طَرَفُهُ المُتَطَرِّفُ</span>: (M, K:) or <i>the point</i> (<span class=\"ar\">حَدّ</span>) <i>of its extremity</i> (M, A) <i>which is between its</i> <span class=\"ar\">شَفْرَتَانِ</span>: (M:) the parts of its two edges that are on either side of it are its <span class=\"ar\">ظُبَتَانِ</span>: the ridge in the middle of it, on the inner and outer sides, is called the <span class=\"ar\">عَيْر</span>; and each has what are termed <span class=\"ar\">غِرَارَانِ</span>, which are the part between the <span class=\"ar\">عَيْر</span> and each one of the <span class=\"ar\">ظُبَتَانِ</span> on the outer side of the sword and the corresponding portion of the inner side, each of the <span class=\"ar\">غِرَارَانِ</span> being on the inner side of the sword and its outer side. (AZ, T, TA.) [The swords of the Arabs, in the older times, were generally straight, twoedged, and tapering to a point; and so are many of them in the present day; a little wider towards the point than towards the hilt.] Hence the saying, <span class=\"ar\">ثَمَرَةُ السَّوْطِ يَتْبَعُهَا ذُبَابُ السَّيْفِ</span> (tropical:) [<i>The knot,</i> or <i>tail, at the end of the whip is followed by the point of the sword;</i> i. e., whipping (if it effect not the desired correction) is followed by slaughter]. (A.) -b9- [Hence,] <span class=\"ar\">ذُبَابٌ</span> signifies likewise (assumed tropical:) The <span class=\"ar\">حَدّ</span> [or <i>point,</i> or <i>extremity,</i> or <i>edge,</i>] of anything. (A 'Obeyd, T.) -b10- (tropical:) The <i>pointed,</i> or <i>sharp, part of the extremity</i> of the ear (A 'Obeyd, M, K) of a horse (A 'Obeyd, M) and of a man. (M.) -b11- (assumed tropical:) The <i>sharp edge</i> of the teeth of camels. (S, TA.) -b12- And (assumed tropical:) The <i>part that first comes forth of the flower</i> of the <span class=\"ar\">حِنَّآء</span> (M, K.)</p><p><b class=\"ar\">ذُبَابَةٌ</b> : see the next preceding paragraph, first sentence, in two places: -b2- and see another sentence, in the latter half of the same paragraph. -b3- (tropical:) <i>A remainder,</i> or <i>remains,</i> (T, S, M, A, * Msb, K,) of a thing, (T, Msb,) of the waters of wells, (T,) or of thirst, (M, A,) and of hunger, (A,) and of a debt, (S, M, K,) and the like, (S,) and of the day, (A,) or, as some say, of anything; (M;) or of a thing that is sound, or valid, or substantial; distinguished from <span class=\"ar\">دُنَانَةٌ</span>, which signifies a remainder, or remains, of a thing that is weak, or frail, and perishing, and particularly of a debt, or of a promise: (S and L in art. <span class=\"ar\">ذن</span>:) pl. <span class=\"ar\">ذُبَابَاتٌ</span>. (T, S, Msb.) You say, <span class=\"ar\">صَدَرَتِ الإِبِلُ</span> <span class=\"ar\">وَبِهَا ذُبَابَةٌ</span>, (M,) or <span class=\"ar\">بِهَا ذُبَابَةٌ مِنْ ظَمَأٍ</span> (A,) i. e. (tropical:) [<i>The camels returned from water having in them</i>] <i>somewhat remaining of thirst.</i> (M.) -b4- And the pl. <span class=\"ar\">ذُبَابَاتٌ</span> also signifies (assumed tropical:) <i>Small mountains:</i> so says El-Andalusee. (MF.)</p><p><b class=\"ar\">ذُبَابِىٌّ</b> : see <span class=\"ar\">ذُبَابٌ</span>.</p><p><b class=\"ar\">ذَبَّابٌ</b> A man <i>who repels from,</i> or <i>defends, with energy, his wife,</i> or <i>wives,</i> or <i>the like;</i> as also <span class=\"ar\"> <span class=\"ar\">مِذَبٌّ</span></span>. (M, K.) -b2- [Hence,] <span class=\"ar\">يِوْمٌ ذَبَّابٌ</span> (tropical:) <i>A sultry day in which the wild animals are infested by numerous gnats, and drive them away with their tails:</i> the act being thus attributed to the day. (A.) -A2- See also what next follows.</p><p><b class=\"ar\">شَفَةٌ ذَبَّانَةٌ</b> , the latter word of the measure <span class=\"ar\">فَعْلَانَةٌ</span>, in some of the copies of the K erroneously written <span class=\"ar\"> <span class=\"ar\">ذَبَّابَةٌ</span></span>, (TA,) [and so in the TT as from the M,] <i>A lip that has become dry,</i> or <i>has lost its moisture.</i> (M, K, TA.)</p><p><b class=\"ar\">ذَبْذَبٌ</b> The <i>penis,</i> (T, * S, M, A, K,) as some say; (M;) as also <span class=\"ar\"> <span class=\"ar\">ذَبْذَبَةٌ</span></span> and <span class=\"ar\"> <span class=\"ar\">ذَبَاذِبُ</span></span>, which last is not a pl., (K,) though of a pl. measure; (TA;) so called because of the motion thereof, to and fro: (TA:) and the <i>tongue:</i> (M, A:) or <span class=\"ar\"> <span class=\"ar\">ذَبْذَبَةٌ</span></span> has this latter meaning: (K:) and <span class=\"ar\"> <span class=\"ar\">ذَبَاذِبُ</span></span> signifies the <i>genitals;</i> or, as some say, the <i>testicles;</i> (M;) one of which is termed <span class=\"ar\"> <span class=\"ar\">ذَبْذَبَةٌ</span></span>. (M, K.)</p><p><b class=\"ar\">ذُبْذُبٌ</b> : see <span class=\"ar\">ذَبَاذِبُ</span>.</p><p><b class=\"ar\">ذِبْذِبٌ</b> : see <span class=\"ar\">ذَبَاذِبُ</span>, in two places.</p><p><b class=\"ar\">ذَبْذَبَةٌ</b> : see <span class=\"ar\">ذَبْذَبٌ</span>, in three places: -b2- and see also <span class=\"ar\">ذَبَاذِبُ</span>.</p><p><b class=\"ar\">ذَبَاذِبُ</b> <i>Certain things that are hung to the</i> [<i>women's camel-vehicle called</i>] <span class=\"ar\">هَوْدَج</span>, (S, M, K,) or <i>to the head of a camel,</i> (M,) <i>for ornament;</i> [i. e. <i>tassels,</i> or <i>pendant tufts of wool,</i> or <i>shreds of woollen cloth, of various colours;</i> (see <span class=\"ar\">رَعَثٌ</span>;)] as also <span class=\"ar\"> <span class=\"ar\">ذَبْذَبَةٌ</span></span>: (M, K:) the sing. of the former is <span class=\"ar\"> <span class=\"ar\">ذِبْذِبٌ</span></span>, (T,) or <span class=\"ar\"> <span class=\"ar\">ذُبْذُبٌ</span></span>, with damm. (TA.) -b2- And The <i>fringes,</i> and <i>edges,</i> of a [garment of the kind called] <span class=\"ar\">بُرْدَة</span>; because of their motion upon the wearer when he walks: sing. <span class=\"ar\"> <span class=\"ar\">ذِبْذِبٌ</span></span>. (TA from a trad.) -b3- See also <span class=\"ar\">ذَبْذَبٌ</span>, in two places.</p><p><b class=\"ar\">ذَابٌّ</b> : see <span class=\"ar\">ذَبٌّ</span>.</p><p><b class=\"ar\">الذُّنْبُبُ</b> : see <span class=\"ar\">ذَبٌّ</span>.</p><p><b class=\"ar\">أَذَبُّ</b> : see <span class=\"ar\">مَذْبُوبٌ</span>: -A2- and <span class=\"ar\">ذَبٌّ</span>. -A3- Also The <i>tush,</i> or <i>canine tooth, of the camel.</i> (T, K.) -A4- And <i>Tall,</i> or <i>long;</i> syn. <span class=\"ar\">طَوِيلٌ</span>. (K.)</p><p><b class=\"ar\">مِذَبٌّ</b> : see <span class=\"ar\">ذَبَّابٌ</span>.</p><p><b class=\"ar\">أَرْضٌ مَذَبَّةٌ</b> (S, M, K) and <span class=\"ar\"> <span class=\"ar\">مَذْبُوبَةٌ</span></span> (Fr, S, K) <i>A land containing,</i> (S,) or <i>abounding with,</i> (M, K,) <i>flies.</i> (S, M, K.)</p><p><b class=\"ar\">مِذَبَّةٌ</b> <i>A thing with which one drives away flies;</i> (S, M, K; *) <i>a fly-whisk made of horse-hairs:</i> (T:) [pl. <span class=\"ar\">مَذَابٌ</span> whence,] one says of wild-animals, <span class=\"ar\">أَذْنَابُهَا مَذَابُّهَا</span> (tropical:) [<i>Their tails are their fly-whisks</i>]. (A.)</p><p><b class=\"ar\">مُذَبِّبٌ</b> (tropical:) A rider <i>hastening,</i> or <i>making haste,</i> (T, S, M, K,) <i>apart from others:</i> (S, M, K:) or <i>striving, labouring, toiling,</i> or <i>exerting himself,</i> in going, or journeying, <i>so as to leave not a</i> <span class=\"ar\">ذُبَابَة</span> [or <i>any part of his journey remaining unaccomplished</i>]. (A.) And it is also applied to a [wild] bull. (A.) In the following saying, <span class=\"ar\">مَسِيرَةٌشَهْرٍ لِلْبَعِيرِ <span class=\"ar\">المُذَبْذِبِ</span></span> (assumed tropical:) [<i>A month's journey to the hastening camel</i>], (M,) or <span class=\"ar\">لِلْبَرِيدِ المُذَبْذِبِ</span> [<i>to the hastening messenger</i>], (TA,) by <span class=\"ar\">المذبذب</span> is meant <span class=\"ar\">المُذَبِّب</span>. (M, TA.) -b2- [(assumed tropical:) A <i>quick</i> journey: or one <i>in which is no flagging,</i> or <i>langour.</i>] You say, <span class=\"ar\">لَا يَنَالُونَ</span> <span class=\"ar\">المَآءِ إِلَّا بِقَرَبٍ مُذَبِّبٍ</span>, i. e. (assumed tropical:) [<i>They will not reach the water but by a</i>] <i>quick</i> [<i>night-journey thereto</i>]. (S.) And <span class=\"ar\">خِمْسٌ مُذَبِّبٌ</span> (assumed tropical:) [<i>A journey in which the camels are watered only on the first and fifth days</i>] <i>in which is no flagging,</i> or <i>langour.</i> (T.) -b3- <span class=\"ar\">ظِمْءٌ مُذَبِّبٌ</span> (assumed tropical:) [<i>An interval between two water-ings</i>] <i>of long duration, in which one journeys from afar</i> (T, S, M, K) <i>and with haste.</i> (T, S, K.)</p><p><b class=\"ar\">مَذْبُوبٌ</b> A camel <i>attacked by flies,</i> (A 'Obeyd, S, M,) <i>that enter his nostrils,</i> (S,) <i>so that his neck becomes twisted, and he dies;</i> as also <span class=\"ar\"> <span class=\"ar\">أَذَبُّ</span></span>: or both signify one <i>that, coming to a cultivated region, finds it unwholesome to him, and dies there:</i> (M:) and the former, a horse <i>into whose nostril the fly has entered.</i> (A.) -b2- See also <span class=\"ar\">أَرْضٌ مَذَبَّةٌ</span>, above. -b3- Also (assumed tropical:) <i>Possessed;</i> or <i>mad,</i> or <i>insane.</i> (K.) -b4- And, accord. to the Abridgment of the 'Eyn, [in a copy of the S written <span class=\"ar\">ذَبُوبٌ</span>, and in other copies thereof omitted,] (assumed tropical:) <i>Foolish; stupid;</i> or <i>unsound, dull,</i> or <i>deficient, in intellect.</i> (TA.)</p><p><b class=\"ar\">مُذَبْذَبٌ</b> <i>Driven away:</i> (TA:) or <i>driven away,</i> or <i>repelled, much.</i> (T, TA.) It is said in a trad., <span class=\"ar\">تَزَوَّجْ وَإِلَّا فَأَنْتَ مِنَ المُذَبْذَبِينَ</span>, i. e. [<i>Marry, or thou wilt be of</i>] <i>those driven away</i> from the believers because thou hast not imitated them, and from the monks because thou hast forsaken their institutes: from <span class=\"ar\">الذَّبُّ</span> “ the act of driving away: ” or, accord. to IAth, it may be from the signification of “ motion and agitation. ” (TA.) And it is said in the Kur [iv. 142], <span class=\"ar\">مُذَبْذَبِينَ بَيْنَ</span> <span class=\"ar\">ذٰلِكَ</span>, meaning <i>Much driven away,</i> or <i>much repelled, from these and from those:</i> (T, TA:) or this is an ex. of the meaning next following. (S, M.) -b2- A man (M, K) <i>wavering,</i> or <i>vacillating, between two things,</i> or <i>affairs;</i> (T, S, M, K;) or <i>between two men, not attaching himself steadily to either;</i> (T;) and <span class=\"ar\"> <span class=\"ar\">مُذَبْذِبٌ</span></span> signifies the same; (K;) as also <span class=\"ar\"> <span class=\"ar\">مُتَذَبْذِبٌ</span></span>. (M.)</p><p><b class=\"ar\">مُذَبْذِبٌ</b> : see what next precedes: -b2- and see also <span class=\"ar\">مُذَبِّبٌ</span>.</p><p><b class=\"ar\">مُتَذَبْذِبٌ</b> : see <span class=\"ar\">مُذَبْذَبٌ</span>, last sentence.</p>"},"ذخر":{"mf":"أصل الادّخار اذتخار، يقال: ذخرته، وادّخرته: إذا أعددته للعقبى. وروي: (أنّ النبيّ صلّى الله عليه وسلم كان لا يدّخر شيئا لغد) <strong>«٤»</strong> والمذاخر:<br>الجوف والعروق المدّخرة للطّعام، قال الشاعر: ١٦٩-<table class=\"poem\"><tr><td>فلما سقيناها العكيس تملّأت </td><td> مذاخرها وامتدّ رشحا وريدها</td></tr></table><strong>«٥»</strong> والإذخر: حشيشة طيّبة الرّيح.","mq":[["احراز شي يحفظه"],"الذال والخاء والراء يدلُّ على إحرازِ شئِ يحفظه. يقال ذخَرْتُ الشّئَ أذْخَرُه ذَخْراً. فإذا قلت افتعلت من ذلك قلت ادّخرتُ. ومن الباب المذاخِر، وهو اسمٌ يجمع جَوفَ الإنسان وعُروقَه. قال منظور (١)<br>:<br>فلمَّا سقيناها العَكِيس تملَّأَتْ … مَذاخِرُها وازداد رَشْحاً وريدُها (٢)<br>ويقولون: ملأ البَعيرُ مَذاخِرَ"],"ln":"<p><b>1.</b> <b class=\"ar\">ذَخَرَهُ</b> , aor. <b class=\"ar\">ذَخَرَ</b> , (S, Msb, K, &amp;c.,) inf. n. <span class=\"ar\"> <span class=\"ar\">ذُخْرٌ</span></span>, (S, K,) or this is a simple subst., and the inf. n. is <span class=\"ar\">ذَخْرٌ</span>; (Msb;) and <span class=\"ar\"> <span class=\"ar\">اِدَّخَرَهُ</span></span>, (S, A, Msb, K,) of the measure <span class=\"ar\">اِفْتَعَلَ</span>, (S, Msb,) originally <span class=\"ar\">اِذْتَخَرَهُ</span>, the <span class=\"ar\">ت</span> being changed into <span class=\"ar\">د</span>, and the <span class=\"ar\">ذ</span> being incorporated into it; and some of the Arabs say <span class=\"ar\"> <span class=\"ar\">اِذَّخَرَهُ</span></span>, which is allowable; but the former is more common; (Zj;) <i>He hoarded it, treasured it,</i> or <i>laid it up for the future; reposited it,</i> or <i>stored it, in secret;</i> (A;) or <i>he prepared it,</i> or <i>provided it;</i> (Msb;) <i>for a time of need:</i> (A, Msb:) or <i>he chose it,</i> or <i>selected it, and</i> (so in some copies of the K and in the TA, but in other copies of the K “ or ”) <i>took it for himself,</i> or <i>prepared it.</i> (K.) Some have made a distinction between <span class=\"ar\">ذخر</span> and <span class=\"ar\">دخر</span>, saying that the former relates to the world to come, and the latter to the present world; but this is a manifest mistake. (MF and others.) -b2- <span class=\"ar\">ذَخَرَ لِنَفْسِهِ حَدِيثًا حَسَنًا</span> (A) (tropical:) <i>He reserved,</i> or <i>preserved, for himself</i> [<i>a good story,</i> or <i>the like</i>]. (TA.) -b3- <span class=\"ar\">ذَخَرَ مِنْ عَدْوِهِ</span> (tropical:) [<i>He</i> (a horse) <i>reserved somewhat of his run,</i> i. e., power of running, or <i>was sparing of it, for the time of need</i>]. (M in art. <span class=\"ar\">صون</span>.) [See also <span class=\"ar\">مُدَّخِرٌ</span>, below.] -b4- <span class=\"ar\">فُلَانٌ مَا</span> <span class=\"ar\">نُصْحًا</span> <span class=\"ar\"><span class=\"ar\">يَدَّخِرُ</span> </span> (tropical:) [<i>Such a one does not treasure in his heart good advice</i>]. (A, TA.)</p><p><b>8.</b> <b class=\"ar\">اِدَّخَرَ</b> and <b class=\"ar\">اِذَّخَرَ</b> : see 1, in three places.</p><p><b class=\"ar\">ذُخْرٌ</b> : see 1: -b2- and see the next paragraph, in two places.</p><p><b class=\"ar\">ذَخِيرَةٌ</b> (S, A, Msb, K) and <span class=\"ar\"> <span class=\"ar\">ذَخْرٌ</span></span> (A, Msb, * K) <i>A thing hoarded, treasured,</i> or <i>laid up; reposited,</i> or <i>stored, in secret;</i> (A;) or <i>prepared,</i> or <i>provided;</i> (Msb;) <i>for a time of need:</i> (A, Msb:) or <i>taken for one's self,</i> or <i>prepared:</i> (K:) pl. of the former, <span class=\"ar\">ذَخَائِرُ</span>; (S, A, Msb;) and of the latter, <span class=\"ar\">أَذْخَارٌ</span>. (Msb, K.) -b2- You say, <span class=\"ar\">جَعَلَ مَا لَهُ <span class=\"ar\">ذُخْرًا</span>عِنْدَ ٱللّٰهِ</span> and <span class=\"ar\">ذَخِيرَةً</span> (tropical:) [<i>He made his wealth to be a store in the hands of God,</i> by applying it to pious uses]. (A.) -b3- And <span class=\"ar\">أَعْمَالُ المُؤمِنِ ذَخَائِرُ</span> (tropical:) [<i>The works of the believer are things laid up for the time of need,</i> i. e. the day of resurrection]. (A.)</p><p><b class=\"ar\">ذَاخِرٌ</b> (assumed tropical:) <i>Fat;</i> as an epithet. (AA, K.)</p><p><b class=\"ar\">إِذْخِرٌ</b> [<i>A kind of sweet rush; juncus odoratus; or schœnanthum;</i>] <i>a certain plant,</i> (S, Mgh, Msb,) or <i>herb,</i> (K,) <i>well known,</i> (Msb,) <i>in form resembling the</i> <span class=\"ar\">كَوْلَان</span> [or <i>papyrus-plant</i>], (Mgh,) <i>sweet-smelling,</i> (K,) or <i>of pungent odour;</i> (Mgh, Msb;) <i>which, when it dries, becomes white;</i> (Msb;) <i>used for roofing houses, over the wood, and for graves:</i> (TA:) <i>it has a root hidden in the ground, slender, pungent in odour; and is like the straight stalks of the</i> <span class=\"ar\">كَوْلَان</span> [or <i>papyrus-plant</i>], <i>save that it is wider, and smaller in the</i> <span class=\"ar\">كُعُوب</span> [which means either the <i>joints or</i> the <i>internodal portions</i>]; <i>and it has a fruit resembling the brooms of reeds, but more slender, and smaller: it is ground, and is an ingredient in perfumes: it grows in rugged</i> <i>and in smooth grounds; but seldom does more than one grow on the same spot: when it dries, it becomes white:</i> (AHn:) 'Iyád asserts that its <span class=\"ar\">ء</span> is a radical letter; but this is a mistake: (MF:) the n. un. is <span class=\"ar\">إِذْخِرَةٌ</span>; (S;) which is applied to a single plant, (AHn,) or to a single fascicle thereof. (Mgh.)</p><p><b class=\"ar\">مِذْخَرٌ</b> (tropical:) The [<i>part of the intestines called</i>] <span class=\"ar\">عَفَج</span>: (TA:) [its pl.] <span class=\"ar\">مَذَاخِرُ</span> is also explained as signifying the <i>intestines; and bellies;</i> (S, K;) and <i>veins:</i> (K:) or the <i>lower part of the belly:</i> (As, K:) or the <i>parts of the inside of a beast in which he stores his fodder and water.</i> (A.) You say <span class=\"ar\">فُلَانٌ مَلَأَ مَذَاخِرَهُ</span> (tropical:) <i>Such a one filled the lower parts of his belly.</i> (As.) And <span class=\"ar\">مَلَأَتِ الدَّابَّةُ مَذَاخِرَهَا</span> (tropical:) <i>The beast satiated itself.</i> (TA.) And <span class=\"ar\">تَمَلَّأَتْ</span> <span class=\"ar\">مَذَاخِرُهُ</span> (tropical:) <i>He became satiated.</i> (A.) And <span class=\"ar\">مَلَأَ</span> <span class=\"ar\">لَنَا فِى مَذَاخِرِهِ عَدَاوَةً</span> (tropical:) [<i>He filled his heart with enmity towards us</i>]. (A.)</p><p><b class=\"ar\">مُدَّخِرٌ</b> <b class=\"ar\">مدخر</b> , or <span class=\"ar\">مُذَّخِرٌ</span>, (accord. to different copies of the K,) (assumed tropical:) A horse <i>that reserves his run;</i> expl. by <span class=\"ar\">المُبْقِى لِحُضْرِهِ</span>: (AO, K, TA:) [Freytag's reading of <span class=\"ar\">مُذَخَّرٌ</span> for <span class=\"ar\">مُدَّخِرٌ</span> or <span class=\"ar\">مُذَّخِرٌ</span>, and his proposed emendation, of <span class=\"ar\">المَنْقِىُّ</span> for <span class=\"ar\">المُبْقِى</span>, both taken from the TK, but neither found by me in any copy of the K, are evidently wrong: see <span class=\"ar\">ذَخَرَ مِنْ عَدْوِهِ</span>, above:] such is the <span class=\"ar\">مِسْوَاط</span>, a horse “ that will not give what he has without the whip: the fem. is with <span class=\"ar\">ة</span>. (TA.)</p>"},"ذيع":{"mq":[["اظهار الشي وظهوره وانتشاره"],"الذال والياء والعين أصلٌ يدلُّ على إظهار الشَّئ وظُهوره وانتشارِه. يقال ذاعَ الخبرُ وغيرُه يَذِيع ذُيوعاً. ورجلٌ مِذياعٌ: لا يكتُم سِرًّا؛ والجمع المذابيع. و<br>فى حديث علىٍّ ﵇<br>: «ليسوا بالمَسَابِيح ولا المَذايِيع البُذْر»<br>. وهاهنا كلمةٌ من هذا فى المعنى من طريقة الانتشار، يقولون: أذاع النّاس [ما (٢)<br>]"],"ln":"<p><b>1.</b> <b class=\"ar\">ذَاعَ</b> , aor. <span class=\"ar\">يَذِيعُ</span>, inf. n. <span class=\"ar\">ذَيْعٌ</span> and <span class=\"ar\">ذُيُوعٌ</span> (S, Msb, K) and <span class=\"ar\">ذَيْعُوعَةٌ</span> and <span class=\"ar\">ذَيَعَانٌ</span>, (S, K,) <i>It</i> (information, news, or tidings, S, K, or discourse, Msb, and a thing, TA) <i>became spread, published,</i> or <i>divulged;</i> (S, Msb, K, TA;) <i>became revealed, made known,</i> or <i>disclosed.</i> (Msb.) -b2- You say also, <span class=\"ar\">ذَاعَ الجَوْرُ</span> (assumed tropical:) <i>Injustice,</i> or <i>tyranny, spread.</i> (TA.) -b3- And <span class=\"ar\">ذَاعَ الجَرَبُ فِى الجِلْدِ</span> (tropical:) <i>The mange,</i> or <i>scab, became general, and spread, in the skin.</i> (TA.)</p><p><b>4.</b> <b class=\"ar\">اذاعهُ</b> , (S, Msb, K,) and <span class=\"ar\">اذاع بِهِ</span>, (Zj, K,) as in the Kur iv. 85, (Zj,) inf. n. <span class=\"ar\">إِذَاعَةٌ</span>, (TA in art. <span class=\"ar\">ذوع</span>,) <i>He spread, published, divulged, revealed, made known,</i> or <i>disclosed, it;</i> (Zj, S, Msb, * K;) <i>and</i> (so Zj, but in the K, “ or, ”) <i>proclaimed it among the people;</i> (Zj, K;) namely, information, news, or tidings, (S,) or discourse, (Msb,) or a secret. (K.) -b2- Hence, app., (TA in art. <span class=\"ar\">ذوع</span>,) <span class=\"ar\">اذاع القَوْمُ</span> (S, K,) and <span class=\"ar\">اذاعت الإِبِلُ</span>, (K,) <span class=\"ar\">مَا فِى الحوض</span>, (S,) or <span class=\"ar\">بِمَا فى الحوض</span>, (K,) (tropical:) <i>The people,</i> or <i>company of men,</i> and <i>the camels, drank what was in the watering-trough,</i> or <i>tank,</i> (S, K, TA,) <i>all of it.</i> (S.) -b3- And hence, app., (TA,) <span class=\"ar\">اذاع بِهِ</span> signifies also (tropical:) <i>He took it away;</i> namely, another's property, (K,) and anything. (TA.) -b4- Accord. to the K, the medial radical letter is both <span class=\"ar\">و</span> and <span class=\"ar\">ى</span>; but correctly it is <span class=\"ar\">ى</span>: (TA in the present art. and in art. <span class=\"ar\">ذوع</span>:) so accord. to AZ and J and Z. (TA in art. <span class=\"ar\">ذوع</span>.)</p><p><b class=\"ar\">مِذْيَاعٌ</b> [<i>A babbler of secrets &amp;c.;</i>] <i>one who will not keep,</i> or <i>conceal, a secret:</i> (S, K:) or <i>one who is unable to conceal his information, news,</i> or <i>tidings:</i> an epithet of an intensive form: (TA:) pl. <span class=\"ar\">مَذَايِيعُ</span>. (S.)</p>"},"ذبذب":{"mf":"الذباب يقع على المعروف من الحشرات الطائرة، وعلى النّحل، والزنابير ونحوهما. قال الشاعر:<br><span class=\"num\">١٦٦-</span><table class=\"poem\"><tr><td>فهذا أوان العرض حيّا ذبابه </td><td> زنابيره والأزرق المتلمّس</td></tr></table><strong>«١»</strong> وقوله تعالى: وَإِنْ يَسْلُبْهُمُ الذُّبابُ شَيْئاً [الحج/ ٧٣]، فهو المعروف، وذباب العين:<br>إنسانها، سمّي به لتصوّره بهيئته، أو لطيران شعاعه طيران الذّباب. وذباب السّيف تشبيها به في إيذائه، وفلان ذباب: إذا كثر التأذّي به.<br>وذبّبت عن فلان: طردت عنه الذّباب، والمِذَبّة: ما يطرد به، ثمّ استعير الذّبّ لمجرّد الدّفع، فقيل: ذببت عن فلان، وذُبَّ البعيرُ: إذا دخل ذباب في أنفه. وجعل بناؤه بناء الأدواء نحو:<br>زكم. وبعير مذبوب، وذَبَّ جِسْمُهُ: هزل فصار كذباب، أو كذباب السّيف، والذَّبْذَبَةُ: حكاية صوت الحركة للشيء المعلّق، ثم استعير لكلّ اضطراب وحركة، قال تعالى: مُذَبْذَبِينَ بَيْنَ ذلِكَ<br>[النساء/ ١٤٣]، أي: مضطربين مائلين تارة إلى المؤمنين، وتارة إلى الكافرين، قال الشاعر:<br><span class=\"num\">١٦٧-</span><br>ترى كلّ ملك دونها يتذبذب<br><strong>«٢»</strong> وذَبَّبْنَا إِبِلَنَا: سقناها سوقا شديدا بتذبذب، قال الشاعر:<br><br><span class=\"num\">١٦٨-</span><br>يذبّب ورد على إثره<br><strong>«١»</strong>","mq":[["احدها طويير"],"الذال والباء فى المضاعف أصولٌ ثلاثة: أحدها طُوَيئرٌ، ثم يُحمَل عليه ويشبَّه به غيرُه، والآخَر الحَدُّ والحِدّة، والثالث الاضطرابُ والحرَكة.<br>فالأوّل الذُّباب، معروف، وواحدته ذُبابة، وجمع الجمع أذِبّة. وممّا يشبّه به ويُحمَل عليه ذُباب العَين: إِنسانُها. ويقال ذَبَبْتُ عنه، إذا دفَعْتَ عنه، كأنّك طردت"],"ln":"<p><b>1.</b> <b class=\"ar\">ذَبَّ عَنْهُ</b> , (T, S, M, &amp;c.,) aor. <b class=\"ar\">ذَبُبَ</b> , (T, M, Msb,) inf. n. <span class=\"ar\">ذَبٌّ</span>, (T, S, M, Msb,) <i>He repelled from him: he defended him.</i> (T, S, M, Msb, K.) You say, <span class=\"ar\">يَذُبُّ عَنْ حَرِيمِهِ</span> <i>He repels from,</i> or <i>defends, his wife,</i> or <i>wives,</i> or <i>the like.</i> (T, Msb.) [See also R. Q. 1.] -b2- And <span class=\"ar\">ذَبٌّ</span> signifies also The act of <i>driving away.</i> (T, TA.) You say, <span class=\"ar\">ذَبَّ الذُّبَابَ</span>, and <span class=\"ar\"> <span class=\"ar\">ذبّبهُ</span></span>, <i>He drove away the fly,</i> or <i>flies.</i> (M, TA.) And <span class=\"ar\">الوَحْشُ تَذُبُّ البَقَّ بِأَذْنَابِهَا</span> [<i>The wild animals drive away the gnats with their tails</i>]. (A.) -b3- And [hence,] <span class=\"ar\">أَتَاهُمْ خَاطِبٌ فَذَبُّوهُ</span> (tropical:) <i>One demanding a woman in marriage came to them, and they rejected him,</i> or <i>turned him back.</i> (A, TA.) -A2- <span class=\"ar\">ذُبَّ</span> (assumed tropical:) <i>He</i> (a man, TA) <i>was,</i> or <i>became, possessed;</i> or <i>mad,</i> or <i>insane.</i> (K, TA.) -A3- <span class=\"ar\">ذَبَّ</span>, (M, K,) aor. <b class=\"ar\">ذَبُبَ</b> , [irreg., (the verb being intrans.,) unless the first pers. be <span class=\"ar\">ذَبُبْتُ</span>, like <span class=\"ar\">لَبُبْتُ</span> &amp;c.,] inf. n. <span class=\"ar\">ذَبٌّ</span>, (M,) <i>He</i> (a man, K) <i>went hither and thither, not remaining in one place.</i> (M, K. *) -A4- <span class=\"ar\">ذَبَّ</span>, [aor. <b class=\"ar\">ذَبِبَ</b> ,] <i>It dried; dried up;</i> or <i>became dry.</i> (T.) You say, <span class=\"ar\">ذَبَّتْ شَفَتُهُ</span>, (S, M, K,) aor. <b class=\"ar\">ذَبِبَ</b> , inf. n. <span class=\"ar\">ذَبٌّ</span> and <span class=\"ar\">ذَبَبٌ</span> and <span class=\"ar\">ذُبُوبٌ</span>, (M, K,) <i>His lip became dry,</i> (M, K,) or <i>lost its moisture,</i> (S,) <i>by reason of thirst,</i> (S, K,) or <i>by reason of vehement thirst,</i> (M,) &amp;c.; (M, K;) as also <span class=\"ar\"> <span class=\"ar\">ذَبَّبَتْ</span></span>. (M, K.) And <span class=\"ar\">ذَبَّ لِسَانُهُ</span> (S, M) in like manner [<i>His tongue became dry</i> &amp;c.]. (M.) And <span class=\"ar\">ذَبَّ</span> said of a plant, <i>It withered,</i> or <i>lost its moisture.</i> (S, K.) And said of a pool of water left by a torrent, <i>It dried up in the end of the hot season.</i> (IAar, M, K.) And <span class=\"ar\">ذَبَّ جِسْمُهُ</span> <i>His body became lean,</i> or <i>emaciated,</i> (S, K, TA,) <i>and lost its moisture.</i> (TA.) And <span class=\"ar\">ذَبَّ</span>, (T, K,) aor. <b class=\"ar\">ذَبِبَ</b> , inf. n. <span class=\"ar\">ذَبٌّ</span>, (T,) <i>His colour,</i> or <i>complexion, became altered, by reason of emaciation</i> or <i>hunger</i> or <i>travel</i> &amp;c. (T, K.) -b2- See also 2.</p><p><b>2.</b> <b class=\"ar\">ذبّب عَنْهُ</b> <i>He repelled from him,</i> or <i>defended him, much,</i> or <i>often.</i> (S.) -b2- <span class=\"ar\">ذبّب الذُّبَابَ</span>: see 1. -A2- <span class=\"ar\">ذَبَّبَتْ شَفَتُهُ</span>: see 1. -A3- [<span class=\"ar\">ذَبَّبَ</span>, inf. n. <span class=\"ar\">تَذْبِيبٌ</span>, also signifies <i>It left a</i> <span class=\"ar\">ذُبَابَة</span>, i. e. <i>somewhat remaining.</i> Hence,] <span class=\"ar\">ذبّب النَّهَارُ</span> (S, A, TA,) or <span class=\"ar\"> <span class=\"ar\">ذَبَّ</span></span>, (so in the K, but corrected in the TA,) (tropical:) <i>The day passed so as to leave thereof only a</i> <span class=\"ar\">ذُبَابَة</span>; (A, TA; *) i. e. (TA) <i>the day had only a</i> [<i>small</i>] <i>remainder of it left.</i> (S, K, TA.) And <span class=\"ar\">طَعْنٌ</span> <span class=\"ar\">وَرَمْىٌ غَيْرُ تَذْبِيبٍ</span> (tropical:) <i>A thrusting,</i> or <i>piercing, and a shooting,</i> or <i>casting, with energy</i> [<i>so as not to leave any force unexerted</i>]. (S, * A, TA.) -b2- [Also <i>It left not a</i> <span class=\"ar\">ذُبَابَة</span>, i.e. <i>anything remaining:</i> thus bearing two contr. significations. Hence,] <span class=\"ar\">ذبّب فِى السَّيْرِ</span> (tropical:) <i>He strove, laboured, toiled,</i> or <i>exerted himself, in going,</i> or <i>journeying, so that he left not a</i> <span class=\"ar\">ذُبَابَة</span> [or <i>any part of his journey remaining unaccomplished</i>]: (A, TA:) [or] <span class=\"ar\">ذبّب</span> signifies (assumed tropical:) <i>he hastened, made haste,</i> or <i>sped;</i> syn. <span class=\"ar\">أَسْرَعَ</span>: (M:) [and, accord. to Et-Tebreezee, this is the primary signification: for he says,] <span class=\"ar\">التَّذْبِيبٌ</span> is like <span class=\"ar\">الطِّرَادُ</span> [app. as meaning (assumed tropical:) <i>the act of charging,</i> by a horse or a horseman]: but the primary meaning is <span class=\"ar\">الإِسْرَاعُ</span>. (Ham p. 207.) And <span class=\"ar\">ذَبَّبْنَا لَيْلَتَنَا</span>, (S, K,) inf. n. <span class=\"ar\">تَذْبِيبٌ</span>, (K,) (assumed tropical:) <i>Our beasts became fatigued,</i> or <i>jaded, by journeying</i> [<i>during</i> that <i>our night</i>]. (S, K.)</p><p><b>R. Q. 1.</b> <b class=\"ar\">ذَبْذَبٌ</b> , (T,) inf. n. <span class=\"ar\">ذَبْذَبَةٌ</span>, (K,) <i>He defended</i> his neighbours and family. (T, K.) [See also 1.] -A2- And <i>He annoyed, molested, harmed,</i> or <i>hurt,</i> (T, K,) people. (K.) -A3- And <i>He made</i> a thing <i>to dangle,</i> or <i>move to and fro;</i> (L;) and <i>made</i> it <i>to be in a state of motion, commotion,</i> or <i>agitation.</i> (L, K. *) -b2- [Hence,] <span class=\"ar\">ذَبْذَبَهُ</span>, inf. n. as above, (assumed tropical:) <i>He left him,</i> or <i>made him to be, confounded,</i> or <i>perplexed, not knowing his right course; wavering, vacillating,</i> or <i>going to and fro.</i> (Msb.) -A4- <span class=\"ar\">ذَبْذَبَةٌ</span> also signifies The <i>dangling,</i> or <i>moving to and fro,</i> of a thing suspended in the air: (S, M:) and <span class=\"ar\"> <span class=\"ar\">تَذَبْذُبٌ</span></span> the <i>being in a state of motion</i> or <i>commotion:</i> (S, L:) [or the latter has both these meanings; for] you say, <span class=\"ar\"> <span class=\"ar\">تَذَبْذَبَ</span>الشَّىْءُ</span> <i>the thing dangled,</i> or <i>moved to and fro,</i> (M, A, L,) <i>in the air;</i> (A;) and <i>was in a state of commotion</i> or <i>agitation.</i> (M, L.) It is said in a trad., <span class=\"ar\">فَكَأَنِّىأَنْظُرُ إِلَى يَدَيْهِ تُذَبْذِبَانِ</span>, meaning <i>And it was as though I looked at his two sleeves in a state of commotion,</i> or <i>shaking.</i> (TA.) And you say, <span class=\"ar\"> <span class=\"ar\">تذَبْذَبَ</span>بَيْنَ أَمْرَيْنِ</span> (assumed tropical:) <i>He wavered,</i> or <i>vacillated, between two affairs.</i> (MA.) And <span class=\"ar\"> <span class=\"ar\">تَذَبْذَبَ</span>أَمْرُهُمْ</span> (assumed tropical:) [<i>Their state of affairs was,</i> or <i>became, fluctuating,</i> or <i>unsteady</i>]. (Lh, T in art. <span class=\"ar\">دل</span>.)</p><p><b>R. Q. 2.</b> <b class=\"ar\">تَذَبْذَبَ</b> , inf. n. <span class=\"ar\">تَذَبْذُبٌ</span>: see the next preceding paragraph, in four places.</p><p><b class=\"ar\">ذَبٌّ</b> <i>Repelling:</i> fem. with <span class=\"ar\">ة</span>: hence <span class=\"ar\">ذَبَّاتُ</span> <span class=\"ar\">السَّبِيبِ</span>, a phrase used by Dhu-r-Rummeh, meaning <i>repelling with their tails:</i> or this may be from the signification next following. (Ham p. 510.) -A2- <i>Much in motion.</i> (Ham ubi suprà.) <span class=\"ar\">ذَبٌّ</span>, (M, L,) or <span class=\"ar\"> <span class=\"ar\">ذَابٌّ</span></span>, (K,) [the former correct, and perhaps the latter also,] applied to a camel, <i>That does not,</i> or <i>will not, remain still,</i> or <i>motionless, in a place.</i> (M, L, K.) A poet says, <span class=\"ar\">فَكَأَنَّنَا فِيهِمْ جِمَالٌ ذَبَّةٌ</span> [<i>And it was as though we were, among them, camels that would not remain still in a place</i>]: which shows that <span class=\"ar\">ذَبٌّ</span> is not an inf. n. used as an epithet; for, were it so, he had said <span class=\"ar\">جِمَالٌ ذَبٌّ</span>. (M, L.) -b2- <span class=\"ar\">الذَّبُّ</span> (tropical:) <i>The wild bull;</i> [<i>a species of bovine antelope;</i>] also called <span class=\"ar\">ذَبُّ الرِّيَادِ</span>; (T, S, M, K;) so called because he goes to and fro, not remaining in one place; (M;) or because he pastures going to and fro; (T, S, * M;) or because his females pasture with him, going to and fro: (T:) and called also <span class=\"ar\"> <span class=\"ar\">الأَذَبُّ</span></span>, (T, K,) by poetic license, for <span class=\"ar\">الذَّبُّ</span>; (T;) and <span class=\"ar\"> <span class=\"ar\">الذُّنْبُبُ</span></span>. (K.) -b3- <span class=\"ar\">ذَبُّ الرِّيَادِ</span> is also applied to (tropical:) A man <i>who goes and comes.</i> (Kr, M, TA.) And (tropical:) A man <i>who is in the habit of visiting women.</i> (AA, T, K.)</p><p><b class=\"ar\">ذُبَابٌ</b> [The <i>common fly;</i>] the <i>black thing that is in houses, that falls into the vessel and into food;</i> (M;) <i>well known:</i> (S, K:) so called, accord. to Ed-Demeeree, because of its fluttering about, or because it returns as often as it is driven away: (TA:) and likewise applied to the <i>bee;</i> (M, K;) which is also called <span class=\"ar\">ذُبَابُ الغَيْثِ</span> [<i>the fly of the rain</i>], (IAth, TA,) or <span class=\"ar\">ذُبَابُ غَيْثٍ</span> [<i>the fly of rain</i>]; because the rain is the means of producing herbage, and by herbage it is fed; (Mgh;) or because it accompanies rain, and lives upon that which the rain causes to grow: (IAth, TA:) [accord. to some, it is a coll. gen. n.; and] the n. un. is <span class=\"ar\"> <span class=\"ar\">ذُبَابَةٌ</span></span>: (S, Msb, K:) one should not say <span class=\"ar\">ذِبَّانَةٌ</span> [as the vulgar do in the present day]: (S:) or one should not say <span class=\"ar\"> <span class=\"ar\">ذُبَابَةٌ</span></span>, though El-Ahmar and Ks are related to have used this word [as meaning <i>a kind of fly</i>]; for <span class=\"ar\">ذُبَابٌ</span> is a sing. [properly speaking], and is used as such in the Kur xxii. 72: (M:) the pl. (of pauc., S, Msb) is <span class=\"ar\">أَذِبَّهٌ</span> and (of mult., S, Msb) <span class=\"ar\">ذِبَّانٌ</span> (S, M, Msb, K) and <span class=\"ar\">ذُبٌّ</span>, (M, K,) the last mentioned by Sb, accord. to the dial. of Temeem. (M.) One says, <span class=\"ar\">إِنَّهُ لَأَوْهَى مِنَ الذُّبَابِ</span> [<i>Verily he is more frail than the fly</i>]. (A.) And <span class=\"ar\">هُوَ أَهْوَنُ عَلَىَّ مِنْ طَنِينِ</span> <span class=\"ar\">الذُّبَابِ</span> [<i>He is more contemptible to me than the buzzing of the fly</i>]. (A.) <span class=\"ar\">مَنْجَى الذُّبَابِ</span> [<i>The refuge of the fly</i>] is a prov., applied to him who is protected by his ignobleness. (Har p. 332: there written <span class=\"ar\">مَنْجَا</span>; and in two places, <span class=\"ar\">منجأ</span>.) And <span class=\"ar\">أَبُو الذُّبَابِ</span> [<i>The father of the fly</i>] is an appellation used as meaning (assumed tropical:) <i>He who has stinking breath;</i> and some say <span class=\"ar\">أَبُو الذِّبَّانِ</span> [<i>the father of the flies</i>]: (M, TA:) and is especially applied to 'Abd-El-Melik Ibn-Marwán: (M, A, TA:) whence the saying, <span class=\"ar\">أَبْخَرُ مِنْ أَبِى الذُّبَابِ</span> (A, TA) and <span class=\"ar\">أَبِى الذِّبَّانِ</span> (TA) [<i>More stinking in breath than Abu-dh-Dhubáb</i> and <i>Abu-dh-Dhibbán</i>]. -b2- [Hence,] (tropical:) <i>Evil,</i> or <i>mischief;</i> (A, K;) and <i>annoyance,</i> or <i>harm;</i> as in the saying, <span class=\"ar\">أَصَابَنِى ذُبَابٌ</span> (tropical:) [<i>Evil, &amp;c., befell me</i>]; (A;) and <span class=\"ar\">أَصَابَ فُلَانًا مِنْ</span> <span class=\"ar\">فُلَانٍ ذُبَابٌ لَاذِعٌ</span> (assumed tropical:) <i>Evil,</i> or <i>mischief,</i> [lit. <i>a hurting fly</i>] <i>fell upon such a one from such a one:</i> (T:) or (tropical:) <i>continual evil,</i> as in the saying, <span class=\"ar\">أَصَابَكَ ذُبَابٌ</span> <span class=\"ar\">مِنْ هٰذَا الأَمْرِ</span> (tropical:) [<i>Continual evil hath befallen thee from this thing,</i> or <i>event</i>]; and <span class=\"ar\">شَرُّهَا ذُبَابٌ</span> (tropical:) [<i>Her,</i> or <i>its,</i> or <i>their, evil is a continual evil</i>]. (TA.) -b3- (assumed tropical:) <i>Ill luck.</i> (T, K.) Fr relates that the Prophet saw a man with long hair; and said <span class=\"ar\">ذُبَابٌ</span>, meaning (assumed tropical:) This is <i>ill luck:</i> and hence, <span class=\"ar\">رَجُلٌ <span class=\"ar\">ذُبَابِىٌّ</span></span> (assumed tropical:) [<i>An unlucky man</i>]. (T.) -b4- (assumed tropical:) <i>Plague,</i> or <i>pestilence.</i> (TA.) -b5- (assumed tropical:) <i>Diabolical possession;</i> or <i>madness,</i> or <i>insanity.</i> (K.) -b6- (assumed tropical:) <i>Ignorance:</i> so in the phrase <span class=\"ar\">رَجُلٌ مَحْشِىٌّ الذُّبَابِ</span> (assumed tropical:) [<i>A man stuffed with ignorance</i>]. (M.) -b7- (tropical:) The <span class=\"ar\">إِنْسَان</span> [as meaning the <i>pupil,</i> or <i>apple,</i>] of the eye: (AZ, T, S, M, A, K:) so in the saying, <span class=\"ar\">هُوَ أَعَزُّ عَلَىَّ مِنْ</span> <span class=\"ar\">ذُبَابِ العَيْنِ</span> (tropical:) [<i>He is dearer to me than the apple of the eye</i>]: (A:) [ISd says,] I think it to be so termed as being likened to the <span class=\"ar\">ذُبَاب</span> [properly so called; i.e. the fly]. (M.) And <span class=\"ar\">الذُّبَابُ</span> also signifies (assumed tropical:) <i>A black speck,</i> or <i>spot, in the interior of the</i> <span class=\"ar\">حَدَقَة</span> [or <i>dark part</i>] <i>of the eye of the horse.</i> (M, K.) The pl. is as above. (M.) -b8- <span class=\"ar\">ذُبَابُ السَّيْفِ</span> (T, S, M, A, Msb, K) and <span class=\"ar\"> <span class=\"ar\">ذُبَابَةٌ</span> السَّيْفِ</span> (TA) (tropical:) <i>The</i> <span class=\"ar\">حَدّ</span>, (M, K,) or <span class=\"ar\">طَرَف</span>, (S, Msb,) [each app. here meaning the <i>point,</i> or <i>extremity,</i> though the former also means the <i>edge,</i>] <i>of the sword,</i> (S, M, Msb, K,) <i>which is the part wherewith one strikes:</i> (S, Msb:) or <i>its extremity with which one is pierced,</i> or <i>transpierced;</i> and the <span class=\"ar\">حَدّ</span> [here meaning edge] with which one strikes is called its <span class=\"ar\">غِرَار</span>: (En-Nadr, T:) or <i>its tapering,</i> or <i>pointed, extremity;</i> expl. by <span class=\"ar\">طَرَفُهُ المُتَطَرِّفُ</span>: (M, K:) or <i>the point</i> (<span class=\"ar\">حَدّ</span>) <i>of its extremity</i> (M, A) <i>which is between its</i> <span class=\"ar\">شَفْرَتَانِ</span>: (M:) the parts of its two edges that are on either side of it are its <span class=\"ar\">ظُبَتَانِ</span>: the ridge in the middle of it, on the inner and outer sides, is called the <span class=\"ar\">عَيْر</span>; and each has what are termed <span class=\"ar\">غِرَارَانِ</span>, which are the part between the <span class=\"ar\">عَيْر</span> and each one of the <span class=\"ar\">ظُبَتَانِ</span> on the outer side of the sword and the corresponding portion of the inner side, each of the <span class=\"ar\">غِرَارَانِ</span> being on the inner side of the sword and its outer side. (AZ, T, TA.) [The swords of the Arabs, in the older times, were generally straight, twoedged, and tapering to a point; and so are many of them in the present day; a little wider towards the point than towards the hilt.] Hence the saying, <span class=\"ar\">ثَمَرَةُ السَّوْطِ يَتْبَعُهَا ذُبَابُ السَّيْفِ</span> (tropical:) [<i>The knot,</i> or <i>tail, at the end of the whip is followed by the point of the sword;</i> i. e., whipping (if it effect not the desired correction) is followed by slaughter]. (A.) -b9- [Hence,] <span class=\"ar\">ذُبَابٌ</span> signifies likewise (assumed tropical:) The <span class=\"ar\">حَدّ</span> [or <i>point,</i> or <i>extremity,</i> or <i>edge,</i>] of anything. (A 'Obeyd, T.) -b10- (tropical:) The <i>pointed,</i> or <i>sharp, part of the extremity</i> of the ear (A 'Obeyd, M, K) of a horse (A 'Obeyd, M) and of a man. (M.) -b11- (assumed tropical:) The <i>sharp edge</i> of the teeth of camels. (S, TA.) -b12- And (assumed tropical:) The <i>part that first comes forth of the flower</i> of the <span class=\"ar\">حِنَّآء</span> (M, K.)</p><p><b class=\"ar\">ذُبَابَةٌ</b> : see the next preceding paragraph, first sentence, in two places: -b2- and see another sentence, in the latter half of the same paragraph. -b3- (tropical:) <i>A remainder,</i> or <i>remains,</i> (T, S, M, A, * Msb, K,) of a thing, (T, Msb,) of the waters of wells, (T,) or of thirst, (M, A,) and of hunger, (A,) and of a debt, (S, M, K,) and the like, (S,) and of the day, (A,) or, as some say, of anything; (M;) or of a thing that is sound, or valid, or substantial; distinguished from <span class=\"ar\">دُنَانَةٌ</span>, which signifies a remainder, or remains, of a thing that is weak, or frail, and perishing, and particularly of a debt, or of a promise: (S and L in art. <span class=\"ar\">ذن</span>:) pl. <span class=\"ar\">ذُبَابَاتٌ</span>. (T, S, Msb.) You say, <span class=\"ar\">صَدَرَتِ الإِبِلُ</span> <span class=\"ar\">وَبِهَا ذُبَابَةٌ</span>, (M,) or <span class=\"ar\">بِهَا ذُبَابَةٌ مِنْ ظَمَأٍ</span> (A,) i. e. (tropical:) [<i>The camels returned from water having in them</i>] <i>somewhat remaining of thirst.</i> (M.) -b4- And the pl. <span class=\"ar\">ذُبَابَاتٌ</span> also signifies (assumed tropical:) <i>Small mountains:</i> so says El-Andalusee. (MF.)</p><p><b class=\"ar\">ذُبَابِىٌّ</b> : see <span class=\"ar\">ذُبَابٌ</span>.</p><p><b class=\"ar\">ذَبَّابٌ</b> A man <i>who repels from,</i> or <i>defends, with energy, his wife,</i> or <i>wives,</i> or <i>the like;</i> as also <span class=\"ar\"> <span class=\"ar\">مِذَبٌّ</span></span>. (M, K.) -b2- [Hence,] <span class=\"ar\">يِوْمٌ ذَبَّابٌ</span> (tropical:) <i>A sultry day in which the wild animals are infested by numerous gnats, and drive them away with their tails:</i> the act being thus attributed to the day. (A.) -A2- See also what next follows.</p><p><b class=\"ar\">شَفَةٌ ذَبَّانَةٌ</b> , the latter word of the measure <span class=\"ar\">فَعْلَانَةٌ</span>, in some of the copies of the K erroneously written <span class=\"ar\"> <span class=\"ar\">ذَبَّابَةٌ</span></span>, (TA,) [and so in the TT as from the M,] <i>A lip that has become dry,</i> or <i>has lost its moisture.</i> (M, K, TA.)</p><p><b class=\"ar\">ذَبْذَبٌ</b> The <i>penis,</i> (T, * S, M, A, K,) as some say; (M;) as also <span class=\"ar\"> <span class=\"ar\">ذَبْذَبَةٌ</span></span> and <span class=\"ar\"> <span class=\"ar\">ذَبَاذِبُ</span></span>, which last is not a pl., (K,) though of a pl. measure; (TA;) so called because of the motion thereof, to and fro: (TA:) and the <i>tongue:</i> (M, A:) or <span class=\"ar\"> <span class=\"ar\">ذَبْذَبَةٌ</span></span> has this latter meaning: (K:) and <span class=\"ar\"> <span class=\"ar\">ذَبَاذِبُ</span></span> signifies the <i>genitals;</i> or, as some say, the <i>testicles;</i> (M;) one of which is termed <span class=\"ar\"> <span class=\"ar\">ذَبْذَبَةٌ</span></span>. (M, K.)</p><p><b class=\"ar\">ذُبْذُبٌ</b> : see <span class=\"ar\">ذَبَاذِبُ</span>.</p><p><b class=\"ar\">ذِبْذِبٌ</b> : see <span class=\"ar\">ذَبَاذِبُ</span>, in two places.</p><p><b class=\"ar\">ذَبْذَبَةٌ</b> : see <span class=\"ar\">ذَبْذَبٌ</span>, in three places: -b2- and see also <span class=\"ar\">ذَبَاذِبُ</span>.</p><p><b class=\"ar\">ذَبَاذِبُ</b> <i>Certain things that are hung to the</i> [<i>women's camel-vehicle called</i>] <span class=\"ar\">هَوْدَج</span>, (S, M, K,) or <i>to the head of a camel,</i> (M,) <i>for ornament;</i> [i. e. <i>tassels,</i> or <i>pendant tufts of wool,</i> or <i>shreds of woollen cloth, of various colours;</i> (see <span class=\"ar\">رَعَثٌ</span>;)] as also <span class=\"ar\"> <span class=\"ar\">ذَبْذَبَةٌ</span></span>: (M, K:) the sing. of the former is <span class=\"ar\"> <span class=\"ar\">ذِبْذِبٌ</span></span>, (T,) or <span class=\"ar\"> <span class=\"ar\">ذُبْذُبٌ</span></span>, with damm. (TA.) -b2- And The <i>fringes,</i> and <i>edges,</i> of a [garment of the kind called] <span class=\"ar\">بُرْدَة</span>; because of their motion upon the wearer when he walks: sing. <span class=\"ar\"> <span class=\"ar\">ذِبْذِبٌ</span></span>. (TA from a trad.) -b3- See also <span class=\"ar\">ذَبْذَبٌ</span>, in two places.</p><p><b class=\"ar\">ذَابٌّ</b> : see <span class=\"ar\">ذَبٌّ</span>.</p><p><b class=\"ar\">الذُّنْبُبُ</b> : see <span class=\"ar\">ذَبٌّ</span>.</p><p><b class=\"ar\">أَذَبُّ</b> : see <span class=\"ar\">مَذْبُوبٌ</span>: -A2- and <span class=\"ar\">ذَبٌّ</span>. -A3- Also The <i>tush,</i> or <i>canine tooth, of the camel.</i> (T, K.) -A4- And <i>Tall,</i> or <i>long;</i> syn. <span class=\"ar\">طَوِيلٌ</span>. (K.)</p><p><b class=\"ar\">مِذَبٌّ</b> : see <span class=\"ar\">ذَبَّابٌ</span>.</p><p><b class=\"ar\">أَرْضٌ مَذَبَّةٌ</b> (S, M, K) and <span class=\"ar\"> <span class=\"ar\">مَذْبُوبَةٌ</span></span> (Fr, S, K) <i>A land containing,</i> (S,) or <i>abounding with,</i> (M, K,) <i>flies.</i> (S, M, K.)</p><p><b class=\"ar\">مِذَبَّةٌ</b> <i>A thing with which one drives away flies;</i> (S, M, K; *) <i>a fly-whisk made of horse-hairs:</i> (T:) [pl. <span class=\"ar\">مَذَابٌ</span> whence,] one says of wild-animals, <span class=\"ar\">أَذْنَابُهَا مَذَابُّهَا</span> (tropical:) [<i>Their tails are their fly-whisks</i>]. (A.)</p><p><b class=\"ar\">مُذَبِّبٌ</b> (tropical:) A rider <i>hastening,</i> or <i>making haste,</i> (T, S, M, K,) <i>apart from others:</i> (S, M, K:) or <i>striving, labouring, toiling,</i> or <i>exerting himself,</i> in going, or journeying, <i>so as to leave not a</i> <span class=\"ar\">ذُبَابَة</span> [or <i>any part of his journey remaining unaccomplished</i>]. (A.) And it is also applied to a [wild] bull. (A.) In the following saying, <span class=\"ar\">مَسِيرَةٌشَهْرٍ لِلْبَعِيرِ <span class=\"ar\">المُذَبْذِبِ</span></span> (assumed tropical:) [<i>A month's journey to the hastening camel</i>], (M,) or <span class=\"ar\">لِلْبَرِيدِ المُذَبْذِبِ</span> [<i>to the hastening messenger</i>], (TA,) by <span class=\"ar\">المذبذب</span> is meant <span class=\"ar\">المُذَبِّب</span>. (M, TA.) -b2- [(assumed tropical:) A <i>quick</i> journey: or one <i>in which is no flagging,</i> or <i>langour.</i>] You say, <span class=\"ar\">لَا يَنَالُونَ</span> <span class=\"ar\">المَآءِ إِلَّا بِقَرَبٍ مُذَبِّبٍ</span>, i. e. (assumed tropical:) [<i>They will not reach the water but by a</i>] <i>quick</i> [<i>night-journey thereto</i>]. (S.) And <span class=\"ar\">خِمْسٌ مُذَبِّبٌ</span> (assumed tropical:) [<i>A journey in which the camels are watered only on the first and fifth days</i>] <i>in which is no flagging,</i> or <i>langour.</i> (T.) -b3- <span class=\"ar\">ظِمْءٌ مُذَبِّبٌ</span> (assumed tropical:) [<i>An interval between two water-ings</i>] <i>of long duration, in which one journeys from afar</i> (T, S, M, K) <i>and with haste.</i> (T, S, K.)</p><p><b class=\"ar\">مَذْبُوبٌ</b> A camel <i>attacked by flies,</i> (A 'Obeyd, S, M,) <i>that enter his nostrils,</i> (S,) <i>so that his neck becomes twisted, and he dies;</i> as also <span class=\"ar\"> <span class=\"ar\">أَذَبُّ</span></span>: or both signify one <i>that, coming to a cultivated region, finds it unwholesome to him, and dies there:</i> (M:) and the former, a horse <i>into whose nostril the fly has entered.</i> (A.) -b2- See also <span class=\"ar\">أَرْضٌ مَذَبَّةٌ</span>, above. -b3- Also (assumed tropical:) <i>Possessed;</i> or <i>mad,</i> or <i>insane.</i> (K.) -b4- And, accord. to the Abridgment of the 'Eyn, [in a copy of the S written <span class=\"ar\">ذَبُوبٌ</span>, and in other copies thereof omitted,] (assumed tropical:) <i>Foolish; stupid;</i> or <i>unsound, dull,</i> or <i>deficient, in intellect.</i> (TA.)</p><p><b class=\"ar\">مُذَبْذَبٌ</b> <i>Driven away:</i> (TA:) or <i>driven away,</i> or <i>repelled, much.</i> (T, TA.) It is said in a trad., <span class=\"ar\">تَزَوَّجْ وَإِلَّا فَأَنْتَ مِنَ المُذَبْذَبِينَ</span>, i. e. [<i>Marry, or thou wilt be of</i>] <i>those driven away</i> from the believers because thou hast not imitated them, and from the monks because thou hast forsaken their institutes: from <span class=\"ar\">الذَّبُّ</span> “ the act of driving away: ” or, accord. to IAth, it may be from the signification of “ motion and agitation. ” (TA.) And it is said in the Kur [iv. 142], <span class=\"ar\">مُذَبْذَبِينَ بَيْنَ</span> <span class=\"ar\">ذٰلِكَ</span>, meaning <i>Much driven away,</i> or <i>much repelled, from these and from those:</i> (T, TA:) or this is an ex. of the meaning next following. (S, M.) -b2- A man (M, K) <i>wavering,</i> or <i>vacillating, between two things,</i> or <i>affairs;</i> (T, S, M, K;) or <i>between two men, not attaching himself steadily to either;</i> (T;) and <span class=\"ar\"> <span class=\"ar\">مُذَبْذِبٌ</span></span> signifies the same; (K;) as also <span class=\"ar\"> <span class=\"ar\">مُتَذَبْذِبٌ</span></span>. (M.)</p><p><b class=\"ar\">مُذَبْذِبٌ</b> : see what next precedes: -b2- and see also <span class=\"ar\">مُذَبِّبٌ</span>.</p><p><b class=\"ar\">مُتَذَبْذِبٌ</b> : see <span class=\"ar\">مُذَبْذَبٌ</span>, last sentence.</p>"},"ذكو":{"mf":"ذَكَتِ النار تَذْكُو: اتّقدت وأضاءت، وذَكَّيْتُهَا تَذْكِيَةً. وذُكَاء اسم للشمس، وابن ذُكَاء للصّبح، وذلك أنه تارة يتصوّر الصّبح ابنا للشمس، وتارة حاجبا لها فقيل: حاجب الشمس، وعبّر عن سرعة الإدراك وحدّة الفهم بالذكاء، كقولهم:<br>فلان هو شعلة نار. وذَكَّيْتُ الشاة: ذبحتها.<br>وحقيقة التّذكية: إخراج الحرارة الغريزيّة، لكن خصّ في الشرع بإبطال الحياة على وجه دون وجه، ويدلّ على هذا الاشتقاق قولهم في الميّت: خامد وهامد، وفي النار الهامدة: ميتة.<br>وذَكَّى الرَّجُلُ، إذا أسنّ <strong>«١»</strong>، وحظي بالذّكاء لكثرة رياضته وتجاربه، وبحسب هذا الاشتقاق لا يسمّى الشيخ مُذَكِّياً إلّا إذا كان ذا تجارب ورياضات. ولما كانت التجارب والرّياضات قلّما توجد إلّا في الشّيوخ لطول عمرهم استعمل الذّكاء فيهم، واستعمل في العتاق من الخيل المسانّ، وعلى هذا قولهم: جري المُذَكِّيَات غلاب <strong>«٢»</strong>.","mq":[["حدة [في] الشي ونفاذ"],"الذال والكاف والحرف المعتلّ أصلٌ واحد مطّردٌ منقاس يدلُّ على حِدَّةٍ [فى] الشَّئ ونفاذٍ. يقال للشَّمس «ذُكَاءُ» لأنَّها تذكو كما تذكو النّار. والصُّبح: ابنُ ذُكاءَ، لأنه من ضوئها.<br>ومن الباب ذكَّيتُ الذَّبيحة أُذكّيها، وذكّيت النّار أذكّيها، وذَكَوْتُها أذْكُوها. والفَرَس المُذكِّى: الذى يأتى عليه بع"],"ln":"<p><b>1.</b> <b class=\"ar\">ذَكَتِ النَّارُ</b> , (S, K, &amp;c.,) aor. <span class=\"ar\">تَذْكُو</span>, (S,) inf. n. <span class=\"ar\">ذَكًا</span> (S, Mgh, K, &amp;c.) and <span class=\"ar\">ذَكَآءٌ</span> accord. to Z (K) and <span class=\"ar\">ذُكُوٌّ</span>, (M, K, TA,) like <span class=\"ar\">عُلُوٌّ</span>; (TA; [accord. to the CK <span class=\"ar\">ذَكْوٌ</span>; and so accord. to the MA, as well as <span class=\"ar\">ذُكُوٌّ</span> and <span class=\"ar\">ذَكًا</span>;]) and <span class=\"ar\"> <span class=\"ar\">استذكت</span></span>; (K;) <i>The fire blazed,</i> or <i>flamed; burned up;</i> or <i>burned brightly</i> or <i>fiercely:</i> (S:) or <i>blazed,</i> or <i>flamed, vehemently,</i> or <i>intensely:</i> (K:) or <i>blazed, flamed,</i> or <i>burned up, completely;</i> agreeably with the primary signification of the root, which is “ completeness. ” (Mgh.) -b2- <span class=\"ar\">ذَكَا المِسْكُ</span> <i>The mush gave forth odour,</i> or <i>fragrance;</i> (MA;) [or <i>a strong,</i> or <i>pungent, odour;</i> for] the primary signification of <span class=\"ar\">ذَكًا</span> in relation to odour is the <i>being strong,</i> [or <i>pungent,</i>] <i>in sweetness</i> or <i>in fetidness.</i> (TA.) -b3- <span class=\"ar\">ذَكِىَ</span>, aor. <span class=\"ar\">يَذْكَى</span>; (S, Msb, K) and <span class=\"ar\">ذَكَا</span>, (Msb, K,) aor. <span class=\"ar\">يَذْكَى</span>, (K,) or <span class=\"ar\">يَذْكُو</span>; (Msb;) and <span class=\"ar\">ذَكُوَ</span>, (MA, K,) aor. <span class=\"ar\">يَذْكُو</span>; (K;) all three mentioned by ISd; (TA;) inf. n. <span class=\"ar\">ذَكَآء</span>; (S, MA, K, * TA; [in my copy of the Msb, the inf. n. of the first is said to be <span class=\"ar\">ذَكًى</span>; but this is app. a mistranscription; or the author perhaps held <span class=\"ar\">ذَكًى</span>, more properly written <span class=\"ar\">ذَكًا</span>, to be the inf. n.; for he says that <span class=\"ar\">ذَكِىَ</span> is of the class of <span class=\"ar\">تَعِبَ</span>, of which the inf. n. is <span class=\"ar\">تَعَبٌ</span>, and afterwards mentions <span class=\"ar\">ذَكَآءُ</span> as though he held this to be a simple subst.;]) said of a man, (S, Msb,) <i>He was,</i> or <i>became, sharp,</i> or <i>acute, in mind,</i> (S, TA,) <i>with quickness of perception, and of intelligence, understanding, sagacity, skill,</i> or <i>knowledge:</i> (TA:) or <i>quick of understanding,</i> (Msb, K,) or <i>intelligence, sagacity, skill,</i> or <i>knowledge:</i> (K:) or <i>quick of perception, and sharp,</i> or <i>acute, in understanding:</i> (Er-Rághib, TA:) or <i>quick in drawing conclusions.</i> (TA. [See <span class=\"ar\">ذَكَآءُ</span>, below.]) [Also, app., said of a camel, and the like, meaning <i>He was,</i> or <i>became, sharp in spirit.</i> See <span class=\"ar\">ذَكِىٌّ</span>.] -A2- [<span class=\"ar\">ذَكَا</span> seems to have been also used by some as meaning <i>He</i> (a beast) <i>was,</i> or <i>became, legalty slaughtered;</i> and consequently, <i>legally clean:</i> or to have been supposed to have this signification. -b2- And hence,] <span class=\"ar\">أَيُّمَا أَرْضٍ جَفَّتْ فَقَدْ ذَكَتْ</span> means (assumed tropical:) <i>Whatever ground has become dry, it has become clean,</i> or <i>pure:</i> but [Mtr, after mentioning this, adds,] I have not found it in the lexicons. (Mgh. [See also <span class=\"ar\">ذَكَاةٌ</span>, below.])</p><p><b>2.</b> <b class=\"ar\">ذكّى النَّارَ</b> , (T, Msb, K,) inf. n. <span class=\"ar\">تَذْكِيَةٌ</span>, (S, TA,) <i>He made the fire to blaze</i> or <i>flame, to burn up,</i> or <i>to burn brightly</i> or <i>fiercely;</i> (T, S, K;) as also <span class=\"ar\"> <span class=\"ar\">اذكاها</span></span>: (S, K:) or <i>he supplied the fire fully with fuel:</i> (Msb, TA:) and <span class=\"ar\"> <span class=\"ar\">اذكى</span>السِّرَاجَ</span> <i>He lighted the lamp.</i> (Har p. 53.) -b2- [<span class=\"ar\">ذكّى العَقْلَ</span>, and <span class=\"ar\">ذكّى</span> alone, said of a medicine &amp;c., <i>It sharpened the intellect.</i>] -A2- <span class=\"ar\">ذكّى</span>, (Mgh, Msb,) inf. n. as above, (S, Mgh, Msb, K,) <i>He slaughtered</i> (S, Mgh, Msb, K) an animal, (Mgh,) or a camel and the like, (Msb,) <i>in the manner</i> [<i>prescribed by the law,</i>] <i>termed</i> <span class=\"ar\">ذَبْحٌ</span>, (S, Mgh, K,) i. e., (Mgh, K,) <i>in the manner termed</i> <span class=\"ar\">ذَكَاةٌ</span> [q. v. infrà]. (Mgh, Msb, K.) The proper signification of <span class=\"ar\">التَّذْكِيَةُ</span> is <i>The causing the natural heat to pass forth:</i> but it is peculiarly applied in the law to signify <i>the destroying of life in a particular manner, exclusive of any other manner.</i> (Er-Rághib, TA.) <span class=\"ar\">إِلَّا مَا ذَكَّيْتُمْ</span>, in the Kur [v. 4], means <i>Except that whereof ye shall attain to the</i> <span class=\"ar\">ذَكَاة</span> [or <i>slaughter in the manner prescribed by the law</i>] (Bd, Msb, TA) said of a man, (S,) <i>He became old,</i> or <i>advanced in age,</i> (S, K,) <i>and big-bodied,</i> or <i>corpulent:</i> (K:) [or <i>he attained to full growth</i> or <i>age:</i> said of a man, and of a horse and the like:] see <span class=\"ar\">ذَكَآءٌ</span>, last sentence. [See also <span class=\"ar\">مُذَكٍّ</span>, below.])</p><p><b>4.</b> <b class=\"ar\">أَذْكَوَ</b> see 2, in two places. -b2- [Hence,] <span class=\"ar\">أَذْكَيْتُ</span> <span class=\"ar\">الحَرْبَ</span> (assumed tropical:) <i>I kindled war.</i> (TA.) -b3- <span class=\"ar\">أَذْكَيْتُ عَلَيْهِ</span> <span class=\"ar\">العُيُونَ</span> <i>I sent against him the scouts.</i> (S.)</p><p><b>10.</b> <b class=\"ar\">إِسْتَذْكَوَ</b> see 1, first sentence. -b2- [Hence, app.,] <span class=\"ar\">استذكى الفَحْلُ عَلَى الأُنْثَى</span> (assumed tropical:) <i>The stallion pressed vehemently upon the female.</i> (TA.)</p><p><b class=\"ar\">ذَكًا</b> an inf. n. of 1; The <i>blazing,</i> or <i>flaming,</i> &amp;c., of fire. (S, K, &amp;c. [See 1, first sentence.]) -b2- See also <span class=\"ar\">ذُكْوَةٌ</span>. -A2- And see <span class=\"ar\">ذَكَاةٌ</span>.</p><p><b class=\"ar\">ذَكٍ</b> a possessive epithet: (ISd, TA:) you say <span class=\"ar\">نَارٌ ذَكِيَةٌ</span>, (K, TA,) without teshdeed, (TA, [in the CK <span class=\"ar\">ذَكِيَّةٌ</span>,]) <i>A fire blazing,</i> or <i>flaming,</i> &amp;c. (K, TA.)</p><p><b class=\"ar\">ذَكَاةٌ</b> : see <span class=\"ar\">ذُكْوَةٌ</span>. -A2- [Also] a subst. (Mgh, Msb, TA) syn. with <span class=\"ar\">تَذْكِيَةٌ</span> (Mgh, Msb, K, TA) as signifying <span class=\"ar\">ذَبْحٌ</span> [i. e. The <i>slaughter</i> of an animal for food <i>in the manner prescribed by the law</i>]; (Mgh, K, TA;) as also <span class=\"ar\"> <span class=\"ar\">ذَكًا</span></span>, (K, TA, [in the CK <span class=\"ar\">ذَكاء</span>,) which is likewise said to be a simple subst.: (TA: [in the TK, <span class=\"ar\">ذَكًا</span> and <span class=\"ar\">ذَكَاةٌ</span> are both said to be inf. ns., of which the verb is <span class=\"ar\">ذَكَا</span>, signifying <span class=\"ar\">ذَبَحَ</span>; but this I do not find in any lexicon of authority:]) <i>it is satisfactorily performed by the severing of the windpipe and gullet,</i> as is related on the authority of Ahmad [Ibn- Hambal], or, as is also related on his authority, <i>by severing them an also the</i> <span class=\"ar\">وَدَجَانِ</span>, [or <i>two external jugular veins</i>], less than which is not lawful; or, accord to A boo-Haneefeh, <i>the severing of the windpipe and gullet and one of the</i> <span class=\"ar\">ودجان</span>; or, accord. to Málik, <i>the severing of the</i> <span class=\"ar\">أَوَدَاج</span> [or <i>external jugular veins</i>] <i>though it be without the severing of the windpipe.</i> (Msb.) The saying <span class=\"ar\">ذَكَاةُ الجَنِينِ ذَكَاةُ أُمِّهِ</span> is for <span class=\"ar\">ذَكَاةُ الجَنِينِ هِىَ</span> <span class=\"ar\">ذَكَاةُ أُمِّهِ</span> [<i>The legal slaughter of the fœtus,</i> or <i>young in the belly, it is the legal slaughter of its mother</i>]: (Msb, TA:) or it is an instance of the transposition of the inchoative and enunciative, (Mgh, Msb,) its implied meaning being <span class=\"ar\">ذَكَاةُ أُمِّ الجَنِينِ</span> <span class=\"ar\">ذَكَاةٌ لَهُ</span> [<i>The legal slaughter of the mother of the fœtus,</i> or <i>young in the belly, is a legal slaughter of it</i> also; so that the latter, like the former, may be lawfully eaten]; (Msb;) i. e., when she is legally slaughtered, it is legally slaughtered: (TA:) the use of the accus. case (Mgh, TA) in the like thereof, (Mgh,) [or] in the phrase <span class=\"ar\">ذكاة</span> <span class=\"ar\">امّه</span>, [i. e., the saying <span class=\"ar\">ذَكَاةَ أُمِّهِ</span>,] is a mistake. (Mgh, TA.) -b2- Hence the saying of Mohammad Ibn-El-Hanafeeyeh, <span class=\"ar\">ذَكَاةُ الأَرْضِ يُبْسُهُا</span> (assumed tropical:) [<i>The cleanness,</i> or <i>purity, of the ground is its becoming dry</i>]; i. e., when it becomes dry from the moisture of uncleanness, it becomes clean, like as a beast becomes clean by means of legal slaughter. (Mgh. [See also 1, last sentence.])</p><p><b class=\"ar\">ذُكْوَةٌ</b> , (T, TA, &amp;c.,) with damm, not <span class=\"ar\">ذَكْوَةٌ</span> as the text of the K indicates it to be (TA) [and as it is written in the copies thereof], and <span class=\"ar\">ذُكْيَةٌ</span>, (S, TA,) also with damm, (TA,) [in the copies of the K <span class=\"ar\">ذَكْيَة</span>,] <i>What is thrown upon the fire,</i> (T, S, K, *) <i>of firewood,</i> or <i>of camel's</i> or <i>similar dung,</i> (T,) <i>to make it blaze,</i> or <i>flame,</i> or <i>burn up,</i> or <i>burn brightly</i> or <i>fiercely.</i> (S, K.) -b2- Also the former, <i>A blazing,</i> or <i>flaming, coal of fire;</i> and so <span class=\"ar\"> <span class=\"ar\">ذَكًا</span></span>, (K, TA,) with the short <span class=\"ar\">ا</span>, on the authority of IDrd; [in the CK <span class=\"ar\">ذَكَاء</span>;] or, as in the M, <span class=\"ar\"> <span class=\"ar\">ذَكَاةٌ</span></span>. (TA.)</p><p><b class=\"ar\">ذَكْوَانٌ</b> <i>A kind of trees:</i> n. un. with <span class=\"ar\">ة</span>: (IAar, TA:) the pl. of the latter is <span class=\"ar\">ذَكَاوِينُ</span>, and signifies <i>small</i> [<i>trees of the kind called</i>] <span class=\"ar\">سَرْح</span> [q. v.]. (M, K, TA. [In the CK, <span class=\"ar\">السَّرْج</span> is erroneously put for <span class=\"ar\">السَّرْح</span>.])</p><p><b class=\"ar\">ذَكَآءُ</b> <i>Sharpness,</i> or <i>acuteness, of mind,</i> (S, Msb, TA,) <i>with quickness of perception, and of intelligence, understanding, sagacity, skill,</i> or <i>knowledge:</i> (TA:) or <i>completeness of intelligence, with quickness of apprehension:</i> (Msb:) or <i>quickness of intelligence, understanding, sagacity, skill,</i> or <i>knowledge:</i> (K:) or <i>quickness of perception, and sharpness,</i> or <i>acuteness, of understanding:</i> thus applied, it is like the phrase <span class=\"ar\">فُلَانٌ شُعْلَةُ نَارٍ</span>: (Er-Rághib, TA:) or <i>quickness in drawing conclusions.</i> (TA. [See <span class=\"ar\">ذِهْنٌ</span>: and see also 1.]) [It app. signifies also <i>Sharpness of spirit;</i> as a quality of a camel and the like. See <span class=\"ar\">ذَكِىٌّ</span>.] -b2- Also <i>Age:</i> (S, K:) or <i>full,</i> or <i>complete, age:</i> so says Mbr in the “ Kámil: ” (TA:) <i>contr. of</i> <span class=\"ar\">فَتَآءٌ</span>: (Ham p. 217:) accord. to Az, its primary signification, universally, is <i>a state of completeness:</i> and <span class=\"ar\">الذَّكَآءُ فِى السِّنّ</span> means <i>completeness of age:</i> accord. to Kh, it means <i>the age of completeness of strength,</i> [app. in a horse, or any solid-hoofed animal, for he says that it is] <i>when a year has passed after the</i> <span class=\"ar\">قُرُوح</span> [or <i>finishing of teething</i>]: (TA:) or <span class=\"ar\">ذَكَآءُ السِّنِّ</span> means <i>the utmost term of youthfulness;</i> from the primary signification of the root, which is “ a state of completeness. ” (Mgh.) Hence the saying of El-Hajjáj, <span class=\"ar\">فُرِرْتُ عَنْ ذَكَآءٍ</span> [<i>I have been examined as to age;</i> app. meaning (assumed tropical:) <i>my abilities have been tested and proved</i>]: and <span class=\"ar\">بَلَغَتِ الدَّابَّةُ</span> <span class=\"ar\">الذَّكَآءَ</span> <i>The beast attained to</i> [<i>fulness of</i>] <i>age</i> (S, TA.) [Hence, also,] one says, <span class=\"ar\">فَتَآ فُلَانٍ</span> <span class=\"ar\">كَذَكَآءِ فُلَانٍ</span> and <span class=\"ar\"> <span class=\"ar\">كَتَذْكِيَةِ</span>فُلَانٍ</span> [<i>The youthfulness of such a one is like the fulness of age of such a one</i>], i. e., the prudence, or discretion, of such a one notwithstanding his deficiency of age is like the prudence, or discretion, of such a one with his fulness of age. (Ham p. 217.)</p><p><b class=\"ar\">ذُكَآءُ</b> , imperfectly decl., <i>The sun:</i> (S, K:) determinate, and not admitting the article <span class=\"ar\">ال</span>: you say, <span class=\"ar\">هٰذِهِ ذُكَآءُ طَالِعَةٌ</span> [<i>This is the sun rising</i>]: (S:) derived from <span class=\"ar\">ذَكَتِ النَّارُ</span>. (TA.) -b2- Hence, (S,) <span class=\"ar\">اِبْنُ ذُكَآءَ</span> <i>The dawn,</i> or <i>daybreak:</i> (S, K:) because it is from the light of the sun. (S.) Homeyd says, [or, accord. to some, Besheer Ibn-En-Nikth, as in one of my copies of the S, in art. <span class=\"ar\">كفر</span>,] <span class=\"ar\">فَوَرَدَتْ قَبْلَ ٱنْبِلَاجِ الفَجْرِ</span> <span class=\"ar\">وَٱبْنُ ذُكَآءَ كَامِنٌ فِى الكَفْرِ</span> [<i>And she,</i> or <i>they, came to the water before the bright shining of the daybreak, while the dawn lay kid in the darkness of night</i>]. (S.)</p><p><b class=\"ar\">ذَكِىٌّ</b> , applied to musk, and so <span class=\"ar\">ذَكِيَّةٌ</span>, (K, TA,) for <span class=\"ar\">مِسْكٌ</span>, as is said by IAmb, is both masc. and fem., and so is <span class=\"ar\">عَنْبَرٌ</span>, (TA,) and <span class=\"ar\"> <span class=\"ar\">ذَاكٍ</span></span>, <i>Diffusing odour:</i> (K:) or <i>having a strong</i> [or <i>pungent</i>] <i>odour.</i> (TA. [See 1, second sentence.]) You say also <span class=\"ar\">رَائِحَةٌ ذَكِيَّةٌ</span> <i>A sharp</i> [or <i>pungent,</i> or <i>a strong,</i>] <i>odour</i> [whether sweet or fetid]; syn. <span class=\"ar\">حَادَّةٌ</span>. (K in art. <span class=\"ar\">حد</span>.) -b2- Applied to a man, <i>Having the attribute,</i> or <i>quality, termed</i> <span class=\"ar\">ذَكَآء</span>, (S, Msb, K,) as meaning <i>sharpness,</i> or <i>acuteness,</i> (S, Msb,) or <i>quickness,</i> (K,) <i>of mind,</i> (S, Msb,) or <i>of intel-ligence,</i> &amp;c.: (K, TA, &amp;c.:) pl. <span class=\"ar\">أَذْكِيَآءُ</span>. (Msb, TA.) It is also, sometimes, applied to a camel [or the like, as meaning <i>Sharp in spirit:</i> see <span class=\"ar\">فُؤَادٌ</span>]. (TA.) -A2- Also <i>i. q.</i> <span class=\"ar\">ذَبِيحٌ</span> [meaning <i>Slaughtered in the manner prescribed by the law, termed</i> <span class=\"ar\">ذَبْحٌ</span> and <span class=\"ar\">ذَكَاةٌ</span>]: (K:) it is of the measure <span class=\"ar\">فَعِيلٌ</span> in the sense of the measure <span class=\"ar\">مَفْعُولٌ</span>: (Msb:) and [therefore] you say <span class=\"ar\">شَاةٌ ذَكِىٌّ</span>, meaning [<i>a sheep,</i> or <i>goat, slaughtered in the manner above mentioned;</i> and also,] <i>to whose</i> <span class=\"ar\">ذَكَاة</span> [or <i>slaughter in that manner</i>] <i>one has attained</i> [<i>while life yet remained therein:</i> see 2]: (Mgh, Msb:) <span class=\"ar\">ذَكِيَّةٌ</span> [as its fem.] is extr. [like <span class=\"ar\">ذَبِيحَةٌ</span>]. (TA.) -b2- Hence, <span class=\"ar\">جِلْدٌ ذَكِىٌّ</span> (tropical:) <i>A skin stripped from an animal that has been slaughtered in the manner mentioned above.</i> (Mgh.)</p><p><b class=\"ar\">ذَاكٍ</b> : see the next preceding paragraph.</p><p><b class=\"ar\">مُذْكٍ</b> ; and the fem., <span class=\"ar\">مُذْكِيَةٌ</span>: see the following paragraph, in three places.</p><p><b class=\"ar\">مُذَكٍّ</b> , applied to a man, (TA,) <i>Old,</i> or <i>advanced in age, and big-bodied,</i> or <i>corpulent:</i> (K, TA:) [or <i>full-grown,</i> or <i>of full age:</i> see <span class=\"ar\">ذَكَآءٌ</span>:] or an <i>old</i> man, but only such as is <i>much experienced and disciplined:</i> (Er-Rághib, TA:) and accord. to ISd, anything [i. e. any animal] <i>old,</i> or <i>advanced in age:</i> by some especially applied to a solid-hoofed animal; and said to mean one <i>that has passed the</i> <span class=\"ar\">قُرُوح</span> [or <i>finishing of teething</i>] <i>by a year:</i> (TA:) or <span class=\"ar\">مَذَاكٍ</span>, (S, K, TA,) which is its pl., (S, TA,) [(like as <span class=\"ar\">مُذَكِّيَاتٌ</span> is pl. of the fem.,) and also pl. of its syn. <span class=\"ar\"> <span class=\"ar\">مُذْكٍ</span></span>,] signifies, applied to horses, (S, K, TA,) <i>of generous race, advanced in age,</i> (TA,) <i>that have passed a year,</i> or <i>two years, after their</i> <span class=\"ar\">قُرُوح</span>: (S, K, TA:) the sing. is like <span class=\"ar\">مُخْلِفٌ</span> applied to a camel: (S, TA:) or <span class=\"ar\">مُذَكٍّ</span> signifies a horse <i>of full age and of complete strength;</i> as also <span class=\"ar\"> <span class=\"ar\">مُذْكٍ</span></span>: (Ham p. 217:) or a horse <i>whose run becomes spent</i> (<span class=\"ar\">يَذْهِبُ</span>), <i>and</i> [<i>then, but not before he has exhausted his power,</i>] <i>stops.</i> (TA.) It is said in a prov., <span class=\"ar\">جَرْىُ</span> <span class=\"ar\">المُذَكِّيَاتُ غِلَابٌ</span> [<i>The running of the horses that have attained to their full age and strength is a contending for superiority</i>]: (Meyd, and so in some copies of the S:) it may mean that the horse in this case contends for superiority with him that runs with him; or that his second run is always more than his first, and his third than his second: (Meyd:) or, as some relate it, <span class=\"ar\">غِلَآءٌ</span>; (Meyd, and so in other copies of the S in this art., and in the S and K in art <span class=\"ar\">غلو</span>;) meaning that the running of such horses is <i>several bowshots:</i> (Meyd, and S and K in art. <span class=\"ar\">غلو</span>:) it is applied to him who is described as entering into contests for excellence with his compeers. (Meyd.) -b2- [Hence,] <span class=\"ar\">سَحَابَةٌ <span class=\"ar\">مُذْكِيَةٌ</span></span>, (K,) or, as in the Tekmileh, <span class=\"ar\">مُذَكِّيَةٌ</span>, (TA,) (assumed tropical:) <i>A cloud that has rained time after time.</i> (K, TA.)</p>"},"ذأم":{"mf":"قال تعالى: اخْرُجْ مِنْها مَذْؤُماً<br>[الأعراف/ ١٨]، أي: مذموما. يقال: ذمته <strong>«٢»</strong> أذيمه ذيما، وذممته أذمّه ذمّا، وذَأَمْتُهُ ذَأْماً.<br>تمّ كتاب الذال<br><br>كتاب الرّاء","mq":[["كراهة وعيب"],"الذال والهمزة والميم أصلٌ يدلُّ على كراهَةٍ وعَيب. يقال أذْأمْتَنِى على كذا، أى أكرَهْتَنى عليه. ويقولون ذأمْتُه، أى حَقَرْتُه. والذّأم العَيب، وهو مذءومٌ. فاما الذَّانُ بالنون، فليس أصلاً، لأنَّ النونَ فيه مبدلة من ميم. قال:<br>ردَدْنا الكتيبةَ مَلمومةً … بها أَفْنُها وبها ذانُها (١)<br>"],"ln":"<p><b>1.</b> <b class=\"ar\">ذَأَمَهُ</b> , (T, S, M, Msb, K,) aor. <b class=\"ar\">ذَأََ</b> , (S, M, Msb, K,) inf. n. <span class=\"ar\">ذَأْمٌ</span>, (S, * M,) <i>He blamed,</i> or <i>found fault with, him,</i> or <i>it;</i> (T, S, Msb;) namely, a man, (T, [in which it is said that <span class=\"ar\">ذَأَمْتُهُ</span> in the sense of <span class=\"ar\">عِبْتُهُ</span> is more common than <span class=\"ar\">ذَمَمْتُهُ</span>, ” though the contr. seems to be manifestly the case,]) or a commodity; (Msb;) and <i>he despised him;</i> like <span class=\"ar\">ذَأَبَهُ</span>: (S:) and <i>he despised him and beat him:</i> (T:) and <i>he despised him and blamed him:</i> (T, M, K:) or <i>he despised him and drove him away;</i> like <span class=\"ar\">ذَأَبَهُ</span>: (M:) and simply <i>he drove him away:</i> (M, K:) or <i>he drove him away and beat him;</i> like <span class=\"ar\">ذَأَبَهُ</span>: (M and TA in art. <span class=\"ar\">ذأب</span>:) and <i>he repaid him,</i> or <i>requited him;</i> syn. <span class=\"ar\">جَزَاهُ</span>: (T and M:) or <i>he overcame him in abasing;</i> syn. <span class=\"ar\">خَزَاهُ</span>. (K and TA. [So in my MS. copy of the K and in the CK: but I doubt not that <span class=\"ar\">جَزَاهُ</span> is the right reading.])</p><p><b>4.</b> <b class=\"ar\">اذأمهُ</b> , (TA,) inf. n. <span class=\"ar\">إِذْآمٌ</span>, (K, TA,) <i>He frightened him,</i> or <i>terrified him;</i> syn. of the inf. n. <span class=\"ar\">رُعْبٌ</span>. (K, TA.) -b2- <span class=\"ar\">أَذْأَمْتَنِى عَلَى كَذَا</span> <i>Thou compelledst me against my will to do such a thing.</i> (Fr, S.)</p><p><b class=\"ar\">ذَأْمٌ</b> <i>i. q.</i> <span class=\"ar\">عَيْبٌ</span> [as a subst., meaning <i>A vice, fault, defect,</i> or <i>the like;</i> like <span class=\"ar\">ذَامٌ</span>, without <span class=\"ar\">ء</span>, and <span class=\"ar\">ذَيْمٌ</span>; as well as an inf. n. of 1, q. v.]: with and without <span class=\"ar\">ء</span> (S.)</p><p><b class=\"ar\">ذَأْمَةٌ</b> <i>A word:</i> so in the saying, <span class=\"ar\">مَا سَمِعْتُ لَهُ ذَأْمَةً</span> [<i>I heard not a word that he had</i> to utter]. (K.)</p><p><b class=\"ar\">مَذْؤُومٌ</b> pass. part. n. of 1. (S, Msb.) <span class=\"ar\">مَذْؤُومًا</span> in the Kur [vii. 17] means <i>Blamed:</i> (TA:) or <i>driven away:</i> (M, TA:) or, accord. to Lh and Mujáhid, <i>banished.</i> (T, TA. *)</p>"},"ذرو":{"mf":"ذِرْوَةُ السّنام وذُرَاه: أعلاه، ومنه قيل: أنا في ذُرَاكَ، أي: في أعلى مكان من جنابك.<br>والمِذْرَوَان: طرفا الأليتين، وذَرَتْهُ الرّيح تَذْرُوهُ وتَذْرِيهِ. قال تعالى: وَالذَّارِياتِ ذَرْواً<br>[الذاريات/ ١]، وقال: تَذْرُوهُ الرِّياحُ [الكهف/ ٤٥]، والذُّرِّيَّة أصلها: الصّغار من الأولاد، وإن كان قد يقع على الصّغار والكبار معا في التّعارف، ويستعمل للواحد والجمع، وأصله الجمع، قال تعالى: ذُرِّيَّةً بَعْضُها مِنْ بَعْضٍ [آل عمران/ ٣٤]، وقال: ذُرِّيَّةَ مَنْ حَمَلْنا مَعَ نُوحٍ [الإسراء/ ٣]، وقال: وَآيَةٌ لَهُمْ أَنَّا حَمَلْنا ذُرِّيَّتَهُمْ فِي الْفُلْكِ الْمَشْحُونِ [يس/ ٤١]، وقال: إِنِّي جاعِلُكَ لِلنَّاسِ إِماماً قالَ وَمِنْ ذُرِّيَّتِي [البقرة/ ١٢٤]، وفي الذُّرِّيَّة ثلاثة أقوال: قيل هو من: ذرأ الله الخلق <strong>«٤»</strong>، فترك همزه، نحو: رويّة وبريّة. وقيل: أصله ذرويّة.<br>وقيل: هو فعليّة من الذّرّ نحو قمريّة. وقال (أبو القاسم البلخيّ) <strong>«٥»</strong> : قوله تعالى: وَلَقَدْ ذَرَأْنا لِجَهَنَّمَ [الأعراف/ ١٧٩]، من قولهم: ذريت<br><br>الحنطة، ولم يعتبر أنّ الأوّل مهموز.","mq":[[],"الذال والراء والحرف المعتل أصلان: أحدهما الشَّئُ يُشرِف على الشَّئ ويُظِلّه، والآخر الشَّئ يتساقط متفرّقاً.<br>فالذِّروة: أعْلَى السَّنامِ وغيره، والجمع ذُرًى. والذَّرَا: كلُّ شئِ استترْتَ به. تقول: أنا فى ظِلِّ فُلانٍ، أى ذَرَاه. والمِذْرَوَانِ: أطراف الأَلْيتَينِ؛ لأنّهما يُشرفان على [ما] بينَهما.<br>وأ"],"ln":"<p><b>1.</b> <b class=\"ar\">ذَرَتْهُ الرِّيحُ</b> , (T, S, M, Msb, K,) aor. <span class=\"ar\">تَذْرُوهُ</span>, (S, M, Msb,) inf. n. <span class=\"ar\">ذَرْوٌ</span>; (S M, Msb, K;) and aor. <span class=\"ar\">تَذْرِيهِ</span>, (S, M,) inf. n. <span class=\"ar\">ذَرْىٌ</span>; (S;) and <span class=\"ar\"> <span class=\"ar\">ذرّتهُ</span></span>; and <span class=\"ar\"> <span class=\"ar\">اذرتهُ</span></span>; (M, K;) the last on the authority of IAar, but said in the T to be disallowed in this sense by AHeyth; (TA;) <i>The wind raised it,</i> (T, S, *) or <i>made it to fly,</i> (AHeyth, T, S, * M, K,) <i>and carried it away;</i> (S, * M, Msb, * K;) <i>and dispersed it;</i> (Msb;) namely, a thing, (Msb, K,) or the dust, (T, S, M,) &amp;c. (S, M.) And accord. to IAar, one says, <span class=\"ar\">ذَرَتِ الرِّيحُ</span>, and <span class=\"ar\"> <span class=\"ar\">أَذْرَت</span></span>, [elliptically,] meaning <span class=\"ar\">ذَرَتِ التُّرَابَ</span> [i. e. <i>The wind raised the dust,</i> or <i>made it to fly,</i> &amp;c.]. (T.) -b2- [Hence,] <span class=\"ar\">ذَرَا الرِّوَايَةَ ذَرْوَ الرِّيحِ الهَشِيمَ</span> (assumed tropical:) <i>He carried on the relation uninterruptedly and rapidly</i> [<i>like as the wind carries away the dry herbage that is broken in pieces.</i>] (TA.) -b3- Hence also, <span class=\"ar\">ذَرَا</span> <span class=\"ar\">النَّاسُ الحِنْطَةَ</span> [<i>The people winnowed the wheat</i>]. (S.) You say, <span class=\"ar\">ذَرَوْتُ الحِنْطَةَ</span>, (IAar, T, M, K, *) aor. <span class=\"ar\">أَذْرُوهَا</span>, inf. n. <span class=\"ar\">ذَرْوٌ</span>; (IAar, T;) and <span class=\"ar\"> <span class=\"ar\">ذَرَّيْتُهَا</span></span>; (M;) <i>I winnowed the wheat:</i> (M, K: *) or <span class=\"ar\"> <span class=\"ar\">ذَرَّيْتُ</span>الطَّعَامَ</span>, inf. n. <span class=\"ar\">تَذْرِيَةٌ</span>; (Msb;) and <span class=\"ar\">ذَرَيْتُهُ</span> and <span class=\"ar\">ذَرَوْتُهُ</span>; (T;) <i>I cleared the wheat from its straw.</i> (Msb.) And <span class=\"ar\">ذَرَوْتُهُ</span>, (S, M,) and <span class=\"ar\">ذَرَيْتُهُ</span>, but the former is more approved; and <span class=\"ar\"> <span class=\"ar\">ذَرَّيْتُهُ</span></span>; (M;) <i>I made it to fly, and go away;</i> (S, M;) namely, a thing, (S,) or grain, and the like. (M.) <span class=\"ar\"> <span class=\"ar\">تَذْرِيَةُ</span>الأَكْدَاسِ</span> is well known [as meaning <i>The winnowing of the heaps of grain</i>]. (S.) And hence, (S,) <span class=\"ar\">ذَرَّيْتُ تُرَابَ المَعْدِنِ</span> <i>I sought the gold of the dust of the mine</i> [<i>by sifting it</i> or <i>winnowing it</i>]: (S, K:) and <span class=\"ar\"> <span class=\"ar\">اِذَّرَيْتُهُ</span></span> signifies the same. (T and S in art. <span class=\"ar\">درى</span>. [See a verse cited in the first paragraph of that art.: and see also 2 in the same art.]) -b4- <span class=\"ar\">ذَرَيْتُ الشَّىْءَ</span>, (T,) or <span class=\"ar\"> <span class=\"ar\">أَذْرَيْتُهُ</span></span>, (S, TA,) accord. to AHeyth, (TA,) <i>I threw the thing</i> [or <i>scattered it</i>] <i>like as one throws grain for sowing.</i> (T, S, TA.) And <span class=\"ar\">ذَرَا الأَرْضَ</span> <i>He sowed the land, scattering the seed;</i> as also <span class=\"ar\">ذَرَأَ الارض</span>; but the former is said to be the more chaste. (MF and TA in art. <span class=\"ar\">ذرأ</span>.) -b5- And <span class=\"ar\">ذَرَاهُمْ</span>, inf. n. <span class=\"ar\">ذَرْوٌ</span>, is a dial. var. of <span class=\"ar\">ذَرَأَهُمْ</span>, meaning <i>He</i> [God] <i>created them.</i> (M.) -b6- <span class=\"ar\">ذَرَا الشَّىْءَ</span> <i>He broke the thing</i> (K, TA) <i>without separating.</i> (TA.) And <span class=\"ar\">ذَرَوْتُ نَابَهُ</span> <i>I broke his canine tooth.</i> (M, TA.) -b7- <span class=\"ar\">ذَرَاهُ بِالرُّمْحِ</span> <i>He displaced,</i> or <i>uprooted, him,</i> or <i>it, with the spear.</i> (Kr, M.) -A2- <span class=\"ar\">ذَرَا</span>, intrans., <i>It</i> (a thing, K, or dust, &amp;c., M) <i>flew up, and went away,</i> or <i>became carried away</i> [by the wind]. (M, K.) -b2- <i>He</i> (a gazelle, K, or, accord. to some, any animal, TA) <i>hastened</i> (K, TA) <i>in his running.</i> (TA.) You say, <span class=\"ar\">مَرَّ يَذْرُو</span>, inf. n. <span class=\"ar\">ذَرْوٌ</span>, <i>He</i> (a man, S) <i>passed,</i> or <i>went, along quickly:</i> (S, M:) accord. to some, said particularly of a gazelle. (M.) And <span class=\"ar\">ذَرَا إِلَى فُلَانٍ</span> <i>He rose and betook himself to such a one.</i> (TA.) -b3- <i>It</i> (a thing) <i>fell.</i> (S, K.) -b4- <span class=\"ar\">ذَرَا نَابَهُ</span>, inf. n. <span class=\"ar\">ذَرْوٌ</span>, <i>His canine tooth broke:</i> or, as some say, <i>fell out.</i> (M.) And <span class=\"ar\">ذَرَافُوهُ</span>, (K,) inf. n. <span class=\"ar\">ذَرْوٌ</span>, (TA,) <i>His teeth fell out from his mouth;</i> (K TA;) as also <span class=\"ar\">ذَرَى</span>, and <span class=\"ar\">ذَرَأَ</span>; but the last is said to be of weak authority, or a mispronunciation. (MF and TA in art. <span class=\"ar\">ذرأ</span>.)</p><p><b>2.</b> <b class=\"ar\">ذَرَّوَ</b> see 1, in five places. -b2- [Hence,] <span class=\"ar\">ذَرَّى رَأْسَهُ</span>, (M, TA,) inf. n. <span class=\"ar\">تَذْرِيَةٌ</span>, (TA,) <i>He combed his head</i> (M, TA) [<i>so as to remove the scurf &amp;c.</i>], <i>like as one winnows a thing:</i> but <span class=\"ar\">دَرَّى</span> [with the unpointed <span class=\"ar\">د</span>] is of higher authority. (M.) -A2- <span class=\"ar\">ذَرَّيْتُهُ</span>, namely, a sheep, inf. n. as above, <i>I shore,</i> or <i>sheared, his wool, leaving somewhat thereof upon his back in order that he might be known thereby:</i> and in like manner one says in relation to a camel. (S, M.) [See <span class=\"ar\">مُذَرًّى</span>.] -b2- [Hence, app, or from <span class=\"ar\">ذِرَوْةٌ</span>, as is indicated in what follows,] (assumed tropical:) <i>I praised him.</i> (IAar, M, K.) You say, <span class=\"ar\">فُلَانٌ</span> <span class=\"ar\">يُذَرِّى فُلَانًا</span> (assumed tropical:) <i>Such a one exalts the state,</i> or <i>condition, of such a one;</i> and <i>praises him.</i> (T.) A poet says, [namely, Ru-beh, (so in the margin of one of my copies of the S,)] <span class=\"ar\">عَيْدًا أُذَرِّى حَسَبِى أَنْ يُشْتَمَا</span> (assumed tropical:) [<i>Purposely I praise and exalt what constitutes my grounds of pretension to respect</i> or <i>honour, lest it should be reviled</i>]: (T, S, M:) as though I put it upon the <span class=\"ar\">ذِرْوَةٌ</span> [q. v.] (M.)</p><p><b>4.</b> <b class=\"ar\">أَذْرَوَ</b> see 1, in three places. -b2- Accord. to AHeyth, this verb is not used in the sense first explained above; but one says, <span class=\"ar\">أَذْرَيْتُ الشَّىْءَ عَنِ الشَّىْءِ</span>, meaning <i>I threw down the thing from the thing:</i> (T, TA:) or <span class=\"ar\">إِذْرَآءٌ</span> signifies the <i>striking</i> a thing <i>and throwing</i> it <i>down:</i> (Lth, T:) and sometimes, the <i>throwing down without cutting.</i> (M.) You say, <span class=\"ar\">ضَرَبْتُهُ بِالسَّيْفِ فَأَذْرَيْتُ رَأْسَهُ</span> [<i>I struck him with the sword and made his head to fall</i> from him]. (T.) And <span class=\"ar\">طَعَنْتُهُ فَأَذْرَيْتُهُ عَنْ فَرَسِهِ</span>, (T,) or <span class=\"ar\">عَنْ ظَهْرِ</span> <span class=\"ar\">دَابَّتِهِ</span>, (S,) i. e. [<i>I thrust him,</i> or <i>pierced him, and</i>] <i>threw him down</i> [<i>from his horse,</i> or <i>from the back of his beast</i>]. (T, S.) And <span class=\"ar\">أَذْرَتِ الدَّابَّةُ</span> <span class=\"ar\">رَاكِبَهَا</span> <i>The beast threw down its rider.</i> (M.) And <span class=\"ar\">اذرى الشَّىْءَ بِالسَّيْفِ</span> <i>He struck the thing with the sword so as to throw it down.</i> (M.) And <span class=\"ar\">أَذْرَتِ العَيْنُ دَمْعَهَا</span>, (S,) or <span class=\"ar\">الدَّمْعَ</span>, (M,) <i>The eye poured forth</i> [or <i>let fall its tears,</i> or <i>the tears</i>]. (S, M.) [See also <span class=\"ar\">أَذْرَأَ</span>.] -A2- <span class=\"ar\">اذرى</span> said of a camel, <i>He was,</i> or <i>became, tall,</i> or <i>long, in his</i> <span class=\"ar\">ذِرْوَة</span> [or <i>hump</i>]. (TA.)</p><p><b>5.</b> <b class=\"ar\">تذرّت الحِنْطَةُ</b> <i>The wheat was,</i> or <i>became, winnowed:</i> (M, K:) or <i>was,</i> or <i>became, cleared from its straw.</i> (TA.) -A2- <span class=\"ar\">تذرّى بِهِ</span> <i>He protected,</i> or <i>sheltered, himself by means of it;</i> (M, Msb;) i. e. by means of a wall, &amp;c., from the wind and the cold; as also <span class=\"ar\"> <span class=\"ar\">استذرى</span>به</span>. (M.) One says, <span class=\"ar\">تَذَرَّ مِنَ الشَّمَالِ بَذْرًى</span> <i>Protect,</i> or <i>shelter, thyself from the north wind by means of a shelter.</i> (T.) And <span class=\"ar\"> <span class=\"ar\">اِسْتَذْرِ</span>بِهٰذِهِ الشَّجَرَةِ</span> <i>Shelter thyself by means of this tree:</i> (T:) or <span class=\"ar\"> <span class=\"ar\">اِسْتَذْرَيْتُ</span>بِالشَّجَرَةِ</span> <i>I shaded and sheltered myself by means of the tree.</i> (S.) And <span class=\"ar\">تذرّتِ الإِبِلُ</span> <i>The camels protected,</i> or <i>sheltered, themselves from the cold, one by means of another;</i> or <i>by means of the</i> [<i>trees called</i>] <span class=\"ar\">عِضَاه</span>. (M.) And <span class=\"ar\"> <span class=\"ar\">اِسْتَذْرَيْتُ</span>بِفُلَانٍ</span> <i>I sought refuge with such a one, and became in his protection.</i> (S.) And <span class=\"ar\">اذرى</span> [thus I find it written, without any syll. signs, evidently for <span class=\"ar\"> <span class=\"ar\">اِذَّرَى</span></span>, of the measure <span class=\"ar\">اِفْتَعَلَ</span>, like <span class=\"ar\">اِلْتَجَأَ</span> and <span class=\"ar\">اِكْتَنَّ</span>,] <i>He sought protection by means of a king.</i> (TA.) -A3- <span class=\"ar\">تذرّى السَّنَامَ</span>, (S,) or <span class=\"ar\">الذِّرْوَةَ</span>, (M, K,) <i>He mounted upon</i> [<i>the hump,</i> or <i>the top</i> of the hump &amp;c.]. (S, M, K.) -b2- [Hence,] <span class=\"ar\">تَذَرَّيْتُ بَنِى فُلَانٍ وَ تَنَصَّيْتُهُمْ</span> (assumed tropical:) <i>I married among the</i> <span class=\"ar\">ذِرْوَة</span> <i>and the</i> <span class=\"ar\">نَاصِيَة</span> <i>of the sons of such a one;</i> (As, T, * S;) i. e., <i>among the noble and high of them:</i> (T:) or <span class=\"ar\">تذرّى فِيهِمْ</span> (assumed tropical:) <i>He married among the</i> <span class=\"ar\">ذِرْوَة</span> <i>of them.</i> (M.)</p><p><b>8.</b> <b class=\"ar\">إِذْتَرَوَ</b> see 1: -A2- and see also 5.</p><p><b>10.</b> <b class=\"ar\">إِسْتَذْرَوَ</b> see 5, in four places. -b2- <span class=\"ar\">اِسْتَذْرَتْ</span>, said of a she-goat, <i>She desired the ram;</i> (S, K;) like <span class=\"ar\">اِسْتَدَرَّتْ</span>. (S.) -b3- And the inf. n. <span class=\"ar\">اِسْتِذْرَآءُ</span> signifies The act of <i>leaping upon a female.</i> (KL.)</p><p><b class=\"ar\">ذُرَةٌ</b> , originally <span class=\"ar\">ذُرَوٌ</span>, (S, Msb, K,) or <span class=\"ar\">ذُرَىٌ</span>, (S, M, * Msb,) the <span class=\"ar\">ة</span> being a substitute (S, Msb) for the final radical letter, (Msb,) [<i>A species of millet;</i> the <i>holcus sorghum</i> of Linn.; thus called in the present day, and also, vulgarly, <span class=\"ar\">ذُرَة صَيْفِىّ</span> and <span class=\"ar\">ذُرَةقَيْظِىّ</span>, to distinguish it from <i>maize,</i> the <i>zea mays</i> of Linn., which is vulgarly called <span class=\"ar\">ذُرَةشَامِىّ</span> and <span class=\"ar\">ذُرَة كِيزَان</span>;] <i>a species of grain;</i> (M;) <i>a certain grain, well known:</i> (S, Msb, K:) the word is used as a n. un. and as a coll. n. (T.) [See <span class=\"ar\">مِيرَةٌ</span>.]</p><p><b class=\"ar\">ذَرْوٌ</b> <i>A portion</i> (<span class=\"ar\">طَرَفٌ</span>) <i>not completed,</i> of a saying; as in the phrase, <span class=\"ar\">بَلَغَنِى عَنْهُ ذَرْوٌ مِنْ قَوْلٍ</span> [<i>An uncompleted portion of a saying was related to me from him</i>]: (T, S:) or <i>a little;</i> a dial. var. of <span class=\"ar\">ذَرْءٌ</span> [q. v.]. (M.) -A2- Also, and <span class=\"ar\"> <span class=\"ar\">ذَرًى</span></span>, <i>i. q.</i> <span class=\"ar\"> <span class=\"ar\">ذُرِّيَّةٌ</span></span>, (M, TA,) [respecting the derivation of which there are different opinions, explained in art. <span class=\"ar\">ذرأ</span>,] i. e. <i>Created beings:</i> [or <i>children,</i> or <i>offspring:</i> (see art <span class=\"ar\">ذرأ</span>:)] or <span class=\"ar\">ذَرْوٌ</span> and <span class=\"ar\"> <span class=\"ar\">ذَرًى</span></span> signify the <i>number of the</i> <span class=\"ar\">ذُرِّيَّة</span>. (M.) One says, <span class=\"ar\">أَنْمَى ٱللّٰهُ ذَرْأَكَ</span> and <span class=\"ar\">ذَرْوَكَ</span>, meaning <i>May God increase</i> [<i>the number of</i>] <i>thine offspring.</i> (T.) -b2- And <span class=\"ar\">ذَرْوُالنَّارِ</span> occurs in a trad., as some relate it, instead of <span class=\"ar\">ذَرْءُ النَّارِ</span>, as others relate it; meaning [either <i>The children of the fire</i> of Hell, agreeably with what next precedes, or] <i>to be scattered in the fire.</i> (S and TA in art. <span class=\"ar\">ذرأ</span>.) -A3- Also, <span class=\"ar\">ذَرْوٌ</span>, The <i>curved extremity of a bow.</i> (So in a copy of the S.)</p><p><b class=\"ar\">ذَرًى</b> , also written <span class=\"ar\">ذَرًا</span>, (or, accord. to some copies of the S, <span class=\"ar\"> <span class=\"ar\">ذُرًى</span></span>,) <i>A thing</i> [<i>such as dust &amp;c.</i>] <i>that the wind has raised,</i> or <i>made to fly, and carried away:</i> (S:) or it signifies <i>what one has winnowed;</i> (M;) or <span class=\"ar\">مَا تَذْرُوهُ</span> [<i>what thou winnowest,</i> as is indicated by the context of this explanation]; like as <span class=\"ar\">نَفَضٌ</span> signifies <span class=\"ar\">مَاتَنْفُضُهُ</span>. (T.) -b2- And <span class=\"ar\">ذَرًى</span> or <span class=\"ar\"> <span class=\"ar\">ذُرًى</span></span> (accord. to different copies of the S) <i>Tears poured forth:</i> (S:) or so <span class=\"ar\"> <span class=\"ar\">ذَرِىٌّ</span></span> [or <span class=\"ar\">دَمْعٌ ذَرِىٌّ</span>]. (M, TA.) -A2- Also <i>A shelter;</i> (M, TA;) <i>anything by which one is protected,</i> or <i>sheltered:</i> (S, Msb:) <i>a shelter from the cold wind, consisting of a wall,</i> or <i>of trees:</i> and particularly <i>a shelter that is made for camels such as are termed</i> <span class=\"ar\">شَوْل</span>, <i>by pulling up trees of the kind called</i> <span class=\"ar\">عَرْفَج</span> <i>&amp;c. and placing them one upon another in the direction whence blows the north,</i> or <i>northerly, wind, in the camel's nightly resting-place.</i> (T.) [Hence,] one says, <span class=\"ar\">فُلَانٌ فِى ذَرَى فُلَانٍ</span> <i>Such a one is in the protection of such a one.</i> (T.) And <span class=\"ar\">أَنَا فِى ظِلِّ فُلَانٌ وَفِى ذَرَاهُ</span> <i>I am in the protection of such a one, and in his shelter.</i> (S.) And [hence, perhaps,] <span class=\"ar\">إِنَّ فُلَانًا لَكَرِيمُ الذَّرَى</span> (assumed tropical:) <i>Verily such a one is generous in disposition.</i> (AZ, T.) -b2- Also The <i>court,</i> or <i>yard,</i> (<span class=\"ar\">فِنَآء</span>,) <i>of a house.</i> (Har pp. 56 and 442.) -A3- see also <span class=\"ar\">ذَرْوٌ</span>, in two places.</p><p><b class=\"ar\">ذُرًى</b> : see <span class=\"ar\">ذَرًى</span>, in two places: -b2- and <span class=\"ar\">ذُرَاوَةٌ</span>.</p><p><b class=\"ar\">ذَرْوَةٌ</b> <i>Much property;</i> like <span class=\"ar\">ثَرْوَةٌ</span>: so in the saying, <span class=\"ar\">هُوَ ذُو ذَرْوَةٍ</span> [<i>He is a possessor of much property</i>]. (TA.) -A2- See also <span class=\"ar\">ذِرْوَةٌ</span>.</p><p><b class=\"ar\">ذُرْوَةٌ</b> : see what next follows.</p><p><b class=\"ar\">ذِرْوَةٌ</b> and <span class=\"ar\"> <span class=\"ar\">ذُرْوَةٌ</span></span> The <i>upper,</i> or <i>uppermost, part</i> of a thing (S, M, Msb, K) of any kind; (M, Msb;) and so, accord. to Et-Takee Esh-Shemenee, <span class=\"ar\"> <span class=\"ar\">ذَرْوَةٌ</span></span>: (TA:) and particularly, of a camel's hump, (S, M,) and of the head: (M:) and <i>a camel's hump</i> itself: (TA:) pl. <span class=\"ar\">ذُرًى</span>. (S, TA.) It is said in a trad., <span class=\"ar\">أَتَى بِإِبِلٍ غُرَرِ الذُّرَى</span> [or <span class=\"ar\">غُرِّ</span> <span class=\"ar\">الذُّرَى</span>?] <i>He brought camels having white humps.</i> (TA.) And in another trad., <span class=\"ar\">عَلَى ذِرْوَةِ كُلِّ بَعِيرِ</span> <span class=\"ar\">شَيْطَانُ</span> [<i>On the hump of every camel is a devil</i>]. (TA.) And in a prov., <span class=\"ar\">مَا زَالَ يَفْتِلُ فِى الذِّرْوَةِ</span> <span class=\"ar\">وَالغَارِبِ</span> [<i>He ceased not to twist</i> the fur of <i>the upper part and the fore part of the hump:</i> originating from, or occurring in, a trad., which see explained in art. <span class=\"ar\">غرب</span>]: it means, (tropical:) <i>he ceased not to render familiar,</i> or <i>tame,</i> [or rather <i>to endeavour to do so,</i>] <i>and to remove refractoriness.</i> (TA.) -b2- [Hence,] <span class=\"ar\">تَزَوَّجَ مِنْهُمْ فِى الذِّرْوَةِ وَ النَّاصِيَةِ</span> (T, M *) (assumed tropical:) <i>He married among the noble and high of them.</i> (T.)</p><p><b class=\"ar\">ذَرِىٌّ</b> : see <span class=\"ar\">ذَرًى</span>. -A2- <span class=\"ar\">ذَرًى ذَرِىٌّ</span> <i>A warm shelter.</i> (TA.)</p><p><b class=\"ar\">ذَرِيَّةٌ</b> <i>A she-camel by means of which one conceals himself from the objects of the chase:</i> on the authority of Th: but the more approved word is with <span class=\"ar\">د</span> [i. e. <span class=\"ar\">دَرِيَّةٌ</span>, or, accord. to AZ, <span class=\"ar\">دَرِيْئَةٌ</span>]. (M.)</p><p><b class=\"ar\">ذُرَاوَةٌ</b> (vulgarly pronounced <span class=\"ar\">دَرَاوَةٌ</span>, TA) <i>What has become broken into small particles,</i> (M, K,) <i>and dried up,</i> (M,) or <i>of what has dried up,</i> (K,) of a plant, or of herbage, <i>and has been blown away by the wind.</i> (M, K.) -b2- And <i>What has fallen of,</i> or <i>from, corn,</i> (M, K,) or especially <i>wheat,</i> (Lh, M,) <i>in the process of winnowing.</i> (M, K.) And <i>What has fallen of,</i> or <i>from, a thing;</i> as also <span class=\"ar\"> <span class=\"ar\">ذُرًى</span></span>. (M, * K.)</p><p><b class=\"ar\">ذُرِّيَّةٌ</b> : see <span class=\"ar\">ذَرْوٌ</span>.</p><p><b class=\"ar\">الذَّرِيَاتٌ</b> [as used in the Kur li. 1] means <i>The winds</i> (S, Bd, Jel) <i>raising,</i> or <i>making to fly, and carrying away,</i> or <i>dispersing, the dust &amp;c.:</i> (Bd, Jel:) or (assumed tropical:) <i>the prolific women;</i> for they scatter children: or (assumed tropical:) <i>the causes of the scattering of the created beings, angels and others.</i> (Bd.)</p><p><b class=\"ar\">مِذْرًى</b> (S, M) and <span class=\"ar\"> <span class=\"ar\">مِذْرَاةٌ</span></span> (M) <i>A wooden implement,</i> (S, M,) or <i>a small wooden implement,</i> (so in one copy of the S,) <i>having</i> [<i>several</i>] <i>ex tremities</i> [or <i>prongs</i>], (S,) <i>with which one winnows</i> (S, M) <i>wheat, and with which the heaps of grain are cleared</i> [<i>from the straw &amp;c.</i>]: (S) or the former word signifies the <i>thing with which the wheat is carried to be winnowed:</i> and the latter, the <i>wooden implement with which one winnows.</i> (T.) -A2- Also, the former word, The <i>extremity of the buttock:</i> (AO, T, M, K:) or <span class=\"ar\"> <span class=\"ar\">مِذْرَوَانِ</span></span> signifies the <i>two extremities of the two buttocks;</i> (A'Obeyd, T, S, M, K *) or the <i>two uppermost parts of the two buttocks;</i> (Meyd in explaining a prov. cited below;) and it has no sing.; (A'Obeyd, T, S, M, Meyd, K;) for if the sing. were <span class=\"ar\">مِذْرًى</span>, the dual would be <span class=\"ar\">مِذْرَيَانِ</span>. (A'Obeyd, T, S, M, Meyd.) Hence, (Meyd,) <span class=\"ar\">جَآءَ يَنْفُضُ <span class=\"ar\">مِذْرَوَيْهِ</span></span> [<i>He came shaking the two extremities,</i> or <i>the two uppermost parts, of his buttocks</i>]; (S, Meyd, K;) a prov., applied to one behaving insolently (<span class=\"ar\">بَاغٍ</span>), and threatening; (S, K; *) or to one threatening vainly: (Meyd, and Har p. 603:) and <span class=\"ar\">جَآءَ يَضْرِبُ <span class=\"ar\">مِذْرَوَيْهِ</span></span> [<i>He came striking. &amp;c.</i>]; a prov. also, applied to him who has come empty, not having accomplished that which he sought. (Har ubi suprà.) -b2- <span class=\"ar\"> <span class=\"ar\">مِذْرَوَانِ</span></span> also signifies The <i>two sides of the head:</i> (M, K:) or <span class=\"ar\">مَذَارٍ</span> signifies the <i>temples of the head;</i> and the sing. is <span class=\"ar\">مِذْرًى</span>; accord. to AA. (S.) -b3- Also, <span class=\"ar\"> <span class=\"ar\">مِذْرَوَانِ</span></span>, The <i>two places,</i> of a bow, <i>upon which lies the string, in the upper portion and the lower:</i> (AHn, S, M, K: *) and in this sense it has no sing.: (S:) or, accord. to AA, its sing. is <span class=\"ar\">مِذْرًى</span>. (M.)</p><p><b class=\"ar\">مِذْرَاةٌ</b> : see the next preceding paragraph, first sentence.</p><p><b class=\"ar\">مِذْرَوَانِ</b> : see <span class=\"ar\">مِذْرًى</span>, in five places.</p><p><b class=\"ar\">مُذَرَّى</b> , fem. <span class=\"ar\">مُذَرَّاةٌ</span>, A sheep <i>having a portion of its wool left unshorn between the shoulders when the rest has been shorn.</i> (T.) [See 2.]</p>"},"ذهل":{"mf":"قال تعالى: يَوْمَ تَرَوْنَها تَذْهَلُ كُلُّ مُرْضِعَةٍ عَمَّا أَرْضَعَتْ<br>[الحج/ ٢]، الذّهول: شغل يورث حزنا ونسيانا، يقال: ذَهَلَ عن كذا وأَذْهَلَهُ كذا.","mq":[["شغل عن شي بذعر او غيره"],"الذال والهاء واللام أصلٌ واحد يدلُّ على شغْلٍ عن شئِ بذُعْرٍ أو غيره. ذَهِلْتُ عن الشّى أَذْهَل، إذا نسيتَه أو شُغِلْت. وأذْهَلَنِى عنه كذا. هذا هو الأصل. وحُكى عن اللحيانى: [جاء بَعْدَ (١)<br>] ذُهْلٍ من الليل وذَهْل، كما تقول: مرَّ هُدْءُ من اللّيل. ويجوز أن يكون ذلك لإظلامه وأنّه يُذْهَل فيه عن الأش"],"ln":"<p><b>1.</b> <b class=\"ar\">ذَهَلَ عَنْهُ</b> , (JK, S, Msb, K,) aor. <b class=\"ar\">ذَهَلَ</b> , (S, K,) inf. n. <span class=\"ar\">ذَهْلٌ</span>, (JK, S,) or <span class=\"ar\">ذُهُولٌ</span>, (Msb,) or both; (K;) and <span class=\"ar\">ذَهِلَ</span>, (S, Msb,) aor. <b class=\"ar\">ذَهَلَ</b> , (Msb,) inf. n. <span class=\"ar\">ذُهُولٌ</span>; (S;) <i>He forgot it,</i> or <i>neglected it;</i> (S;) <i>he was,</i> or <i>became, unmindful of it;</i> (S, Msb:) or <i>he neglected it intentionally;</i> (JK, T, M, K, * TA; <span class=\"ar\">عَلَى عَهْدٍ</span> in the K being a mistake for <span class=\"ar\">على عَمْدٍ</span>, as in the [JK and T and] M; TA;) or <i>in consequence of his being diverted by something:</i> (T, K:) or <i>he forgot it,</i> or <i>dismissed it from his mind, intentionally, and became diverted from it:</i> (Z, Msb:) <span class=\"ar\">ذُهُولٌ</span> is the <i>neglecting a thing, dismissing it from the mind:</i> (Ham p. 31:) or the <i>quitting a thing, with confusion,</i> or <i>perplexity,</i> or <i>alienation of mind, such as arises from fear</i> &amp;c.: (Ksh and Bd in xxii. 2:) or the <i>being diverted from one's constant companion,</i> or <i>familiar, so</i> <i>as to forget him;</i> and <i>being content to relinquish him:</i> (K;) or <i>diversion that occasions grief and forgetfulness.</i> (Er-Rághib, TA.) Hence, in the Kur [xxii. 2], <span class=\"ar\">يَوْمَ تَرَوْنَهَا تَذْهَلُ كُلُّ مُرْضِعَةٍ عَمَّا</span> <span class=\"ar\">أَرْضَعَتٌ</span> [<i>On the when thou shalt see it, every woman giving suck shall forget,</i> or <i>neglect,</i> &amp;c., <i>what she has suckled</i>]. (TA.) -A2- See also what next follows.</p><p><b>4.</b> <b class=\"ar\">أَذْهَلَنِى عَنْهُ</b> , (JK, * S, Msb, TA,) inf. n. <span class=\"ar\">إِذْهَالٌ</span>, (TA,) <i>It</i> (a thing, JK, S, TA,) or <i>he,</i> (a man, Msb,) <i>caused me to forget it,</i> or <i>neglect it;</i> (S;) or <i>to be unmindful of it;</i> (S, Msb;) or <i>to neglect it intentionally:</i> (JK:) [like <span class=\"ar\">أَذَهَنَنِى عنه</span>:] and sometimes one says <span class=\"ar\"> <span class=\"ar\">ذَهَلَنِى</span></span>; (Msb, TA;) [like <span class=\"ar\">ذَهَنَنى</span>;] but this is rare; or, rather, unknown. (TA.)</p><p><b class=\"ar\">ذَهْلٌ</b> : see what next follows.</p><p><b class=\"ar\">جَآءَ بَعْدَ ذُهْلٍ مِنَ اللَّيْلِ</b> , (S, K, *) and <span class=\"ar\"> <span class=\"ar\">ذَهْلٍ</span></span>, (S, K,) <i>He came after a short portion,</i> or <i>a period,</i> (<span class=\"ar\">سَاعَة</span>, K, or <span class=\"ar\">هَدْء</span>, S,) <i>of the night:</i> (S, K:) so called because sleep causes men to forget (<span class=\"ar\">يُذْهِلُ النَّاسَ</span>) therein: (Ham p. 4:) or <i>a large portion; such as the third,</i> or <i>the half:</i> so says IDrd; but he doubts its correctness; and ISd holds it to be preferably with <span class=\"ar\">د</span>. (TA.) -A2- <span class=\"ar\">ذُهْلٌ</span> also signifies The <i>tree</i> [or <i>plant</i>] <span class=\"ar\">بَشَام</span> [q. v.]. (JK, Sgh, K.)</p><p><b class=\"ar\">ذُهْلُولٌ</b> A horse <i>fleet,</i> or <i>swift:</i> (K:) or <i>light,</i> or <i>active:</i> and so a man: pl. <span class=\"ar\">ذَهَالِيلُ</span>. (JK.)</p><p><b class=\"ar\">ذَاهِلٌ</b> [act. part. n. of 1. -b2- And] A man <i>who cares not for ornament and the anointing of himself.</i> (JK.)</p>"},"ذعن":{"mf":"مُذْعِنِينَ<br><strong>«١»</strong> أي: منقادين، يقال: ناقة مِذْعَان، أي: منقادة.","mq":[["الاصحاب والانقياد"],"الذال والعين * والنون أصلٌ واحدٌ يدلُّ على الإصحاب والانقياد. يقال أذعَنَ الرّحلُ، إذا انقاد، يُذْعِن إذعاناً. وبناؤه ذَعَنَ، إلا أنَّ استعماله أَذْعَنَ. ويقال ناقةٌ مِذعانٌ: سَلِسَة الرأس منقادة.<br>"],"ln":"<p><b>1.</b> <b class=\"ar\">ذَعِنَ</b> : see what next follows.</p><p><b>4.</b> <b class=\"ar\">اذعن لَهُ</b> , (S, Msb, * K, &amp;c.,) inf. n. <span class=\"ar\">إِذْعَانٌ</span>, (Msb,) <i>He was,</i> or <i>became, quick in obedience to him,</i> or <i>it:</i> (K:) this is its [proper, or primary,] meaning, accord. to Aboo-Is-hák, in the language of the Arabs: (TA:) and <i>he acknowledged,</i> or <i>confessed, to him:</i> (K:) and <i>he was,</i> or <i>became, lowly,</i> or <i>humble, and abject, to him:</i> (S, K:) and <i>he was,</i> or <i>became, tractable, submissive,</i> or <i>manageable, to him;</i> (S, * Msb, * K, TA;) <i>and easy;</i> (K, * TA;) <i>not disobedient;</i> (Msb;) as also <span class=\"ar\"> <span class=\"ar\">ذَعِنَ</span></span>, aor. <b class=\"ar\">ذَعَنَ</b> , (K,) inf. n. <span class=\"ar\">ذَعَنٌ</span>. (TA.) You say, <span class=\"ar\">اذعن لِى بِحَقِّى</span> <i>He obeyed me with respect to that</i> [<i>right,</i> or <i>due,</i>] <i>which I sought to obtain from him, and hastened to render it:</i> and <i>he acknowledged,</i> or <i>confessed, to me my right,</i> or <i>due, willingly, not against his will;</i> as also <span class=\"ar\">أَمْعَنَ</span>. (TA.) Some have used <span class=\"ar\">إِذْعَانٌ</span> as meaning <i>Perception,</i> and <i>understanding:</i> but there is no foundation for this in the language of the Arabs; and its being tropical, as some of the sheykhs have endeavoured to show it to be, is improbable. (MF.)</p><p><b class=\"ar\">مُذْعِنٌ</b> [act. part. n. of 4]. <span class=\"ar\">وَإِنْ يَكُنْ لَهُمُ ٱلْحَقُّ</span> <span class=\"ar\">يَأْتُوا إِلَيْهِ مُذْعِنِينَ</span>, in the Kur [xxiv. 48], means [<i>But if the right be theirs,</i>] <i>they come to him quickly obedient:</i> (TA:) or [simply] <i>obedient; not compelled against their will:</i> (Fr, TA:) or <i>acknowledging,</i> or <i>confessing, and lowly,</i> or <i>humble:</i> or <i>tractable, submissive,</i> or <i>manageable, and easy.</i> (TA.) <span class=\"ar\"> <span class=\"ar\">مِذْعَانٌ</span></span>, also, signifies <i>Tractable, submissive,</i> or <i>manageable,</i> (Msb, K,) <i>to her leader,</i> (TA.) <i>and easy in the head;</i> (K;) applied to a she-camel: (Msb, K:) and, applied to a man, <i>tractable, submissive,</i> or <i>manageable.</i> (A, TA.)</p><p><b class=\"ar\">مِذْعَانٌ</b> : see what next precedes.</p><p><b class=\"ar\">رَأَيْتُهُمْ مُذْعَانِّينَ</b> is a mistake for <span class=\"ar\">رايتهم مُذْعَابِّينَ</span>, meaning <i>I saw them following one another,</i> or <i>doing so uninterruptedly.</i> (K.)</p>"},"ذود":{"mf":"ذُدْتُهُ عن كذا أَذُودُهُ. قال تعالى: وَوَجَدَ مِنْ دُونِهِمُ امْرَأَتَيْنِ تَذُودانِ<br><strong>[القصص/ ٢٣]، أي:</strong><br>تطردان، ذودا، والذَّوْدُ من الإبل: العشرة.","mq":[["تنحية الشي عن الشي","جماعة الابل"],"الذال والواو والدال أصلان: أحدهما تنْحِية الشّئ عن الشئ، والآخَر جماعةُ الإبل. ومحتملٌ أن يكون البابان راجعَينِ إلى أصل واحد.<br>فالأوّل قولهم: ذُدْت فلاناً عن الشئ أذُودُه ذَوْداً، وذُدْت إبِلى أذودُها ذَوداً وذِيادا. ويقال أذَدْتُ فلاناً: أعنتُه على ذِياد إبِله.<br>والأصل الآخر الذَّوْد من النَّعَم قال"],"ln":"<p><b>1.</b> <b class=\"ar\">ذَادَ</b> , (M, A,) first pers. <span class=\"ar\">ذُدْتُ</span>, (T, S,) aor. <span class=\"ar\">يَذُودُ</span>, (T, A,) inf. n. <span class=\"ar\">ذَوْدٌ</span>, (T,) or <span class=\"ar\">ذِيَادٌ</span>, (S,) or both, (M, A, K,) <i>He drove:</i> (S, M, K:) <i>he drove away:</i> (T, S, M, A, K:) and <i>he repelled.</i> (M, K.) You say, <span class=\"ar\">ذَدْتُ الإِبِلَ</span> <i>I drove the camels:</i> (S:) and <i>I drove them away:</i> (T, S:) and [so <span class=\"ar\"> <span class=\"ar\">ذَوَّدْتُهَا</span></span>, for] <span class=\"ar\">تَذْوِيدٌ</span> signifies the same as <span class=\"ar\">ذِيَادٌ</span>. (S.) And <span class=\"ar\">ذاد الإِبَلِ عَنِ المَآءِ</span>, (A, Msb,) aor. <span class=\"ar\">يَذُودُ</span>, inf. n. <span class=\"ar\">ذَوْدٌ</span> and <span class=\"ar\">ذِيَادٌ</span>, <i>He</i> (the pastor) [<i>drove away,</i> or <i>repelled,</i> or] <i>kept back,</i> or <i>debarred, the camels from the water;</i> or <i>prevented them from coming to it.</i> (Msb.) And <span class=\"ar\">ذادهُ عَنْ</span> <span class=\"ar\">كَذَا</span>, (A,) and <span class=\"ar\">ذُدْتُهُ</span>, (S,) <i>He,</i> and <i>I, drove him away from such a thing.</i> (S, A. [And the like is said in the M.]) And <span class=\"ar\">ذاد عَنِ الحَرَمِ</span> <i>He repelled from,</i> or <i>defended, the sacred territory.</i> (L.) And <span class=\"ar\">الثَّوْرُ يَذُودُ عَنْ نَفْسِهِ بِمِذْوَدِهِ</span>, i. e. (tropical:) [<i>The bull repels from,</i> or <i>defends, himself</i>] <i>with his horn: and</i> <span class=\"ar\">الفَارِسُ بِمِذْوَدِهِ</span>, i. e. (tropical:) [<i>the horseman</i>] <i>with his spear,</i> or <i>short spear.</i> (A.) And <span class=\"ar\">ذاد عَنْ</span> <span class=\"ar\">عِرْضِهِ</span> (assumed tropical:) <i>He defended his honour.</i> (L.) And <span class=\"ar\">ذاد</span> <span class=\"ar\">عَنِّى الهَمَّ</span> (tropical:) [<i>He dispelled from me anxiety.</i>] (A.)</p><p><b>2.</b> <b class=\"ar\">ذَوَّدَ</b> see above.</p><p><b>4.</b> <b class=\"ar\">اذادهُ</b> <i>He aided,</i> or <i>assisted, him to drive,</i> or <i>drive away,</i> (T, S, M, A,) <i>his camels.</i> (T, S, A.) [In the K, <span class=\"ar\">أَذَدْتُهُ</span> is said to signify <span class=\"ar\">أَعَنْتُهُ عَلَى ذِيَادِ</span> <span class=\"ar\">أَهْلِهِ</span>: but <span class=\"ar\">اهله</span> is app. a mistake for <span class=\"ar\">إِبِلِهِ</span>: or <span class=\"ar\">عَنْ</span> is omitted before <span class=\"ar\">اهله</span>; and if so, the meaning is <i>I aided,</i> or <i>assisted, him to defend his family;</i> but in this latter case, we should read <span class=\"ar\">ذِيَادٍ</span>, which would be less chaste than <span class=\"ar\">الذِّيَادِ</span>.]</p><p><b class=\"ar\">ذَوْدٌ</b> <i>A number of camels, from three to ten:</i> (Lth, AZ, As, T, S, M, A, Mgh, Msb, K:) this is the meaning that is of best repute: (TA:) [in this explanation in the T from AZ, and in the K, the nouns of number are mase.; and so in the next here following: in the rest, fem.:] or <i>from three to ten:</i> and <i>a little more:</i> (IAar, M:) or <i>from three to nine:</i> (M, L:) or <i>from three to fifteen:</i> or <i>from three to twenty;</i> (M, L, K;) and <i>a little more:</i> (L:) or <i>from three to thirty:</i> (M, L, K:) or <i>from two to nine:</i> (M, Mgh, L, K:) [said to be] applied only to <i>females:</i> (Lth, A'Obeyd, T, M, Mgh, Msb, K:) so in the Bári': (Msb:) and it is of the fem. gender; (T, S, M, Msb, K;) i. e., the word is fem.: (MF:) but its dim. is [ <span class=\"ar\"> <span class=\"ar\">ذُوَيْدٌ</span></span>,] without <span class=\"ar\">ة</span>; contr. to analogy: (M:) the word <span class=\"ar\">ذَوْدٌ</span> is a pl., (M, K,) meaning a quasipl. n., (MF,) having no sing. (S, M, K) of the same root: (S:) or a sing.; (K;) and its pl. is <span class=\"ar\">أَذْوَادٌ</span>: (T, S, M, A, Msb, K:) or a sing. and pl.: (M, K:) the Arabs said <span class=\"ar\">ثَلَاثُ أَذْوَادٍ</span> and <span class=\"ar\">ثَلَاثُ ذَوْدٍ</span> and so with all the inferior ns. of number, making <span class=\"ar\">ذَوْد</span> a substitute for <span class=\"ar\">أَذْوَاد</span>: and they also said <span class=\"ar\">ثَلَاثُ ذَوْدٍ</span> meaning thereby <i>three she-camels.</i> (M, L.) It is said in a trad., <span class=\"ar\">لَيْسَ فِيمَا دُونَ خَمْسِ</span> <span class=\"ar\">ذَوْدٍ مِنَ الإِبِلِ صَدَقَةٌ</span>, (T, L,) or <span class=\"ar\">لَيْسَ فِىأَقَلَّ مِنْ</span> <span class=\"ar\">خَمْسٍ ذَوْدٍ صَدَقَةٌ</span>, (T, Msb,) meaning [<i>There is not in the case of less than five</i>] <i>camels</i> [<i>any poorrate</i>]: for the poor-rate is incumbent on him who possesses five camels whether they be males or females. (L.) And in another trad. it is said, <span class=\"ar\">فِى خَمْسِ ذَوْدٍ شَاةٌ</span> [<i>In the case of five camels, a sheep</i> or <i>goat</i> shall be given]. (Mgh.) And it is said in a prov., <span class=\"ar\">الذَّوْدُ إِلَى الذَّوْدِ إِبِلٌ</span> [<i>A few she-camels with a few she-camels are a herd of camels</i>]; (T, S, M, A;) meaning that a little with a little is much; <span class=\"ar\">الى</span> being here used in the sense of <span class=\"ar\">مَعَ</span>: (S, A:) or <span class=\"ar\">الى</span> is here used in its proper sense; a word signifying “ joined ” or the like being understood; (TA;) i. e. a few joined to a few becomes much: (M:) [or,] accord. to the K [and the T], this prov. shows that <span class=\"ar\">ذود</span> is here used in the place of <span class=\"ar\">اِثْنَتَانِ</span> [i. e. <i>two</i> she-camels]; for two added to two are a pl.; but this requires consideration. (MF.)</p><p><b class=\"ar\">ذُوَيْدٌ</b> : see the next preceding paragraph.</p><p><b class=\"ar\">ذَوَّادٌ</b> : see the next following paragraph.</p><p><b class=\"ar\">ذَائِدٌ</b> <i>Driving: driving away: and repelling:</i> pl. <span class=\"ar\">ذُوَّدٌ</span> and <span class=\"ar\">ذُوَّادٌ</span> and <span class=\"ar\">ذَادَةٌ</span>. (M, K.) -b2- Also, and <span class=\"ar\"> <span class=\"ar\">ذَوَّادٌ</span></span>, [but the latter has an intensive meaning,] (assumed tropical:) A man who is <i>a defender,</i> or <i>protector, of that which,</i> or <i>those whom, it is necessary to defend,</i> or <i>protect:</i> (S, K:) <i>who is wont to repel attacks upon his honour.</i> (S, * TA.)</p><p><b class=\"ar\">مَذَادٌ</b> <i>A place where beasts pasture at pleasure, where they eat and drink what they please, amid abundance of herbage.</i> (IAar, K.)</p><p><b class=\"ar\">مِذْوَدٌ</b> [<i>An instrument for driving, driving away,</i> or <i>repelling.</i> -b2- ] (tropical:) <i>A spear,</i> or <i>short spear,</i> with which one repels from, or defends, himself. (A.) -b3- (tropical:) The <i>horn</i> of a bull, (T, A, K,) with which he repels from, or defends, himself. (A.) -b4- (tropical:) The <i>tongue:</i> (S, M, A, K:) because with it a man defends his honour. (M.) Hassán Ibn-Thábit says, <span class=\"ar\">لِسَانِى وَسَيْفِى صَارِمَانِ كِلَاهُمَا</span> <span class=\"ar\">وَيَبْلُغُ مَا لَا يَبْلُغُ السَّيْفُ مِذْوَدِى</span> (tropical:) [<i>My tongue and my sword are sharp, both of them; and my tongue reacheth what my sword will not reach</i>]. (S, TA.) -b5- (tropical:) [A man <i>who defends well,</i> or <i>vigorously;</i> as also <span class=\"ar\"> <span class=\"ar\">مِذْوَادٌ</span></span>:] you say <span class=\"ar\">رِجَالٌ مَذَاوِدٌ</span> and <span class=\"ar\">مَذَاوِيدُ</span>. (A.) -b6- The <i>manger</i> (<span class=\"ar\">مِعْلَف</span>, T, K, TA, in some copies of the K <span class=\"ar\">معتلف</span>, TA) of a horse or similar beast. (T, K. [A manger is thus called in the present day.])</p><p><b class=\"ar\">مِذْوَادٌ</b> : see the next preceding paragraph.</p>"}});
